import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface Point {
  x: number;
  y: number;
}

export interface Particle {
  x: number;
  y: number;
  vx: number;
  vy: number;
  life: number;
  maxLife: number;
  size: number;
  color: string;
}

export interface HandData {
  wrist: Point;
  indexTip: Point;
  middleTip: Point;
  ringTip: Point;
  pinkyTip: Point;
  thumbTip: Point;
  isOpen: boolean; // Simple heuristic for open hand vs fist
  opacity: number; // Smoothed opacity value
}

import { Point } from '../types';

// Constants for colors
export const COLOR_PRIMARY = '#FFA014'; // Amber
export const COLOR_SECONDARY = '#FFC832'; // Gold
export const COLOR_CORE = '#FFFFFF'; // White

// Helper to draw a regular polygon
export const drawPolygon = (
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  radius: number,
  sides: number,
  rotation: number
) => {
  ctx.beginPath();
  for (let i = 0; i < sides; i++) {
    const theta = rotation + (i * 2 * Math.PI) / sides;
    const px = x + radius * Math.cos(theta);
    const py = y + radius * Math.sin(theta);
    if (i === 0) ctx.moveTo(px, py);
    else ctx.lineTo(px, py);
  }
  ctx.closePath();
  ctx.stroke();
};

// Layer 1: Runes Ring
// We generate "runes" by drawing random lines within small segments along the ring
export const drawRuneRing = (
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  radius: number,
  rotation: number
) => {
  const segments = 24;
  ctx.strokeStyle = COLOR_PRIMARY;
  ctx.lineWidth = 2;

  // Outer circle
  ctx.beginPath();
  ctx.arc(x, y, radius, 0, Math.PI * 2);
  ctx.stroke();

  // Inner border for runes
  ctx.beginPath();
  ctx.arc(x, y, radius * 0.85, 0, Math.PI * 2);
  ctx.stroke();

  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(rotation);

  for (let i = 0; i < segments; i++) {
    const angle = (Math.PI * 2) / segments;
    ctx.save();
    ctx.rotate(i * angle);
    ctx.translate(radius * 0.925, 0); // Move to between the two circles

    // Procedural Rune Glyph (Deterministic based on index i)
    // We use Math.sin/cos with high frequencies to simulate "random" but stable glyphs
    const seed = i * 13.37;
    const size = radius * 0.05;

    ctx.beginPath();
    ctx.moveTo(-size, -size + Math.sin(seed) * size);
    ctx.lineTo(size, size - Math.cos(seed) * size);
    ctx.moveTo(-size, size);
    ctx.lineTo(size + Math.sin(seed * 2) * 5, -size);
    if (i % 3 === 0) ctx.rect(-size / 2, -size / 2, size, size);

    ctx.strokeStyle = COLOR_SECONDARY;
    ctx.lineWidth = 1.5;
    ctx.stroke();

    ctx.restore();
  }
  ctx.restore();
};

// Layer 2: Hexagram (Star of David) / Sacred Geometry
export const drawSacredGeometry = (
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  radius: number,
  rotation: number
) => {
  ctx.strokeStyle = COLOR_PRIMARY;
  ctx.lineWidth = 3;
  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(rotation);

  // Triangle 1
  ctx.beginPath();
  for (let i = 0; i < 3; i++) {
    const theta = (i * 2 * Math.PI) / 3;
    const px = radius * Math.cos(theta);
    const py = radius * Math.sin(theta);
    if (i === 0) ctx.moveTo(px, py);
    else ctx.lineTo(px, py);
  }
  ctx.closePath();
  ctx.stroke();

  // Triangle 2 (Inverted)
  ctx.beginPath();
  for (let i = 0; i < 3; i++) {
    const theta = (i * 2 * Math.PI) / 3 + Math.PI; // Offset by 180 deg
    const px = radius * Math.cos(theta);
    const py = radius * Math.sin(theta);
    if (i === 0) ctx.moveTo(px, py);
    else ctx.lineTo(px, py);
  }
  ctx.closePath();
  ctx.stroke();

  // Inner Circle connecting intersections
  ctx.beginPath();
  ctx.arc(0, 0, radius * 0.5, 0, Math.PI * 2);
  ctx.strokeStyle = COLOR_SECONDARY;
  ctx.lineWidth = 1;
  ctx.stroke();

  ctx.restore();
};

// Layer 3: Rotating Square (Diamond)
export const drawSquareLayer = (
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  radius: number,
  rotation: number
) => {
  ctx.strokeStyle = COLOR_SECONDARY;
  ctx.lineWidth = 4;

  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(rotation);

  // A square is a 4-sided polygon
  ctx.beginPath();
  const size = radius;
  ctx.rect(-size / 2, -size / 2, size, size);
  ctx.stroke();

  // Decorative corners
  ctx.fillStyle = COLOR_CORE;
  const cornerSize = 4;
  ctx.fillRect(-size / 2 - cornerSize, -size / 2 - cornerSize, cornerSize * 2, cornerSize * 2);
  ctx.fillRect(size / 2 - cornerSize, -size / 2 - cornerSize, cornerSize * 2, cornerSize * 2);
  ctx.fillRect(size / 2 - cornerSize, size / 2 - cornerSize, cornerSize * 2, cornerSize * 2);
  ctx.fillRect(-size / 2 - cornerSize, size / 2 - cornerSize, cornerSize * 2, cornerSize * 2);

  ctx.restore();
};

// Layer 4: Pulsing Pentagram
export const drawPentagram = (
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  radius: number,
  rotation: number,
  pulse: number
) => {
  const r = radius * (0.8 + pulse * 0.2); // Apply pulse to scale
  ctx.strokeStyle = COLOR_CORE;
  ctx.lineWidth = 2 + pulse * 2;
  ctx.shadowBlur = 10 + pulse * 10;
  ctx.shadowColor = COLOR_PRIMARY;

  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(rotation);

  ctx.beginPath();
  for (let i = 0; i < 5; i++) {
    // Draw lines skipping vertices to make a star
    const theta = (i * 4 * Math.PI) / 5 - Math.PI / 2;
    const px = r * Math.cos(theta);
    const py = r * Math.sin(theta);
    if (i === 0) ctx.moveTo(px, py);
    else ctx.lineTo(px, py);
  }
  ctx.closePath();
  ctx.stroke();

  ctx.shadowBlur = 0; // Reset
  ctx.restore();
};

import React, { useEffect, useRef, useState, useCallback } from 'react';
import Webcam from 'react-webcam';
import { Hands, Results } from '@mediapipe/hands';
import { Camera } from '@mediapipe/camera_utils';
import { Particle, HandData } from '../types';
import { 
  drawRuneRing, 
  drawSacredGeometry, 
  drawSquareLayer, 
  drawPentagram,
  COLOR_PRIMARY,
  COLOR_SECONDARY
} from '../utils/geometry';

interface MagicOverlayProps {
  width: number;
  height: number;
}

const MagicOverlay: React.FC<MagicOverlayProps> = ({ width, height }) => {
  const webcamRef = useRef<Webcam>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();
  const particlesRef = useRef<Particle[]>([]);
  const handDataRef = useRef<HandData[]>([]);

  // Initialize MediaPipe Hands
  useEffect(() => {
    const hands = new Hands({
      locateFile: (file) => {
        return `https://cdn.jsdelivr.net/npm/@mediapipe/hands/${file}`;
      },
    });

    hands.setOptions({
      maxNumHands: 2,
      modelComplexity: 1,
      minDetectionConfidence: 0.6,
      minTrackingConfidence: 0.5,
    });

    hands.onResults(onResults);

    if (typeof webcamRef.current?.video !== 'undefined' && webcamRef.current.video !== null) {
      const camera = new Camera(webcamRef.current.video, {
        onFrame: async () => {
          if (webcamRef.current?.video) {
            await hands.send({ image: webcamRef.current.video });
          }
        },
        width: width,
        height: height,
      });
      camera.start();
    }

    return () => {
        // Cleanup if needed
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [width, height]);

  // Handle MediaPipe Results
  const onResults = useCallback((results: Results) => {
    const videoWidth = webcamRef.current?.video?.videoWidth || width;
    const videoHeight = webcamRef.current?.video?.videoHeight || height;

    if (results.multiHandLandmarks) {
      const newHandData: HandData[] = results.multiHandLandmarks.map((landmarks) => {
        // Map 0-1 coords to canvas size
        // Note: Webcam is mirrored, so we mirror x coordinate: (1 - x)
        const mapPt = (p: any) => ({ x: (1 - p.x) * videoWidth, y: p.y * videoHeight });

        const wrist = mapPt(landmarks[0]);
        const indexTip = mapPt(landmarks[8]);
        const middleTip = mapPt(landmarks[12]);
        const ringTip = mapPt(landmarks[16]);
        const pinkyTip = mapPt(landmarks[20]);
        const thumbTip = mapPt(landmarks[4]);

        // Heuristic for Openness: Distance of tips from wrist
        const dist = (p1: any, p2: any) => Math.hypot(p1.x - p2.x, p1.y - p2.y);
        const avgDist = (
          dist(wrist, indexTip) + 
          dist(wrist, middleTip) + 
          dist(wrist, ringTip) + 
          dist(wrist, pinkyTip)
        ) / 4;

        // Scale factor depends on hand z-depth approximately, but simplified here:
        // A full open hand usually has avg finger length > X pixels relative to palm size.
        // We use a relative measure: distance between wrist and index_mcp (knuckle)
        const knuckle = mapPt(landmarks[5]);
        const palmSize = dist(wrist, knuckle);

        const isOpen = avgDist > palmSize * 1.8;

        return {
          wrist,
          indexTip,
          middleTip,
          ringTip,
          pinkyTip,
          thumbTip,
          isOpen,
          opacity: 0, // Will be smoothed in render loop
        };
      });

      // Update refs with basic smoothing could happen here, but we'll do direct replacement
      // For smoother opacity, we need to persist state between frames, which is handled in render loop logic below
      // but for raw data input, we just update the target.

      // To preserve opacity transition, we match hands by proximity or index
      // Simple approach: Just use index 0 and 1
      handDataRef.current = newHandData; 
    }
  }, [width, height]);


  // Particle System Update
  const updateParticles = (ctx: CanvasRenderingContext2D, width: number, height: number) => {
    // Add new particles if hands are active
    // This logic happens inside render loop to sync with hand position

    // Physics Update
    for (let i = particlesRef.current.length - 1; i >= 0; i--) {
      const p = particlesRef.current[i];
      p.x += p.vx;
      p.y += p.vy;
      p.vy -= 0.15; // Negative gravity (float up)
      p.vx *= 0.95; // Drag
      p.vy *= 0.98; // Drag
      p.size *= 0.97; // Shrink
      p.life -= 1;

      if (p.life <= 0 || p.size < 0.5) {
        particlesRef.current.splice(i, 1);
      } else {
        // Draw Particle
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);

        // High glow for plasma look
        ctx.shadowBlur = 15;
        ctx.shadowColor = p.color;
        ctx.fillStyle = p.color;

        // Opacity fade
        ctx.globalAlpha = p.life / p.maxLife;
        ctx.fill();
        ctx.globalAlpha = 1.0;
        ctx.shadowBlur = 0; // Reset
      }
    }
  };

  const spawnParticles = (x: number, y: number, intensity: number) => {
    const count = Math.floor(4 * intensity); // High density
    for (let i = 0; i < count; i++) {
      const angle = Math.random() * Math.PI * 2;
      const speed = Math.random() * 2;
      particlesRef.current.push({
        x: x + (Math.random() - 0.5) * 40,
        y: y + (Math.random() - 0.5) * 40,
        vx: Math.cos(angle) * speed,
        vy: Math.sin(angle) * speed - 1, // Initial upward drift
        life: 40 + Math.random() * 20,
        maxLife: 60,
        size: 4 + Math.random() * 6, // 4px to 10px
        color: Math.random() > 0.5 ? COLOR_PRIMARY : COLOR_SECONDARY,
      });
    }
  };

  // Main Render Loop
  const animate = useCallback((time: number) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Clear and set composite mode for "Energy" look
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.globalCompositeOperation = 'screen'; // or 'lighter'

    // Process Hands
    handDataRef.current.forEach((hand) => {
       // Smooth Opacity (Transition)
       // We cheat slightly by modifying the ref directly for this animation frame
       // In a rigorous app we might use a separate state map.
       const targetOpacity = hand.isOpen ? 1 : 0;
       // Lerp opacity
       // We store current opacity on the object. Since onResults creates new objects, 
       // we might lose state. *Correction*: onResults replaces the array. 
       // To fix flickering, we assume full open/close snap for now OR 
       // implementing a proper tracking ID system is complex for this snippet.
       // Let's use the 'isOpen' directly for geometry visibility but maybe lerp the size/alpha?

       // Let's just use isOpen boolean to drive intensity for responsiveness as requested.
       const intensity = hand.isOpen ? 1 : 0.1;

       if (intensity > 0.2) {
         const centerX = hand.middleTip.x;
         const centerY = hand.middleTip.y + 30; // Shift down to palm center roughly

         // Physics Rotation Variables
         const t = time * 0.001;

         // 1. Runes Ring (Rotate CW, Slow)
         ctx.globalAlpha = intensity;
         drawRuneRing(ctx, centerX, centerY, 120, t * 0.5);

         // 2. Hexagram (Rotate CCW, Medium)
         drawSacredGeometry(ctx, centerX, centerY, 90, -t * 1.5);

         // 3. Square (Rotate CW, Fast)
         drawSquareLayer(ctx, centerX, centerY, 65, t * 2.5);

         // 4. Pentagram (Pulse)
         const pulse = Math.sin(time * 0.005) * 0.5 + 0.5;
         drawPentagram(ctx, centerX, centerY, 40, t, pulse);

         // Spawn Particles
         spawnParticles(centerX, centerY, intensity);
       }
    });

    // Process Particles
    updateParticles(ctx, canvas.width, canvas.height);

    requestRef.current = requestAnimationFrame(animate);
  }, []);

  useEffect(() => {
    requestRef.current = requestAnimationFrame(animate);
    return () => {
      if (requestRef.current) cancelAnimationFrame(requestRef.current);
    };
  }, [animate]);

  return (
    <div className="relative w-full h-full bg-black overflow-hidden flex items-center justify-center">
        {/* Webcam is hidden but active for processing */}
        <Webcam
          ref={webcamRef}
          audio={false}
          width={width}
          height={height}
          mirrored={true}
          className="absolute opacity-0 pointer-events-none" 
        />

        {/* Visible Canvas */}
        {/* We mirror the canvas via CSS to match the mirrored webcam logic seamlessly if needed, 
            but our coordinate mapping already handles the mirror math. 
            So we just display it normally.
            Actually, to create the "Selfie Mirror" effect, the webcam is mirrored. 
            Our coordinates (1-x) un-mirror it for processing? 
            Wait, standard MediaPipe: if you send mirrored video, landmarks are mirrored. 
            We want the user to see themselves like a mirror. 
            So we render the webcam video as background (optional) or just black?
            The prompt implies a Simulator. Usually this means Overlay.
            Let's show the Webcam feed visible behind the magic.
        */}
        <Webcam
          audio={false}
          width={width}
          height={height}
          mirrored={true}
          className="absolute top-0 left-0 w-full h-full object-cover opacity-80"
        />

        <canvas
          ref={canvasRef}
          width={width}
          height={height}
          className="absolute top-0 left-0 w-full h-full object-cover z-10"
        />

        <div className="absolute bottom-10 left-0 w-full text-center pointer-events-none z-20">
          <p className="text-amber-400 font-mono text-sm opacity-80 tracking-widest uppercase glow-text">
            Open hand to Summon • Close to Dispel
          </p>
        </div>

        <style>{`
          .glow-text {
            text-shadow: 0 0 10px #FFA014;
          }
        `}</style>
    </div>
  );
};

export default MagicOverlay;

import React, { useState, useEffect } from 'react';
import MagicOverlay from './components/MagicOverlay';

const App: React.FC = () => {
  const [dimensions, setDimensions] = useState({ width: 640, height: 480 });

  useEffect(() => {
    const handleResize = () => {
      setDimensions({
        width: window.innerWidth,
        height: window.innerHeight
      });
    };

    window.addEventListener('resize', handleResize);
    handleResize(); // Initial set

    return () => window.removeEventListener('resize', handleResize);
  }, []);

  return (
    <div className="w-screen h-screen bg-neutral-900 overflow-hidden relative">
      <MagicOverlay width={dimensions.width} height={dimensions.height} />

      {/* Overlay UI for aesthetics */}
      <div className="absolute top-0 left-0 p-6 pointer-events-none">
        <h1 className="text-3xl font-bold text-amber-500 tracking-tighter" style={{ textShadow: '0 0 15px #FFC832' }}>
          ELDRITCH ARTS
        </h1>
        <div className="w-16 h-1 bg-amber-500 mt-2 shadow-[0_0_10px_#FFA014]"></div>
      </div>
    </div>
  );
};

export default App;

import React, { useEffect, useRef, useState, useCallback } from 'react';
import Webcam from 'react-webcam';
import { Hands, Results } from '@mediapipe/hands';
import { Particle, HandData } from '../types';
import { 
  drawRuneRing, 
  drawSacredGeometry, 
  drawSquareLayer, 
  drawPentagram,
  COLOR_PRIMARY,
  COLOR_SECONDARY
} from '../utils/geometry';

interface MagicOverlayProps {
  width: number;
  height: number;
}

const MagicOverlay: React.FC<MagicOverlayProps> = ({ width, height }) => {
  const webcamRef = useRef<Webcam>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();
  const particlesRef = useRef<Particle[]>([]);
  const handDataRef = useRef<HandData[]>([]);

  // Handle MediaPipe Results
  const onResults = useCallback((results: Results) => {
    const videoWidth = webcamRef.current?.video?.videoWidth || width;
    const videoHeight = webcamRef.current?.video?.videoHeight || height;

    if (results.multiHandLandmarks) {
      const newHandData: HandData[] = results.multiHandLandmarks.map((landmarks) => {
        // Map 0-1 coords to canvas size
        // Note: Webcam is mirrored, so we mirror x coordinate: (1 - x)
        const mapPt = (p: any) => ({ x: (1 - p.x) * videoWidth, y: p.y * videoHeight });

        const wrist = mapPt(landmarks[0]);
        const indexTip = mapPt(landmarks[8]);
        const middleTip = mapPt(landmarks[12]);
        const ringTip = mapPt(landmarks[16]);
        const pinkyTip = mapPt(landmarks[20]);
        const thumbTip = mapPt(landmarks[4]);

        // Heuristic for Openness: Distance of tips from wrist
        const dist = (p1: any, p2: any) => Math.hypot(p1.x - p2.x, p1.y - p2.y);
        const avgDist = (
          dist(wrist, indexTip) + 
          dist(wrist, middleTip) + 
          dist(wrist, ringTip) + 
          dist(wrist, pinkyTip)
        ) / 4;

        // Scale factor depends on hand z-depth approximately, but simplified here:
        // A full open hand usually has avg finger length > X pixels relative to palm size.
        // We use a relative measure: distance between wrist and index_mcp (knuckle)
        const knuckle = mapPt(landmarks[5]);
        const palmSize = dist(wrist, knuckle);

        const isOpen = avgDist > palmSize * 1.8;

        return {
          wrist,
          indexTip,
          middleTip,
          ringTip,
          pinkyTip,
          thumbTip,
          isOpen,
          opacity: 0, // Will be smoothed in render loop
        };
      });

      handDataRef.current = newHandData; 
    }
  }, [width, height]);

  // Initialize MediaPipe Hands
  useEffect(() => {
    let isActive = true;
    const hands = new Hands({
      locateFile: (file) => {
        return `https://cdn.jsdelivr.net/npm/@mediapipe/hands/${file}`;
      },
    });

    hands.setOptions({
      maxNumHands: 2,
      modelComplexity: 1,
      minDetectionConfidence: 0.6,
      minTrackingConfidence: 0.5,
    });

    hands.onResults(onResults);

    // Custom loop to send frames to MediaPipe
    const processVideo = async () => {
      if (!isActive) return;

      if (
        webcamRef.current && 
        webcamRef.current.video && 
        webcamRef.current.video.readyState === 4
      ) {
        try {
          await hands.send({ image: webcamRef.current.video });
        } catch (error) {
          console.error("MediaPipe error:", error);
        }
      }

      if (isActive) {
        requestAnimationFrame(processVideo);
      }
    };

    processVideo();

    return () => {
      isActive = false;
      hands.close();
    };
  }, [onResults]); // Removed width/height from dependency as they are handled in onResults logic mostly

  // Particle System Update
  const updateParticles = (ctx: CanvasRenderingContext2D, width: number, height: number) => {
    // Physics Update
    for (let i = particlesRef.current.length - 1; i >= 0; i--) {
      const p = particlesRef.current[i];
      p.x += p.vx;
      p.y += p.vy;
      p.vy -= 0.15; // Negative gravity (float up)
      p.vx *= 0.95; // Drag
      p.vy *= 0.98; // Drag
      p.size *= 0.97; // Shrink
      p.life -= 1;

      if (p.life <= 0 || p.size < 0.5) {
        particlesRef.current.splice(i, 1);
      } else {
        // Draw Particle
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);

        // High glow for plasma look
        ctx.shadowBlur = 15;
        ctx.shadowColor = p.color;
        ctx.fillStyle = p.color;

        // Opacity fade
        ctx.globalAlpha = p.life / p.maxLife;
        ctx.fill();
        ctx.globalAlpha = 1.0;
        ctx.shadowBlur = 0; // Reset
      }
    }
  };

  const spawnParticles = (x: number, y: number, intensity: number) => {
    const count = Math.floor(4 * intensity); // High density
    for (let i = 0; i < count; i++) {
      const angle = Math.random() * Math.PI * 2;
      const speed = Math.random() * 2;
      particlesRef.current.push({
        x: x + (Math.random() - 0.5) * 40,
        y: y + (Math.random() - 0.5) * 40,
        vx: Math.cos(angle) * speed,
        vy: Math.sin(angle) * speed - 1, // Initial upward drift
        life: 40 + Math.random() * 20,
        maxLife: 60,
        size: 4 + Math.random() * 6, // 4px to 10px
        color: Math.random() > 0.5 ? COLOR_PRIMARY : COLOR_SECONDARY,
      });
    }
  };

  // Main Render Loop
  const animate = useCallback((time: number) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Clear and set composite mode for "Energy" look
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.globalCompositeOperation = 'screen'; // or 'lighter'

    // Process Hands
    handDataRef.current.forEach((hand) => {
       // Let's just use isOpen boolean to drive intensity for responsiveness as requested.
       const intensity = hand.isOpen ? 1 : 0.1;

       if (intensity > 0.2) {
         const centerX = hand.middleTip.x;
         const centerY = hand.middleTip.y + 30; // Shift down to palm center roughly

         // Physics Rotation Variables
         const t = time * 0.001;

         // 1. Runes Ring (Rotate CW, Slow)
         ctx.globalAlpha = intensity;
         drawRuneRing(ctx, centerX, centerY, 120, t * 0.5);

         // 2. Hexagram (Rotate CCW, Medium)
         drawSacredGeometry(ctx, centerX, centerY, 90, -t * 1.5);

         // 3. Square (Rotate CW, Fast)
         drawSquareLayer(ctx, centerX, centerY, 65, t * 2.5);

         // 4. Pentagram (Pulse)
         const pulse = Math.sin(time * 0.005) * 0.5 + 0.5;
         drawPentagram(ctx, centerX, centerY, 40, t, pulse);

         // Spawn Particles
         spawnParticles(centerX, centerY, intensity);
       }
    });

    // Process Particles
    updateParticles(ctx, canvas.width, canvas.height);

    requestRef.current = requestAnimationFrame(animate);
  }, []);

  useEffect(() => {
    requestRef.current = requestAnimationFrame(animate);
    return () => {
      if (requestRef.current) cancelAnimationFrame(requestRef.current);
    };
  }, [animate]);

  return (
    <div className="relative w-full h-full bg-black overflow-hidden flex items-center justify-center">
        {/* Webcam is hidden but active for processing */}
        <Webcam
          ref={webcamRef}
          audio={false}
          width={width}
          height={height}
          mirrored={true}
          className="absolute opacity-0 pointer-events-none" 
        />

        {/* Visible Webcam Feedback */}
        <Webcam
          audio={false}
          width={width}
          height={height}
          mirrored={true}
          className="absolute top-0 left-0 w-full h-full object-cover opacity-80"
        />

        <canvas
          ref={canvasRef}
          width={width}
          height={height}
          className="absolute top-0 left-0 w-full h-full object-cover z-10"
        />

        <div className="absolute bottom-10 left-0 w-full text-center pointer-events-none z-20">
          <p className="text-amber-400 font-mono text-sm opacity-80 tracking-widest uppercase glow-text">
            Open hand to Summon • Close to Dispel
          </p>
        </div>

