import React, { useEffect, useRef, useState, useCallback } from 'react';
import Webcam from 'react-webcam';
import { Particle, HandData } from '../types';
import { 
  drawRuneRing, 
  drawSacredGeometry, 
  drawSquareLayer, 
  drawPentagram,
  COLOR_PRIMARY,
  COLOR_SECONDARY
} from '../utils/geometry';

interface MagicOverlayProps {
  width: number;
  height: number;
}

const MagicOverlay: React.FC<MagicOverlayProps> = ({ width, height }) => {
  const webcamRef = useRef<Webcam>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();
  const particlesRef = useRef<Particle[]>([]);
  const handDataRef = useRef<HandData[]>([]);

  // Handle MediaPipe Results
  const onResults = useCallback((results: any) => {
    const videoWidth = webcamRef.current?.video?.videoWidth || width;
    const videoHeight = webcamRef.current?.video?.videoHeight || height;

    if (results.multiHandLandmarks) {
      const newHandData: HandData[] = results.multiHandLandmarks.map((landmarks: any[]) => {
        // Map 0-1 coords to canvas size
        // Note: Webcam is mirrored, so we mirror x coordinate: (1 - x)
        const mapPt = (p: any) => ({ x: (1 - p.x) * videoWidth, y: p.y * videoHeight });

        const wrist = mapPt(landmarks[0]);
        const indexTip = mapPt(landmarks[8]);
        const middleTip = mapPt(landmarks[12]);
        const ringTip = mapPt(landmarks[16]);
        const pinkyTip = mapPt(landmarks[20]);
        const thumbTip = mapPt(landmarks[4]);

        // Heuristic for Openness: Distance of tips from wrist
        const dist = (p1: any, p2: any) => Math.hypot(p1.x - p2.x, p1.y - p2.y);
        const avgDist = (
          dist(wrist, indexTip) + 
          dist(wrist, middleTip) + 
          dist(wrist, ringTip) + 
          dist(wrist, pinkyTip)
        ) / 4;

        // Scale factor depends on hand z-depth approximately, but simplified here:
        // A full open hand usually has avg finger length > X pixels relative to palm size.
        // We use a relative measure: distance between wrist and index_mcp (knuckle)
        const knuckle = mapPt(landmarks[5]);
        const palmSize = dist(wrist, knuckle);

        const isOpen = avgDist > palmSize * 1.8;

        return {
          wrist,
          indexTip,
          middleTip,
          ringTip,
          pinkyTip,
          thumbTip,
          isOpen,
          opacity: 0, // Will be smoothed in render loop
        };
      });

      handDataRef.current = newHandData; 
    }
  }, [width, height]);

  // Initialize MediaPipe Hands
  useEffect(() => {
    let isActive = true;

    // Access global Hands class injected by script tag
    const Hands = (window as any).Hands;
    if (!Hands) {
      console.error("MediaPipe Hands not loaded");
      return;
    }

    const hands = new Hands({
      locateFile: (file: string) => {
        return `https://cdn.jsdelivr.net/npm/@mediapipe/hands/${file}`;
      },
    });

    hands.setOptions({
      maxNumHands: 2,
      modelComplexity: 1,
      minDetectionConfidence: 0.6,
      minTrackingConfidence: 0.5,
    });

    hands.onResults(onResults);

    // Custom loop to send frames to MediaPipe
    const processVideo = async () => {
      if (!isActive) return;

      if (
        webcamRef.current && 
        webcamRef.current.video && 
        webcamRef.current.video.readyState === 4
      ) {
        try {
          await hands.send({ image: webcamRef.current.video });
        } catch (error) {
          console.error("MediaPipe error:", error);
        }
      }

      if (isActive) {
        requestAnimationFrame(processVideo);
      }
    };

    processVideo();

    return () => {
      isActive = false;
      hands.close();
    };
  }, [onResults]);

  // Particle System Update
  const updateParticles = (ctx: CanvasRenderingContext2D, width: number, height: number) => {
    // Physics Update
    for (let i = particlesRef.current.length - 1; i >= 0; i--) {
      const p = particlesRef.current[i];
      p.x += p.vx;
      p.y += p.vy;
      p.vy -= 0.15; // Negative gravity (float up)
      p.vx *= 0.95; // Drag
      p.vy *= 0.98; // Drag
      p.size *= 0.97; // Shrink
      p.life -= 1;

      if (p.life <= 0 || p.size < 0.5) {
        particlesRef.current.splice(i, 1);
      } else {
        // Draw Particle
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);

        // High glow for plasma look
        ctx.shadowBlur = 15;
        ctx.shadowColor = p.color;
        ctx.fillStyle = p.color;

        // Opacity fade
        ctx.globalAlpha = p.life / p.maxLife;
        ctx.fill();
        ctx.globalAlpha = 1.0;
        ctx.shadowBlur = 0; // Reset
      }
    }
  };

  const spawnParticles = (x: number, y: number, intensity: number) => {
    const count = Math.floor(4 * intensity); // High density
    for (let i = 0; i < count; i++) {
      const angle = Math.random() * Math.PI * 2;
      const speed = Math.random() * 2;
      particlesRef.current.push({
        x: x + (Math.random() - 0.5) * 40,
        y: y + (Math.random() - 0.5) * 40,
        vx: Math.cos(angle) * speed,
        vy: Math.sin(angle) * speed - 1, // Initial upward drift
        life: 40 + Math.random() * 20,
        maxLife: 60,
        size: 4 + Math.random() * 6, // 4px to 10px
        color: Math.random() > 0.5 ? COLOR_PRIMARY : COLOR_SECONDARY,
      });
    }
  };

  // Main Render Loop
  const animate = useCallback((time: number) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Clear and set composite mode for "Energy" look
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.globalCompositeOperation = 'screen'; // or 'lighter'

    // Process Hands
    handDataRef.current.forEach((hand) => {
       // Let's just use isOpen boolean to drive intensity for responsiveness as requested.
       const intensity = hand.isOpen ? 1 : 0.1;

       if (intensity > 0.2) {
         const centerX = hand.middleTip.x;
         const centerY = hand.middleTip.y + 30; // Shift down to palm center roughly

         // Physics Rotation Variables
         const t = time * 0.001;

         // 1. Runes Ring (Rotate CW, Slow)
         ctx.globalAlpha = intensity;
         drawRuneRing(ctx, centerX, centerY, 120, t * 0.5);

         // 2. Hexagram (Rotate CCW, Medium)
         drawSacredGeometry(ctx, centerX, centerY, 90, -t * 1.5);

         // 3. Square (Rotate CW, Fast)
         drawSquareLayer(ctx, centerX, centerY, 65, t * 2.5);

         // 4. Pentagram (Pulse)
         const pulse = Math.sin(time * 0.005) * 0.5 + 0.5;
         drawPentagram(ctx, centerX, centerY, 40, t, pulse);

         // Spawn Particles
         spawnParticles(centerX, centerY, intensity);
       }
    });

    // Process Particles
    updateParticles(ctx, canvas.width, canvas.height);

    requestRef.current = requestAnimationFrame(animate);
  }, []);

  useEffect(() => {
    requestRef.current = requestAnimationFrame(animate);
    return () => {
      if (requestRef.current) cancelAnimationFrame(requestRef.current);
    };
  }, [animate]);

  return (
    <div className="relative w-full h-full bg-black overflow-hidden flex items-center justify-center">
        {/* Webcam is hidden but active for processing */}
        <Webcam
          ref={webcamRef}
          audio={false}
          width={width}
          height={height}
          mirrored={true}
          className="absolute opacity-0 pointer-events-none" 
        />

        {/* Visible Webcam Feedback */}
        <Webcam
          audio={false}
          width={width}
          height={height}
          mirrored={true}
          className="absolute top-0 left-0 w-full h-full object-cover opacity-80"
        />

        <canvas
          ref={canvasRef}
          width={width}
          height={height}
          className="absolute top-0 left-0 w-full h-full object-cover z-10"
        />

        <div className="absolute bottom-10 left-0 w-full text-center pointer-events-none z-20">
          <p className="text-amber-400 font-mono text-sm opacity-80 tracking-widest uppercase glow-text">
            Open hand to Summon • Close to Dispel
          </p>
        </div>

        <style>{`
          .glow-text {
            text-shadow: 0 0 10px #FFA014;
          }
        `}</style>
    </div>
  );
};

export default MagicOverlay;

export type ElementType = 'NEUTRAL' | 'FIRE' | 'WATER' | 'THUNDER' | 'WIND';

export interface Point {
  x: number;
  y: number;
  z?: number;
}

export interface Particle {
  x: number;
  y: number;
  vx: number;
  vy: number;
  life: number;
  maxLife: number;
  size: number;
  color: string;
  element: ElementType; // Particle behavior depends on this
}

export interface HandData {
  wrist: Point;
  indexTip: Point;
  middleTip: Point;
  ringTip: Point;
  pinkyTip: Point;
  thumbTip: Point;
  indexBase: Point; // Added for gesture detection
  middleBase: Point;
  ringBase: Point;
  pinkyBase: Point;
  isOpen: boolean;
  gesture: ElementType; // Detected gesture/element
  opacity: number;
}

export interface Theme {
  primary: string;
  secondary: string;
  core: string;
  shadow: string;
}

import { Point, ElementType, Theme } from '../types';

// Element Themes
export const THEMES: Record<ElementType, Theme> = {
  NEUTRAL: { primary: '#FFA014', secondary: '#FFC832', core: '#FFFFFF', shadow: '#FFA014' }, // Amber
  FIRE: { primary: '#FF4500', secondary: '#FF8C00', core: '#FFFF00', shadow: '#FF0000' }, // Red/Orange
  WATER: { primary: '#1E90FF', secondary: '#00BFFF', core: '#E0FFFF', shadow: '#0000FF' }, // Blue
  THUNDER: { primary: '#9400D3', secondary: '#FF00FF', core: '#FFFFE0', shadow: '#4B0082' }, // Purple/Lightning
  WIND: { primary: '#00FA9A', secondary: '#98FB98', core: '#F0FFF0', shadow: '#006400' }, // Green/Mint
};

// Layer 1: Runes Ring
export const drawRuneRing = (
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  radius: number,
  rotation: number,
  theme: Theme
) => {
  const segments = 24;
  ctx.strokeStyle = theme.primary;
  ctx.lineWidth = 2;

  // Outer circle
  ctx.beginPath();
  ctx.arc(x, y, radius, 0, Math.PI * 2);
  ctx.stroke();

  // Inner border for runes
  ctx.beginPath();
  ctx.arc(x, y, radius * 0.85, 0, Math.PI * 2);
  ctx.stroke();

  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(rotation);

  for (let i = 0; i < segments; i++) {
    const angle = (Math.PI * 2) / segments;
    ctx.save();
    ctx.rotate(i * angle);
    ctx.translate(radius * 0.925, 0); 

    // Procedural Rune Glyph
    const seed = i * 13.37;
    const size = radius * 0.05;

    ctx.beginPath();
    ctx.moveTo(-size, -size + Math.sin(seed) * size);
    ctx.lineTo(size, size - Math.cos(seed) * size);
    ctx.moveTo(-size, size);
    ctx.lineTo(size + Math.sin(seed * 2) * 5, -size);
    if (i % 3 === 0) ctx.rect(-size / 2, -size / 2, size, size);

    ctx.strokeStyle = theme.secondary;
    ctx.lineWidth = 1.5;
    ctx.stroke();

    ctx.restore();
  }
  ctx.restore();
};

// Layer 2: Sacred Geometry (Hexagram/Triangle)
export const drawSacredGeometry = (
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  radius: number,
  rotation: number,
  theme: Theme
) => {
  ctx.strokeStyle = theme.primary;
  ctx.lineWidth = 3;
  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(rotation);

  // Triangle 1
  ctx.beginPath();
  for (let i = 0; i < 3; i++) {
    const theta = (i * 2 * Math.PI) / 3;
    const px = radius * Math.cos(theta);
    const py = radius * Math.sin(theta);
    if (i === 0) ctx.moveTo(px, py);
    else ctx.lineTo(px, py);
  }
  ctx.closePath();
  ctx.stroke();

  // Triangle 2 (Inverted)
  ctx.beginPath();
  for (let i = 0; i < 3; i++) {
    const theta = (i * 2 * Math.PI) / 3 + Math.PI; 
    const px = radius * Math.cos(theta);
    const py = radius * Math.sin(theta);
    if (i === 0) ctx.moveTo(px, py);
    else ctx.lineTo(px, py);
  }
  ctx.closePath();
  ctx.stroke();

  // Inner Circle
  ctx.beginPath();
  ctx.arc(0, 0, radius * 0.5, 0, Math.PI * 2);
  ctx.strokeStyle = theme.secondary;
  ctx.lineWidth = 1;
  ctx.stroke();

  ctx.restore();
};

// Layer 3: Rotating Square (Diamond)
export const drawSquareLayer = (
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  radius: number,
  rotation: number,
  theme: Theme
) => {
  ctx.strokeStyle = theme.secondary;
  ctx.lineWidth = 4;

  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(rotation);

  ctx.beginPath();
  const size = radius;
  ctx.rect(-size / 2, -size / 2, size, size);
  ctx.stroke();

  // Decorative corners
  ctx.fillStyle = theme.core;
  const cornerSize = 4;
  ctx.fillRect(-size / 2 - cornerSize, -size / 2 - cornerSize, cornerSize * 2, cornerSize * 2);
  ctx.fillRect(size / 2 - cornerSize, -size / 2 - cornerSize, cornerSize * 2, cornerSize * 2);
  ctx.fillRect(size / 2 - cornerSize, size / 2 - cornerSize, cornerSize * 2, cornerSize * 2);
  ctx.fillRect(-size / 2 - cornerSize, size / 2 - cornerSize, cornerSize * 2, cornerSize * 2);

  ctx.restore();
};

// Layer 4: Pulsing Pentagram
export const drawPentagram = (
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  radius: number,
  rotation: number,
  pulse: number,
  theme: Theme
) => {
  const r = radius * (0.8 + pulse * 0.2); 
  ctx.strokeStyle = theme.core;
  ctx.lineWidth = 2 + pulse * 2;
  ctx.shadowBlur = 10 + pulse * 10;
  ctx.shadowColor = theme.shadow;

  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(rotation);

  ctx.beginPath();
  for (let i = 0; i < 5; i++) {
    const theta = (i * 4 * Math.PI) / 5 - Math.PI / 2;
    const px = r * Math.cos(theta);
    const py = r * Math.sin(theta);
    if (i === 0) ctx.moveTo(px, py);
    else ctx.lineTo(px, py);
  }
  ctx.closePath();
  ctx.stroke();

  ctx.shadowBlur = 0; 
  ctx.restore();
};

import React, { useEffect, useRef, useCallback, useState } from 'react';
import Webcam from 'react-webcam';
import { Particle, HandData, ElementType } from '../types';
import { 
  drawRuneRing, 
  drawSacredGeometry, 
  drawSquareLayer, 
  drawPentagram,
  THEMES
} from '../utils/geometry';

interface MagicOverlayProps {
  width: number;
  height: number;
}

const MagicOverlay: React.FC<MagicOverlayProps> = ({ width, height }) => {
  const webcamRef = useRef<Webcam>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();
  const particlesRef = useRef<Particle[]>([]);
  const handDataRef = useRef<HandData[]>([]);
  const [currentElement, setCurrentElement] = useState<ElementType>('NEUTRAL');

  // Gesture Recognition Logic
  const detectGesture = (
    wrist: any, 
    indexTip: any, indexBase: any, 
    middleTip: any, middleBase: any, 
    ringTip: any, ringBase: any, 
    pinkyTip: any, pinkyBase: any
  ): ElementType => {
    // 1. Check for WATER (Rain) - Hand pointing down
    // Wrist is higher (smaller y) than fingers
    if (wrist.y < indexTip.y && wrist.y < middleTip.y) {
      return 'WATER';
    }

    // Finger extensions (using distance from base to tip)
    const isExtended = (tip: any, base: any) => {
        // Simple distance check, if tip is far from base
        return Math.hypot(tip.x - base.x, tip.y - base.y) > 30; // Threshold
    };

    // Check if fingers are curled (fist)
    // Curled means tip is close to base or below base relative to palm direction
    const dIndex = Math.hypot(indexTip.x - indexBase.x, indexTip.y - indexBase.y);
    const dMiddle = Math.hypot(middleTip.x - middleBase.x, middleTip.y - middleBase.y);
    const dRing = Math.hypot(ringTip.x - ringBase.x, ringTip.y - ringBase.y);
    const dPinky = Math.hypot(pinkyTip.x - pinkyBase.x, pinkyTip.y - pinkyBase.y);

    // Threshold for curled finger (tunable)
    const curledThresh = 40; 
    const isFist = dIndex < curledThresh && dMiddle < curledThresh && dRing < curledThresh && dPinky < curledThresh;

    if (isFist) return 'THUNDER';

    // Check for WIND (Peace Sign / Victory)
    // Index and Middle extended, Ring and Pinky curled
    const isPeace = dIndex > curledThresh && dMiddle > curledThresh && dRing < curledThresh && dPinky < curledThresh;
    if (isPeace) return 'WIND';

    // Default: Open Hand Up -> FIRE
    return 'FIRE';
  };

  // Handle MediaPipe Results
  const onResults = useCallback((results: any) => {
    const videoWidth = webcamRef.current?.video?.videoWidth || width;
    const videoHeight = webcamRef.current?.video?.videoHeight || height;

    if (results.multiHandLandmarks) {
      let activeType: ElementType = 'NEUTRAL';

      const newHandData: HandData[] = results.multiHandLandmarks.map((landmarks: any[]) => {
        const mapPt = (p: any) => ({ x: (1 - p.x) * videoWidth, y: p.y * videoHeight });

        const wrist = mapPt(landmarks[0]);
        const indexTip = mapPt(landmarks[8]);
        const indexBase = mapPt(landmarks[5]);
        const middleTip = mapPt(landmarks[12]);
        const middleBase = mapPt(landmarks[9]);
        const ringTip = mapPt(landmarks[16]);
        const ringBase = mapPt(landmarks[13]);
        const pinkyTip = mapPt(landmarks[20]);
        const pinkyBase = mapPt(landmarks[17]);
        const thumbTip = mapPt(landmarks[4]);

        const gesture = detectGesture(
            wrist, 
            indexTip, indexBase, 
            middleTip, middleBase, 
            ringTip, ringBase, 
            pinkyTip, pinkyBase
        );

        if (gesture !== 'NEUTRAL') activeType = gesture;

        return {
          wrist,
          indexTip, middleTip, ringTip, pinkyTip, thumbTip,
          indexBase, middleBase, ringBase, pinkyBase,
          isOpen: gesture !== 'THUNDER', // Simplified
          gesture,
          opacity: 1,
        };
      });

      handDataRef.current = newHandData;
      // Debounce logic could go here, but for responsiveness we update directly
      if (newHandData.length > 0) {
        setCurrentElement(activeType);
      } else {
        setCurrentElement('NEUTRAL');
      }
    } else {
      handDataRef.current = [];
      setCurrentElement('NEUTRAL');
    }
  }, [width, height]);

  // Initialize MediaPipe
  useEffect(() => {
    let isActive = true;
    const Hands = (window as any).Hands;
    if (!Hands) return;

    const hands = new Hands({
      locateFile: (file: string) => `https://cdn.jsdelivr.net/npm/@mediapipe/hands/${file}`,
    });

    hands.setOptions({
      maxNumHands: 2,
      modelComplexity: 1,
      minDetectionConfidence: 0.6,
      minTrackingConfidence: 0.5,
    });

    hands.onResults(onResults);

    const processVideo = async () => {
      if (!isActive) return;
      if (webcamRef.current?.video?.readyState === 4) {
        try {
          await hands.send({ image: webcamRef.current.video });
        } catch (e) { console.error(e); }
      }
      if (isActive) requestAnimationFrame(processVideo);
    };
    processVideo();

    return () => {
      isActive = false;
      hands.close();
    };
  }, [onResults]);

  // Elemental Physics
  const updateParticles = (ctx: CanvasRenderingContext2D, width: number, height: number, centerX: number, centerY: number) => {
    for (let i = particlesRef.current.length - 1; i >= 0; i--) {
      const p = particlesRef.current[i];

      // Default Drag
      p.vx *= 0.95;
      p.vy *= 0.95;

      switch (p.element) {
        case 'FIRE':
          p.vy -= 0.3; // Rise
          p.size *= 0.96;
          p.vx += (Math.random() - 0.5) * 0.5; // Turbulent
          break;
        case 'WATER':
          p.vy += 0.4; // Gravity
          p.y += p.vy; // Apply gravity more aggressively
          if (p.y > height) p.life = 0; // Kill at bottom
          p.size *= 0.99;
          break;
        case 'WIND':
            // Spiral around center
            const dx = p.x - centerX;
            const dy = p.y - centerY;
            const dist = Math.sqrt(dx*dx + dy*dy);
            const angle = Math.atan2(dy, dx);
            const speed = 5;
            // Tangential force
            p.vx += Math.cos(angle + Math.PI/2) * 1; 
            p.vy += Math.sin(angle + Math.PI/2) * 1;
            // Centripetal force (keep in circle)
            p.vx -= (dx / dist) * 0.5; 
            p.vy -= (dy / dist) * 0.5;
            p.size *= 0.98;
            break;
        case 'THUNDER':
            // Erratic movement
            p.vx += (Math.random() - 0.5) * 4;
            p.vy += (Math.random() - 0.5) * 4;
            p.size = Math.random() * 3 + 1; // Flicker size
            break;
        default:
          p.vy -= 0.1;
          p.size *= 0.97;
      }

      p.x += p.vx;
      p.y += p.vy;
      p.life -= 1;

      if (p.life <= 0 || p.size < 0.2) {
        particlesRef.current.splice(i, 1);
      } else {
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
        ctx.shadowBlur = p.element === 'THUNDER' ? 20 : 10;
        ctx.shadowColor = p.color;
        ctx.fillStyle = p.color;
        ctx.globalAlpha = Math.min(1, p.life / 20);
        ctx.fill();
        ctx.globalAlpha = 1.0;
        ctx.shadowBlur = 0;
      }
    }
  };

  const spawnParticles = (x: number, y: number, element: ElementType) => {
    const theme = THEMES[element];
    const count = element === 'THUNDER' ? 2 : 5; 

