  const detectGesture = (
    wrist: any, 
    indexTip: any, indexBase: any, 
    middleTip: any, middleBase: any, 
    ringTip: any, ringBase: any, 
    pinkyTip: any, pinkyBase: any
  ): ElementType => {
    // Calculate Palm Size (Reference Unit)
    // Distance from Wrist to Middle Finger Base (MCP)
    const palmSize = Math.hypot(middleBase.x - wrist.x, middleBase.y - wrist.y);

    // 1. Check for WATER (Rain) - Hand pointing down
    // Wrist is significantly higher (smaller y) than middle finger base
    // And palm is vertical-ish
    if (wrist.y < middleBase.y - palmSize * 0.5) {
       // Also check if fingers are somewhat extended or relaxed down
       return 'WATER';
    }

    // Helper: Is finger extended?
    // Distance from tip to base > threshold relative to palm size
    const isExtended = (tip: any, base: any) => {
        const len = Math.hypot(tip.x - base.x, tip.y - base.y);
        return len > palmSize * 0.8; 
    };

    // Check finger states
    const indexOpen = isExtended(indexTip, indexBase);
    const middleOpen = isExtended(middleTip, middleBase);
    const ringOpen = isExtended(ringTip, ringBase);
    const pinkyOpen = isExtended(pinkyTip, pinkyBase);

    // THUNDER: Fist (All fingers closed)
    if (!indexOpen && !middleOpen && !ringOpen && !pinkyOpen) {
        return 'THUNDER';
    }

    // WIND: Peace Sign (Index & Middle Open, Ring & Pinky Closed)
    if (indexOpen && middleOpen && !ringOpen && !pinkyOpen) {
        return 'WIND';
    }

    // FIRE: Open Hand (All/Most fingers open) pointing up
    // Default fallback for open hand
    if (indexOpen && middleOpen && ringOpen) {
        return 'FIRE';
    }

    return 'NEUTRAL'; // Transition state
  };

