    for (let i = particlesRef.current.length - 1; i >= 0; i--) {
      const p = particlesRef.current[i];

      // Default Drag
      p.vx *= 0.95;
      p.vy *= 0.95;

      switch (p.element) {
        case 'FIRE':
          p.vy -= 0.3; // Rise
          p.size *= 0.96;
          p.vx += (Math.random() - 0.5) * 0.5; // Turbulent
          break;
        case 'WATER':
          p.vy += 0.4; // Gravity
          p.y += p.vy; // Apply gravity more aggressively
          if (p.y > height) p.life = 0; // Kill at bottom
          p.size *= 0.99;
          break;
        case 'WIND':
            // Spiral around center
            const dx = p.x - centerX;
            const dy = p.y - centerY;
            const dist = Math.sqrt(dx*dx + dy*dy) + 0.1; // Avoid divide by zero
            const angle = Math.atan2(dy, dx);
            // Tangential force
            p.vx += Math.cos(angle + Math.PI/2) * 1.5; 
            p.vy += Math.sin(angle + Math.PI/2) * 1.5;
            // Centripetal force (keep in circle)
            p.vx -= (dx / dist) * 0.8; 
            p.vy -= (dy / dist) * 0.8;
            p.size *= 0.98;
            break;
        case 'THUNDER':
            // Erratic movement
            p.vx += (Math.random() - 0.5) * 6;
            p.vy += (Math.random() - 0.5) * 6;
            p.size = Math.random() * 4 + 1; // Flicker size
            break;
        default:
          p.vy -= 0.1;
          p.size *= 0.97;
      }

      p.x += p.vx;
      p.y += p.vy;
      p.life -= 1;

      if (p.life <= 0 || p.size < 0.2) {
        particlesRef.current.splice(i, 1);
      } else {
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
        ctx.shadowBlur = p.element === 'THUNDER' ? 20 : 10;
        ctx.shadowColor = p.color;
        ctx.fillStyle = p.color;
        ctx.globalAlpha = Math.min(1, p.life / 20);
        ctx.fill();
        ctx.globalAlpha = 1.0;
        ctx.shadowBlur = 0;
      }
    }
  };

  const spawnParticles = (x: number, y: number, element: ElementType) => {
    const theme = THEMES[element];
    const count = element === 'THUNDER' ? 2 : 5; 

    for (let i = 0; i < count; i++) {
      const angle = Math.random() * Math.PI * 2;
