            </div>
            <div className="text-xs text-white opacity-70 space-y-1">
                <p>✋ Palm Up: FIRE</p>
                <p>👇 Palm Down: WATER</p>
                <p>👊 Fist: THUNDER</p>
                <p>✌️ Victory: WIND</p>
            </div>
        </div>
