        return 'THUNDER';
    }

    // 2. WIND: Peace/Victory (Index & Middle Open only)
    if (indexOpen && middleOpen && !ringOpen && !pinkyOpen) {
        return 'WIND';
    }

    // 3. WATER: Hand pointing down (and generally open)
    if (isPointingDown && (indexOpen || middleOpen)) {
        return 'WATER';
    }

    // 4. FIRE: Hand pointing up, Fingers Open
    if (!isPointingDown && indexOpen && middleOpen && ringOpen) {
        return 'FIRE';
    }

    return 'NEUTRAL';
  };

  const drawSkeleton = (ctx: CanvasRenderingContext2D, hand: HandData) => {
      ctx.strokeStyle = "rgba(255, 255, 255, 0.3)";
      ctx.lineWidth = 1;
      ctx.fillStyle = "rgba(255, 255, 255, 0.5)";

      const points = [
          hand.wrist, 
          hand.indexBase, hand.indexTip,
          hand.middleBase, hand.middleTip,
          hand.ringBase, hand.ringTip,
          hand.pinkyBase, hand.pinkyTip,
          hand.thumbTip
      ];

      // Simple connections for debug
      ctx.beginPath();
      ctx.moveTo(hand.wrist.x, hand.wrist.y);
      ctx.lineTo(hand.indexBase.x, hand.indexBase.y);
      ctx.lineTo(hand.indexTip.x, hand.indexTip.y);
      ctx.stroke();

      ctx.beginPath();
      ctx.moveTo(hand.wrist.x, hand.wrist.y);
      ctx.lineTo(hand.middleBase.x, hand.middleBase.y);
      ctx.lineTo(hand.middleTip.x, hand.middleTip.y);
      ctx.stroke();

      ctx.beginPath();
      ctx.moveTo(hand.wrist.x, hand.wrist.y);
      ctx.lineTo(hand.pinkyBase.x, hand.pinkyBase.y);
      ctx.lineTo(hand.pinkyTip.x, hand.pinkyTip.y);
      ctx.stroke();

      points.forEach(p => {
          ctx.beginPath();
          ctx.arc(p.x, p.y, 2, 0, Math.PI * 2);
          ctx.fill();
      });
  };

  // Handle MediaPipe Results
  const onResults = useCallback((results: any) => {
    const videoWidth = webcamRef.current?.video?.videoWidth || width;
    const videoHeight = webcamRef.current?.video?.videoHeight || height;

    if (results.multiHandLandmarks && results.multiHandLandmarks.length > 0) {
      let activeType: ElementType = 'NEUTRAL';
      setDebugInfo(`Hands Detected: ${results.multiHandLandmarks.length}`);

      const newHandData: HandData[] = results.multiHandLandmarks.map((landmarks: any[]) => {
        const gesture = detectGesture(landmarks, videoWidth, videoHeight);
        if (gesture !== 'NEUTRAL') activeType = gesture;

        // Map for rendering
        const mapPt = (idx: number) => ({ x: (1 - landmarks[idx].x) * videoWidth, y: landmarks[idx].y * videoHeight });

        return {
          wrist: mapPt(0),
          indexTip: mapPt(8),
          middleTip: mapPt(12),
          ringTip: mapPt(16),
          pinkyTip: mapPt(20),
          thumbTip: mapPt(4),
          indexBase: mapPt(5),
          middleBase: mapPt(9),
          ringBase: mapPt(13),
          pinkyBase: mapPt(17),
          isOpen: gesture !== 'THUNDER', 
          gesture,
          opacity: 1,
        };
      });

      handDataRef.current = newHandData;

      // Check for gesture change to trigger highlight
      if (activeType !== prevElementRef.current) {
          if (activeType !== 'NEUTRAL') {
              highlightRef.current = 1.0; 
              playChime(activeType); 
          }
          prevElementRef.current = activeType;
      }

      if (activeType !== 'NEUTRAL') {
          setCurrentElement(activeType);
      } else {
         setCurrentElement('NEUTRAL');
      }
    } else {
      handDataRef.current = [];
      setDebugInfo("No Hands Detected");
      if (prevElementRef.current !== 'NEUTRAL') {
          prevElementRef.current = 'NEUTRAL';
      }
      setCurrentElement('NEUTRAL');
    }
  }, [width, height, playChime]);

  // Initialize MediaPipe
  useEffect(() => {
    let hands: any = null;
    let isActive = true;
    let frameId: number;
    let lastVideoTime = -1;

    const initHands = async () => {
       if (!(window as any).Hands) {
           console.log("Waiting for MediaPipe Hands script...");
           setTimeout(initHands, 500);
           return;
       }

       console.log("Initializing MediaPipe Hands...");
       hands = new (window as any).Hands({
         locateFile: (file: string) => `https://cdn.jsdelivr.net/npm/@mediapipe/hands@0.4.1675469240/${file}`,
       });

       hands.setOptions({
         maxNumHands: 2,
         modelComplexity: 1,
         minDetectionConfidence: 0.5, // Lowered for better tracking
         minTrackingConfidence: 0.5,
       });

       hands.onResults(onResults);
       setIsModelLoaded(true);

       const processVideo = async () => {
         if (!isActive) return;
         if (webcamRef.current && webcamRef.current.video && webcamRef.current.video.readyState === 4) {
             const video = webcamRef.current.video;
             // Only send if time changed to avoid over-processing
             if (video.currentTime !== lastVideoTime) {
                 lastVideoTime = video.currentTime;
                 try {
                    await hands.send({ image: video });
                 } catch (e) { 
                    console.error("MediaPipe send error:", e); 
                 }
             }
         }
         frameId = requestAnimationFrame(processVideo);
       };
       processVideo();
    };

    initHands();

    return () => {
      isActive = false;
      if (frameId) cancelAnimationFrame(frameId);
      if (hands) hands.close();
    };
  }, [onResults]);

  // Elemental Physics and Rendering
  const updateParticles = (ctx: CanvasRenderingContext2D, width: number, height: number, centerX: number, centerY: number) => {
    for (let i = particlesRef.current.length - 1; i >= 0; i--) {
      const p = particlesRef.current[i];
      p.vx *= 0.95;
      p.vy *= 0.95;

      switch (p.element) {
        case 'FIRE':
          p.vy -= 0.3; 
          p.size *= 0.96;
          p.vx += (Math.random() - 0.5) * 0.5;
          break;
        case 'WATER':
          p.vy += 0.4;
          p.y += p.vy;
          if (p.y > height) p.life = 0;
          p.size *= 0.99;
          break;
        case 'WIND':
            const dx = p.x - centerX;
            const dy = p.y - centerY;
            const dist = Math.sqrt(dx*dx + dy*dy) + 0.1;
            const angle = Math.atan2(dy, dx);
            p.vx += Math.cos(angle + Math.PI/2) * 1.5; 
            p.vy += Math.sin(angle + Math.PI/2) * 1.5;
            p.vx -= (dx / dist) * 0.8; 
            p.vy -= (dy / dist) * 0.8;
            p.size *= 0.98;
            break;
        case 'THUNDER':
            p.vx += (Math.random() - 0.5) * 6;
            p.vy += (Math.random() - 0.5) * 6;
            p.size = Math.random() * 4 + 1;
            break;
        default:
          p.vy -= 0.1;
          p.size *= 0.97;
      }

      p.x += p.vx;
      p.y += p.vy;
      p.life -= 1;

      if (p.life <= 0 || p.size < 0.2) {
        particlesRef.current.splice(i, 1);
      } else {
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
        ctx.shadowBlur = p.element === 'THUNDER' ? 20 : 10;
        ctx.shadowColor = p.color;
        ctx.fillStyle = p.color;
        ctx.globalAlpha = Math.min(1, p.life / 20);
        ctx.fill();
        ctx.globalAlpha = 1.0;
        ctx.shadowBlur = 0;
      }
    }
  };

  const spawnParticles = (x: number, y: number, element: ElementType) => {
    const theme = THEMES[element];
    const count = element === 'THUNDER' ? 2 : 5; 

    for (let i = 0; i < count; i++) {
      const angle = Math.random() * Math.PI * 2;
      const speed = Math.random() * 3;

      let vx = Math.cos(angle) * speed;
      let vy = Math.sin(angle) * speed;
      let life = 40 + Math.random() * 20;
      let size = 3 + Math.random() * 5;

      if (element === 'WATER') {
        vx = (Math.random() - 0.5) * 2;
        vy = 0; 
        life = 60;
      }

      particlesRef.current.push({
        x: x + (Math.random() - 0.5) * 30,
        y: y + (Math.random() - 0.5) * 30,
        vx,
        vy,
        life,
        maxLife: life,
        size,
        color: Math.random() > 0.5 ? theme.primary : theme.secondary,
        element
      });
    }
  };

  // Main Render Loop
  const animate = useCallback((time: number) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (highlightRef.current > 0.01) {
        highlightRef.current *= 0.9;
    } else {
        highlightRef.current = 0;
    }
    const flash = highlightRef.current;

    ctx.globalCompositeOperation = 'screen'; 

    let lastCenterX = width / 2;
    let lastCenterY = height / 2;

    handDataRef.current.forEach((hand) => {
       // DEBUG: Draw Skeleton to verify tracking
       drawSkeleton(ctx, hand);

       const element = hand.gesture;
       const theme = THEMES[element];
       const intensity = 1;

       const centerX = hand.middleBase.x; // Use Base for more stability
       const centerY = hand.middleBase.y; 
       lastCenterX = centerX;
       lastCenterY = centerY;

       const t = time * 0.001;
       let rotSpeed = 1;
       if (element === 'WIND') rotSpeed = 3;
       if (element === 'WATER') rotSpeed = 0.5;
       if (element === 'THUNDER') rotSpeed = 5 * Math.random();

       ctx.globalAlpha = intensity;

       if (element !== 'NEUTRAL') {
           if (flash > 0.05) {
               ctx.save();
               ctx.translate(centerX, centerY);
               const waveSize = 120 + (1 - flash) * 100;
               ctx.beginPath();
               ctx.arc(0, 0, waveSize, 0, Math.PI * 2);
               ctx.lineWidth = 10 * flash;
               ctx.strokeStyle = theme.core;
               ctx.shadowBlur = 20;
               ctx.shadowColor = theme.secondary;
               ctx.globalAlpha = flash;
               ctx.stroke();
               ctx.restore();

               ctx.save();
               ctx.shadowBlur = 30 * flash;
               ctx.shadowColor = theme.core;
               ctx.globalAlpha = flash; 
               drawRuneRing(ctx, centerX, centerY, 120, t * 0.5 * rotSpeed, theme);
               ctx.restore();
           }

           drawRuneRing(ctx, centerX, centerY, 120, t * 0.5 * rotSpeed, theme);
           drawSacredGeometry(ctx, centerX, centerY, 90, -t * 1.5 * rotSpeed, theme);
           drawSquareLayer(ctx, centerX, centerY, 65, t * 2.5 * rotSpeed, theme);

           const pulse = element === 'THUNDER' ? Math.random() : Math.sin(time * 0.005) * 0.5 + 0.5;
           drawPentagram(ctx, centerX, centerY, 40, t * rotSpeed, pulse, theme);

           spawnParticles(centerX, centerY, element);
       } else {
           if (Math.random() > 0.8) spawnParticles(centerX, centerY, 'NEUTRAL');
           ctx.globalAlpha = 0.3;
           drawRuneRing(ctx, centerX, centerY, 50, t * 0.2, theme);
       }
    });

    updateParticles(ctx, canvas.width, canvas.height, lastCenterX, lastCenterY);
    requestRef.current = requestAnimationFrame(animate);
  }, [width, height]);

  useEffect(() => {
    requestRef.current = requestAnimationFrame(animate);
    return () => { if (requestRef.current) cancelAnimationFrame(requestRef.current); };
  }, [animate]);

  return (
    <div className="relative w-full h-full bg-black overflow-hidden flex items-center justify-center">
        <Webcam
          ref={webcamRef}
          audio={false}
          width={width}
          height={height}
          mirrored={true}
          screenshotFormat="image/jpeg"
          className="absolute opacity-0 pointer-events-none" 
        />
        <Webcam
          audio={false}
          width={width}
          height={height}
          mirrored={true}
          className="absolute top-0 left-0 w-full h-full object-cover opacity-80"
        />
        <canvas
          ref={canvasRef}
          width={width}
          height={height}
          className="absolute top-0 left-0 w-full h-full object-cover z-10"
        />

        {!isModelLoaded && (
            <div className="absolute inset-0 flex items-center justify-center bg-black bg-opacity-80 z-50">
                <div className="text-amber-500 font-mono text-xl animate-pulse">
                    Summoning Grimoire... (Loading Models)
                </div>
            </div>
        )}

        {/* HUD with Debug Info */}
        <div className="absolute top-4 right-4 text-right z-20 font-mono pointer-events-none">
            <div className={`text-2xl font-bold mb-2 tracking-widest transition-all duration-300 ${
                highlightRef.current > 0.1 ? 'scale-110' : ''
            } ${
                currentElement === 'FIRE' ? 'text-orange-500' :
                currentElement === 'WATER' ? 'text-blue-500' :
                currentElement === 'WIND' ? 'text-green-400' :
                currentElement === 'THUNDER' ? 'text-purple-500' : 'text-amber-500'
            }`}>
                ELEMENT: {currentElement}
            </div>
            <div className="text-xs text-white opacity-70 space-y-1 mb-2">
                <p>Status: {debugInfo}</p>
            </div>
            <div className="text-xs text-white opacity-70 space-y-1">
                <p>✋ Palm Up: FIRE</p>
                <p>👇 Palm Down: WATER</p>
                <p>👊 Fist: THUNDER</p>
                <p>✌️ Victory: WIND</p>
            </div>
        </div>
    </div>
  );
};

export default MagicOverlay;

import React, { useEffect, useRef, useCallback, useState } from 'react';
import Webcam from 'react-webcam';
import { Particle, HandData, ElementType, Theme } from '../types';
import { 
  drawRuneRing, 
  drawSacredGeometry, 
  drawSquareLayer, 
  drawPentagram,
  THEMES
} from '../utils/geometry';

interface MagicOverlayProps {
  width: number;
  height: number;
}

const COMBO_THEMES: Record<string, Theme> = {
  'BLIZZARD': { primary: '#00FFFF', secondary: '#E0FFFF', core: '#FFFFFF', shadow: '#008B8B' },
  'PLASMA': { primary: '#FF00FF', secondary: '#9400D3', core: '#FFFFFF', shadow: '#4B0082' },
  'STEAM': { primary: '#B0C4DE', secondary: '#F0F8FF', core: '#FFFFFF', shadow: '#778899' },
  'TEMPEST': { primary: '#000080', secondary: '#4169E1', core: '#00BFFF', shadow: '#191970' },
  'INFERNO': { primary: '#8B0000', secondary: '#FF4500', core: '#FFFF00', shadow: '#FF0000' },
  'VOID': { primary: '#000000', secondary: '#4B0082', core: '#FFFFFF', shadow: '#9400D3' },
};

const getCombo = (g1: ElementType, g2: ElementType): string | null => {
    const sorted = [g1, g2].sort().join('_');
    switch(sorted) {
        case 'WATER_WIND': return 'BLIZZARD';
        case 'FIRE_WIND': return 'PLASMA';
        case 'FIRE_WATER': return 'STEAM';
        case 'THUNDER_WATER': return 'TEMPEST';
        case 'FIRE_FIRE': return 'INFERNO';
        case 'THUNDER_THUNDER': return 'VOID';
        default: return null;
    }
};

const MagicOverlay: React.FC<MagicOverlayProps> = ({ width, height }) => {
  const webcamRef = useRef<Webcam>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>(0);
  const particlesRef = useRef<Particle[]>([]);
  const handDataRef = useRef<HandData[]>([]);
  const [currentElement, setCurrentElement] = useState<string>('NEUTRAL');
  const [isModelLoaded, setIsModelLoaded] = useState(false);
  const [debugInfo, setDebugInfo] = useState<string>("Initializing...");

  // Visual Feedback State
  const highlightRef = useRef<number>(0);
  const prevElementRef = useRef<string>('NEUTRAL');
  const activeComboRef = useRef<string | null>(null);

  // Audio Context
  const audioContextRef = useRef<AudioContext | null>(null);

  // Initialize Audio
  useEffect(() => {
    const AudioContextClass = (window as any).AudioContext || (window as any).webkitAudioContext;
    if (AudioContextClass) {
        audioContextRef.current = new AudioContextClass();
    }
  }, []);

  const playChime = useCallback((element: string) => {
    if (!audioContextRef.current) return;
    const ctx = audioContextRef.current;
    if (ctx.state === 'suspended') {
        ctx.resume().catch(console.error);
    }

    const osc = ctx.createOscillator();
    const gain = ctx.createGain();

    osc.connect(gain);
    gain.connect(ctx.destination);

    let freq = 440;
    let type: OscillatorType = 'sine';
    let duration = 0.5;

    // Sound Design per Element/Combo
    switch (element) {
        case 'FIRE': 
        case 'INFERNO':
            freq = 220; 
            type = 'sawtooth'; 
            osc.frequency.setValueAtTime(freq, ctx.currentTime);
            osc.frequency.exponentialRampToValueAtTime(freq * (element === 'INFERNO' ? 3 : 2), ctx.currentTime + 0.3);
            break;
        case 'WATER': 
        case 'STEAM':
            freq = 600; 
            type = 'sine';
            osc.frequency.setValueAtTime(freq, ctx.currentTime);
            osc.frequency.exponentialRampToValueAtTime(200, ctx.currentTime + 0.2);
            duration = 0.3;
            break;
        case 'THUNDER': 
        case 'TEMPEST':
        case 'VOID':
            freq = 150; 
            type = 'square';
            osc.frequency.setValueAtTime(freq, ctx.currentTime);
            osc.frequency.linearRampToValueAtTime(freq * 0.8, ctx.currentTime + 0.1);
            if (element === 'VOID') {
                const lfo = ctx.createOscillator();
                lfo.frequency.value = 50;
                lfo.connect(gain.gain);
                lfo.start();
                lfo.stop(ctx.currentTime + duration);
            }
            break;
        case 'WIND': 
        case 'BLIZZARD':
        case 'PLASMA':
            freq = 880; 
            type = 'triangle';
            osc.frequency.setValueAtTime(freq, ctx.currentTime);
            if (element === 'PLASMA') {
                osc.frequency.linearRampToValueAtTime(freq * 1.5, ctx.currentTime + 0.5);
            }
            break;
        default: 
            freq = 440;
    }

    if (!['FIRE', 'WATER', 'INFERNO', 'STEAM', 'PLASMA'].includes(element)) {
         osc.frequency.setValueAtTime(freq, ctx.currentTime);
    }

    osc.type = type;

    const now = ctx.currentTime;
    gain.gain.setValueAtTime(0, now);
    gain.gain.linearRampToValueAtTime(0.05, now + 0.05);
    gain.gain.exponentialRampToValueAtTime(0.001, now + duration);

    osc.start(now);
    osc.stop(now + duration);
  }, []);

  // Improved Gesture Recognition Logic
  const detectGesture = (landmarks: any[], videoWidth: number, videoHeight: number): ElementType => {
    const mapPt = (idx: number) => ({ 
        x: (1 - landmarks[idx].x) * videoWidth, 
        y: landmarks[idx].y * videoHeight 
    });

    const wrist = mapPt(0);
    const indexTip = mapPt(8);
    const middleTip = mapPt(12);
    const ringTip = mapPt(16);
    const pinkyTip = mapPt(20);

    const indexMCP = mapPt(5);
    const middleMCP = mapPt(9);
    const ringMCP = mapPt(13);
    const pinkyMCP = mapPt(17);

    const dist = (p1: any, p2: any) => Math.hypot(p1.x - p2.x, p1.y - p2.y);
    const isFingerOpen = (tip: any, mcp: any) => dist(tip, wrist) > dist(mcp, wrist) * 1.1;

    const indexOpen = isFingerOpen(indexTip, indexMCP);
    const middleOpen = isFingerOpen(middleTip, middleMCP);
    const ringOpen = isFingerOpen(ringTip, ringMCP);
    const pinkyOpen = isFingerOpen(pinkyTip, pinkyMCP);
    const isPointingDown = wrist.y < middleMCP.y;

    if (!indexOpen && !middleOpen && !ringOpen && !pinkyOpen) return 'THUNDER';
    if (indexOpen && middleOpen && !ringOpen && !pinkyOpen) return 'WIND';
    if (isPointingDown && (indexOpen || middleOpen)) return 'WATER';
    if (!isPointingDown && indexOpen && middleOpen && ringOpen) return 'FIRE';

    return 'NEUTRAL';
  };

  const drawSkeleton = (ctx: CanvasRenderingContext2D, hand: HandData) => {
      ctx.strokeStyle = "rgba(255, 255, 255, 0.15)";
      ctx.lineWidth = 1;
      ctx.fillStyle = "rgba(255, 255, 255, 0.3)";

      const points = [
          hand.wrist, 
          hand.indexBase, hand.indexTip,
          hand.middleBase, hand.middleTip,
          hand.ringBase, hand.ringTip,
          hand.pinkyBase, hand.pinkyTip,
          hand.thumbTip
      ];

      // Simple connections
      const drawLine = (p1: any, p2: any) => {
          ctx.beginPath();
          ctx.moveTo(p1.x, p1.y);
          ctx.lineTo(p2.x, p2.y);
          ctx.stroke();
      }
      drawLine(hand.wrist, hand.indexBase);
      drawLine(hand.indexBase, hand.indexTip);
      drawLine(hand.wrist, hand.middleBase);
      drawLine(hand.middleBase, hand.middleTip);
      drawLine(hand.wrist, hand.pinkyBase);
      drawLine(hand.pinkyBase, hand.pinkyTip);

      points.forEach(p => {
          ctx.beginPath();
          ctx.arc(p.x, p.y, 2, 0, Math.PI * 2);
          ctx.fill();
      });
  };

  const onResults = useCallback((results: any) => {
    const videoWidth = webcamRef.current?.video?.videoWidth || width;
    const videoHeight = webcamRef.current?.video?.videoHeight || height;

    if (results.multiHandLandmarks && results.multiHandLandmarks.length > 0) {
      setDebugInfo(`Hands: ${results.multiHandLandmarks.length}`);

      const newHandData: HandData[] = results.multiHandLandmarks.map((landmarks: any[]) => {
        const gesture = detectGesture(landmarks, videoWidth, videoHeight);
        const mapPt = (idx: number) => ({ x: (1 - landmarks[idx].x) * videoWidth, y: landmarks[idx].y * videoHeight });

        return {
          wrist: mapPt(0),
          indexTip: mapPt(8),
          middleTip: mapPt(12),
          ringTip: mapPt(16),
          pinkyTip: mapPt(20),
          thumbTip: mapPt(4),
          indexBase: mapPt(5),
          middleBase: mapPt(9),
          ringBase: mapPt(13),
          pinkyBase: mapPt(17),
          isOpen: gesture !== 'THUNDER', 
          gesture,
          opacity: 1,
        };
      });

      handDataRef.current = newHandData;

      let newElement = 'NEUTRAL';
      let activeCombo = null;

      // Check for Combo
      if (newHandData.length === 2) {
          const g1 = newHandData[0].gesture;
          const g2 = newHandData[1].gesture;
          if (g1 !== 'NEUTRAL' && g2 !== 'NEUTRAL') {
             activeCombo = getCombo(g1, g2);
          }
      }

      if (activeCombo) {
          newElement = activeCombo;
      } else {
          // Priority to first non-neutral
          const activeHand = newHandData.find(h => h.gesture !== 'NEUTRAL');
          if (activeHand) newElement = activeHand.gesture;
      }

      activeComboRef.current = activeCombo;

      if (newElement !== prevElementRef.current) {
          if (newElement !== 'NEUTRAL') {
              highlightRef.current = 1.0; 
              playChime(newElement); 
          }
          prevElementRef.current = newElement;
      }

      setCurrentElement(newElement);

    } else {
      handDataRef.current = [];
      setDebugInfo("No Hands");
      activeComboRef.current = null;
      if (prevElementRef.current !== 'NEUTRAL') {
          prevElementRef.current = 'NEUTRAL';
          setCurrentElement('NEUTRAL');
      }
    }
  }, [width, height, playChime]);

  useEffect(() => {
    let hands: any = null;
    let isActive = true;
    let frameId: number;
    let lastVideoTime = -1;

    const initHands = async () => {
       if (!(window as any).Hands) {
           setTimeout(initHands, 500);
           return;
       }

       hands = new (window as any).Hands({
         locateFile: (file: string) => `https://cdn.jsdelivr.net/npm/@mediapipe/hands@0.4.1675469240/${file}`,
       });

       hands.setOptions({
         maxNumHands: 2,
         modelComplexity: 1,
         minDetectionConfidence: 0.5,
         minTrackingConfidence: 0.5,
       });

       hands.onResults(onResults);
       setIsModelLoaded(true);

       const processVideo = async () => {
         if (!isActive) return;
         if (webcamRef.current && webcamRef.current.video && webcamRef.current.video.readyState === 4) {
             const video = webcamRef.current.video;
             if (video.currentTime !== lastVideoTime) {
                 lastVideoTime = video.currentTime;
                 try {
                    await hands.send({ image: video });
                 } catch (e) { 
                    console.error("MediaPipe error:", e); 
                 }
             }
         }
         frameId = requestAnimationFrame(processVideo);
       };
       processVideo();
    };

    initHands();

    return () => {
      isActive = false;
      if (frameId) cancelAnimationFrame(frameId);
      if (hands) hands.close();
    };
  }, [onResults]);

  const updateParticles = (ctx: CanvasRenderingContext2D, width: number, height: number, centerX: number, centerY: number, activeTheme: Theme | null) => {
    for (let i = particlesRef.current.length - 1; i >= 0; i--) {
      const p = particlesRef.current[i];
      p.vx *= 0.95;
      p.vy *= 0.95;

      // Combo-specific physics if complex, else fallback to standard
      // Simple physics update for all
      p.x += p.vx;
      p.y += p.vy;
      p.life -= 1;
      p.size *= 0.96;

      if (p.element === 'WIND' || p.element === 'BLIZZARD' || p.element === 'PLASMA') {
         // Spiral logic
         const dx = p.x - centerX;
         const dy = p.y - centerY;
         const dist = Math.sqrt(dx*dx + dy*dy) + 1;
         const angle = Math.atan2(dy, dx);
         p.vx += Math.cos(angle + Math.PI/2) * 2;
         p.vy += Math.sin(angle + Math.PI/2) * 2;
         p.vx -= dx/dist;
         p.vy -= dy/dist;
      }
      if (p.element === 'FIRE' || p.element === 'INFERNO') {
          p.vy -= 0.5;
          p.vx += (Math.random() - 0.5);
      }
      if (p.element === 'WATER' || p.element === 'STEAM') {
          p.vy += 0.2;
      }

      if (p.life <= 0 || p.size < 0.2) {
        particlesRef.current.splice(i, 1);
      } else {
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
        ctx.fillStyle = p.color;
        ctx.globalAlpha = Math.min(1, p.life / 20);
        ctx.shadowBlur = 15;
        ctx.shadowColor = p.color;
        ctx.fill();
        ctx.shadowBlur = 0;
      }
    }
  };

  const spawnParticles = (x: number, y: number, element: string, theme: Theme) => {
    const count = 4;
    for (let i = 0; i < count; i++) {
      const angle = Math.random() * Math.PI * 2;
      const speed = Math.random() * 5;
      let vx = Math.cos(angle) * speed;
      let vy = Math.sin(angle) * speed;

      particlesRef.current.push({
        x: x + (Math.random() - 0.5) * 20,
        y: y + (Math.random() - 0.5) * 20,
        vx, vy,
        life: 30 + Math.random() * 20,
        maxLife: 50,
        size: 4 + Math.random() * 6,
        color: Math.random() > 0.5 ? theme.primary : theme.secondary,
        element: element as ElementType // Casting purely for physics switch
      });
    }
  };

  const animate = useCallback((time: number) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (highlightRef.current > 0.01) highlightRef.current *= 0.9;
    else highlightRef.current = 0;
    const flash = highlightRef.current;

    ctx.globalCompositeOperation = 'screen'; 

    let lastCenterX = width / 2;
    let lastCenterY = height / 2;
    const t = time * 0.001;

    // Check for active combo
    const comboName = activeComboRef.current;

    if (comboName && handDataRef.current.length === 2) {
        // --- COMBO RENDERING MODE ---
        const h1 = handDataRef.current[0];
        const h2 = handDataRef.current[1];
        const theme = COMBO_THEMES[comboName];

        // Midpoint
        const midX = (h1.middleBase.x + h2.middleBase.x) / 2;
        const midY = (h1.middleBase.y + h2.middleBase.y) / 2;
        lastCenterX = midX;
        lastCenterY = midY;

        // Draw Energy Beam between hands
        ctx.save();
        ctx.beginPath();
        ctx.moveTo(h1.middleBase.x, h1.middleBase.y);
        ctx.lineTo(h2.middleBase.x, h2.middleBase.y);
        ctx.strokeStyle = theme.core;
        ctx.lineWidth = 10 + Math.sin(t * 10) * 5;
        ctx.lineCap = 'round';
        ctx.shadowBlur = 30;
        ctx.shadowColor = theme.primary;
        ctx.globalAlpha = 0.8;
        ctx.stroke();

        // Secondary beam wobble
        ctx.beginPath();
        ctx.moveTo(h1.middleBase.x, h1.middleBase.y);
        const dist = Math.hypot(h2.middleBase.x - h1.middleBase.x, h2.middleBase.y - h1.middleBase.y);
        const angle = Math.atan2(h2.middleBase.y - h1.middleBase.y, h2.middleBase.x - h1.middleBase.x);
        for(let i=0; i<=20; i++) {
             const p = i/20;
             const perp = Math.sin(p * Math.PI * 4 + t * 10) * 20;
             const bx = h1.middleBase.x + (h2.middleBase.x - h1.middleBase.x) * p + Math.cos(angle + Math.PI/2)*perp;
             const by = h1.middleBase.y + (h2.middleBase.y - h1.middleBase.y) * p + Math.sin(angle + Math.PI/2)*perp;
             ctx.lineTo(bx, by);
        }
        ctx.strokeStyle = theme.secondary;
        ctx.lineWidth = 4;
        ctx.stroke();
        ctx.restore();

        // Huge Central Array
        ctx.globalAlpha = 1;
        if (flash > 0.05) {
            ctx.save();
            ctx.shadowBlur = 50 * flash;
            ctx.shadowColor = theme.core;
            drawRuneRing(ctx, midX, midY, 200, t * 2, theme);
            ctx.restore();
        }

        drawRuneRing(ctx, midX, midY, 180, t, theme);
        drawSacredGeometry(ctx, midX, midY, 140, -t * 2, theme);
        drawSquareLayer(ctx, midX, midY, 100, t * 3, theme);
        drawPentagram(ctx, midX, midY, 60, -t, 1, theme);

        spawnParticles(midX, midY, comboName, theme);

        // Draw small markers on hands
        handDataRef.current.forEach(h => {
             drawSkeleton(ctx, h);
             drawRuneRing(ctx, h.middleBase.x, h.middleBase.y, 40, t*5, theme);
        });

    } else {
        // --- INDIVIDUAL RENDERING MODE ---
        handDataRef.current.forEach((hand) => {
           drawSkeleton(ctx, hand);

           const element = hand.gesture;
           const theme = (element !== 'NEUTRAL' && THEMES[element]) ? THEMES[element] : THEMES['NEUTRAL'];
           const centerX = hand.middleBase.x; 
           const centerY = hand.middleBase.y; 

           if (element !== 'NEUTRAL') {
               // Flash effect
               if (flash > 0.05 && highlightRef.current > 0.05) {
                   ctx.save();
                   ctx.translate(centerX, centerY);
                   const waveSize = 120 + (1 - flash) * 100;
                   ctx.beginPath();
                   ctx.arc(0, 0, waveSize, 0, Math.PI * 2);
                   ctx.lineWidth = 10 * flash;
                   ctx.strokeStyle = theme.core;
                   ctx.shadowBlur = 20;
                   ctx.shadowColor = theme.secondary;
                   ctx.globalAlpha = flash;
                   ctx.stroke();
                   ctx.restore();
               }

               drawRuneRing(ctx, centerX, centerY, 120, t * 0.5, theme);
               drawSacredGeometry(ctx, centerX, centerY, 90, -t * 1.5, theme);
               drawSquareLayer(ctx, centerX, centerY, 65, t * 2.5, theme);
               const pulse = Math.sin(time * 0.005) * 0.5 + 0.5;
               drawPentagram(ctx, centerX, centerY, 40, t, pulse, theme);

               spawnParticles(centerX, centerY, element, theme);
               lastCenterX = centerX;
               lastCenterY = centerY;
           } else {
               ctx.globalAlpha = 0.3;
               drawRuneRing(ctx, centerX, centerY, 50, t * 0.2, theme);
           }
        });
    }

    updateParticles(ctx, canvas.width, canvas.height, lastCenterX, lastCenterY, null);
    requestRef.current = requestAnimationFrame(animate);
  }, [width, height]);

  useEffect(() => {
    requestRef.current = requestAnimationFrame(animate);
    return () => { if (requestRef.current) cancelAnimationFrame(requestRef.current); };
  }, [animate]);

  return (
    <div className="relative w-full h-full bg-black overflow-hidden flex items-center justify-center">
        <Webcam
          ref={webcamRef}
          audio={false}
          width={width}
          height={height}
          mirrored={true}
          screenshotFormat="image/jpeg"
          className="absolute opacity-0 pointer-events-none" 
        />
        <Webcam
          audio={false}
          width={width}
          height={height}
          mirrored={true}
          className="absolute top-0 left-0 w-full h-full object-cover opacity-80"
        />
        <canvas
          ref={canvasRef}
          width={width}
          height={height}
          className="absolute top-0 left-0 w-full h-full object-cover z-10"
        />

        {!isModelLoaded && (
            <div className="absolute inset-0 flex items-center justify-center bg-black bg-opacity-80 z-50">
                <div className="text-amber-500 font-mono text-xl animate-pulse">
                    Summoning Grimoire... (Loading Models)
                </div>
            </div>
        )}

        <div className="absolute top-4 right-4 text-right z-20 font-mono pointer-events-none">
            <div className={`text-2xl font-bold mb-2 tracking-widest transition-all duration-300 ${
                highlightRef.current > 0.1 ? 'scale-110' : ''
            } ${
                currentElement === 'FIRE' ? 'text-orange-500' :
                currentElement === 'WATER' ? 'text-blue-500' :
                currentElement === 'WIND' ? 'text-green-400' :
                currentElement === 'THUNDER' ? 'text-purple-500' : 
                currentElement === 'INFERNO' ? 'text-red-600' :
                currentElement === 'BLIZZARD' ? 'text-cyan-300' :
                currentElement === 'VOID' ? 'text-violet-900' :
                'text-amber-500'
            }`}>
                SPELL: {currentElement}
            </div>
            <div className="text-xs text-white opacity-70 space-y-1 mb-2">
                <p>Status: {debugInfo}</p>
            </div>
            <div className="text-xs text-white opacity-70 space-y-1">
                <p>✋ Palm Up: FIRE</p>
                <p>👇 Palm Down: WATER</p>
                <p>👊 Fist: THUNDER</p>
                <p>✌️ Victory: WIND</p>
            </div>
        </div>
    </div>
  );
};

export default MagicOverlay;

export type ElementType = 'NEUTRAL' | 'FIRE' | 'WATER' | 'THUNDER' | 'WIND';
export type ComboType = 'BLIZZARD' | 'PLASMA' | 'STEAM' | 'TEMPEST' | 'INFERNO' | 'VOID';

export interface Point {
  x: number;
  y: number;
  z?: number;
}

export interface Particle {
  x: number;
  y: number;
  vx: number;
  vy: number;
  life: number;
  maxLife: number;
  size: number;
  color: string;
  element: ElementType | ComboType; // Particle behavior depends on this
}

export interface HandData {
  wrist: Point;
  indexTip: Point;
  middleTip: Point;
  ringTip: Point;
  pinkyTip: Point;
  thumbTip: Point;
  indexBase: Point; // Added for gesture detection
  middleBase: Point;
  ringBase: Point;
  pinkyBase: Point;
  isOpen: boolean;
  gesture: ElementType; // Detected gesture/element
  opacity: number;
}

export interface Theme {
  primary: string;
  secondary: string;
  core: string;
  shadow: string;
}

import React, { useEffect, useRef, useCallback, useState } from 'react';
import Webcam from 'react-webcam';
import { Particle, HandData, ElementType, Theme } from '../types';
import { 
  drawRuneRing, 
  drawSacredGeometry, 
  drawSquareLayer, 
  drawPentagram,
  THEMES
} from '../utils/geometry';

interface MagicOverlayProps {
  width: number;
  height: number;
}

const COMBO_THEMES: Record<string, Theme> = {
  'BLIZZARD': { primary: '#00FFFF', secondary: '#E0FFFF', core: '#FFFFFF', shadow: '#008B8B' },
  'PLASMA': { primary: '#FF00FF', secondary: '#9400D3', core: '#FFFFFF', shadow: '#4B0082' },
  'STEAM': { primary: '#B0C4DE', secondary: '#F0F8FF', core: '#FFFFFF', shadow: '#778899' },
  'TEMPEST': { primary: '#000080', secondary: '#4169E1', core: '#00BFFF', shadow: '#191970' },
  'INFERNO': { primary: '#8B0000', secondary: '#FF4500', core: '#FFFF00', shadow: '#FF0000' },
  'VOID': { primary: '#000000', secondary: '#4B0082', core: '#FFFFFF', shadow: '#9400D3' },
};

const getCombo = (g1: ElementType, g2: ElementType): string | null => {
    const sorted = [g1, g2].sort().join('_');
    switch(sorted) {
        case 'WATER_WIND': return 'BLIZZARD';
        case 'FIRE_WIND': return 'PLASMA';
        case 'FIRE_WATER': return 'STEAM';
        case 'THUNDER_WATER': return 'TEMPEST';
        case 'FIRE_FIRE': return 'INFERNO';
        case 'THUNDER_THUNDER': return 'VOID';
        default: return null;
    }
};

const MagicOverlay: React.FC<MagicOverlayProps> = ({ width, height }) => {
  const webcamRef = useRef<Webcam>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>(0);
  const particlesRef = useRef<Particle[]>([]);
  const handDataRef = useRef<HandData[]>([]);
  const [currentElement, setCurrentElement] = useState<string>('NEUTRAL');
  const [isModelLoaded, setIsModelLoaded] = useState(false);
  const [debugInfo, setDebugInfo] = useState<string>("Initializing...");

  // Visual Feedback State
  const highlightRef = useRef<number>(0);
  const prevElementRef = useRef<string>('NEUTRAL');
  const activeComboRef = useRef<string | null>(null);

  // Audio Context
  const audioContextRef = useRef<AudioContext | null>(null);

  // Initialize Audio
  useEffect(() => {
    const AudioContextClass = (window as any).AudioContext || (window as any).webkitAudioContext;
    if (AudioContextClass) {
        audioContextRef.current = new AudioContextClass();
    }
  }, []);

  const playChime = useCallback((element: string) => {
    if (!audioContextRef.current) return;
    const ctx = audioContextRef.current;
    if (ctx.state === 'suspended') {
        ctx.resume().catch(console.error);
    }

    const osc = ctx.createOscillator();
    const gain = ctx.createGain();

    osc.connect(gain);
    gain.connect(ctx.destination);

    let freq = 440;
    let type: OscillatorType = 'sine';
    let duration = 0.5;

    // Sound Design per Element/Combo
    switch (element) {
        case 'FIRE': 
        case 'INFERNO':
            freq = 220; 
            type = 'sawtooth'; 
            osc.frequency.setValueAtTime(freq, ctx.currentTime);
            osc.frequency.exponentialRampToValueAtTime(freq * (element === 'INFERNO' ? 3 : 2), ctx.currentTime + 0.3);
            break;
        case 'WATER': 
        case 'STEAM':
            freq = 600; 
            type = 'sine';
            osc.frequency.setValueAtTime(freq, ctx.currentTime);
            osc.frequency.exponentialRampToValueAtTime(200, ctx.currentTime + 0.2);
            duration = 0.3;
            break;
        case 'THUNDER': 
        case 'TEMPEST':
        case 'VOID':
            freq = 150; 
            type = 'square';
            osc.frequency.setValueAtTime(freq, ctx.currentTime);
            osc.frequency.linearRampToValueAtTime(freq * 0.8, ctx.currentTime + 0.1);
            if (element === 'VOID') {
                const lfo = ctx.createOscillator();
                lfo.frequency.value = 50;
                lfo.connect(gain.gain);
                lfo.start();
                lfo.stop(ctx.currentTime + duration);
            }
            break;
        case 'WIND': 
        case 'BLIZZARD':
        case 'PLASMA':
            freq = 880; 
            type = 'triangle';
            osc.frequency.setValueAtTime(freq, ctx.currentTime);
            if (element === 'PLASMA') {
                osc.frequency.linearRampToValueAtTime(freq * 1.5, ctx.currentTime + 0.5);
            }
            break;
        default: 
            freq = 440;
    }

    if (!['FIRE', 'WATER', 'INFERNO', 'STEAM', 'PLASMA'].includes(element)) {
         osc.frequency.setValueAtTime(freq, ctx.currentTime);
    }

    osc.type = type;

    const now = ctx.currentTime;
    gain.gain.setValueAtTime(0, now);
    gain.gain.linearRampToValueAtTime(0.05, now + 0.05);
    gain.gain.exponentialRampToValueAtTime(0.001, now + duration);

    osc.start(now);
    osc.stop(now + duration);
  }, []);

  // Improved Gesture Recognition Logic
  const detectGesture = (landmarks: any[], videoWidth: number, videoHeight: number): ElementType => {
    const mapPt = (idx: number) => ({ 
        x: (1 - landmarks[idx].x) * videoWidth, 
        y: landmarks[idx].y * videoHeight 
    });

    const wrist = mapPt(0);
    const indexTip = mapPt(8);
    const middleTip = mapPt(12);
    const ringTip = mapPt(16);
    const pinkyTip = mapPt(20);

    const indexMCP = mapPt(5);
    const middleMCP = mapPt(9);
    const ringMCP = mapPt(13);
    const pinkyMCP = mapPt(17);

    const dist = (p1: any, p2: any) => Math.hypot(p1.x - p2.x, p1.y - p2.y);
    const isFingerOpen = (tip: any, mcp: any) => dist(tip, wrist) > dist(mcp, wrist) * 1.1;

    const indexOpen = isFingerOpen(indexTip, indexMCP);
    const middleOpen = isFingerOpen(middleTip, middleMCP);
    const ringOpen = isFingerOpen(ringTip, ringMCP);
    const pinkyOpen = isFingerOpen(pinkyTip, pinkyMCP);
    const isPointingDown = wrist.y < middleMCP.y;

    if (!indexOpen && !middleOpen && !ringOpen && !pinkyOpen) return 'THUNDER';
    if (indexOpen && middleOpen && !ringOpen && !pinkyOpen) return 'WIND';
    if (isPointingDown && (indexOpen || middleOpen)) return 'WATER';
    if (!isPointingDown && indexOpen && middleOpen && ringOpen) return 'FIRE';

    return 'NEUTRAL';
  };

  const drawSkeleton = (ctx: CanvasRenderingContext2D, hand: HandData) => {
      ctx.strokeStyle = "rgba(255, 255, 255, 0.15)";
      ctx.lineWidth = 1;
      ctx.fillStyle = "rgba(255, 255, 255, 0.3)";

      const points = [
          hand.wrist, 
          hand.indexBase, hand.indexTip,
          hand.middleBase, hand.middleTip,
          hand.ringBase, hand.ringTip,
          hand.pinkyBase, hand.pinkyTip,
          hand.thumbTip
      ];

      // Simple connections
      const drawLine = (p1: any, p2: any) => {
          ctx.beginPath();
          ctx.moveTo(p1.x, p1.y);
          ctx.lineTo(p2.x, p2.y);
          ctx.stroke();
      }
      drawLine(hand.wrist, hand.indexBase);
      drawLine(hand.indexBase, hand.indexTip);
      drawLine(hand.wrist, hand.middleBase);
      drawLine(hand.middleBase, hand.middleTip);
      drawLine(hand.wrist, hand.pinkyBase);
      drawLine(hand.pinkyBase, hand.pinkyTip);

      points.forEach(p => {
          ctx.beginPath();
          ctx.arc(p.x, p.y, 2, 0, Math.PI * 2);
          ctx.fill();
      });
  };

  const onResults = useCallback((results: any) => {
    const videoWidth = webcamRef.current?.video?.videoWidth || width;
    const videoHeight = webcamRef.current?.video?.videoHeight || height;

    if (results.multiHandLandmarks && results.multiHandLandmarks.length > 0) {
      setDebugInfo(`Hands: ${results.multiHandLandmarks.length}`);

      const newHandData: HandData[] = results.multiHandLandmarks.map((landmarks: any[]) => {
        const gesture = detectGesture(landmarks, videoWidth, videoHeight);
        const mapPt = (idx: number) => ({ x: (1 - landmarks[idx].x) * videoWidth, y: landmarks[idx].y * videoHeight });

        return {
          wrist: mapPt(0),
          indexTip: mapPt(8),
          middleTip: mapPt(12),
          ringTip: mapPt(16),
          pinkyTip: mapPt(20),
          thumbTip: mapPt(4),
          indexBase: mapPt(5),
          middleBase: mapPt(9),
          ringBase: mapPt(13),
          pinkyBase: mapPt(17),
          isOpen: gesture !== 'THUNDER', 
          gesture,
          opacity: 1,
        };
      });

      handDataRef.current = newHandData;

      let newElement = 'NEUTRAL';
      let activeCombo = null;

      // Check for Combo
      if (newHandData.length === 2) {
          const g1 = newHandData[0].gesture;
          const g2 = newHandData[1].gesture;
          if (g1 !== 'NEUTRAL' && g2 !== 'NEUTRAL') {
             activeCombo = getCombo(g1, g2);
          }
      }

      if (activeCombo) {
          newElement = activeCombo;
      } else {
          // Priority to first non-neutral
          const activeHand = newHandData.find(h => h.gesture !== 'NEUTRAL');
          if (activeHand) newElement = activeHand.gesture;
      }

      activeComboRef.current = activeCombo;

      if (newElement !== prevElementRef.current) {
          if (newElement !== 'NEUTRAL') {
              highlightRef.current = 1.0; 
              playChime(newElement); 
          }
          prevElementRef.current = newElement;
      }

      setCurrentElement(newElement);

    } else {
      handDataRef.current = [];
      setDebugInfo("No Hands");
      activeComboRef.current = null;
      if (prevElementRef.current !== 'NEUTRAL') {
          prevElementRef.current = 'NEUTRAL';
          setCurrentElement('NEUTRAL');
      }
    }
  }, [width, height, playChime]);

  useEffect(() => {
    let hands: any = null;
    let isActive = true;
    let frameId: number;
    let lastVideoTime = -1;

    const initHands = async () => {
       if (!(window as any).Hands) {
           setTimeout(initHands, 500);
           return;
       }

       hands = new (window as any).Hands({
         locateFile: (file: string) => `https://cdn.jsdelivr.net/npm/@mediapipe/hands@0.4.1675469240/${file}`,
       });

       hands.setOptions({
         maxNumHands: 2,
         modelComplexity: 1,
         minDetectionConfidence: 0.5,
         minTrackingConfidence: 0.5,
       });

       hands.onResults(onResults);
       setIsModelLoaded(true);

       const processVideo = async () => {
         if (!isActive) return;
         if (webcamRef.current && webcamRef.current.video && webcamRef.current.video.readyState === 4) {
             const video = webcamRef.current.video;
             if (video.currentTime !== lastVideoTime) {
                 lastVideoTime = video.currentTime;
                 try {
                    await hands.send({ image: video });
                 } catch (e) { 
                    console.error("MediaPipe error:", e); 
                 }
             }
         }
         frameId = requestAnimationFrame(processVideo);
       };
       processVideo();
    };

    initHands();

    return () => {
      isActive = false;
      if (frameId) cancelAnimationFrame(frameId);
      if (hands) hands.close();
    };
  }, [onResults]);

  const updateParticles = (ctx: CanvasRenderingContext2D, width: number, height: number, centerX: number, centerY: number, activeTheme: Theme | null) => {
    for (let i = particlesRef.current.length - 1; i >= 0; i--) {
      const p = particlesRef.current[i];
      p.vx *= 0.95;
      p.vy *= 0.95;

      // Combo-specific physics if complex, else fallback to standard
      // Simple physics update for all
      p.x += p.vx;
      p.y += p.vy;
      p.life -= 1;
      p.size *= 0.96;

      if (p.element === 'WIND' || p.element === 'BLIZZARD' || p.element === 'PLASMA') {
         // Spiral logic
         const dx = p.x - centerX;
         const dy = p.y - centerY;
         const dist = Math.sqrt(dx*dx + dy*dy) + 1;
         const angle = Math.atan2(dy, dx);
         p.vx += Math.cos(angle + Math.PI/2) * 2;
         p.vy += Math.sin(angle + Math.PI/2) * 2;
         p.vx -= dx/dist;
         p.vy -= dy/dist;
      }
      if (p.element === 'FIRE' || p.element === 'INFERNO') {
          p.vy -= 0.5;
          p.vx += (Math.random() - 0.5);
      }
      if (p.element === 'WATER' || p.element === 'STEAM') {
          p.vy += 0.2;
      }

      if (p.life <= 0 || p.size < 0.2) {
        particlesRef.current.splice(i, 1);
      } else {
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
        ctx.fillStyle = p.color;
        ctx.globalAlpha = Math.min(1, p.life / 20);
        ctx.shadowBlur = 15;
        ctx.shadowColor = p.color;
        ctx.fill();
        ctx.shadowBlur = 0;
      }
    }
  };

  const spawnParticles = (x: number, y: number, element: string, theme: Theme) => {
    const count = 4;
    for (let i = 0; i < count; i++) {
      const angle = Math.random() * Math.PI * 2;
      const speed = Math.random() * 5;
      let vx = Math.cos(angle) * speed;
      let vy = Math.sin(angle) * speed;

      particlesRef.current.push({
        x: x + (Math.random() - 0.5) * 20,
        y: y + (Math.random() - 0.5) * 20,
        vx, vy,
        life: 30 + Math.random() * 20,
        maxLife: 50,
        size: 4 + Math.random() * 6,
        color: Math.random() > 0.5 ? theme.primary : theme.secondary,
        element: element as Particle['element'] // Casting purely for physics switch
      });
    }
  };

  const animate = useCallback((time: number) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (highlightRef.current > 0.01) highlightRef.current *= 0.9;
    else highlightRef.current = 0;
    const flash = highlightRef.current;

    ctx.globalCompositeOperation = 'screen'; 

    let lastCenterX = width / 2;
    let lastCenterY = height / 2;
    const t = time * 0.001;

    // Check for active combo
    const comboName = activeComboRef.current;

    if (comboName && handDataRef.current.length === 2) {
        // --- COMBO RENDERING MODE ---
        const h1 = handDataRef.current[0];
        const h2 = handDataRef.current[1];
        const theme = COMBO_THEMES[comboName];

        // Midpoint
        const midX = (h1.middleBase.x + h2.middleBase.x) / 2;
        const midY = (h1.middleBase.y + h2.middleBase.y) / 2;
        lastCenterX = midX;
        lastCenterY = midY;

        // Draw Energy Beam between hands
        ctx.save();
        ctx.beginPath();
        ctx.moveTo(h1.middleBase.x, h1.middleBase.y);
        ctx.lineTo(h2.middleBase.x, h2.middleBase.y);
        ctx.strokeStyle = theme.core;
        ctx.lineWidth = 10 + Math.sin(t * 10) * 5;
        ctx.lineCap = 'round';
        ctx.shadowBlur = 30;
        ctx.shadowColor = theme.primary;
        ctx.globalAlpha = 0.8;
        ctx.stroke();

        // Secondary beam wobble
        ctx.beginPath();
        ctx.moveTo(h1.middleBase.x, h1.middleBase.y);
        const dist = Math.hypot(h2.middleBase.x - h1.middleBase.x, h2.middleBase.y - h1.middleBase.y);
        const angle = Math.atan2(h2.middleBase.y - h1.middleBase.y, h2.middleBase.x - h1.middleBase.x);
        for(let i=0; i<=20; i++) {
             const p = i/20;
             const perp = Math.sin(p * Math.PI * 4 + t * 10) * 20;
             const bx = h1.middleBase.x + (h2.middleBase.x - h1.middleBase.x) * p + Math.cos(angle + Math.PI/2)*perp;
             const by = h1.middleBase.y + (h2.middleBase.y - h1.middleBase.y) * p + Math.sin(angle + Math.PI/2)*perp;
             ctx.lineTo(bx, by);
        }
        ctx.strokeStyle = theme.secondary;
        ctx.lineWidth = 4;
        ctx.stroke();
        ctx.restore();

        // Huge Central Array
        ctx.globalAlpha = 1;
        if (flash > 0.05) {
            ctx.save();
            ctx.shadowBlur = 50 * flash;
            ctx.shadowColor = theme.core;
            drawRuneRing(ctx, midX, midY, 200, t * 2, theme);
            ctx.restore();
        }

        drawRuneRing(ctx, midX, midY, 180, t, theme);
        drawSacredGeometry(ctx, midX, midY, 140, -t * 2, theme);
        drawSquareLayer(ctx, midX, midY, 100, t * 3, theme);
        drawPentagram(ctx, midX, midY, 60, -t, 1, theme);

        spawnParticles(midX, midY, comboName, theme);

        // Draw small markers on hands
        handDataRef.current.forEach(h => {
             drawSkeleton(ctx, h);
             drawRuneRing(ctx, h.middleBase.x, h.middleBase.y, 40, t*5, theme);
        });

    } else {
        // --- INDIVIDUAL RENDERING MODE ---
        handDataRef.current.forEach((hand) => {
           drawSkeleton(ctx, hand);

           const element = hand.gesture;
           const theme = (element !== 'NEUTRAL' && THEMES[element]) ? THEMES[element] : THEMES['NEUTRAL'];
           const centerX = hand.middleBase.x; 
           const centerY = hand.middleBase.y; 

           if (element !== 'NEUTRAL') {
               // Flash effect
               if (flash > 0.05 && highlightRef.current > 0.05) {
                   ctx.save();
                   ctx.translate(centerX, centerY);
                   const waveSize = 120 + (1 - flash) * 100;
                   ctx.beginPath();
                   ctx.arc(0, 0, waveSize, 0, Math.PI * 2);
                   ctx.lineWidth = 10 * flash;
                   ctx.strokeStyle = theme.core;
                   ctx.shadowBlur = 20;
                   ctx.shadowColor = theme.secondary;
                   ctx.globalAlpha = flash;
                   ctx.stroke();
                   ctx.restore();
               }

               drawRuneRing(ctx, centerX, centerY, 120, t * 0.5, theme);
               drawSacredGeometry(ctx, centerX, centerY, 90, -t * 1.5, theme);
               drawSquareLayer(ctx, centerX, centerY, 65, t * 2.5, theme);
               const pulse = Math.sin(time * 0.005) * 0.5 + 0.5;
               drawPentagram(ctx, centerX, centerY, 40, t, pulse, theme);

               spawnParticles(centerX, centerY, element, theme);
               lastCenterX = centerX;
               lastCenterY = centerY;
           } else {
               ctx.globalAlpha = 0.3;
               drawRuneRing(ctx, centerX, centerY, 50, t * 0.2, theme);
           }
        });
    }

    updateParticles(ctx, canvas.width, canvas.height, lastCenterX, lastCenterY, null);
    requestRef.current = requestAnimationFrame(animate);
  }, [width, height]);

  useEffect(() => {
    requestRef.current = requestAnimationFrame(animate);
    return () => { if (requestRef.current) cancelAnimationFrame(requestRef.current); };
  }, [animate]);

  return (
    <div className="relative w-full h-full bg-black overflow-hidden flex items-center justify-center">
        <Webcam
          ref={webcamRef}
          audio={false}
          width={width}
          height={height}
          mirrored={true}
          screenshotFormat="image/jpeg"
          className="absolute opacity-0 pointer-events-none" 
        />
        <Webcam
          audio={false}
          width={width}
          height={height}
          mirrored={true}
          className="absolute top-0 left-0 w-full h-full object-cover opacity-80"
        />
        <canvas
          ref={canvasRef}
          width={width}
          height={height}
          className="absolute top-0 left-0 w-full h-full object-cover z-10"
        />

        {!isModelLoaded && (
            <div className="absolute inset-0 flex items-center justify-center bg-black bg-opacity-80 z-50">
                <div className="text-amber-500 font-mono text-xl animate-pulse">
                    Summoning Grimoire... (Loading Models)
                </div>
            </div>
        )}

        <div className="absolute top-4 right-4 text-right z-20 font-mono pointer-events-none">
            <div className={`text-2xl font-bold mb-2 tracking-widest transition-all duration-300 ${
                highlightRef.current > 0.1 ? 'scale-110' : ''
            } ${
                currentElement === 'FIRE' ? 'text-orange-500' :
                currentElement === 'WATER' ? 'text-blue-500' :
                currentElement === 'WIND' ? 'text-green-400' :
                currentElement === 'THUNDER' ? 'text-purple-500' : 
                currentElement === 'INFERNO' ? 'text-red-600' :
                currentElement === 'BLIZZARD' ? 'text-cyan-300' :
                currentElement === 'VOID' ? 'text-violet-900' :
                'text-amber-500'
            }`}>
                SPELL: {currentElement}
            </div>
            <div className="text-xs text-white opacity-70 space-y-1 mb-2">
                <p>Status: {debugInfo}</p>
            </div>
            <div className="text-xs text-white opacity-70 space-y-1">
                <p>✋ Palm Up: FIRE</p>
                <p>👇 Palm Down: WATER</p>
                <p>👊 Fist: THUNDER</p>
                <p>✌️ Victory: WIND</p>
            </div>
        </div>
    </div>
  );
};

export default MagicOverlay;

import React, { useEffect, useRef, useCallback, useState } from 'react';
import Webcam from 'react-webcam';
import { Particle, HandData, ElementType, Theme } from '../types';
import { 
  drawRuneRing, 
  drawSacredGeometry, 
  drawSquareLayer, 
  drawPentagram,
  THEMES
} from '../utils/geometry';

interface MagicOverlayProps {
  width: number;
  height: number;
}

const COMBO_THEMES: Record<string, Theme> = {
  'BLIZZARD': { primary: '#00FFFF', secondary: '#E0FFFF', core: '#FFFFFF', shadow: '#008B8B' },
  'PLASMA': { primary: '#FF00FF', secondary: '#9400D3', core: '#FFFFFF', shadow: '#4B0082' },
  'STEAM': { primary: '#B0C4DE', secondary: '#F0F8FF', core: '#FFFFFF', shadow: '#778899' },
  'TEMPEST': { primary: '#000080', secondary: '#4169E1', core: '#00BFFF', shadow: '#191970' },
  'INFERNO': { primary: '#8B0000', secondary: '#FF4500', core: '#FFFF00', shadow: '#FF0000' },
  'VOID': { primary: '#000000', secondary: '#4B0082', core: '#FFFFFF', shadow: '#9400D3' },
};

const getCombo = (g1: ElementType, g2: ElementType): string | null => {
    const sorted = [g1, g2].sort().join('_');
    switch(sorted) {
        case 'WATER_WIND': return 'BLIZZARD';
        case 'FIRE_WIND': return 'PLASMA';
        case 'FIRE_WATER': return 'STEAM';
        case 'THUNDER_WATER': return 'TEMPEST';
        case 'FIRE_FIRE': return 'INFERNO';
        case 'THUNDER_THUNDER': return 'VOID';
        default: return null;
    }
};

const MagicOverlay: React.FC<MagicOverlayProps> = ({ width, height }) => {
  const webcamRef = useRef<Webcam>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>(0);
  const particlesRef = useRef<Particle[]>([]);
  const handDataRef = useRef<HandData[]>([]);
  const [currentElement, setCurrentElement] = useState<string>('NEUTRAL');
  const [isModelLoaded, setIsModelLoaded] = useState(false);
  const [debugInfo, setDebugInfo] = useState<string>("Initializing...");

  // Visual Feedback State
  const highlightRef = useRef<number>(0);
  const prevElementRef = useRef<string>('NEUTRAL');
  const activeComboRef = useRef<string | null>(null);

  // Audio Context
  const audioContextRef = useRef<AudioContext | null>(null);

  // Initialize Audio
  useEffect(() => {
    const AudioContextClass = (window as any).AudioContext || (window as any).webkitAudioContext;
    if (AudioContextClass) {
        audioContextRef.current = new AudioContextClass();
    }
  }, []);

  const playChime = useCallback((element: string) => {
    if (!audioContextRef.current) return;
    const ctx = audioContextRef.current;
    if (ctx.state === 'suspended') {
        ctx.resume().catch(console.error);
    }

    const osc = ctx.createOscillator();
    const gain = ctx.createGain();

    osc.connect(gain);
    gain.connect(ctx.destination);

    let freq = 440;
    let type: OscillatorType = 'sine';
    let duration = 0.5;

    // Sound Design per Element/Combo
    switch (element) {
        case 'FIRE': 
        case 'INFERNO':
            freq = 220; 
            type = 'sawtooth'; 
            osc.frequency.setValueAtTime(freq, ctx.currentTime);
            osc.frequency.exponentialRampToValueAtTime(freq * (element === 'INFERNO' ? 3 : 2), ctx.currentTime + 0.3);
            break;
        case 'WATER': 
        case 'STEAM':
            freq = 600; 
            type = 'sine';
            osc.frequency.setValueAtTime(freq, ctx.currentTime);
            osc.frequency.exponentialRampToValueAtTime(200, ctx.currentTime + 0.2);
            duration = 0.3;
            break;
        case 'THUNDER': 
        case 'TEMPEST':
        case 'VOID':
            freq = 150; 
            type = 'square';
            osc.frequency.setValueAtTime(freq, ctx.currentTime);
            osc.frequency.linearRampToValueAtTime(freq * 0.8, ctx.currentTime + 0.1);
            if (element === 'VOID') {
                const lfo = ctx.createOscillator();
                lfo.frequency.value = 50;
                lfo.connect(gain.gain);
                lfo.start();
                lfo.stop(ctx.currentTime + duration);
            }
            break;
        case 'WIND': 
        case 'BLIZZARD':
        case 'PLASMA':
            freq = 880; 
            type = 'triangle';
            osc.frequency.setValueAtTime(freq, ctx.currentTime);
            if (element === 'PLASMA') {
                osc.frequency.linearRampToValueAtTime(freq * 1.5, ctx.currentTime + 0.5);
            }
            break;
        default: 
            freq = 440;
    }

    if (!['FIRE', 'WATER', 'INFERNO', 'STEAM', 'PLASMA'].includes(element)) {
         osc.frequency.setValueAtTime(freq, ctx.currentTime);
    }

    osc.type = type;

    const now = ctx.currentTime;
    gain.gain.setValueAtTime(0, now);
    gain.gain.linearRampToValueAtTime(0.05, now + 0.05);
    gain.gain.exponentialRampToValueAtTime(0.001, now + duration);

    osc.start(now);
    osc.stop(now + duration);
  }, []);

  // Improved Gesture Recognition Logic
  const detectGesture = (landmarks: any[], videoWidth: number, videoHeight: number): ElementType => {
    const mapPt = (idx: number) => ({ 
        x: (1 - landmarks[idx].x) * videoWidth, 
        y: landmarks[idx].y * videoHeight 
    });

    const wrist = mapPt(0);
    const indexTip = mapPt(8);
    const middleTip = mapPt(12);
    const ringTip = mapPt(16);
    const pinkyTip = mapPt(20);

    const indexMCP = mapPt(5);
    const middleMCP = mapPt(9);
    const ringMCP = mapPt(13);
    const pinkyMCP = mapPt(17);

    const dist = (p1: any, p2: any) => Math.hypot(p1.x - p2.x, p1.y - p2.y);
    const isFingerOpen = (tip: any, mcp: any) => dist(tip, wrist) > dist(mcp, wrist) * 1.1;

    const indexOpen = isFingerOpen(indexTip, indexMCP);
    const middleOpen = isFingerOpen(middleTip, middleMCP);
    const ringOpen = isFingerOpen(ringTip, ringMCP);
    const pinkyOpen = isFingerOpen(pinkyTip, pinkyMCP);
    const isPointingDown = wrist.y < middleMCP.y;

    if (!indexOpen && !middleOpen && !ringOpen && !pinkyOpen) return 'THUNDER';
    if (indexOpen && middleOpen && !ringOpen && !pinkyOpen) return 'WIND';
    if (isPointingDown && (indexOpen || middleOpen)) return 'WATER';
    if (!isPointingDown && indexOpen && middleOpen && ringOpen) return 'FIRE';

    return 'NEUTRAL';
  };

  const drawSkeleton = (ctx: CanvasRenderingContext2D, hand: HandData) => {
      ctx.strokeStyle = "rgba(255, 255, 255, 0.15)";
      ctx.lineWidth = 1;
      ctx.fillStyle = "rgba(255, 255, 255, 0.3)";

      const points = [
          hand.wrist, 
          hand.indexBase, hand.indexTip,
          hand.middleBase, hand.middleTip,
          hand.ringBase, hand.ringTip,
          hand.pinkyBase, hand.pinkyTip,
          hand.thumbTip
      ];

      // Simple connections
      const drawLine = (p1: any, p2: any) => {
          ctx.beginPath();
          ctx.moveTo(p1.x, p1.y);
          ctx.lineTo(p2.x, p2.y);
          ctx.stroke();
      }
      drawLine(hand.wrist, hand.indexBase);
      drawLine(hand.indexBase, hand.indexTip);
      drawLine(hand.wrist, hand.middleBase);
      drawLine(hand.middleBase, hand.middleTip);
      drawLine(hand.wrist, hand.pinkyBase);
      drawLine(hand.pinkyBase, hand.pinkyTip);

      points.forEach(p => {
          ctx.beginPath();
          ctx.arc(p.x, p.y, 2, 0, Math.PI * 2);
          ctx.fill();
      });
  };

  const onResults = useCallback((results: any) => {
    const videoWidth = webcamRef.current?.video?.videoWidth || width;
    const videoHeight = webcamRef.current?.video?.videoHeight || height;

    if (results.multiHandLandmarks && results.multiHandLandmarks.length > 0) {
      setDebugInfo(`Hands: ${results.multiHandLandmarks.length}`);

      const newHandData: HandData[] = results.multiHandLandmarks.map((landmarks: any[]) => {
        const gesture = detectGesture(landmarks, videoWidth, videoHeight);
        const mapPt = (idx: number) => ({ x: (1 - landmarks[idx].x) * videoWidth, y: landmarks[idx].y * videoHeight });

        return {
          wrist: mapPt(0),
          indexTip: mapPt(8),
          middleTip: mapPt(12),
          ringTip: mapPt(16),
          pinkyTip: mapPt(20),
          thumbTip: mapPt(4),
          indexBase: mapPt(5),
          middleBase: mapPt(9),
          ringBase: mapPt(13),
          pinkyBase: mapPt(17),
          isOpen: gesture !== 'THUNDER', 
          gesture,
          opacity: 1,
        };
      });

      handDataRef.current = newHandData;

      let newElement = 'NEUTRAL';
      let activeCombo = null;

      // Check for Combo
      if (newHandData.length === 2) {
          const g1 = newHandData[0].gesture;
          const g2 = newHandData[1].gesture;
          if (g1 !== 'NEUTRAL' && g2 !== 'NEUTRAL') {
             activeCombo = getCombo(g1, g2);
          }
      }

      if (activeCombo) {
          newElement = activeCombo;
      } else {
          // Priority to first non-neutral
          const activeHand = newHandData.find(h => h.gesture !== 'NEUTRAL');
          if (activeHand) newElement = activeHand.gesture;
      }

      activeComboRef.current = activeCombo;

      if (newElement !== prevElementRef.current) {
          if (newElement !== 'NEUTRAL') {
              highlightRef.current = 1.0; 
              playChime(newElement); 
          }
          prevElementRef.current = newElement;
      }

      setCurrentElement(newElement);

    } else {
      handDataRef.current = [];
      setDebugInfo("No Hands");
      activeComboRef.current = null;
      if (prevElementRef.current !== 'NEUTRAL') {
          prevElementRef.current = 'NEUTRAL';
          setCurrentElement('NEUTRAL');
      }
    }
  }, [width, height, playChime]);

  useEffect(() => {
    let hands: any = null;
    let isActive = true;
    let frameId: number;
    let lastVideoTime = -1;

    const initHands = async () => {
       if (!(window as any).Hands) {
           setTimeout(initHands, 500);
           return;
       }

       hands = new (window as any).Hands({
         locateFile: (file: string) => `https://cdn.jsdelivr.net/npm/@mediapipe/hands@0.4.1675469240/${file}`,
       });

       hands.setOptions({
         maxNumHands: 2,
         modelComplexity: 1,
         minDetectionConfidence: 0.5,
         minTrackingConfidence: 0.5,
       });

       hands.onResults(onResults);
       setIsModelLoaded(true);

       const processVideo = async () => {
         if (!isActive) return;
         if (webcamRef.current && webcamRef.current.video && webcamRef.current.video.readyState === 4) {
             const video = webcamRef.current.video;
             if (video.currentTime !== lastVideoTime) {
                 lastVideoTime = video.currentTime;
                 try {
                    await hands.send({ image: video });
                 } catch (e) { 
                    console.error("MediaPipe error:", e); 
                 }
             }
         }
         frameId = requestAnimationFrame(processVideo);
       };
       processVideo();
    };

    initHands();

    return () => {
      isActive = false;
      if (frameId) cancelAnimationFrame(frameId);
      if (hands) hands.close();
    };
  }, [onResults]);

  const updateParticles = (ctx: CanvasRenderingContext2D, width: number, height: number, centerX: number, centerY: number, activeTheme: Theme | null) => {
    for (let i = particlesRef.current.length - 1; i >= 0; i--) {
      const p = particlesRef.current[i];
      p.vx *= 0.95;
      p.vy *= 0.95;

      // Combo-specific physics if complex, else fallback to standard
      // Simple physics update for all
      p.x += p.vx;
      p.y += p.vy;
      p.life -= 1;
      p.size *= 0.96;

      if (p.element === 'WIND' || p.element === 'BLIZZARD' || p.element === 'PLASMA') {
         // Spiral logic
         const dx = p.x - centerX;
         const dy = p.y - centerY;
         const dist = Math.sqrt(dx*dx + dy*dy) + 1;
         const angle = Math.atan2(dy, dx);
         p.vx += Math.cos(angle + Math.PI/2) * 2;
         p.vy += Math.sin(angle + Math.PI/2) * 2;
         p.vx -= dx/dist;
         p.vy -= dy/dist;
      }
      if (p.element === 'FIRE' || p.element === 'INFERNO') {
          p.vy -= 0.5;
          p.vx += (Math.random() - 0.5);
      }
      if (p.element === 'WATER' || p.element === 'STEAM') {
          p.vy += 0.2;
      }

      if (p.life <= 0 || p.size < 0.2) {
        particlesRef.current.splice(i, 1);
      } else {
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
        ctx.fillStyle = p.color;
        ctx.globalAlpha = Math.min(1, p.life / 20);
        ctx.shadowBlur = 15;
        ctx.shadowColor = p.color;
        ctx.fill();
        ctx.shadowBlur = 0;
      }
    }
  };

  const spawnParticles = (x: number, y: number, element: string, theme: Theme) => {
    const count = 4;
    for (let i = 0; i < count; i++) {
      const angle = Math.random() * Math.PI * 2;
      const speed = Math.random() * 5;
      let vx = Math.cos(angle) * speed;
      let vy = Math.sin(angle) * speed;

      particlesRef.current.push({
        x: x + (Math.random() - 0.5) * 20,
        y: y + (Math.random() - 0.5) * 20,
        vx, vy,
        life: 30 + Math.random() * 20,
        maxLife: 50,
        size: 4 + Math.random() * 6,
        color: Math.random() > 0.5 ? theme.primary : theme.secondary,
        element: element as Particle['element'] // Casting purely for physics switch
      });
    }
  };

  const animate = useCallback((time: number) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (highlightRef.current > 0.01) highlightRef.current *= 0.9;
    else highlightRef.current = 0;
    const flash = highlightRef.current;

    ctx.globalCompositeOperation = 'screen'; 

    let lastCenterX = width / 2;
    let lastCenterY = height / 2;
    const t = time * 0.001;

    // Check for active combo
    const comboName = activeComboRef.current;

    if (comboName && handDataRef.current.length === 2) {
        // --- COMBO RENDERING MODE ---
        const h1 = handDataRef.current[0];
        const h2 = handDataRef.current[1];
        const theme = COMBO_THEMES[comboName];

        // Midpoint
        const midX = (h1.middleBase.x + h2.middleBase.x) / 2;
        const midY = (h1.middleBase.y + h2.middleBase.y) / 2;
        lastCenterX = midX;
        lastCenterY = midY;

        // 1. Draw Energy Beam between hands (Base Glow)
        ctx.save();
        ctx.beginPath();
        ctx.moveTo(h1.middleBase.x, h1.middleBase.y);
        ctx.lineTo(h2.middleBase.x, h2.middleBase.y);
        ctx.strokeStyle = theme.primary;
        ctx.lineWidth = 20 + Math.sin(t * 10) * 5; // Pulsating width
        ctx.lineCap = 'round';
        ctx.shadowBlur = 40;
        ctx.shadowColor = theme.secondary;
        ctx.globalAlpha = 0.4;
        ctx.stroke();
        ctx.restore();

        // 2. Core Beam
        ctx.save();
        ctx.beginPath();
        ctx.moveTo(h1.middleBase.x, h1.middleBase.y);
        ctx.lineTo(h2.middleBase.x, h2.middleBase.y);
        ctx.strokeStyle = theme.core;
        ctx.lineWidth = 6;
        ctx.shadowBlur = 20;
        ctx.shadowColor = theme.primary;
        ctx.globalAlpha = 0.9;
        ctx.stroke();
        ctx.restore();

        // 3. Converging Energy (Moving Dash)
        ctx.save();
        ctx.beginPath();
        ctx.moveTo(h1.middleBase.x, h1.middleBase.y);
        ctx.lineTo(h2.middleBase.x, h2.middleBase.y);
        ctx.strokeStyle = '#FFFFFF';
        ctx.lineWidth = 3;
        ctx.setLineDash([10, 40]);
        ctx.lineDashOffset = -t * 200; // Fast flowing energy effect
        ctx.globalCompositeOperation = 'overlay';
        ctx.stroke();
        ctx.restore();

        // 4. Secondary beam wobble (Electricity)
        ctx.save();
        ctx.beginPath();
        ctx.moveTo(h1.middleBase.x, h1.middleBase.y);
        const dist = Math.hypot(h2.middleBase.x - h1.middleBase.x, h2.middleBase.y - h1.middleBase.y);
        const angle = Math.atan2(h2.middleBase.y - h1.middleBase.y, h2.middleBase.x - h1.middleBase.x);
        for(let i=0; i<=20; i++) {
             const p = i/20;
             const perp = Math.sin(p * Math.PI * 4 + t * 20) * (15 + Math.random() * 5); // Faster jitter
             const bx = h1.middleBase.x + (h2.middleBase.x - h1.middleBase.x) * p + Math.cos(angle + Math.PI/2)*perp;
             const by = h1.middleBase.y + (h2.middleBase.y - h1.middleBase.y) * p + Math.sin(angle + Math.PI/2)*perp;
             ctx.lineTo(bx, by);
        }
        ctx.strokeStyle = theme.secondary;
        ctx.lineWidth = 2;
        ctx.shadowBlur = 10;
        ctx.shadowColor = theme.core;
        ctx.stroke();
        ctx.restore();

        // Huge Central Array
        ctx.globalAlpha = 1;
        if (flash > 0.05) {
            ctx.save();
            ctx.shadowBlur = 50 * flash;
            ctx.shadowColor = theme.core;
            drawRuneRing(ctx, midX, midY, 200, t * 2, theme);
            ctx.restore();
        }

        drawRuneRing(ctx, midX, midY, 180, t, theme);
        drawSacredGeometry(ctx, midX, midY, 140, -t * 2, theme);
        drawSquareLayer(ctx, midX, midY, 100, t * 3, theme);
        drawPentagram(ctx, midX, midY, 60, -t, 1, theme);

        spawnParticles(midX, midY, comboName, theme);

        // Draw Aura on Hands
        handDataRef.current.forEach(h => {
             drawSkeleton(ctx, h);

             // Pulsating Aura
             const auraSize = 50 + Math.sin(t * 20) * 10;
             const grad = ctx.createRadialGradient(h.middleBase.x, h.middleBase.y, 10, h.middleBase.x, h.middleBase.y, auraSize);
             grad.addColorStop(0, theme.core);
             grad.addColorStop(0.4, theme.primary);
             grad.addColorStop(1, 'rgba(0,0,0,0)');

             ctx.save();
             ctx.fillStyle = grad;
             ctx.globalAlpha = 0.5;
             ctx.beginPath();
             ctx.arc(h.middleBase.x, h.middleBase.y, auraSize, 0, Math.PI * 2);
             ctx.fill();
             ctx.restore();

             // Hand Rune
             drawRuneRing(ctx, h.middleBase.x, h.middleBase.y, 40, t*5, theme);
        });

    } else {
        // --- INDIVIDUAL RENDERING MODE ---
        handDataRef.current.forEach((hand) => {
           drawSkeleton(ctx, hand);

           const element = hand.gesture;
           const theme = (element !== 'NEUTRAL' && THEMES[element]) ? THEMES[element] : THEMES['NEUTRAL'];
           const centerX = hand.middleBase.x; 
           const centerY = hand.middleBase.y; 

           if (element !== 'NEUTRAL') {
               // Flash effect
               if (flash > 0.05 && highlightRef.current > 0.05) {
                   ctx.save();
                   ctx.translate(centerX, centerY);
                   const waveSize = 120 + (1 - flash) * 100;
                   ctx.beginPath();
                   ctx.arc(0, 0, waveSize, 0, Math.PI * 2);
                   ctx.lineWidth = 10 * flash;
                   ctx.strokeStyle = theme.core;
                   ctx.shadowBlur = 20;
                   ctx.shadowColor = theme.secondary;
                   ctx.globalAlpha = flash;
                   ctx.stroke();
                   ctx.restore();
               }

               drawRuneRing(ctx, centerX, centerY, 120, t * 0.5, theme);
               drawSacredGeometry(ctx, centerX, centerY, 90, -t * 1.5, theme);
               drawSquareLayer(ctx, centerX, centerY, 65, t * 2.5, theme);
               const pulse = Math.sin(time * 0.005) * 0.5 + 0.5;
               drawPentagram(ctx, centerX, centerY, 40, t, pulse, theme);

               spawnParticles(centerX, centerY, element, theme);
               lastCenterX = centerX;
               lastCenterY = centerY;
           } else {
               ctx.globalAlpha = 0.3;
               drawRuneRing(ctx, centerX, centerY, 50, t * 0.2, theme);
           }
        });
    }

    updateParticles(ctx, canvas.width, canvas.height, lastCenterX, lastCenterY, null);
    requestRef.current = requestAnimationFrame(animate);
  }, [width, height]);

  useEffect(() => {
    requestRef.current = requestAnimationFrame(animate);
    return () => { if (requestRef.current) cancelAnimationFrame(requestRef.current); };
  }, [animate]);

  return (
    <div className="relative w-full h-full bg-black overflow-hidden flex items-center justify-center">
        <Webcam
          ref={webcamRef}
          audio={false}
          width={width}
          height={height}
          mirrored={true}
          screenshotFormat="image/jpeg"
          className="absolute opacity-0 pointer-events-none" 
        />
        <Webcam
          audio={false}
          width={width}
          height={height}
          mirrored={true}
          className="absolute top-0 left-0 w-full h-full object-cover opacity-80"
        />
        <canvas
          ref={canvasRef}
          width={width}
          height={height}
          className="absolute top-0 left-0 w-full h-full object-cover z-10"
        />

        {!isModelLoaded && (
            <div className="absolute inset-0 flex items-center justify-center bg-black bg-opacity-80 z-50">
                <div className="text-amber-500 font-mono text-xl animate-pulse">
                    Summoning Grimoire... (Loading Models)
                </div>
            </div>
        )}

        <div className="absolute top-4 right-4 text-right z-20 font-mono pointer-events-none">
            <div className={`text-2xl font-bold mb-2 tracking-widest transition-all duration-300 ${
                highlightRef.current > 0.1 ? 'scale-110' : ''
            } ${
                currentElement === 'FIRE' ? 'text-orange-500' :
                currentElement === 'WATER' ? 'text-blue-500' :
                currentElement === 'WIND' ? 'text-green-400' :
                currentElement === 'THUNDER' ? 'text-purple-500' : 
                currentElement === 'INFERNO' ? 'text-red-600' :
                currentElement === 'BLIZZARD' ? 'text-cyan-300' :
                currentElement === 'VOID' ? 'text-violet-900' :
                'text-amber-500'
            }`}>
                SPELL: {currentElement}
            </div>
            <div className="text-xs text-white opacity-70 space-y-1 mb-2">
                <p>Status: {debugInfo}</p>
            </div>
            <div className="text-xs text-white opacity-70 space-y-1">
                <p>✋ Palm Up: FIRE</p>
                <p>👇 Palm Down: WATER</p>
                <p>👊 Fist: THUNDER</p>
                <p>✌️ Victory: WIND</p>
            </div>
        </div>
    </div>
  );
};

export default MagicOverlay;

export type ElementType = 'NEUTRAL' | 'FIRE' | 'WATER' | 'THUNDER' | 'WIND';
export type ComboType = 'BLIZZARD' | 'PLASMA' | 'STEAM' | 'TEMPEST' | 'INFERNO' | 'VOID';
export type ParticleType = 'ORB' | 'LEAF' | 'SPARK' | 'DROP' | 'MIST' | 'EMBER';

export interface Point {
  x: number;
  y: number;
  z?: number;
}

export interface Particle {
  x: number;
  y: number;
  vx: number;
  vy: number;
  life: number;
  maxLife: number;
  size: number;
  color: string;
  element: ElementType | ComboType;
  type: ParticleType;
  angle: number;           // For rotation (leaves)
  angularVelocity: number; // For rotation speed
}

export interface HandData {
  wrist: Point;
  indexTip: Point;
  middleTip: Point;
  ringTip: Point;
  pinkyTip: Point;
  thumbTip: Point;
  indexBase: Point; 
  middleBase: Point;
  ringBase: Point;
  pinkyBase: Point;
  isOpen: boolean;
  gesture: ElementType;
  opacity: number;
}

export interface Theme {
  primary: string;
  secondary: string;
  core: string;
  shadow: string;
}

import React, { useEffect, useRef, useCallback, useState } from 'react';
import Webcam from 'react-webcam';
import { Particle, HandData, ElementType, Theme, ParticleType } from '../types';
import { 
  drawRuneRing, 
  drawSacredGeometry, 
  drawSquareLayer, 
  drawPentagram,
  THEMES
} from '../utils/geometry';

interface MagicOverlayProps {
  width: number;
  height: number;
}

const COMBO_THEMES: Record<string, Theme> = {
  'BLIZZARD': { primary: '#00FFFF', secondary: '#E0FFFF', core: '#FFFFFF', shadow: '#008B8B' },
  'PLASMA': { primary: '#FF00FF', secondary: '#9400D3', core: '#FFFFFF', shadow: '#4B0082' },
  'STEAM': { primary: '#B0C4DE', secondary: '#F0F8FF', core: '#FFFFFF', shadow: '#778899' },
  'TEMPEST': { primary: '#000080', secondary: '#4169E1', core: '#00BFFF', shadow: '#191970' },
  'INFERNO': { primary: '#8B0000', secondary: '#FF4500', core: '#FFFF00', shadow: '#FF0000' },
  'VOID': { primary: '#000000', secondary: '#4B0082', core: '#FFFFFF', shadow: '#9400D3' },
};

const getCombo = (g1: ElementType, g2: ElementType): string | null => {
    const sorted = [g1, g2].sort().join('_');
    switch(sorted) {
        case 'WATER_WIND': return 'BLIZZARD';
        case 'FIRE_WIND': return 'PLASMA';
        case 'FIRE_WATER': return 'STEAM';
        case 'THUNDER_WATER': return 'TEMPEST';
        case 'FIRE_FIRE': return 'INFERNO';
        case 'THUNDER_THUNDER': return 'VOID';
        default: return null;
    }
};

const MagicOverlay: React.FC<MagicOverlayProps> = ({ width, height }) => {
  const webcamRef = useRef<Webcam>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>(0);
  const particlesRef = useRef<Particle[]>([]);
  const handDataRef = useRef<HandData[]>([]);
  const [currentElement, setCurrentElement] = useState<string>('NEUTRAL');
  const [isModelLoaded, setIsModelLoaded] = useState(false);
  const [debugInfo, setDebugInfo] = useState<string>("Initializing...");

  // Visual Feedback State
  const highlightRef = useRef<number>(0);
  const prevElementRef = useRef<string>('NEUTRAL');
  const activeComboRef = useRef<string | null>(null);

  // Audio Context
  const audioContextRef = useRef<AudioContext | null>(null);

  useEffect(() => {
    const AudioContextClass = (window as any).AudioContext || (window as any).webkitAudioContext;
    if (AudioContextClass) {
        audioContextRef.current = new AudioContextClass();
    }
  }, []);

  const playChime = useCallback((element: string) => {
    if (!audioContextRef.current) return;
    const ctx = audioContextRef.current;
    if (ctx.state === 'suspended') {
        ctx.resume().catch(console.error);
    }

    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.connect(gain);
    gain.connect(ctx.destination);

    let freq = 440;
    let type: OscillatorType = 'sine';
    let duration = 0.5;

    switch (element) {
        case 'FIRE': 
        case 'INFERNO':
            freq = 220; type = 'sawtooth'; 
            osc.frequency.setValueAtTime(freq, ctx.currentTime);
            osc.frequency.exponentialRampToValueAtTime(freq * 3, ctx.currentTime + 0.3);
            break;
        case 'WATER': 
        case 'STEAM':
            freq = 600; type = 'sine';
            osc.frequency.setValueAtTime(freq, ctx.currentTime);
            osc.frequency.exponentialRampToValueAtTime(200, ctx.currentTime + 0.2);
            duration = 0.3;
            break;
        case 'THUNDER': 
        case 'TEMPEST':
        case 'VOID':
            freq = 150; type = 'square';
            osc.frequency.setValueAtTime(freq, ctx.currentTime);
            osc.frequency.linearRampToValueAtTime(freq * 0.8, ctx.currentTime + 0.1);
            break;
        case 'WIND': 
        case 'BLIZZARD':
        case 'PLASMA':
            freq = 880; type = 'triangle';
            osc.frequency.setValueAtTime(freq, ctx.currentTime);
            break;
    }

    osc.type = type;
    const now = ctx.currentTime;
    gain.gain.setValueAtTime(0, now);
    gain.gain.linearRampToValueAtTime(0.05, now + 0.05);
    gain.gain.exponentialRampToValueAtTime(0.001, now + duration);
    osc.start(now);
    osc.stop(now + duration);
  }, []);

  const detectGesture = (landmarks: any[], videoWidth: number, videoHeight: number): ElementType => {
    const mapPt = (idx: number) => ({ x: (1 - landmarks[idx].x) * videoWidth, y: landmarks[idx].y * videoHeight });
    const wrist = mapPt(0);
    const indexTip = mapPt(8);
    const middleTip = mapPt(12);
    const ringTip = mapPt(16);
    const pinkyTip = mapPt(20);
    const indexMCP = mapPt(5);
    const middleMCP = mapPt(9);

    const dist = (p1: any, p2: any) => Math.hypot(p1.x - p2.x, p1.y - p2.y);
    const isFingerOpen = (tip: any, mcp: any) => dist(tip, wrist) > dist(mcp, wrist) * 1.1;

    const indexOpen = isFingerOpen(indexTip, indexMCP);
    const middleOpen = isFingerOpen(middleTip, middleMCP);
    const ringOpen = isFingerOpen(ringTip, ringMCP);
    const pinkyOpen = isFingerOpen(pinkyTip, wrist); // Compare to wrist for pinky
    const isPointingDown = wrist.y < middleMCP.y;

    if (!indexOpen && !middleOpen && !ringOpen && !pinkyOpen) return 'THUNDER';
    if (indexOpen && middleOpen && !ringOpen && !pinkyOpen) return 'WIND';
    if (isPointingDown && (indexOpen || middleOpen)) return 'WATER';
    if (!isPointingDown && indexOpen && middleOpen && ringOpen) return 'FIRE';

    return 'NEUTRAL';
  };

  const drawSkeleton = (ctx: CanvasRenderingContext2D, hand: HandData) => {
      ctx.strokeStyle = "rgba(255, 255, 255, 0.2)";
      ctx.lineWidth = 1;
      ctx.fillStyle = "rgba(255, 255, 255, 0.4)";
      const points = [hand.wrist, hand.indexBase, hand.indexTip, hand.middleBase, hand.middleTip, hand.ringBase, hand.ringTip, hand.pinkyBase, hand.pinkyTip, hand.thumbTip];

      const drawLine = (p1: any, p2: any) => { ctx.beginPath(); ctx.moveTo(p1.x, p1.y); ctx.lineTo(p2.x, p2.y); ctx.stroke(); }
      drawLine(hand.wrist, hand.indexBase); drawLine(hand.indexBase, hand.indexTip);
      drawLine(hand.wrist, hand.middleBase); drawLine(hand.middleBase, hand.middleTip);
      drawLine(hand.wrist, hand.pinkyBase); drawLine(hand.pinkyBase, hand.pinkyTip);

      points.forEach(p => { ctx.beginPath(); ctx.arc(p.x, p.y, 2, 0, Math.PI * 2); ctx.fill(); });
  };

  const onResults = useCallback((results: any) => {
    const videoWidth = webcamRef.current?.video?.videoWidth || width;
    const videoHeight = webcamRef.current?.video?.videoHeight || height;

    if (results.multiHandLandmarks && results.multiHandLandmarks.length > 0) {
      setDebugInfo(`Hands: ${results.multiHandLandmarks.length}`);
      const newHandData: HandData[] = results.multiHandLandmarks.map((landmarks: any[]) => {
        const gesture = detectGesture(landmarks, videoWidth, videoHeight);
        const mapPt = (idx: number) => ({ x: (1 - landmarks[idx].x) * videoWidth, y: landmarks[idx].y * videoHeight });
        return {
          wrist: mapPt(0), indexTip: mapPt(8), middleTip: mapPt(12), ringTip: mapPt(16), pinkyTip: mapPt(20), thumbTip: mapPt(4),
          indexBase: mapPt(5), middleBase: mapPt(9), ringBase: mapPt(13), pinkyBase: mapPt(17),
          isOpen: gesture !== 'THUNDER', gesture, opacity: 1,
        };
      });

      handDataRef.current = newHandData;
      let newElement = 'NEUTRAL';
      let activeCombo = null;

      if (newHandData.length === 2) {
          const g1 = newHandData[0].gesture;
          const g2 = newHandData[1].gesture;
          if (g1 !== 'NEUTRAL' && g2 !== 'NEUTRAL') activeCombo = getCombo(g1, g2);
      }

      if (activeCombo) newElement = activeCombo;
      else {
          const activeHand = newHandData.find(h => h.gesture !== 'NEUTRAL');
          if (activeHand) newElement = activeHand.gesture;
      }
      activeComboRef.current = activeCombo;

      if (newElement !== prevElementRef.current) {
          if (newElement !== 'NEUTRAL') { highlightRef.current = 1.0; playChime(newElement); }
          prevElementRef.current = newElement;
      }
      setCurrentElement(newElement);
    } else {
      handDataRef.current = [];
      setDebugInfo("No Hands");
      activeComboRef.current = null;
      if (prevElementRef.current !== 'NEUTRAL') { prevElementRef.current = 'NEUTRAL'; setCurrentElement('NEUTRAL'); }
    }
  }, [width, height, playChime]);

  useEffect(() => {
    let hands: any = null;
    let isActive = true;
    let frameId: number;
    let lastVideoTime = -1;

    const initHands = async () => {
       if (!(window as any).Hands) { setTimeout(initHands, 500); return; }
       hands = new (window as any).Hands({ locateFile: (file: string) => `https://cdn.jsdelivr.net/npm/@mediapipe/hands@0.4.1675469240/${file}` });
       hands.setOptions({ maxNumHands: 2, modelComplexity: 1, minDetectionConfidence: 0.5, minTrackingConfidence: 0.5 });
       hands.onResults(onResults);
       setIsModelLoaded(true);
       const processVideo = async () => {
         if (!isActive) return;
         if (webcamRef.current && webcamRef.current.video && webcamRef.current.video.readyState === 4) {
             const video = webcamRef.current.video;
             if (video.currentTime !== lastVideoTime) {
                 lastVideoTime = video.currentTime;
                 try { await hands.send({ image: video }); } catch (e) { console.error("MediaPipe error:", e); }
             }
         }
         frameId = requestAnimationFrame(processVideo);
       };
       processVideo();
    };
    initHands();
    return () => { isActive = false; if (frameId) cancelAnimationFrame(frameId); if (hands) hands.close(); };
  }, [onResults]);

  // --- PHYSICS ENGINE ---
  const updateParticles = (ctx: CanvasRenderingContext2D, width: number, height: number, centerX: number, centerY: number) => {
    for (let i = particlesRef.current.length - 1; i >= 0; i--) {
      const p = particlesRef.current[i];

      // General Drag
      p.vx *= 0.95;
      p.vy *= 0.95;

      // Element Specific Physics
      switch (p.element) {
          case 'WIND':
          case 'BLIZZARD':
              // Vortex/Spiral Physics
              const dx = p.x - centerX;
              const dy = p.y - centerY;
              const dist = Math.sqrt(dx*dx + dy*dy) + 1;
              const angle = Math.atan2(dy, dx);
              // Tangential force (Rotation)
              p.vx += Math.cos(angle + Math.PI/2) * 1.5;
              p.vy += Math.sin(angle + Math.PI/2) * 1.5;
              // Centripetal force (Suck in)
              p.vx -= (dx / dist) * 0.5;
              p.vy -= (dy / dist) * 0.5;
              p.angle += p.angularVelocity; // Spin the leaf
              break;

          case 'WATER':
          case 'STEAM':
              // Gravity & Rain
              p.vy += 1.2; // Strong gravity
              p.x += Math.sin(p.life * 0.1) * 0.5; // Slight waver
              break;

          case 'THUNDER':
          case 'TEMPEST':
          case 'VOID':
              // Chaotic / Jitter
              p.vx += (Math.random() - 0.5) * 4;
              p.vy += (Math.random() - 0.5) * 4;
              if (Math.random() < 0.1) { // Lightning jump
                  p.x += (Math.random() - 0.5) * 20;
                  p.y += (Math.random() - 0.5) * 20;
              }
              break;

          case 'FIRE':
          case 'INFERNO':
              // Thermal Lift / Turbulence
              p.vy -= 0.6; // Rise
              p.vx += (Math.random() - 0.5) * 1.5; // Turbulence
              p.size *= 0.96; // Shrink faster
              break;

          default:
              p.vy -= 0.1; // Neutral float
      }

      p.x += p.vx;
      p.y += p.vy;
      p.life -= 1;
      if (p.element !== 'FIRE') p.size *= 0.98;

      if (p.life <= 0 || p.size < 0.2 || p.y > height + 50) {
        particlesRef.current.splice(i, 1);
      } else {
        // --- RENDERER ---
        ctx.save();
        ctx.globalAlpha = Math.min(1, p.life / 20);

        if (p.type === 'LEAF') {
            ctx.translate(p.x, p.y);
            ctx.rotate(p.angle);
            ctx.fillStyle = p.color;
            ctx.beginPath();
            ctx.ellipse(0, 0, p.size, p.size * 0.4, 0, 0, Math.PI * 2);
            ctx.fill();
        } 
        else if (p.type === 'DROP') {
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 2;
            ctx.lineCap = 'round';
            ctx.beginPath();
            ctx.moveTo(p.x, p.y);
            // Stretch rain drop based on velocity
            ctx.lineTo(p.x - p.vx, p.y - p.vy * 3); 
            ctx.stroke();
        }
        else if (p.type === 'SPARK') {
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 2;
            ctx.shadowColor = p.color;
            ctx.shadowBlur = 10;
            ctx.beginPath();
            ctx.moveTo(p.x - p.vx, p.y - p.vy);
            ctx.lineTo(p.x + p.vx, p.y + p.vy);
            ctx.stroke();
            // Occasional cross-bolt
            if (Math.random() > 0.5) {
                ctx.beginPath();
                ctx.moveTo(p.x, p.y);
                ctx.lineTo(p.x + (Math.random()-0.5)*20, p.y + (Math.random()-0.5)*20);
                ctx.stroke();
            }
        }
        else if (p.type === 'EMBER') {
            ctx.fillStyle = p.color;
            ctx.shadowColor = 'orange';
            ctx.shadowBlur = 15;
            ctx.beginPath();
            ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
            ctx.fill();
        }
        else { // ORB / MIST
            ctx.fillStyle = p.color;
            ctx.shadowColor = p.color;
            ctx.shadowBlur = p.type === 'ORB' ? 10 : 0;
            ctx.beginPath();
            ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
            ctx.fill();
        }
        ctx.restore();
      }
    }
  };

  const spawnParticles = (x: number, y: number, element: string, theme: Theme) => {
    let count = 3;
    let type: ParticleType = 'ORB';
    let speed = Math.random() * 5;
    let spread = 20;

    // Customize Spawn based on Element
    if (element === 'WIND' || element === 'BLIZZARD') {
        type = Math.random() > 0.5 ? 'LEAF' : 'MIST';
        count = 4;
    } else if (element === 'WATER' || element === 'STEAM') {
        type = Math.random() > 0.7 ? 'MIST' : 'DROP';
        count = 5;
        spread = 40; // Wide rain area
    } else if (element === 'THUNDER' || element === 'TEMPEST' || element === 'VOID') {
        type = 'SPARK';
        count = 2; // Fewer but erratic
        speed = 8;
    } else if (element === 'FIRE' || element === 'INFERNO') {
        type = Math.random() > 0.8 ? 'MIST' : 'EMBER';
        count = 4;
    }

    for (let i = 0; i < count; i++) {
      const angle = Math.random() * Math.PI * 2;
      let vx = Math.cos(angle) * speed;
      let vy = Math.sin(angle) * speed;

      // Initial velocity overrides
      if (element === 'WATER' || element === 'STEAM') { vx *= 0.2; vy = Math.random() * 2; } // Start falling

      // Color tweaks
      let color = Math.random() > 0.5 ? theme.primary : theme.secondary;
      if (element === 'WIND') color = Math.random() > 0.5 ? '#00FFFF' : '#F0FFF0'; // Cyan/White
      if (element === 'THUNDER') color = Math.random() > 0.5 ? '#FFFF00' : '#9400D3'; // Yellow/Purple

      particlesRef.current.push({
        x: x + (Math.random() - 0.5) * spread,
        y: y + (Math.random() - 0.5) * spread,
        vx, vy,
        life: 30 + Math.random() * 30,
        maxLife: 60,
        size: 3 + Math.random() * 5,
        color,
        element: element as Particle['element'],
        type,
        angle: Math.random() * Math.PI * 2,
        angularVelocity: (Math.random() - 0.5) * 0.2
      });
    }
  };

  const animate = useCallback((time: number) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (highlightRef.current > 0.01) highlightRef.current *= 0.9;
    else highlightRef.current = 0;
    const flash = highlightRef.current;

    // Use 'lighter' for high-energy anime look
    ctx.globalCompositeOperation = 'lighter'; 

    let lastCenterX = width / 2;
    let lastCenterY = height / 2;
    const t = time * 0.001;

    // Check for active combo
    const comboName = activeComboRef.current;

    if (comboName && handDataRef.current.length === 2) {
        // --- COMBO MODE ---
        const h1 = handDataRef.current[0];
        const h2 = handDataRef.current[1];
        const theme = COMBO_THEMES[comboName];

        const midX = (h1.middleBase.x + h2.middleBase.x) / 2;
        const midY = (h1.middleBase.y + h2.middleBase.y) / 2;
        lastCenterX = midX;
        lastCenterY = midY;

        // 1. Base Beam
        ctx.save();
        ctx.beginPath();
        ctx.moveTo(h1.middleBase.x, h1.middleBase.y);
        ctx.lineTo(h2.middleBase.x, h2.middleBase.y);
        ctx.strokeStyle = theme.primary;
        ctx.lineWidth = 20 + Math.sin(t * 10) * 5; 
        ctx.lineCap = 'round';
        ctx.shadowBlur = 40;
        ctx.shadowColor = theme.secondary;
        ctx.globalAlpha = 0.4;
        ctx.stroke();
        ctx.restore();

        // 2. Converging Energy
        ctx.save();
        ctx.beginPath();
        ctx.moveTo(h1.middleBase.x, h1.middleBase.y);
        ctx.lineTo(h2.middleBase.x, h2.middleBase.y);
        ctx.strokeStyle = '#FFFFFF';
        ctx.lineWidth = 3;
        ctx.setLineDash([10, 40]);
        ctx.lineDashOffset = -t * 200; 
        ctx.globalCompositeOperation = 'overlay';
        ctx.stroke();
        ctx.restore();

        // 3. Electric Arcs
        ctx.save();
        ctx.beginPath();
        ctx.moveTo(h1.middleBase.x, h1.middleBase.y);
        const dist = Math.hypot(h2.middleBase.x - h1.middleBase.x, h2.middleBase.y - h1.middleBase.y);
        const angle = Math.atan2(h2.middleBase.y - h1.middleBase.y, h2.middleBase.x - h1.middleBase.x);
        for(let i=0; i<=20; i++) {
             const p = i/20;
             const perp = Math.sin(p * Math.PI * 4 + t * 20) * (15 + Math.random() * 5);
             const bx = h1.middleBase.x + (h2.middleBase.x - h1.middleBase.x) * p + Math.cos(angle + Math.PI/2)*perp;
             const by = h1.middleBase.y + (h2.middleBase.y - h1.middleBase.y) * p + Math.sin(angle + Math.PI/2)*perp;
             ctx.lineTo(bx, by);
        }
        ctx.strokeStyle = theme.secondary;
        ctx.lineWidth = 2;
        ctx.shadowBlur = 10;
        ctx.shadowColor = theme.core;
        ctx.stroke();
        ctx.restore();

        // Array
        ctx.globalAlpha = 1;
        drawRuneRing(ctx, midX, midY, 180, t, theme);
        drawSacredGeometry(ctx, midX, midY, 140, -t * 2, theme);
        drawSquareLayer(ctx, midX, midY, 100, t * 3, theme);
        drawPentagram(ctx, midX, midY, 60, -t, 1, theme);

        spawnParticles(midX, midY, comboName, theme);

        handDataRef.current.forEach(h => {
             drawSkeleton(ctx, h);
             const auraSize = 50 + Math.sin(t * 20) * 10;
             const grad = ctx.createRadialGradient(h.middleBase.x, h.middleBase.y, 10, h.middleBase.x, h.middleBase.y, auraSize);
             grad.addColorStop(0, theme.core);
             grad.addColorStop(0.4, theme.primary);
             grad.addColorStop(1, 'rgba(0,0,0,0)');
             ctx.save();
             ctx.fillStyle = grad;
             ctx.globalAlpha = 0.5;
             ctx.beginPath();
             ctx.arc(h.middleBase.x, h.middleBase.y, auraSize, 0, Math.PI * 2);
             ctx.fill();
             ctx.restore();
             drawRuneRing(ctx, h.middleBase.x, h.middleBase.y, 40, t*5, theme);
        });

    } else {
        // --- INDIVIDUAL MODE ---
        handDataRef.current.forEach((hand) => {
           drawSkeleton(ctx, hand);
           const element = hand.gesture;
           const theme = (element !== 'NEUTRAL' && THEMES[element]) ? THEMES[element] : THEMES['NEUTRAL'];
           const centerX = hand.middleBase.x; 
           const centerY = hand.middleBase.y; 

           if (element !== 'NEUTRAL') {
               if (flash > 0.05 && highlightRef.current > 0.05) {
                   ctx.save();
                   ctx.translate(centerX, centerY);
                   const waveSize = 120 + (1 - flash) * 100;
                   ctx.beginPath();
                   ctx.arc(0, 0, waveSize, 0, Math.PI * 2);
                   ctx.lineWidth = 10 * flash;
                   ctx.strokeStyle = theme.core;
                   ctx.shadowBlur = 20;
                   ctx.shadowColor = theme.secondary;
                   ctx.globalAlpha = flash;
                   ctx.stroke();
                   ctx.restore();
               }

               drawRuneRing(ctx, centerX, centerY, 120, t * 0.5, theme);
               drawSacredGeometry(ctx, centerX, centerY, 90, -t * 1.5, theme);
               drawSquareLayer(ctx, centerX, centerY, 65, t * 2.5, theme);
               const pulse = Math.sin(time * 0.005) * 0.5 + 0.5;
               drawPentagram(ctx, centerX, centerY, 40, t, pulse, theme);

               spawnParticles(centerX, centerY, element, theme);
               lastCenterX = centerX;
               lastCenterY = centerY;
           } else {
               ctx.globalAlpha = 0.3;
               drawRuneRing(ctx, centerX, centerY, 50, t * 0.2, theme);
           }
        });
    }

    updateParticles(ctx, canvas.width, canvas.height, lastCenterX, lastCenterY);
    requestRef.current = requestAnimationFrame(animate);
  }, [width, height]);

  useEffect(() => {
    requestRef.current = requestAnimationFrame(animate);
    return () => { if (requestRef.current) cancelAnimationFrame(requestRef.current); };
  }, [animate]);

  return (
    <div className="relative w-full h-full bg-black overflow-hidden flex items-center justify-center">
        <Webcam ref={webcamRef} audio={false} width={width} height={height} mirrored={true} screenshotFormat="image/jpeg" className="absolute opacity-0 pointer-events-none" />
        <Webcam audio={false} width={width} height={height} mirrored={true} className="absolute top-0 left-0 w-full h-full object-cover opacity-80" />
        <canvas ref={canvasRef} width={width} height={height} className="absolute top-0 left-0 w-full h-full object-cover z-10" />
        {!isModelLoaded && (
            <div className="absolute inset-0 flex items-center justify-center bg-black bg-opacity-80 z-50">
                <div className="text-amber-500 font-mono text-xl animate-pulse">Summoning Grimoire... (Loading Models)</div>
            </div>
        )}
        <div className="absolute top-4 right-4 text-right z-20 font-mono pointer-events-none">
            <div className={`text-2xl font-bold mb-2 tracking-widest transition-all duration-300 ${highlightRef.current > 0.1 ? 'scale-110' : ''} ${
                currentElement === 'FIRE' ? 'text-orange-500' :
                currentElement === 'WATER' ? 'text-blue-500' :
                currentElement === 'WIND' ? 'text-cyan-300' :
                currentElement === 'THUNDER' ? 'text-purple-500' : 
                currentElement === 'INFERNO' ? 'text-red-600' :
                currentElement === 'BLIZZARD' ? 'text-cyan-100' :
                currentElement === 'VOID' ? 'text-violet-900' : 'text-amber-500'
            }`}>SPELL: {currentElement}</div>
            <div className="text-xs text-white opacity-70 space-y-1 mb-2"><p>Status: {debugInfo}</p></div>
            <div className="text-xs text-white opacity-70 space-y-1">
                <p>✋ Palm Up: FIRE</p>
                <p>👇 Palm Down: WATER (RAIN)</p>
                <p>👊 Fist: THUNDER</p>
                <p>✌️ Victory: WIND</p>
            </div>
        </div>
    </div>
  );
};

export default MagicOverlay;

import React, { useEffect, useRef, useCallback, useState } from 'react';
import Webcam from 'react-webcam';
import { Particle, HandData, ElementType, Theme, ParticleType } from '../types';
import { 
  drawRuneRing, 
  drawSacredGeometry, 
  drawSquareLayer, 
  drawPentagram,
  THEMES
} from '../utils/geometry';

interface MagicOverlayProps {
  width: number;
  height: number;
}

const COMBO_THEMES: Record<string, Theme> = {
  'BLIZZARD': { primary: '#00FFFF', secondary: '#E0FFFF', core: '#FFFFFF', shadow: '#008B8B' },
  'PLASMA': { primary: '#FF00FF', secondary: '#9400D3', core: '#FFFFFF', shadow: '#4B0082' },
  'STEAM': { primary: '#B0C4DE', secondary: '#F0F8FF', core: '#FFFFFF', shadow: '#778899' },
  'TEMPEST': { primary: '#000080', secondary: '#4169E1', core: '#00BFFF', shadow: '#191970' },
  'INFERNO': { primary: '#8B0000', secondary: '#FF4500', core: '#FFFF00', shadow: '#FF0000' },
  'VOID': { primary: '#000000', secondary: '#4B0082', core: '#FFFFFF', shadow: '#9400D3' },
};

const getCombo = (g1: ElementType, g2: ElementType): string | null => {
    const sorted = [g1, g2].sort().join('_');
    switch(sorted) {
        case 'WATER_WIND': return 'BLIZZARD';
        case 'FIRE_WIND': return 'PLASMA';
        case 'FIRE_WATER': return 'STEAM';
        case 'THUNDER_WATER': return 'TEMPEST';
        case 'FIRE_FIRE': return 'INFERNO';
        case 'THUNDER_THUNDER': return 'VOID';
        default: return null;
    }
};

const MagicOverlay: React.FC<MagicOverlayProps> = ({ width, height }) => {
  const webcamRef = useRef<Webcam>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>(0);
  const particlesRef = useRef<Particle[]>([]);
  const handDataRef = useRef<HandData[]>([]);
  const [currentElement, setCurrentElement] = useState<string>('NEUTRAL');
  const [isModelLoaded, setIsModelLoaded] = useState(false);
  const [debugInfo, setDebugInfo] = useState<string>("Initializing...");

  // Visual Feedback State
  const highlightRef = useRef<number>(0);
  const prevElementRef = useRef<string>('NEUTRAL');
  const activeComboRef = useRef<string | null>(null);

  // Audio Context
  const audioContextRef = useRef<AudioContext | null>(null);

  useEffect(() => {
    const AudioContextClass = (window as any).AudioContext || (window as any).webkitAudioContext;
    if (AudioContextClass) {
        audioContextRef.current = new AudioContextClass();
    }
  }, []);

  const playChime = useCallback((element: string) => {
    if (!audioContextRef.current) return;
    const ctx = audioContextRef.current;
    if (ctx.state === 'suspended') {
        ctx.resume().catch(console.error);
    }

    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.connect(gain);
    gain.connect(ctx.destination);

    let freq = 440;
    let type: OscillatorType = 'sine';
    let duration = 0.5;

    switch (element) {
        case 'FIRE': 
        case 'INFERNO':
            freq = 220; type = 'sawtooth'; 
            osc.frequency.setValueAtTime(freq, ctx.currentTime);
            osc.frequency.exponentialRampToValueAtTime(freq * 3, ctx.currentTime + 0.3);
            break;
        case 'WATER': 
        case 'STEAM':
            freq = 600; type = 'sine';
            osc.frequency.setValueAtTime(freq, ctx.currentTime);
            osc.frequency.exponentialRampToValueAtTime(200, ctx.currentTime + 0.2);
            duration = 0.3;
            break;
        case 'THUNDER': 
        case 'TEMPEST':
        case 'VOID':
            freq = 150; type = 'square';
            osc.frequency.setValueAtTime(freq, ctx.currentTime);
            osc.frequency.linearRampToValueAtTime(freq * 0.8, ctx.currentTime + 0.1);
            break;
        case 'WIND': 
        case 'BLIZZARD':
        case 'PLASMA':
            freq = 880; type = 'triangle';
            osc.frequency.setValueAtTime(freq, ctx.currentTime);
            break;
    }

    osc.type = type;
    const now = ctx.currentTime;
    gain.gain.setValueAtTime(0, now);
    gain.gain.linearRampToValueAtTime(0.05, now + 0.05);
    gain.gain.exponentialRampToValueAtTime(0.001, now + duration);
    osc.start(now);
    osc.stop(now + duration);
  }, []);

  const detectGesture = (landmarks: any[], videoWidth: number, videoHeight: number): ElementType => {
    const mapPt = (idx: number) => ({ x: (1 - landmarks[idx].x) * videoWidth, y: landmarks[idx].y * videoHeight });
    const wrist = mapPt(0);
    const indexTip = mapPt(8);
    const middleTip = mapPt(12);
    const ringTip = mapPt(16);
    const pinkyTip = mapPt(20);
    const indexMCP = mapPt(5);
    const middleMCP = mapPt(9);
    const ringMCP = mapPt(13);

    const dist = (p1: any, p2: any) => Math.hypot(p1.x - p2.x, p1.y - p2.y);
    const isFingerOpen = (tip: any, mcp: any) => dist(tip, wrist) > dist(mcp, wrist) * 1.1;

    const indexOpen = isFingerOpen(indexTip, indexMCP);
    const middleOpen = isFingerOpen(middleTip, middleMCP);
    const ringOpen = isFingerOpen(ringTip, ringMCP);
    const pinkyOpen = isFingerOpen(pinkyTip, wrist); // Compare to wrist for pinky
    const isPointingDown = wrist.y < middleMCP.y;

    if (!indexOpen && !middleOpen && !ringOpen && !pinkyOpen) return 'THUNDER';
    if (indexOpen && middleOpen && !ringOpen && !pinkyOpen) return 'WIND';
    if (isPointingDown && (indexOpen || middleOpen)) return 'WATER';
    if (!isPointingDown && indexOpen && middleOpen && ringOpen) return 'FIRE';

    return 'NEUTRAL';
  };

  const drawSkeleton = (ctx: CanvasRenderingContext2D, hand: HandData) => {
      ctx.strokeStyle = "rgba(255, 255, 255, 0.2)";
      ctx.lineWidth = 1;
      ctx.fillStyle = "rgba(255, 255, 255, 0.4)";
      const points = [hand.wrist, hand.indexBase, hand.indexTip, hand.middleBase, hand.middleTip, hand.ringBase, hand.ringTip, hand.pinkyBase, hand.pinkyTip, hand.thumbTip];

      const drawLine = (p1: any, p2: any) => { ctx.beginPath(); ctx.moveTo(p1.x, p1.y); ctx.lineTo(p2.x, p2.y); ctx.stroke(); }
      drawLine(hand.wrist, hand.indexBase); drawLine(hand.indexBase, hand.indexTip);
      drawLine(hand.wrist, hand.middleBase); drawLine(hand.middleBase, hand.middleTip);
      drawLine(hand.wrist, hand.pinkyBase); drawLine(hand.pinkyBase, hand.pinkyTip);

      points.forEach(p => { ctx.beginPath(); ctx.arc(p.x, p.y, 2, 0, Math.PI * 2); ctx.fill(); });
  };

  const onResults = useCallback((results: any) => {
    const videoWidth = webcamRef.current?.video?.videoWidth || width;
    const videoHeight = webcamRef.current?.video?.videoHeight || height;

    if (results.multiHandLandmarks && results.multiHandLandmarks.length > 0) {
      setDebugInfo(`Hands: ${results.multiHandLandmarks.length}`);
      const newHandData: HandData[] = results.multiHandLandmarks.map((landmarks: any[]) => {
        const gesture = detectGesture(landmarks, videoWidth, videoHeight);
        const mapPt = (idx: number) => ({ x: (1 - landmarks[idx].x) * videoWidth, y: landmarks[idx].y * videoHeight });
        return {
          wrist: mapPt(0), indexTip: mapPt(8), middleTip: mapPt(12), ringTip: mapPt(16), pinkyTip: mapPt(20), thumbTip: mapPt(4),
          indexBase: mapPt(5), middleBase: mapPt(9), ringBase: mapPt(13), pinkyBase: mapPt(17),
          isOpen: gesture !== 'THUNDER', gesture, opacity: 1,
        };
      });

      handDataRef.current = newHandData;
      let newElement = 'NEUTRAL';
      let activeCombo = null;

      if (newHandData.length === 2) {
          const g1 = newHandData[0].gesture;
          const g2 = newHandData[1].gesture;
          if (g1 !== 'NEUTRAL' && g2 !== 'NEUTRAL') activeCombo = getCombo(g1, g2);
      }

      if (activeCombo) newElement = activeCombo;
      else {
          const activeHand = newHandData.find(h => h.gesture !== 'NEUTRAL');
          if (activeHand) newElement = activeHand.gesture;
      }
      activeComboRef.current = activeCombo;

      if (newElement !== prevElementRef.current) {
          if (newElement !== 'NEUTRAL') { highlightRef.current = 1.0; playChime(newElement); }
          prevElementRef.current = newElement;
      }
      setCurrentElement(newElement);
    } else {
      handDataRef.current = [];
      setDebugInfo("No Hands");
      activeComboRef.current = null;
      if (prevElementRef.current !== 'NEUTRAL') { prevElementRef.current = 'NEUTRAL'; setCurrentElement('NEUTRAL'); }
    }
  }, [width, height, playChime]);

  useEffect(() => {
    let hands: any = null;
    let isActive = true;
    let frameId: number;
    let lastVideoTime = -1;

    const initHands = async () => {
       if (!(window as any).Hands) { setTimeout(initHands, 500); return; }
       hands = new (window as any).Hands({ locateFile: (file: string) => `https://cdn.jsdelivr.net/npm/@mediapipe/hands@0.4.1675469240/${file}` });
       hands.setOptions({ maxNumHands: 2, modelComplexity: 1, minDetectionConfidence: 0.5, minTrackingConfidence: 0.5 });
       hands.onResults(onResults);
       setIsModelLoaded(true);
       const processVideo = async () => {
         if (!isActive) return;
         if (webcamRef.current && webcamRef.current.video && webcamRef.current.video.readyState === 4) {
             const video = webcamRef.current.video;
             if (video.currentTime !== lastVideoTime) {
                 lastVideoTime = video.currentTime;
                 try { await hands.send({ image: video }); } catch (e) { console.error("MediaPipe error:", e); }
             }
         }
         frameId = requestAnimationFrame(processVideo);
       };
       processVideo();
    };
    initHands();
    return () => { isActive = false; if (frameId) cancelAnimationFrame(frameId); if (hands) hands.close(); };
  }, [onResults]);

  // --- PHYSICS ENGINE ---
  const updateParticles = (ctx: CanvasRenderingContext2D, width: number, height: number, centerX: number, centerY: number) => {
    for (let i = particlesRef.current.length - 1; i >= 0; i--) {
      const p = particlesRef.current[i];

      // General Drag
      p.vx *= 0.95;
      p.vy *= 0.95;

      // Element Specific Physics
      switch (p.element) {
          case 'WIND':
          case 'BLIZZARD':
              // Vortex/Spiral Physics
              const dx = p.x - centerX;
              const dy = p.y - centerY;
              const dist = Math.sqrt(dx*dx + dy*dy) + 1;
              const angle = Math.atan2(dy, dx);
              // Tangential force (Rotation)
              p.vx += Math.cos(angle + Math.PI/2) * 1.5;
              p.vy += Math.sin(angle + Math.PI/2) * 1.5;
              // Centripetal force (Suck in)
              p.vx -= (dx / dist) * 0.5;
              p.vy -= (dy / dist) * 0.5;
              p.angle += p.angularVelocity; // Spin the leaf
              break;

          case 'WATER':
          case 'STEAM':
              // Gravity & Rain
              p.vy += 1.2; // Strong gravity
              p.x += Math.sin(p.life * 0.1) * 0.5; // Slight waver
              break;

          case 'THUNDER':
          case 'TEMPEST':
          case 'VOID':
              // Chaotic / Jitter
              p.vx += (Math.random() - 0.5) * 4;
              p.vy += (Math.random() - 0.5) * 4;
              if (Math.random() < 0.1) { // Lightning jump
                  p.x += (Math.random() - 0.5) * 20;
                  p.y += (Math.random() - 0.5) * 20;
              }
              break;

          case 'FIRE':
          case 'INFERNO':
              // Thermal Lift / Turbulence
              p.vy -= 0.6; // Rise
              p.vx += (Math.random() - 0.5) * 1.5; // Turbulence
              p.size *= 0.96; // Shrink faster
              break;

          default:
              p.vy -= 0.1; // Neutral float
      }

      p.x += p.vx;
      p.y += p.vy;
      p.life -= 1;
      if (p.element !== 'FIRE') p.size *= 0.98;

      if (p.life <= 0 || p.size < 0.2 || p.y > height + 50) {
        particlesRef.current.splice(i, 1);
      } else {
        // --- RENDERER ---
        ctx.save();
        ctx.globalAlpha = Math.min(1, p.life / 20);

        if (p.type === 'LEAF') {
            ctx.translate(p.x, p.y);
            ctx.rotate(p.angle);
            ctx.fillStyle = p.color;
            ctx.beginPath();
            ctx.ellipse(0, 0, p.size, p.size * 0.4, 0, 0, Math.PI * 2);
            ctx.fill();
        } 
        else if (p.type === 'DROP') {
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 2;
            ctx.lineCap = 'round';
            ctx.beginPath();
            ctx.moveTo(p.x, p.y);
            // Stretch rain drop based on velocity
            ctx.lineTo(p.x - p.vx, p.y - p.vy * 3); 
            ctx.stroke();
        }
        else if (p.type === 'SPARK') {
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 2;
            ctx.shadowColor = p.color;
            ctx.shadowBlur = 10;
            ctx.beginPath();
            ctx.moveTo(p.x - p.vx, p.y - p.vy);
            ctx.lineTo(p.x + p.vx, p.y + p.vy);
            ctx.stroke();
            // Occasional cross-bolt
            if (Math.random() > 0.5) {
                ctx.beginPath();
                ctx.moveTo(p.x, p.y);
                ctx.lineTo(p.x + (Math.random()-0.5)*20, p.y + (Math.random()-0.5)*20);
                ctx.stroke();
            }
        }
        else if (p.type === 'EMBER') {
            ctx.fillStyle = p.color;
            ctx.shadowColor = 'orange';
            ctx.shadowBlur = 15;
            ctx.beginPath();
            ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
            ctx.fill();
        }
        else { // ORB / MIST
            ctx.fillStyle = p.color;
            ctx.shadowColor = p.color;
            ctx.shadowBlur = p.type === 'ORB' ? 10 : 0;
            ctx.beginPath();
            ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
            ctx.fill();
        }
        ctx.restore();
      }
    }
  };

  const spawnParticles = (x: number, y: number, element: string, theme: Theme) => {
    let count = 3;
    let type: ParticleType = 'ORB';
    let speed = Math.random() * 5;
    let spread = 20;

    // Customize Spawn based on Element
    if (element === 'WIND' || element === 'BLIZZARD') {
        type = Math.random() > 0.5 ? 'LEAF' : 'MIST';
        count = 4;
    } else if (element === 'WATER' || element === 'STEAM') {
        type = Math.random() > 0.7 ? 'MIST' : 'DROP';
        count = 5;
        spread = 40; // Wide rain area
    } else if (element === 'THUNDER' || element === 'TEMPEST' || element === 'VOID') {
        type = 'SPARK';
        count = 2; // Fewer but erratic
        speed = 8;
    } else if (element === 'FIRE' || element === 'INFERNO') {
        type = Math.random() > 0.8 ? 'MIST' : 'EMBER';
        count = 4;
    }

    for (let i = 0; i < count; i++) {
      const angle = Math.random() * Math.PI * 2;
      let vx = Math.cos(angle) * speed;
      let vy = Math.sin(angle) * speed;

      // Initial velocity overrides
      if (element === 'WATER' || element === 'STEAM') { vx *= 0.2; vy = Math.random() * 2; } // Start falling

      // Color tweaks
      let color = Math.random() > 0.5 ? theme.primary : theme.secondary;
      if (element === 'WIND') color = Math.random() > 0.5 ? '#00FFFF' : '#F0FFF0'; // Cyan/White
      if (element === 'THUNDER') color = Math.random() > 0.5 ? '#FFFF00' : '#9400D3'; // Yellow/Purple

      particlesRef.current.push({
        x: x + (Math.random() - 0.5) * spread,
        y: y + (Math.random() - 0.5) * spread,
        vx, vy,
        life: 30 + Math.random() * 30,
        maxLife: 60,
        size: 3 + Math.random() * 5,
        color,
        element: element as Particle['element'],
        type,
        angle: Math.random() * Math.PI * 2,
        angularVelocity: (Math.random() - 0.5) * 0.2
      });
    }
  };

  const animate = useCallback((time: number) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (highlightRef.current > 0.01) highlightRef.current *= 0.9;
    else highlightRef.current = 0;
    const flash = highlightRef.current;

    // Use 'lighter' for high-energy anime look
    ctx.globalCompositeOperation = 'lighter'; 

    let lastCenterX = width / 2;
    let lastCenterY = height / 2;
    const t = time * 0.001;

    // Check for active combo
    const comboName = activeComboRef.current;

    if (comboName && handDataRef.current.length === 2) {
        // --- COMBO MODE ---
        const h1 = handDataRef.current[0];
        const h2 = handDataRef.current[1];
        const theme = COMBO_THEMES[comboName];

        const midX = (h1.middleBase.x + h2.middleBase.x) / 2;
        const midY = (h1.middleBase.y + h2.middleBase.y) / 2;
        lastCenterX = midX;
        lastCenterY = midY;

        // 1. Base Beam
        ctx.save();
        ctx.beginPath();
        ctx.moveTo(h1.middleBase.x, h1.middleBase.y);
        ctx.lineTo(h2.middleBase.x, h2.middleBase.y);
        ctx.strokeStyle = theme.primary;
        ctx.lineWidth = 20 + Math.sin(t * 10) * 5; 
        ctx.lineCap = 'round';
        ctx.shadowBlur = 40;
        ctx.shadowColor = theme.secondary;
        ctx.globalAlpha = 0.4;
        ctx.stroke();
        ctx.restore();

        // 2. Converging Energy
        ctx.save();
        ctx.beginPath();
        ctx.moveTo(h1.middleBase.x, h1.middleBase.y);
        ctx.lineTo(h2.middleBase.x, h2.middleBase.y);
        ctx.strokeStyle = '#FFFFFF';
        ctx.lineWidth = 3;
        ctx.setLineDash([10, 40]);
        ctx.lineDashOffset = -t * 200; 
        ctx.globalCompositeOperation = 'overlay';
        ctx.stroke();
        ctx.restore();

        // 3. Electric Arcs
        ctx.save();
        ctx.beginPath();
        ctx.moveTo(h1.middleBase.x, h1.middleBase.y);
        const dist = Math.hypot(h2.middleBase.x - h1.middleBase.x, h2.middleBase.y - h1.middleBase.y);
        const angle = Math.atan2(h2.middleBase.y - h1.middleBase.y, h2.middleBase.x - h1.middleBase.x);
        for(let i=0; i<=20; i++) {
             const p = i/20;
             const perp = Math.sin(p * Math.PI * 4 + t * 20) * (15 + Math.random() * 5);
             const bx = h1.middleBase.x + (h2.middleBase.x - h1.middleBase.x) * p + Math.cos(angle + Math.PI/2)*perp;
             const by = h1.middleBase.y + (h2.middleBase.y - h1.middleBase.y) * p + Math.sin(angle + Math.PI/2)*perp;
             ctx.lineTo(bx, by);
        }
        ctx.strokeStyle = theme.secondary;
        ctx.lineWidth = 2;
        ctx.shadowBlur = 10;
        ctx.shadowColor = theme.core;
        ctx.stroke();
        ctx.restore();

        // Array
        ctx.globalAlpha = 1;
        drawRuneRing(ctx, midX, midY, 180, t, theme);
        drawSacredGeometry(ctx, midX, midY, 140, -t * 2, theme);
        drawSquareLayer(ctx, midX, midY, 100, t * 3, theme);
        drawPentagram(ctx, midX, midY, 60, -t, 1, theme);

        spawnParticles(midX, midY, comboName, theme);

        handDataRef.current.forEach(h => {
             drawSkeleton(ctx, h);
             const auraSize = 50 + Math.sin(t * 20) * 10;
             const grad = ctx.createRadialGradient(h.middleBase.x, h.middleBase.y, 10, h.middleBase.x, h.middleBase.y, auraSize);
             grad.addColorStop(0, theme.core);
             grad.addColorStop(0.4, theme.primary);
             grad.addColorStop(1, 'rgba(0,0,0,0)');
             ctx.save();
             ctx.fillStyle = grad;
             ctx.globalAlpha = 0.5;
             ctx.beginPath();
             ctx.arc(h.middleBase.x, h.middleBase.y, auraSize, 0, Math.PI * 2);
             ctx.fill();
             ctx.restore();
             drawRuneRing(ctx, h.middleBase.x, h.middleBase.y, 40, t*5, theme);
        });

    } else {
        // --- INDIVIDUAL MODE ---
        handDataRef.current.forEach((hand) => {
           drawSkeleton(ctx, hand);
           const element = hand.gesture;
           const theme = (element !== 'NEUTRAL' && THEMES[element]) ? THEMES[element] : THEMES['NEUTRAL'];
           const centerX = hand.middleBase.x; 
           const centerY = hand.middleBase.y; 

           if (element !== 'NEUTRAL') {
               if (flash > 0.05 && highlightRef.current > 0.05) {
                   ctx.save();
                   ctx.translate(centerX, centerY);
                   const waveSize = 120 + (1 - flash) * 100;
                   ctx.beginPath();
                   ctx.arc(0, 0, waveSize, 0, Math.PI * 2);
                   ctx.lineWidth = 10 * flash;
                   ctx.strokeStyle = theme.core;
                   ctx.shadowBlur = 20;
                   ctx.shadowColor = theme.secondary;
                   ctx.globalAlpha = flash;
                   ctx.stroke();
                   ctx.restore();
               }

               drawRuneRing(ctx, centerX, centerY, 120, t * 0.5, theme);
               drawSacredGeometry(ctx, centerX, centerY, 90, -t * 1.5, theme);
               drawSquareLayer(ctx, centerX, centerY, 65, t * 2.5, theme);
               const pulse = Math.sin(time * 0.005) * 0.5 + 0.5;
               drawPentagram(ctx, centerX, centerY, 40, t, pulse, theme);

               spawnParticles(centerX, centerY, element, theme);
               lastCenterX = centerX;
               lastCenterY = centerY;
           } else {
               ctx.globalAlpha = 0.3;
               drawRuneRing(ctx, centerX, centerY, 50, t * 0.2, theme);
           }
        });
    }

    updateParticles(ctx, canvas.width, canvas.height, lastCenterX, lastCenterY);
    requestRef.current = requestAnimationFrame(animate);
  }, [width, height]);

  useEffect(() => {
    requestRef.current = requestAnimationFrame(animate);
    return () => { if (requestRef.current) cancelAnimationFrame(requestRef.current); };
  }, [animate]);

  return (
    <div className="relative w-full h-full bg-black overflow-hidden flex items-center justify-center">
        <Webcam ref={webcamRef} audio={false} width={width} height={height} mirrored={true} screenshotFormat="image/jpeg" className="absolute opacity-0 pointer-events-none" />
        <Webcam audio={false} width={width} height={height} mirrored={true} className="absolute top-0 left-0 w-full h-full object-cover opacity-80" />
        <canvas ref={canvasRef} width={width} height={height} className="absolute top-0 left-0 w-full h-full object-cover z-10" />
        {!isModelLoaded && (
            <div className="absolute inset-0 flex items-center justify-center bg-black bg-opacity-80 z-50">
                <div className="text-amber-500 font-mono text-xl animate-pulse">Summoning Grimoire... (Loading Models)</div>
            </div>
        )}
        <div className="absolute top-4 right-4 text-right z-20 font-mono pointer-events-none">
            <div className={`text-2xl font-bold mb-2 tracking-widest transition-all duration-300 ${highlightRef.current > 0.1 ? 'scale-110' : ''} ${
                currentElement === 'FIRE' ? 'text-orange-500' :
                currentElement === 'WATER' ? 'text-blue-500' :
                currentElement === 'WIND' ? 'text-cyan-300' :
                currentElement === 'THUNDER' ? 'text-purple-500' : 
                currentElement === 'INFERNO' ? 'text-red-600' :
                currentElement === 'BLIZZARD' ? 'text-cyan-100' :
                currentElement === 'VOID' ? 'text-violet-900' : 'text-amber-500'
            }`}>SPELL: {currentElement}</div>
            <div className="text-xs text-white opacity-70 space-y-1 mb-2"><p>Status: {debugInfo}</p></div>
            <div className="text-xs text-white opacity-70 space-y-1">
                <p>✋ Palm Up: FIRE</p>
                <p>👇 Palm Down: WATER (RAIN)</p>
                <p>👊 Fist: THUNDER</p>
                <p>✌️ Victory: WIND</p>
            </div>
        </div>
    </div>
  );
};

export default MagicOverlay;

export type ElementType = 'NEUTRAL' | 'FIRE' | 'WATER' | 'THUNDER' | 'WIND';
export type ComboType = 'BLIZZARD' | 'PLASMA' | 'STEAM' | 'TEMPEST' | 'INFERNO' | 'VOID';
export type ParticleType = 'ORB' | 'LEAF' | 'SPARK' | 'DROP' | 'MIST' | 'EMBER';

export interface Point {
  x: number;
  y: number;
  z?: number;
}

export interface Particle {
  x: number;
  y: number;
  vx: number;
  vy: number;
  life: number;
  maxLife: number;
  size: number;
  color: string;
  element: ElementType | ComboType;
  type: ParticleType;
  angle: number;           // For rotation (leaves)
  angularVelocity: number; // For rotation speed
}

export interface HandData {
  wrist: Point;
  indexTip: Point;
  middleTip: Point;
  ringTip: Point;
  pinkyTip: Point;
  thumbTip: Point;
  indexBase: Point; 
  middleBase: Point;
  ringBase: Point;
  pinkyBase: Point;
  isOpen: boolean;
  gesture: ElementType;
  opacity: number;
}

export interface Theme {
  primary: string;
  secondary: string;
  core: string;
  shadow: string;
}

import React, { useEffect, useRef, useCallback, useState } from 'react';
import Webcam from 'react-webcam';
import { Particle, HandData, ElementType, Theme, ParticleType } from '../types';
import { 
  drawRuneRing, 
  drawSacredGeometry, 
  drawSquareLayer, 
  drawPentagram,
  THEMES
} from '../utils/geometry';

interface MagicOverlayProps {
  width: number;
  height: number;
}

const COMBO_THEMES: Record<string, Theme> = {
  'BLIZZARD': { primary: '#00FFFF', secondary: '#E0FFFF', core: '#FFFFFF', shadow: '#008B8B' },
  'PLASMA': { primary: '#FF00FF', secondary: '#9400D3', core: '#FFFFFF', shadow: '#4B0082' },
  'STEAM': { primary: '#B0C4DE', secondary: '#F0F8FF', core: '#FFFFFF', shadow: '#778899' },
  'TEMPEST': { primary: '#000080', secondary: '#4169E1', core: '#00BFFF', shadow: '#191970' },
  'INFERNO': { primary: '#8B0000', secondary: '#FF4500', core: '#FFFF00', shadow: '#FF0000' },
  'VOID': { primary: '#000000', secondary: '#4B0082', core: '#FFFFFF', shadow: '#9400D3' },
};

const getCombo = (g1: ElementType, g2: ElementType): string | null => {
    const sorted = [g1, g2].sort().join('_');
    switch(sorted) {
        case 'WATER_WIND': return 'BLIZZARD';
        case 'FIRE_WIND': return 'PLASMA';
        case 'FIRE_WATER': return 'STEAM';
        case 'THUNDER_WATER': return 'TEMPEST';
        case 'FIRE_FIRE': return 'INFERNO';
        case 'THUNDER_THUNDER': return 'VOID';
        default: return null;
    }
};

const MagicOverlay: React.FC<MagicOverlayProps> = ({ width, height }) => {
  const webcamRef = useRef<Webcam>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>(0);
  const particlesRef = useRef<Particle[]>([]);
  const handDataRef = useRef<HandData[]>([]);
  const [currentElement, setCurrentElement] = useState<string>('NEUTRAL');
  const [isModelLoaded, setIsModelLoaded] = useState(false);
  const [debugInfo, setDebugInfo] = useState<string>("Initializing...");

  // Visual Feedback State
  const highlightRef = useRef<number>(0);
  const prevElementRef = useRef<string>('NEUTRAL');
  const activeComboRef = useRef<string | null>(null);

  // Audio Context
  const audioContextRef = useRef<AudioContext | null>(null);

  useEffect(() => {
    const AudioContextClass = (window as any).AudioContext || (window as any).webkitAudioContext;
    if (AudioContextClass) {
        audioContextRef.current = new AudioContextClass();
    }
  }, []);

  const playChime = useCallback((element: string) => {
    if (!audioContextRef.current) return;
    const ctx = audioContextRef.current;
    if (ctx.state === 'suspended') {
        ctx.resume().catch(console.error);
    }

    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.connect(gain);
    gain.connect(ctx.destination);

    let freq = 440;
    let type: OscillatorType = 'sine';
    let duration = 0.5;

    switch (element) {
        case 'FIRE': 
        case 'INFERNO':
            freq = 220; type = 'sawtooth'; 
            osc.frequency.setValueAtTime(freq, ctx.currentTime);
            osc.frequency.exponentialRampToValueAtTime(freq * 3, ctx.currentTime + 0.3);
            break;
        case 'WATER': 
        case 'STEAM':
            freq = 600; type = 'sine';
            osc.frequency.setValueAtTime(freq, ctx.currentTime);
            osc.frequency.exponentialRampToValueAtTime(200, ctx.currentTime + 0.2);
            duration = 0.3;
            break;
        case 'THUNDER': 
        case 'TEMPEST':
        case 'VOID':
            freq = 150; type = 'square';
            osc.frequency.setValueAtTime(freq, ctx.currentTime);
            osc.frequency.linearRampToValueAtTime(freq * 0.8, ctx.currentTime + 0.1);
            break;
        case 'WIND': 
        case 'BLIZZARD':
        case 'PLASMA':
            freq = 880; type = 'triangle';
            osc.frequency.setValueAtTime(freq, ctx.currentTime);
            break;
    }

    osc.type = type;
    const now = ctx.currentTime;
    gain.gain.setValueAtTime(0, now);
    gain.gain.linearRampToValueAtTime(0.05, now + 0.05);
    gain.gain.exponentialRampToValueAtTime(0.001, now + duration);
    osc.start(now);
    osc.stop(now + duration);
  }, []);

  const detectGesture = (landmarks: any[], videoWidth: number, videoHeight: number): ElementType => {
    const mapPt = (idx: number) => ({ x: (1 - landmarks[idx].x) * videoWidth, y: landmarks[idx].y * videoHeight });
    const wrist = mapPt(0);
    const indexTip = mapPt(8);
    const middleTip = mapPt(12);
    const ringTip = mapPt(16);
    const pinkyTip = mapPt(20);
    const indexMCP = mapPt(5);
    const middleMCP = mapPt(9);
    const ringMCP = mapPt(13); // Fixed missing ringMCP
    const pinkyMCP = mapPt(17);

    const dist = (p1: any, p2: any) => Math.hypot(p1.x - p2.x, p1.y - p2.y);

    // Check if finger is open (tip further from wrist than base)
    const isFingerOpen = (tip: any, mcp: any) => dist(tip, wrist) > dist(mcp, wrist) * 1.1;

    const indexOpen = isFingerOpen(indexTip, indexMCP);
    const middleOpen = isFingerOpen(middleTip, middleMCP);
    const ringOpen = isFingerOpen(ringTip, ringMCP);
    const pinkyOpen = isFingerOpen(pinkyTip, pinkyMCP);

    // Orientation: Y grows downwards. 
    // If Wrist Y < Middle MCP Y, the wrist is ABOVE the hand -> Hand Pointing DOWN
    const isPointingDown = wrist.y < middleMCP.y;

    if (isPointingDown) {
        // Rain/Water: Hand pointing down (even if closed or open, as long as pointing down)
        // Adding a check for at least some fingers open to avoid false positives during transitions
        if (indexOpen || middleOpen) return 'WATER';
    } else {
        // Pointing Up
        if (!indexOpen && !middleOpen && !ringOpen && !pinkyOpen) return 'THUNDER'; // Fist
        if (indexOpen && middleOpen && !ringOpen && !pinkyOpen) return 'WIND'; // Victory Sign
        if (indexOpen && middleOpen && ringOpen) return 'FIRE'; // Open Hand (Palm Up)
    }

    return 'NEUTRAL';
  };

  const drawSkeleton = (ctx: CanvasRenderingContext2D, hand: HandData) => {
      ctx.strokeStyle = "rgba(255, 255, 255, 0.2)";
      ctx.lineWidth = 1;
      ctx.fillStyle = "rgba(255, 255, 255, 0.4)";
      const points = [hand.wrist, hand.indexBase, hand.indexTip, hand.middleBase, hand.middleTip, hand.ringBase, hand.ringTip, hand.pinkyBase, hand.pinkyTip, hand.thumbTip];

      const drawLine = (p1: any, p2: any) => { ctx.beginPath(); ctx.moveTo(p1.x, p1.y); ctx.lineTo(p2.x, p2.y); ctx.stroke(); }
      drawLine(hand.wrist, hand.indexBase); drawLine(hand.indexBase, hand.indexTip);
      drawLine(hand.wrist, hand.middleBase); drawLine(hand.middleBase, hand.middleTip);
      drawLine(hand.wrist, hand.pinkyBase); drawLine(hand.pinkyBase, hand.pinkyTip);

      points.forEach(p => { ctx.beginPath(); ctx.arc(p.x, p.y, 2, 0, Math.PI * 2); ctx.fill(); });
  };

  const onResults = useCallback((results: any) => {
    const videoWidth = webcamRef.current?.video?.videoWidth || width;
    const videoHeight = webcamRef.current?.video?.videoHeight || height;

    if (results.multiHandLandmarks && results.multiHandLandmarks.length > 0) {
      setDebugInfo(`Hands: ${results.multiHandLandmarks.length}`);
      const newHandData: HandData[] = results.multiHandLandmarks.map((landmarks: any[]) => {
        const gesture = detectGesture(landmarks, videoWidth, videoHeight);
        const mapPt = (idx: number) => ({ x: (1 - landmarks[idx].x) * videoWidth, y: landmarks[idx].y * videoHeight });
        return {
          wrist: mapPt(0), indexTip: mapPt(8), middleTip: mapPt(12), ringTip: mapPt(16), pinkyTip: mapPt(20), thumbTip: mapPt(4),
          indexBase: mapPt(5), middleBase: mapPt(9), ringBase: mapPt(13), pinkyBase: mapPt(17),
          isOpen: gesture !== 'THUNDER', gesture, opacity: 1,
        };
      });

      handDataRef.current = newHandData;
      let newElement = 'NEUTRAL';
      let activeCombo = null;

      if (newHandData.length === 2) {
          const g1 = newHandData[0].gesture;
          const g2 = newHandData[1].gesture;
          if (g1 !== 'NEUTRAL' && g2 !== 'NEUTRAL') activeCombo = getCombo(g1, g2);
      }

      if (activeCombo) newElement = activeCombo;
      else {
          const activeHand = newHandData.find(h => h.gesture !== 'NEUTRAL');
          if (activeHand) newElement = activeHand.gesture;
      }
      activeComboRef.current = activeCombo;

      if (newElement !== prevElementRef.current) {
          if (newElement !== 'NEUTRAL') { highlightRef.current = 1.0; playChime(newElement); }
          prevElementRef.current = newElement;
      }
      setCurrentElement(newElement);
    } else {
      handDataRef.current = [];
      setDebugInfo("No Hands");
      activeComboRef.current = null;
      if (prevElementRef.current !== 'NEUTRAL') { prevElementRef.current = 'NEUTRAL'; setCurrentElement('NEUTRAL'); }
    }
  }, [width, height, playChime]);

  useEffect(() => {
    let hands: any = null;
    let isActive = true;
    let frameId: number;
    let lastVideoTime = -1;

    const initHands = async () => {
       if (!(window as any).Hands) { setTimeout(initHands, 500); return; }
       hands = new (window as any).Hands({ locateFile: (file: string) => `https://cdn.jsdelivr.net/npm/@mediapipe/hands@0.4.1675469240/${file}` });
       hands.setOptions({ maxNumHands: 2, modelComplexity: 1, minDetectionConfidence: 0.5, minTrackingConfidence: 0.5 });
       hands.onResults(onResults);
       setIsModelLoaded(true);
       const processVideo = async () => {
         if (!isActive) return;
         if (webcamRef.current && webcamRef.current.video && webcamRef.current.video.readyState === 4) {
             const video = webcamRef.current.video;
             if (video.currentTime !== lastVideoTime) {
                 lastVideoTime = video.currentTime;
                 try { await hands.send({ image: video }); } catch (e) { console.error("MediaPipe error:", e); }
             }
         }
         frameId = requestAnimationFrame(processVideo);
       };
       processVideo();
    };
    initHands();
    return () => { isActive = false; if (frameId) cancelAnimationFrame(frameId); if (hands) hands.close(); };
  }, [onResults]);

  // --- PHYSICS ENGINE ---
  const updateParticles = (ctx: CanvasRenderingContext2D, width: number, height: number, centerX: number, centerY: number) => {
    for (let i = particlesRef.current.length - 1; i >= 0; i--) {
      const p = particlesRef.current[i];

      // General Drag
      p.vx *= 0.95;
      p.vy *= 0.95;

      // Element Specific Physics
      switch (p.element) {
          case 'WIND':
          case 'BLIZZARD':
              // Vortex/Spiral Physics
              const dx = p.x - centerX;
              const dy = p.y - centerY;
              const dist = Math.sqrt(dx*dx + dy*dy) + 1;
              const angle = Math.atan2(dy, dx);
              // Tangential force (Rotation)
              p.vx += Math.cos(angle + Math.PI/2) * 1.5;
              p.vy += Math.sin(angle + Math.PI/2) * 1.5;
              // Centripetal force (Suck in)
              p.vx -= (dx / dist) * 0.5;
              p.vy -= (dy / dist) * 0.5;
              p.angle += p.angularVelocity; // Spin the leaf
              break;

          case 'WATER':
          case 'STEAM':
              // Gravity & Rain
              p.vy += 1.2; // Strong gravity
              p.x += Math.sin(p.life * 0.1) * 0.5; // Slight waver
              break;

          case 'THUNDER':
          case 'TEMPEST':
          case 'VOID':
              // Chaotic / Jitter
              p.vx += (Math.random() - 0.5) * 4;
              p.vy += (Math.random() - 0.5) * 4;
              if (Math.random() < 0.1) { // Lightning jump
                  p.x += (Math.random() - 0.5) * 20;
                  p.y += (Math.random() - 0.5) * 20;
              }
              break;

          case 'FIRE':
          case 'INFERNO':
              // Thermal Lift / Turbulence
              p.vy -= 0.6; // Rise
              p.vx += (Math.random() - 0.5) * 1.5; // Turbulence
              p.size *= 0.96; // Shrink faster
              break;

          default:
              p.vy -= 0.1; // Neutral float
      }

      p.x += p.vx;
      p.y += p.vy;
      p.life -= 1;
      if (p.element !== 'FIRE') p.size *= 0.98;

      if (p.life <= 0 || p.size < 0.2 || p.y > height + 50) {
        particlesRef.current.splice(i, 1);
      } else {
        // --- RENDERER ---
        ctx.save();
        ctx.globalAlpha = Math.min(1, p.life / 20);

        if (p.type === 'LEAF') {
            ctx.translate(p.x, p.y);
            ctx.rotate(p.angle);
            ctx.fillStyle = p.color;
            ctx.beginPath();
            ctx.ellipse(0, 0, p.size, p.size * 0.4, 0, 0, Math.PI * 2);
            ctx.fill();
        } 
        else if (p.type === 'DROP') {
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 2;
            ctx.lineCap = 'round';
            ctx.beginPath();
            ctx.moveTo(p.x, p.y);
            // Stretch rain drop based on velocity
            ctx.lineTo(p.x - p.vx, p.y - p.vy * 3); 
            ctx.stroke();
        }
        else if (p.type === 'SPARK') {
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 2;
            ctx.shadowColor = p.color;
            ctx.shadowBlur = 10;
            ctx.beginPath();
            ctx.moveTo(p.x - p.vx, p.y - p.vy);
            ctx.lineTo(p.x + p.vx, p.y + p.vy);
            ctx.stroke();
            // Occasional cross-bolt
            if (Math.random() > 0.5) {
                ctx.beginPath();
                ctx.moveTo(p.x, p.y);
                ctx.lineTo(p.x + (Math.random()-0.5)*20, p.y + (Math.random()-0.5)*20);
                ctx.stroke();
            }
        }
        else if (p.type === 'EMBER') {
            ctx.fillStyle = p.color;
            ctx.shadowColor = 'orange';
            ctx.shadowBlur = 15;
            ctx.beginPath();
            ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
            ctx.fill();
        }
        else { // ORB / MIST
            ctx.fillStyle = p.color;
            ctx.shadowColor = p.color;
            ctx.shadowBlur = p.type === 'ORB' ? 10 : 0;
            ctx.beginPath();
            ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
            ctx.fill();
        }
        ctx.restore();
      }
    }
  };

  const spawnParticles = (x: number, y: number, element: string, theme: Theme) => {
    let count = 3;
    let type: ParticleType = 'ORB';
    let speed = Math.random() * 5;
    let spread = 20;

    // Customize Spawn based on Element
    if (element === 'WIND' || element === 'BLIZZARD') {
        type = Math.random() > 0.5 ? 'LEAF' : 'MIST';
        count = 4;
    } else if (element === 'WATER' || element === 'STEAM') {
        type = Math.random() > 0.7 ? 'MIST' : 'DROP';
        count = 5;
        spread = 40; // Wide rain area
    } else if (element === 'THUNDER' || element === 'TEMPEST' || element === 'VOID') {
        type = 'SPARK';
        count = 2; // Fewer but erratic
        speed = 8;
    } else if (element === 'FIRE' || element === 'INFERNO') {
        type = Math.random() > 0.8 ? 'MIST' : 'EMBER';
        count = 4;
    }

    for (let i = 0; i < count; i++) {
      const angle = Math.random() * Math.PI * 2;
      let vx = Math.cos(angle) * speed;
      let vy = Math.sin(angle) * speed;

      // Initial velocity overrides
      if (element === 'WATER' || element === 'STEAM') { vx *= 0.2; vy = Math.random() * 2; } // Start falling

      // Color tweaks
      let color = Math.random() > 0.5 ? theme.primary : theme.secondary;
      if (element === 'WIND') color = Math.random() > 0.5 ? '#00FFFF' : '#F0FFF0'; // Cyan/White
      if (element === 'THUNDER') color = Math.random() > 0.5 ? '#FFFF00' : '#9400D3'; // Yellow/Purple

      particlesRef.current.push({
        x: x + (Math.random() - 0.5) * spread,
        y: y + (Math.random() - 0.5) * spread,
        vx, vy,
        life: 30 + Math.random() * 30,
        maxLife: 60,
        size: 3 + Math.random() * 5,
        color,
        element: element as Particle['element'],
        type,
        angle: Math.random() * Math.PI * 2,
        angularVelocity: (Math.random() - 0.5) * 0.2
      });
    }
  };

  const animate = useCallback((time: number) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (highlightRef.current > 0.01) highlightRef.current *= 0.9;
    else highlightRef.current = 0;
    const flash = highlightRef.current;

    // Use 'lighter' for high-energy anime look
    ctx.globalCompositeOperation = 'lighter'; 

    let lastCenterX = width / 2;
    let lastCenterY = height / 2;
    const t = time * 0.001;

    // Check for active combo
    const comboName = activeComboRef.current;

    if (comboName && handDataRef.current.length === 2) {
        // --- COMBO MODE ---
        const h1 = handDataRef.current[0];
        const h2 = handDataRef.current[1];
        const theme = COMBO_THEMES[comboName];

        const midX = (h1.middleBase.x + h2.middleBase.x) / 2;
        const midY = (h1.middleBase.y + h2.middleBase.y) / 2;
        lastCenterX = midX;
        lastCenterY = midY;

        // 1. Base Beam
        ctx.save();
        ctx.beginPath();
        ctx.moveTo(h1.middleBase.x, h1.middleBase.y);
        ctx.lineTo(h2.middleBase.x, h2.middleBase.y);
        ctx.strokeStyle = theme.primary;
        ctx.lineWidth = 20 + Math.sin(t * 10) * 5; 
        ctx.lineCap = 'round';
        ctx.shadowBlur = 40;
        ctx.shadowColor = theme.secondary;
        ctx.globalAlpha = 0.4;
        ctx.stroke();
        ctx.restore();

        // 2. Converging Energy
        ctx.save();
        ctx.beginPath();
        ctx.moveTo(h1.middleBase.x, h1.middleBase.y);
        ctx.lineTo(h2.middleBase.x, h2.middleBase.y);
        ctx.strokeStyle = '#FFFFFF';
        ctx.lineWidth = 3;
        ctx.setLineDash([10, 40]);
        ctx.lineDashOffset = -t * 200; 
        ctx.globalCompositeOperation = 'overlay';
        ctx.stroke();
        ctx.restore();

        // 3. Electric Arcs
        ctx.save();
        ctx.beginPath();
        ctx.moveTo(h1.middleBase.x, h1.middleBase.y);
        const dist = Math.hypot(h2.middleBase.x - h1.middleBase.x, h2.middleBase.y - h1.middleBase.y);
        const angle = Math.atan2(h2.middleBase.y - h1.middleBase.y, h2.middleBase.x - h1.middleBase.x);
        for(let i=0; i<=20; i++) {
             const p = i/20;
             const perp = Math.sin(p * Math.PI * 4 + t * 20) * (15 + Math.random() * 5);
             const bx = h1.middleBase.x + (h2.middleBase.x - h1.middleBase.x) * p + Math.cos(angle + Math.PI/2)*perp;
             const by = h1.middleBase.y + (h2.middleBase.y - h1.middleBase.y) * p + Math.sin(angle + Math.PI/2)*perp;
             ctx.lineTo(bx, by);
        }
        ctx.strokeStyle = theme.secondary;
        ctx.lineWidth = 2;
        ctx.shadowBlur = 10;
        ctx.shadowColor = theme.core;
        ctx.stroke();
        ctx.restore();

        // Array
        ctx.globalAlpha = 1;
        drawRuneRing(ctx, midX, midY, 180, t, theme);
        drawSacredGeometry(ctx, midX, midY, 140, -t * 2, theme);
        drawSquareLayer(ctx, midX, midY, 100, t * 3, theme);
        drawPentagram(ctx, midX, midY, 60, -t, 1, theme);

        spawnParticles(midX, midY, comboName, theme);

        handDataRef.current.forEach(h => {
             drawSkeleton(ctx, h);
             const auraSize = 50 + Math.sin(t * 20) * 10;
             const grad = ctx.createRadialGradient(h.middleBase.x, h.middleBase.y, 10, h.middleBase.x, h.middleBase.y, auraSize);
             grad.addColorStop(0, theme.core);
             grad.addColorStop(0.4, theme.primary);
             grad.addColorStop(1, 'rgba(0,0,0,0)');
             ctx.save();
             ctx.fillStyle = grad;
             ctx.globalAlpha = 0.5;
             ctx.beginPath();
             ctx.arc(h.middleBase.x, h.middleBase.y, auraSize, 0, Math.PI * 2);
             ctx.fill();
             ctx.restore();
             drawRuneRing(ctx, h.middleBase.x, h.middleBase.y, 40, t*5, theme);
        });

    } else {
        // --- INDIVIDUAL MODE ---
        handDataRef.current.forEach((hand) => {
           drawSkeleton(ctx, hand);
           const element = hand.gesture;
           const theme = (element !== 'NEUTRAL' && THEMES[element]) ? THEMES[element] : THEMES['NEUTRAL'];
           const centerX = hand.middleBase.x; 
           const centerY = hand.middleBase.y; 

           if (element !== 'NEUTRAL') {
               if (flash > 0.05 && highlightRef.current > 0.05) {
                   ctx.save();
                   ctx.translate(centerX, centerY);
                   const waveSize = 120 + (1 - flash) * 100;
                   ctx.beginPath();
                   ctx.arc(0, 0, waveSize, 0, Math.PI * 2);
                   ctx.lineWidth = 10 * flash;
                   ctx.strokeStyle = theme.core;
                   ctx.shadowBlur = 20;
                   ctx.shadowColor = theme.secondary;
                   ctx.globalAlpha = flash;
                   ctx.stroke();
                   ctx.restore();
               }

               drawRuneRing(ctx, centerX, centerY, 120, t * 0.5, theme);
               drawSacredGeometry(ctx, centerX, centerY, 90, -t * 1.5, theme);
               drawSquareLayer(ctx, centerX, centerY, 65, t * 2.5, theme);
               const pulse = Math.sin(time * 0.005) * 0.5 + 0.5;
               drawPentagram(ctx, centerX, centerY, 40, t, pulse, theme);

               spawnParticles(centerX, centerY, element, theme);
               lastCenterX = centerX;
               lastCenterY = centerY;
           } else {
               ctx.globalAlpha = 0.3;
               drawRuneRing(ctx, centerX, centerY, 50, t * 0.2, theme);
           }
        });
    }

    updateParticles(ctx, canvas.width, canvas.height, lastCenterX, lastCenterY);
    requestRef.current = requestAnimationFrame(animate);
  }, [width, height]);

  useEffect(() => {
    requestRef.current = requestAnimationFrame(animate);
    return () => { if (requestRef.current) cancelAnimationFrame(requestRef.current); };
  }, [animate]);

  return (
    <div className="relative w-full h-full bg-black overflow-hidden flex items-center justify-center">
        <Webcam ref={webcamRef} audio={false} width={width} height={height} mirrored={true} screenshotFormat="image/jpeg" className="absolute opacity-0 pointer-events-none" />
        <Webcam audio={false} width={width} height={height} mirrored={true} className="absolute top-0 left-0 w-full h-full object-cover opacity-80" />
        <canvas ref={canvasRef} width={width} height={height} className="absolute top-0 left-0 w-full h-full object-cover z-10" />
        {!isModelLoaded && (
            <div className="absolute inset-0 flex items-center justify-center bg-black bg-opacity-80 z-50">
                <div className="text-amber-500 font-mono text-xl animate-pulse">Summoning Grimoire... (Loading Models)</div>
            </div>
        )}
        <div className="absolute top-4 right-4 text-right z-20 font-mono pointer-events-none">
            <div className={`text-2xl font-bold mb-2 tracking-widest transition-all duration-300 ${highlightRef.current > 0.1 ? 'scale-110' : ''} ${
                currentElement === 'FIRE' ? 'text-orange-500' :
                currentElement === 'WATER' ? 'text-blue-500' :
                currentElement === 'WIND' ? 'text-cyan-300' :
                currentElement === 'THUNDER' ? 'text-purple-500' : 
                currentElement === 'INFERNO' ? 'text-red-600' :
                currentElement === 'BLIZZARD' ? 'text-cyan-100' :
                currentElement === 'VOID' ? 'text-violet-900' : 'text-amber-500'
            }`}>SPELL: {currentElement}</div>
            <div className="text-xs text-white opacity-70 space-y-1 mb-2"><p>Status: {debugInfo}</p></div>
            <div className="text-xs text-white opacity-70 space-y-1">
                <p>✋ Palm Up: FIRE</p>
                <p>👇 Palm Down: WATER (RAIN)</p>
                <p>👊 Fist: THUNDER</p>
                <p>✌️ Victory: WIND</p>
            </div>
        </div>
    </div>
  );
};

export default MagicOverlay;

import { Point, ElementType, Theme } from '../types';

// Element Themes - Updated for High Energy Anime Style
export const THEMES: Record<ElementType, Theme> = {
  NEUTRAL: { primary: '#FFA014', secondary: '#FFC832', core: '#FFFFFF', shadow: '#FFA014' }, // Amber
  FIRE: { primary: '#FF4500', secondary: '#FF0000', core: '#FFFF00', shadow: '#8B0000' }, // Orange/Red
  WATER: { primary: '#1E90FF', secondary: '#87CEEB', core: '#F0F8FF', shadow: '#00008B' }, // Blue/LightBlue
  THUNDER: { primary: '#8A2BE2', secondary: '#FFFF00', core: '#FFFFFF', shadow: '#4B0082' }, // Purple/Yellow
  WIND: { primary: '#00FFFF', secondary: '#F0FFFF', core: '#FFFFFF', shadow: '#008B8B' }, // Cyan/White
};

// Layer 1: Runes Ring
export const drawRuneRing = (
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  radius: number,
  rotation: number,
  theme: Theme
) => {
  const segments = 24;
  ctx.strokeStyle = theme.primary;
  ctx.lineWidth = 2;

  // Outer circle
  ctx.beginPath();
  ctx.arc(x, y, radius, 0, Math.PI * 2);
  ctx.stroke();

  // Inner border for runes
  ctx.beginPath();
  ctx.arc(x, y, radius * 0.85, 0, Math.PI * 2);
  ctx.stroke();

  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(rotation);

  for (let i = 0; i < segments; i++) {
    const angle = (Math.PI * 2) / segments;
    ctx.save();
    ctx.rotate(i * angle);
    ctx.translate(radius * 0.925, 0); 

    // Procedural Rune Glyph
    const seed = i * 13.37;
    const size = radius * 0.05;

    ctx.beginPath();
    ctx.moveTo(-size, -size + Math.sin(seed) * size);
    ctx.lineTo(size, size - Math.cos(seed) * size);
    ctx.moveTo(-size, size);
    ctx.lineTo(size + Math.sin(seed * 2) * 5, -size);
    if (i % 3 === 0) ctx.rect(-size / 2, -size / 2, size, size);

    ctx.strokeStyle = theme.secondary;
    ctx.lineWidth = 1.5;
    ctx.stroke();

    ctx.restore();
  }
  ctx.restore();
};

// Layer 2: Sacred Geometry (Hexagram/Triangle)
export const drawSacredGeometry = (
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  radius: number,
  rotation: number,
  theme: Theme
) => {
  ctx.strokeStyle = theme.primary;
  ctx.lineWidth = 3;
  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(rotation);

  // Triangle 1
  ctx.beginPath();
  for (let i = 0; i < 3; i++) {
    const theta = (i * 2 * Math.PI) / 3;
    const px = radius * Math.cos(theta);
    const py = radius * Math.sin(theta);
    if (i === 0) ctx.moveTo(px, py);
    else ctx.lineTo(px, py);
  }
  ctx.closePath();
  ctx.stroke();

  // Triangle 2 (Inverted)
  ctx.beginPath();
  for (let i = 0; i < 3; i++) {
    const theta = (i * 2 * Math.PI) / 3 + Math.PI; 
    const px = radius * Math.cos(theta);
    const py = radius * Math.sin(theta);
    if (i === 0) ctx.moveTo(px, py);
    else ctx.lineTo(px, py);
  }
  ctx.closePath();
  ctx.stroke();

  // Inner Circle
  ctx.beginPath();
  ctx.arc(0, 0, radius * 0.5, 0, Math.PI * 2);
  ctx.strokeStyle = theme.secondary;
  ctx.lineWidth = 1;
  ctx.stroke();

  ctx.restore();
};

// Layer 3: Rotating Square (Diamond)
export const drawSquareLayer = (
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  radius: number,
  rotation: number,
  theme: Theme
) => {
  ctx.strokeStyle = theme.secondary;
  ctx.lineWidth = 4;

  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(rotation);

  ctx.beginPath();
  const size = radius;
  ctx.rect(-size / 2, -size / 2, size, size);
  ctx.stroke();

  // Decorative corners
  ctx.fillStyle = theme.core;
  const cornerSize = 4;
  ctx.fillRect(-size / 2 - cornerSize, -size / 2 - cornerSize, cornerSize * 2, cornerSize * 2);
  ctx.fillRect(size / 2 - cornerSize, -size / 2 - cornerSize, cornerSize * 2, cornerSize * 2);
  ctx.fillRect(size / 2 - cornerSize, size / 2 - cornerSize, cornerSize * 2, cornerSize * 2);
  ctx.fillRect(-size / 2 - cornerSize, size / 2 - cornerSize, cornerSize * 2, cornerSize * 2);

  ctx.restore();
};

// Layer 4: Pulsing Pentagram
export const drawPentagram = (
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  radius: number,
  rotation: number,
  pulse: number,
  theme: Theme
) => {
  const r = radius * (0.8 + pulse * 0.2); 
  ctx.strokeStyle = theme.core;
  ctx.lineWidth = 2 + pulse * 2;
  ctx.shadowBlur = 10 + pulse * 10;
  ctx.shadowColor = theme.shadow;

  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(rotation);

  ctx.beginPath();
  for (let i = 0; i < 5; i++) {
    const theta = (i * 4 * Math.PI) / 5 - Math.PI / 2;
    const px = r * Math.cos(theta);
    const py = r * Math.sin(theta);
    if (i === 0) ctx.moveTo(px, py);
    else ctx.lineTo(px, py);
  }
  ctx.closePath();
  ctx.stroke();

  ctx.shadowBlur = 0; 
  ctx.restore();
};

import React, { useEffect, useRef, useCallback, useState } from 'react';
import Webcam from 'react-webcam';
import { Particle, HandData, ElementType, Theme, ParticleType } from '../types';
import { 
  drawRuneRing, 
  drawSacredGeometry, 
  drawSquareLayer, 
  drawPentagram,
  THEMES
} from '../utils/geometry';

interface MagicOverlayProps {
  width: number;
  height: number;
}

const COMBO_THEMES: Record<string, Theme> = {
  'BLIZZARD': { primary: '#00FFFF', secondary: '#E0FFFF', core: '#FFFFFF', shadow: '#008B8B' }, // Ice/Wind
  'PLASMA': { primary: '#FF00FF', secondary: '#00FFFF', core: '#FFFFFF', shadow: '#9400D3' }, // Fire/Wind
  'STEAM': { primary: '#F0F8FF', secondary: '#B0C4DE', core: '#FFFFFF', shadow: '#778899' }, // Fire/Water
  'TEMPEST': { primary: '#000080', secondary: '#8A2BE2', core: '#FFFF00', shadow: '#191970' }, // Thunder/Water
  'INFERNO': { primary: '#FF0000', secondary: '#FF4500', core: '#FFFF00', shadow: '#8B0000' }, // Fire/Fire
  'VOID': { primary: '#000000', secondary: '#4B0082', core: '#FFFFFF', shadow: '#9400D3' }, // Thunder/Thunder
};

const getCombo = (g1: ElementType, g2: ElementType): string | null => {
    const sorted = [g1, g2].sort().join('_');
    switch(sorted) {
        case 'WATER_WIND': return 'BLIZZARD';
        case 'FIRE_WIND': return 'PLASMA';
        case 'FIRE_WATER': return 'STEAM';
        case 'THUNDER_WATER': return 'TEMPEST';
        case 'FIRE_FIRE': return 'INFERNO';
        case 'THUNDER_THUNDER': return 'VOID';
        default: return null;
    }
};

const MagicOverlay: React.FC<MagicOverlayProps> = ({ width, height }) => {
  const webcamRef = useRef<Webcam>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>(0);
  const particlesRef = useRef<Particle[]>([]);
  const handDataRef = useRef<HandData[]>([]);
  const [currentElement, setCurrentElement] = useState<string>('NEUTRAL');
  const [isModelLoaded, setIsModelLoaded] = useState(false);
  const [debugInfo, setDebugInfo] = useState<string>("Initializing...");

  // Visual Feedback State
  const highlightRef = useRef<number>(0);
  const prevElementRef = useRef<string>('NEUTRAL');
  const activeComboRef = useRef<string | null>(null);

  // Audio Context
  const audioContextRef = useRef<AudioContext | null>(null);

  useEffect(() => {
    const AudioContextClass = (window as any).AudioContext || (window as any).webkitAudioContext;
    if (AudioContextClass) {
        audioContextRef.current = new AudioContextClass();
    }
  }, []);

  const playChime = useCallback((element: string) => {
    if (!audioContextRef.current) return;
    const ctx = audioContextRef.current;
    if (ctx.state === 'suspended') {
        ctx.resume().catch(console.error);
    }

    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.connect(gain);
    gain.connect(ctx.destination);

    let freq = 440;
    let type: OscillatorType = 'sine';
    let duration = 0.5;

    switch (element) {
        case 'FIRE': 
        case 'INFERNO':
            freq = 220; type = 'sawtooth'; 
            osc.frequency.setValueAtTime(freq, ctx.currentTime);
            osc.frequency.exponentialRampToValueAtTime(freq * 3, ctx.currentTime + 0.3);
            break;
        case 'WATER': 
        case 'STEAM':
            freq = 600; type = 'sine';
            osc.frequency.setValueAtTime(freq, ctx.currentTime);
            osc.frequency.exponentialRampToValueAtTime(200, ctx.currentTime + 0.2);
            duration = 0.3;
            break;
        case 'THUNDER': 
        case 'TEMPEST':
        case 'VOID':
            freq = 150; type = 'square';
            osc.frequency.setValueAtTime(freq, ctx.currentTime);
            osc.frequency.linearRampToValueAtTime(freq * 0.8, ctx.currentTime + 0.1);
            break;
        case 'WIND': 
        case 'BLIZZARD':
        case 'PLASMA':
            freq = 880; type = 'triangle';
            osc.frequency.setValueAtTime(freq, ctx.currentTime);
            break;
    }

    osc.type = type;
    const now = ctx.currentTime;
    gain.gain.setValueAtTime(0, now);
    gain.gain.linearRampToValueAtTime(0.05, now + 0.05);
    gain.gain.exponentialRampToValueAtTime(0.001, now + duration);
    osc.start(now);
    osc.stop(now + duration);
  }, []);

  // --- IMPROVED GESTURE DETECTION ---
  const detectGesture = (landmarks: any[], videoWidth: number, videoHeight: number): ElementType => {
    const mapPt = (idx: number) => ({ x: (1 - landmarks[idx].x) * videoWidth, y: landmarks[idx].y * videoHeight });
    const wrist = mapPt(0);
    const indexTip = mapPt(8);
    const middleTip = mapPt(12);
    const ringTip = mapPt(16);
    const pinkyTip = mapPt(20);
    const indexMCP = mapPt(5);
    const middleMCP = mapPt(9);

    const dist = (p1: any, p2: any) => Math.hypot(p1.x - p2.x, p1.y - p2.y);
    // Robust open check: tip is farther from wrist than knuckle is
    const isFingerOpen = (tip: any, mcp: any) => dist(tip, wrist) > dist(mcp, wrist);

    // Orientation Check
    // If Wrist Y is SMALLER than Middle MCP Y, the wrist is ABOVE the hand (since Y=0 is top).
    // This means the hand is pointing DOWN.
    const isHandPointingDown = wrist.y < middleMCP.y; 

    const indexOpen = isFingerOpen(indexTip, indexMCP);
    const middleOpen = isFingerOpen(middleTip, middleMCP);
    const ringOpen = isFingerOpen(ringTip, wrist);
    const pinkyOpen = isFingerOpen(pinkyTip, wrist);

    // 1. WATER: Hand pointing down (Rain)
    if (isHandPointingDown) {
        return 'WATER';
    }

    // 2. Upright Hand Gestures
    const openCount = [indexOpen, middleOpen, ringOpen, pinkyOpen].filter(Boolean).length;

    // THUNDER: Fist (0-1 fingers open, usually thumb doesn't count here)
    if (openCount <= 1 && !indexOpen && !middleOpen) return 'THUNDER';

    // WIND: Victory Sign (Index & Middle Open, Ring & Pinky Closed)
    if (indexOpen && middleOpen && !ringOpen && !pinkyOpen) return 'WIND';

    // FIRE: Open Palm (3+ fingers open)
    if (openCount >= 3) return 'FIRE';

    return 'NEUTRAL';
  };

  const drawSkeleton = (ctx: CanvasRenderingContext2D, hand: HandData) => {
      ctx.strokeStyle = "rgba(255, 255, 255, 0.2)";
      ctx.lineWidth = 1;
      ctx.fillStyle = "rgba(255, 255, 255, 0.4)";
      const points = [hand.wrist, hand.indexBase, hand.indexTip, hand.middleBase, hand.middleTip, hand.ringBase, hand.ringTip, hand.pinkyBase, hand.pinkyTip, hand.thumbTip];

      const drawLine = (p1: any, p2: any) => { ctx.beginPath(); ctx.moveTo(p1.x, p1.y); ctx.lineTo(p2.x, p2.y); ctx.stroke(); }
      drawLine(hand.wrist, hand.indexBase); drawLine(hand.indexBase, hand.indexTip);
      drawLine(hand.wrist, hand.middleBase); drawLine(hand.middleBase, hand.middleTip);
      drawLine(hand.wrist, hand.pinkyBase); drawLine(hand.pinkyBase, hand.pinkyTip);

      points.forEach(p => { ctx.beginPath(); ctx.arc(p.x, p.y, 2, 0, Math.PI * 2); ctx.fill(); });
  };

  const onResults = useCallback((results: any) => {
    const videoWidth = webcamRef.current?.video?.videoWidth || width;
    const videoHeight = webcamRef.current?.video?.videoHeight || height;

    if (results.multiHandLandmarks && results.multiHandLandmarks.length > 0) {
      setDebugInfo(`Hands detected: ${results.multiHandLandmarks.length}`);
      const newHandData: HandData[] = results.multiHandLandmarks.map((landmarks: any[]) => {
        const gesture = detectGesture(landmarks, videoWidth, videoHeight);
        const mapPt = (idx: number) => ({ x: (1 - landmarks[idx].x) * videoWidth, y: landmarks[idx].y * videoHeight });
        return {
          wrist: mapPt(0), indexTip: mapPt(8), middleTip: mapPt(12), ringTip: mapPt(16), pinkyTip: mapPt(20), thumbTip: mapPt(4),
          indexBase: mapPt(5), middleBase: mapPt(9), ringBase: mapPt(13), pinkyBase: mapPt(17),
          isOpen: gesture !== 'THUNDER', gesture, opacity: 1,
        };
      });

      handDataRef.current = newHandData;
      let newElement = 'NEUTRAL';
      let activeCombo = null;

      if (newHandData.length === 2) {
          const g1 = newHandData[0].gesture;
          const g2 = newHandData[1].gesture;
          if (g1 !== 'NEUTRAL' && g2 !== 'NEUTRAL') activeCombo = getCombo(g1, g2);
      }

      if (activeCombo) newElement = activeCombo;
      else {
          const activeHand = newHandData.find(h => h.gesture !== 'NEUTRAL');
          if (activeHand) newElement = activeHand.gesture;
      }
      activeComboRef.current = activeCombo;

      if (newElement !== prevElementRef.current) {
          if (newElement !== 'NEUTRAL') { highlightRef.current = 1.0; playChime(newElement); }
          prevElementRef.current = newElement;
      }
      setCurrentElement(newElement);
    } else {
      handDataRef.current = [];
      setDebugInfo("No Hands");
      activeComboRef.current = null;
      if (prevElementRef.current !== 'NEUTRAL') { prevElementRef.current = 'NEUTRAL'; setCurrentElement('NEUTRAL'); }
    }
  }, [width, height, playChime]);

  useEffect(() => {
    let hands: any = null;
    let isActive = true;
    let frameId: number;
    let lastVideoTime = -1;

    const initHands = async () => {
       if (!(window as any).Hands) { setTimeout(initHands, 500); return; }
       hands = new (window as any).Hands({ locateFile: (file: string) => `https://cdn.jsdelivr.net/npm/@mediapipe/hands@0.4.1675469240/${file}` });
       hands.setOptions({ maxNumHands: 2, modelComplexity: 1, minDetectionConfidence: 0.5, minTrackingConfidence: 0.5 });
       hands.onResults(onResults);
       setIsModelLoaded(true);
       const processVideo = async () => {
         if (!isActive) return;
         if (webcamRef.current && webcamRef.current.video && webcamRef.current.video.readyState === 4) {
             const video = webcamRef.current.video;
             if (video.currentTime !== lastVideoTime) {
                 lastVideoTime = video.currentTime;
                 try { await hands.send({ image: video }); } catch (e) { console.error("MediaPipe error:", e); }
             }
         }
         frameId = requestAnimationFrame(processVideo);
       };
       processVideo();
    };
    initHands();
    return () => { isActive = false; if (frameId) cancelAnimationFrame(frameId); if (hands) hands.close(); };
  }, [onResults]);

  // --- PHYSICS ENGINE ---
  const updateParticles = (ctx: CanvasRenderingContext2D, width: number, height: number, centerX: number, centerY: number) => {
    for (let i = particlesRef.current.length - 1; i >= 0; i--) {
      const p = particlesRef.current[i];

      // Basic Drag
      p.vx *= 0.96;
      p.vy *= 0.96;

      // --- ELEMENT SPECIFIC PHYSICS ---
      switch (p.element) {
          case 'WIND':
          case 'BLIZZARD':
          case 'PLASMA':
              // VORTEX PHYSICS: Spiral towards center
              // If it's a combo, center is screen center. If single, hand center.
              // However, full screen wind should spiral around the center of the screen mostly
              const targetX = (p.element === 'WIND') ? centerX : width/2;
              const targetY = (p.element === 'WIND') ? centerY : height/2;

              const dx = p.x - targetX;
              const dy = p.y - targetY;
              const dist = Math.sqrt(dx*dx + dy*dy) + 1;
              const angle = Math.atan2(dy, dx);

              // Rotation Force (Tangential)
              const rotSpeed = 2.0;
              p.vx += Math.cos(angle + Math.PI/2) * rotSpeed;
              p.vy += Math.sin(angle + Math.PI/2) * rotSpeed;

              // Suction Force (Centripetal)
              const suckSpeed = 0.5;
              p.vx -= Math.cos(angle) * suckSpeed;
              p.vy -= Math.sin(angle) * suckSpeed;

              // Spin the particle itself
              p.angle += p.angularVelocity;
              break;

          case 'WATER':
          case 'STEAM':
          case 'TEMPEST':
              // GRAVITY: Heavy rain
              p.vy += 0.8; 
              // Horizontal momentum slightly maintained but mostly falling
              p.vx *= 0.99;
              break;

          case 'THUNDER':
          case 'VOID':
              // CHAOS: Jittering electricity
              p.vx += (Math.random() - 0.5) * 6;
              p.vy += (Math.random() - 0.5) * 6;
              // Attraction to center (Ball Lightning feel)
              if (p.element === 'THUNDER') {
                  p.vx += (centerX - p.x) * 0.05;
                  p.vy += (centerY - p.y) * 0.05;
              }
              break;

          case 'FIRE':
          case 'INFERNO':
              // THERMAL LIFT: Rising heat
              p.vy -= 0.5; 
              p.vx += (Math.sin(p.life * 0.2) * 0.5); // Wavy smoke
              p.size *= 0.95; // Burn out
              break;
      }

      p.x += p.vx;
      p.y += p.vy;
      p.life -= 1;

      // Kill conditions
      if (p.life <= 0 || p.size < 0.2 || p.y > height + 100 || p.y < -100) {
        particlesRef.current.splice(i, 1);
      } else {
        // --- RENDERER ---
        ctx.save();
        ctx.globalAlpha = Math.min(1, p.life / 20);

        if (p.type === 'LEAF') {
            ctx.translate(p.x, p.y);
            ctx.rotate(p.angle);
            ctx.fillStyle = p.color;
            ctx.beginPath();
            // Draw Leaf Shape
            ctx.moveTo(0, -p.size);
            ctx.quadraticCurveTo(p.size, 0, 0, p.size);
            ctx.quadraticCurveTo(-p.size, 0, 0, -p.size);
            ctx.fill();
        } 
        else if (p.type === 'DROP') {
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 2;
            ctx.lineCap = 'round';
            ctx.beginPath();
            ctx.moveTo(p.x, p.y);
            // Stretch rain drop based on velocity (Motion Blur)
            const len = Math.max(5, p.vy * 4);
            ctx.lineTo(p.x - p.vx, p.y - len); 
            ctx.stroke();
        }
        else if (p.type === 'SPARK') {
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 2;
            ctx.shadowColor = p.color;
            ctx.shadowBlur = 10;
            ctx.beginPath();
            // Jagged line
            ctx.moveTo(p.x - p.vx, p.y - p.vy);
            ctx.lineTo(p.x, p.y);
            ctx.lineTo(p.x + p.vx * 2, p.y + p.vy * 2);
            ctx.stroke();
        }
        else if (p.type === 'EMBER') {
            ctx.fillStyle = p.color;
            ctx.shadowColor = '#FF4500';
            ctx.shadowBlur = 10;
            ctx.beginPath();
            ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
            ctx.fill();
        }
        else { // MIST / ORB
            ctx.fillStyle = p.color;
            ctx.shadowColor = p.color;
            ctx.shadowBlur = 20;
            ctx.beginPath();
            ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
            ctx.fill();
        }
        ctx.restore();
      }
    }
  };

  const spawnParticles = (x: number, y: number, element: string, theme: Theme) => {
    // Check if it's a combo (longer names usually, or check map)
    const isCombo = activeComboRef.current !== null;
    const count = isCombo ? 8 : 3; 

    // Specific particle settings
    let type: ParticleType = 'ORB';
    let speed = 2 + Math.random() * 4;
    let baseColor = theme.primary;

    if (element === 'WIND' || element.includes('BLIZZARD')) {
        type = Math.random() > 0.4 ? 'LEAF' : 'MIST';
        baseColor = Math.random() > 0.5 ? '#00FFFF' : '#FFFFFF';
    } else if (element === 'WATER' || element.includes('STEAM')) {
        type = 'DROP';
        speed = 0; // Starts by falling
    } else if (element === 'THUNDER' || element.includes('TEMPEST')) {
        type = 'SPARK';
        baseColor = Math.random() > 0.5 ? '#8A2BE2' : '#FFFF00';
    } else if (element === 'FIRE' || element.includes('INFERNO')) {
        type = Math.random() > 0.5 ? 'EMBER' : 'MIST';
        baseColor = Math.random() > 0.5 ? '#FF4500' : '#FFD700';
    }

    for (let i = 0; i < count; i++) {
      let spawnX = x;
      let spawnY = y;

      // FULL SCREEN SPAWN FOR COMBOS or Rain
      if (isCombo || element === 'WATER' || element === 'BLIZZARD') {
          spawnX = Math.random() * width;
          // Rain spawns at top, others anywhere
          spawnY = (element === 'WATER' || element === 'BLIZZARD') 
                   ? Math.random() * -50 // Top of screen
                   : Math.random() * height;
      } else {
          // Hand localized spawn
          spawnX = x + (Math.random() - 0.5) * 40;
          spawnY = y + (Math.random() - 0.5) * 40;
      }

      const angle = Math.random() * Math.PI * 2;
      let vx = Math.cos(angle) * speed;
      let vy = Math.sin(angle) * speed;

      if (type === 'DROP') { vx = (Math.random()-0.5); vy = 5 + Math.random() * 5; } // Fast fall start

      particlesRef.current.push({
        x: spawnX,
        y: spawnY,
        vx, vy,
        life: 40 + Math.random() * 40,
        maxLife: 80,
        size: 3 + Math.random() * 5,
        color: baseColor,
        element: element as Particle['element'],
        type,
        angle: Math.random() * Math.PI * 2,
        angularVelocity: (Math.random() - 0.5) * 0.2
      });
    }
  };

  const animate = useCallback((time: number) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (highlightRef.current > 0.01) highlightRef.current *= 0.9;
    else highlightRef.current = 0;
    const flash = highlightRef.current;

    // High Energy Composite Mode
    ctx.globalCompositeOperation = 'screen'; 

    let lastCenterX = width / 2;
    let lastCenterY = height / 2;
    const t = time * 0.001;

    // Check for active combo
    const comboName = activeComboRef.current;

    if (comboName && handDataRef.current.length === 2) {
        // --- COMBO MODE ---
        const h1 = handDataRef.current[0];
        const h2 = handDataRef.current[1];
        const theme = COMBO_THEMES[comboName];

        const midX = (h1.middleBase.x + h2.middleBase.x) / 2;
        const midY = (h1.middleBase.y + h2.middleBase.y) / 2;
        lastCenterX = midX;
        lastCenterY = midY;

        // 1. Connection Beams
        ctx.save();
        ctx.beginPath();
        ctx.moveTo(h1.middleBase.x, h1.middleBase.y);
        ctx.lineTo(h2.middleBase.x, h2.middleBase.y);
        ctx.strokeStyle = theme.primary;
        ctx.lineWidth = 25 + Math.sin(t * 15) * 5; 
        ctx.lineCap = 'round';
        ctx.shadowBlur = 50;
        ctx.shadowColor = theme.secondary;
        ctx.globalAlpha = 0.6;
        ctx.stroke();

        // Core Beam
        ctx.strokeStyle = '#FFFFFF';
        ctx.lineWidth = 5;
        ctx.globalAlpha = 1.0;
        ctx.stroke();
        ctx.restore();

        // 2. Huge Magic Circle at Center
        drawRuneRing(ctx, midX, midY, 200, t, theme);
        drawSacredGeometry(ctx, midX, midY, 150, -t * 2, theme);
        drawPentagram(ctx, midX, midY, 80, -t, 1, theme);

        // Spawn Full Screen Combo Particles
        spawnParticles(midX, midY, comboName, theme);

        // Hand Auras
        handDataRef.current.forEach(h => {
             drawSkeleton(ctx, h);
             drawRuneRing(ctx, h.middleBase.x, h.middleBase.y, 40, t*5, theme);
        });

    } else {
        // --- INDIVIDUAL MODE ---
        handDataRef.current.forEach((hand) => {
           drawSkeleton(ctx, hand);
           const element = hand.gesture;
           const theme = (element !== 'NEUTRAL' && THEMES[element]) ? THEMES[element] : THEMES['NEUTRAL'];
           const centerX = hand.middleBase.x; 
           const centerY = hand.middleBase.y; 

           if (element !== 'NEUTRAL') {
               // Flash on cast
               if (flash > 0.05 && highlightRef.current > 0.05) {
                   ctx.save();
                   ctx.translate(centerX, centerY);
                   const waveSize = 120 + (1 - flash) * 100;
                   ctx.beginPath();
                   ctx.arc(0, 0, waveSize, 0, Math.PI * 2);
                   ctx.lineWidth = 10 * flash;
                   ctx.strokeStyle = theme.core;
                   ctx.shadowBlur = 20;
                   ctx.shadowColor = theme.secondary;
                   ctx.globalAlpha = flash;
                   ctx.stroke();
                   ctx.restore();
               }

               drawRuneRing(ctx, centerX, centerY, 120, t * 0.5, theme);
               drawSacredGeometry(ctx, centerX, centerY, 90, -t * 1.5, theme);
               drawPentagram(ctx, centerX, centerY, 50, t, Math.sin(t*5)*0.5+0.5, theme);

               spawnParticles(centerX, centerY, element, theme);
               lastCenterX = centerX;
               lastCenterY = centerY;
           } else {
               ctx.globalAlpha = 0.3;
               drawRuneRing(ctx, centerX, centerY, 50, t * 0.2, theme);
           }
        });
    }

    updateParticles(ctx, canvas.width, canvas.height, lastCenterX, lastCenterY);
    requestRef.current = requestAnimationFrame(animate);
  }, [width, height]);

  useEffect(() => {
    requestRef.current = requestAnimationFrame(animate);
    return () => { if (requestRef.current) cancelAnimationFrame(requestRef.current); };
  }, [animate]);

  return (
    <div className="relative w-full h-full bg-black overflow-hidden flex items-center justify-center">
        <Webcam ref={webcamRef} audio={false} width={width} height={height} mirrored={true} screenshotFormat="image/jpeg" className="absolute opacity-0 pointer-events-none" />
        <Webcam audio={false} width={width} height={height} mirrored={true} className="absolute top-0 left-0 w-full h-full object-cover opacity-80" />
        <canvas ref={canvasRef} width={width} height={height} className="absolute top-0 left-0 w-full h-full object-cover z-10" />
        {!isModelLoaded && (
            <div className="absolute inset-0 flex items-center justify-center bg-black bg-opacity-80 z-50">
                <div className="text-amber-500 font-mono text-xl animate-pulse">Summoning Grimoire... (Loading Models)</div>
            </div>
        )}
        <div className="absolute top-4 right-4 text-right z-20 font-mono pointer-events-none">
            <div className={`text-2xl font-bold mb-2 tracking-widest transition-all duration-300 ${highlightRef.current > 0.1 ? 'scale-110' : ''} ${
                currentElement === 'FIRE' ? 'text-orange-500' :
                currentElement === 'WATER' ? 'text-blue-500' :
                currentElement === 'WIND' ? 'text-cyan-300' :
                currentElement === 'THUNDER' ? 'text-purple-500' : 
                currentElement === 'INFERNO' ? 'text-red-600' :
                currentElement === 'BLIZZARD' ? 'text-cyan-100' :
                currentElement === 'VOID' ? 'text-violet-900' : 'text-amber-500'
            }`}>SPELL: {currentElement}</div>
            <div className="text-xs text-white opacity-70 space-y-1 mb-2"><p>Status: {debugInfo}</p></div>
            <div className="text-xs text-white opacity-70 space-y-1">
                <p>✋ Palm Up: FIRE</p>
                <p>👇 Palm Down: WATER (RAIN)</p>
                <p>👊 Fist: THUNDER</p>
                <p>✌️ Victory: WIND</p>
            </div>
        </div>
    </div>
  );
};

export default MagicOverlay;

import React, { useEffect, useRef, useCallback, useState } from 'react';
import Webcam from 'react-webcam';
import { Particle, HandData, ElementType, Theme, ParticleType } from '../types';
import { 
  drawRuneRing, 
  drawSacredGeometry, 
  drawSquareLayer, 
  drawPentagram,
  THEMES
} from '../utils/geometry';

interface MagicOverlayProps {
  width: number;
  height: number;
}

const COMBO_THEMES: Record<string, Theme> = {
  'BLIZZARD': { primary: '#00FFFF', secondary: '#E0FFFF', core: '#FFFFFF', shadow: '#008B8B' }, // Ice/Wind
  'PLASMA': { primary: '#FF00FF', secondary: '#00FFFF', core: '#FFFFFF', shadow: '#9400D3' }, // Fire/Wind
  'STEAM': { primary: '#F0F8FF', secondary: '#B0C4DE', core: '#FFFFFF', shadow: '#778899' }, // Fire/Water
  'TEMPEST': { primary: '#000080', secondary: '#8A2BE2', core: '#FFFF00', shadow: '#191970' }, // Thunder/Water
  'INFERNO': { primary: '#FF0000', secondary: '#FF4500', core: '#FFFF00', shadow: '#8B0000' }, // Fire/Fire
  'VOID': { primary: '#000000', secondary: '#4B0082', core: '#FFFFFF', shadow: '#9400D3' }, // Thunder/Thunder
};

const getCombo = (g1: ElementType, g2: ElementType): string | null => {
    const sorted = [g1, g2].sort().join('_');
    switch(sorted) {
        case 'WATER_WIND': return 'BLIZZARD';
        case 'FIRE_WIND': return 'PLASMA';
        case 'FIRE_WATER': return 'STEAM';
        case 'THUNDER_WATER': return 'TEMPEST';
        case 'FIRE_FIRE': return 'INFERNO';
        case 'THUNDER_THUNDER': return 'VOID';
        default: return null;
    }
};

const MagicOverlay: React.FC<MagicOverlayProps> = ({ width, height }) => {
  const webcamRef = useRef<Webcam>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>(0);
  const particlesRef = useRef<Particle[]>([]);
  const handDataRef = useRef<HandData[]>([]);
  const [currentElement, setCurrentElement] = useState<string>('NEUTRAL');
  const [isModelLoaded, setIsModelLoaded] = useState(false);
  const [debugInfo, setDebugInfo] = useState<string>("Initializing...");

  // Visual Feedback State
  const highlightRef = useRef<number>(0);
  const prevElementRef = useRef<string>('NEUTRAL');
  const activeComboRef = useRef<string | null>(null);

  // Audio Context
  const audioContextRef = useRef<AudioContext | null>(null);

  useEffect(() => {
    const AudioContextClass = (window as any).AudioContext || (window as any).webkitAudioContext;
    if (AudioContextClass) {
        audioContextRef.current = new AudioContextClass();
    }
  }, []);

  const playChime = useCallback((element: string) => {
    if (!audioContextRef.current) return;
    const ctx = audioContextRef.current;
    if (ctx.state === 'suspended') {
        ctx.resume().catch(console.error);
    }

    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.connect(gain);
    gain.connect(ctx.destination);

    let freq = 440;
    let type: OscillatorType = 'sine';
    let duration = 0.5;

    switch (element) {
        case 'FIRE': 
        case 'INFERNO':
            freq = 220; type = 'sawtooth'; 
            osc.frequency.setValueAtTime(freq, ctx.currentTime);
            osc.frequency.exponentialRampToValueAtTime(freq * 3, ctx.currentTime + 0.3);
            break;
        case 'WATER': 
        case 'STEAM':
            freq = 600; type = 'sine';
            osc.frequency.setValueAtTime(freq, ctx.currentTime);
            osc.frequency.exponentialRampToValueAtTime(200, ctx.currentTime + 0.2);
            duration = 0.3;
            break;
        case 'THUNDER': 
        case 'TEMPEST':
        case 'VOID':
            freq = 150; type = 'square';
            osc.frequency.setValueAtTime(freq, ctx.currentTime);
            osc.frequency.linearRampToValueAtTime(freq * 0.8, ctx.currentTime + 0.1);
            break;
        case 'WIND': 
        case 'BLIZZARD':
        case 'PLASMA':
            freq = 880; type = 'triangle';
            osc.frequency.setValueAtTime(freq, ctx.currentTime);
            break;
    }

    osc.type = type;
    const now = ctx.currentTime;
    gain.gain.setValueAtTime(0, now);
    gain.gain.linearRampToValueAtTime(0.05, now + 0.05);
    gain.gain.exponentialRampToValueAtTime(0.001, now + duration);
    osc.start(now);
    osc.stop(now + duration);
  }, []);

  const detectGesture = (landmarks: any[], videoWidth: number, videoHeight: number): ElementType => {
    const mapPt = (idx: number) => ({ x: (1 - landmarks[idx].x) * videoWidth, y: landmarks[idx].y * videoHeight });
    const wrist = mapPt(0);
    const indexTip = mapPt(8);
    const middleTip = mapPt(12);
    const ringTip = mapPt(16);
    const pinkyTip = mapPt(20);
    const indexMCP = mapPt(5);
    const middleMCP = mapPt(9);
    const ringMCP = mapPt(13); // Fixed missing ringMCP
    const pinkyMCP = mapPt(17);

    const dist = (p1: any, p2: any) => Math.hypot(p1.x - p2.x, p1.y - p2.y);

    // Check if finger is open (tip further from wrist than base)
    const isFingerOpen = (tip: any, mcp: any) => dist(tip, wrist) > dist(mcp, wrist) * 1.1;

    const indexOpen = isFingerOpen(indexTip, indexMCP);
    const middleOpen = isFingerOpen(middleTip, middleMCP);
    const ringOpen = isFingerOpen(ringTip, ringMCP);
    const pinkyOpen = isFingerOpen(pinkyTip, pinkyMCP);

    // Orientation: Y grows downwards. 
    // If Wrist Y < Middle MCP Y, the wrist is ABOVE the hand -> Hand Pointing DOWN
    const isPointingDown = wrist.y < middleMCP.y;

    if (isPointingDown) {
        // Rain/Water: Hand pointing down (even if closed or open, as long as pointing down)
        // Adding a check for at least some fingers open to avoid false positives during transitions
        if (indexOpen || middleOpen) return 'WATER';
    } else {
        // Pointing Up
        if (!indexOpen && !middleOpen && !ringOpen && !pinkyOpen) return 'THUNDER'; // Fist
        if (indexOpen && middleOpen && !ringOpen && !pinkyOpen) return 'WIND'; // Victory Sign
        if (indexOpen && middleOpen && ringOpen) return 'FIRE'; // Open Hand (Palm Up)
    }

    return 'NEUTRAL';
  };

  const drawSkeleton = (ctx: CanvasRenderingContext2D, hand: HandData) => {
      ctx.strokeStyle = "rgba(255, 255, 255, 0.2)";
      ctx.lineWidth = 1;
      ctx.fillStyle = "rgba(255, 255, 255, 0.4)";
      const points = [hand.wrist, hand.indexBase, hand.indexTip, hand.middleBase, hand.middleTip, hand.ringBase, hand.ringTip, hand.pinkyBase, hand.pinkyTip, hand.thumbTip];

      const drawLine = (p1: any, p2: any) => { ctx.beginPath(); ctx.moveTo(p1.x, p1.y); ctx.lineTo(p2.x, p2.y); ctx.stroke(); }
      drawLine(hand.wrist, hand.indexBase); drawLine(hand.indexBase, hand.indexTip);
      drawLine(hand.wrist, hand.middleBase); drawLine(hand.middleBase, hand.middleTip);
      drawLine(hand.wrist, hand.pinkyBase); drawLine(hand.pinkyBase, hand.pinkyTip);

      points.forEach(p => { ctx.beginPath(); ctx.arc(p.x, p.y, 2, 0, Math.PI * 2); ctx.fill(); });
  };

  const onResults = useCallback((results: any) => {
    const videoWidth = webcamRef.current?.video?.videoWidth || width;
    const videoHeight = webcamRef.current?.video?.videoHeight || height;

    if (results.multiHandLandmarks && results.multiHandLandmarks.length > 0) {
      setDebugInfo(`Hands: ${results.multiHandLandmarks.length}`);
      const newHandData: HandData[] = results.multiHandLandmarks.map((landmarks: any[]) => {
        const gesture = detectGesture(landmarks, videoWidth, videoHeight);
        const mapPt = (idx: number) => ({ x: (1 - landmarks[idx].x) * videoWidth, y: landmarks[idx].y * videoHeight });
        return {
          wrist: mapPt(0), indexTip: mapPt(8), middleTip: mapPt(12), ringTip: mapPt(16), pinkyTip: mapPt(20), thumbTip: mapPt(4),
          indexBase: mapPt(5), middleBase: mapPt(9), ringBase: mapPt(13), pinkyBase: mapPt(17),
          isOpen: gesture !== 'THUNDER', gesture, opacity: 1,
        };
      });

      handDataRef.current = newHandData;
      let newElement = 'NEUTRAL';
      let activeCombo = null;

      if (newHandData.length === 2) {
          const g1 = newHandData[0].gesture;
          const g2 = newHandData[1].gesture;
          if (g1 !== 'NEUTRAL' && g2 !== 'NEUTRAL') activeCombo = getCombo(g1, g2);
      }

      if (activeCombo) newElement = activeCombo;
      else {
          const activeHand = newHandData.find(h => h.gesture !== 'NEUTRAL');
          if (activeHand) newElement = activeHand.gesture;
      }
      activeComboRef.current = activeCombo;

      if (newElement !== prevElementRef.current) {
          if (newElement !== 'NEUTRAL') { highlightRef.current = 1.0; playChime(newElement); }
          prevElementRef.current = newElement;
      }
      setCurrentElement(newElement);
    } else {
      handDataRef.current = [];
      setDebugInfo("No Hands");
      activeComboRef.current = null;
      if (prevElementRef.current !== 'NEUTRAL') { prevElementRef.current = 'NEUTRAL'; setCurrentElement('NEUTRAL'); }
    }
  }, [width, height, playChime]);

  useEffect(() => {
    let hands: any = null;
    let isActive = true;
    let frameId: number;
    let lastVideoTime = -1;

    const initHands = async () => {
       if (!(window as any).Hands) { setTimeout(initHands, 500); return; }
       hands = new (window as any).Hands({ locateFile: (file: string) => `https://cdn.jsdelivr.net/npm/@mediapipe/hands@0.4.1675469240/${file}` });
       hands.setOptions({ maxNumHands: 2, modelComplexity: 1, minDetectionConfidence: 0.5, minTrackingConfidence: 0.5 });
       hands.onResults(onResults);
       setIsModelLoaded(true);
       const processVideo = async () => {
         if (!isActive) return;
         if (webcamRef.current && webcamRef.current.video && webcamRef.current.video.readyState === 4) {
             const video = webcamRef.current.video;
             if (video.currentTime !== lastVideoTime) {
                 lastVideoTime = video.currentTime;
                 try { await hands.send({ image: video }); } catch (e) { console.error("MediaPipe error:", e); }
             }
         }
         frameId = requestAnimationFrame(processVideo);
       };
       processVideo();
    };
    initHands();
    return () => { isActive = false; if (frameId) cancelAnimationFrame(frameId); if (hands) hands.close(); };
  }, [onResults]);

  // --- PHYSICS ENGINE ---
  const updateParticles = (ctx: CanvasRenderingContext2D, width: number, height: number, centerX: number, centerY: number) => {
    for (let i = particlesRef.current.length - 1; i >= 0; i--) {
      const p = particlesRef.current[i];

      // General Drag
      p.vx *= 0.95;
      p.vy *= 0.95;

      // Element Specific Physics
      switch (p.element) {
          case 'WIND':
          case 'BLIZZARD':
              // Vortex/Spiral Physics
              const dx = p.x - centerX;
              const dy = p.y - centerY;
              const dist = Math.sqrt(dx*dx + dy*dy) + 1;
              const angle = Math.atan2(dy, dx);
              // Tangential force (Rotation)
              p.vx += Math.cos(angle + Math.PI/2) * 1.5;
              p.vy += Math.sin(angle + Math.PI/2) * 1.5;
              // Centripetal force (Suck in)
              p.vx -= (dx / dist) * 0.5;
              p.vy -= (dy / dist) * 0.5;
              p.angle += p.angularVelocity; // Spin the leaf
              break;

          case 'WATER':
          case 'STEAM':
              // Gravity & Rain
              p.vy += 1.2; // Strong gravity
              p.x += Math.sin(p.life * 0.1) * 0.5; // Slight waver
              break;

          case 'THUNDER':
          case 'TEMPEST':
          case 'VOID':
              // Chaotic / Jitter
              p.vx += (Math.random() - 0.5) * 4;
              p.vy += (Math.random() - 0.5) * 4;
              if (Math.random() < 0.1) { // Lightning jump
                  p.x += (Math.random() - 0.5) * 20;
                  p.y += (Math.random() - 0.5) * 20;
              }
              break;

          case 'FIRE':
          case 'INFERNO':
              // Thermal Lift / Turbulence
              p.vy -= 0.6; // Rise
              p.vx += (Math.random() - 0.5) * 1.5; // Turbulence
              p.size *= 0.96; // Shrink faster
              break;

          default:
              p.vy -= 0.1; // Neutral float
      }

      p.x += p.vx;
      p.y += p.vy;
      p.life -= 1;
      if (p.element !== 'FIRE') p.size *= 0.98;

      if (p.life <= 0 || p.size < 0.2 || p.y > height + 50) {
        particlesRef.current.splice(i, 1);
      } else {
        // --- RENDERER ---
        ctx.save();
        // Fade in and out
        ctx.globalAlpha = Math.min(1, p.life / 20, (p.maxLife - p.life) / 10);

        if (p.type === 'LEAF') {
            ctx.translate(p.x, p.y);
            ctx.rotate(p.angle);
            ctx.fillStyle = p.color;
            ctx.beginPath();
            ctx.ellipse(0, 0, p.size, p.size * 0.4, 0, 0, Math.PI * 2);
            ctx.fill();
        } 
        else if (p.type === 'DROP') {
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 2;
            ctx.lineCap = 'round';
            ctx.beginPath();
            ctx.moveTo(p.x, p.y);
            // Stretch rain drop based on velocity
            ctx.lineTo(p.x - p.vx, p.y - p.vy * 3); 
            ctx.stroke();
        }
        else if (p.type === 'SPARK') {
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 2;
            ctx.shadowColor = p.color;
            ctx.shadowBlur = 10;
            ctx.beginPath();
            ctx.moveTo(p.x - p.vx, p.y - p.vy);
            ctx.lineTo(p.x + p.vx, p.y + p.vy);
            ctx.stroke();
            // Occasional cross-bolt
            if (Math.random() > 0.5) {
                ctx.beginPath();
                ctx.moveTo(p.x, p.y);
                ctx.lineTo(p.x + (Math.random()-0.5)*20, p.y + (Math.random()-0.5)*20);
                ctx.stroke();
            }
        }
        else if (p.type === 'EMBER') {
            ctx.fillStyle = p.color;
            ctx.shadowColor = 'orange';
            ctx.shadowBlur = 15;
            ctx.beginPath();
            ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
            ctx.fill();
        }
        else { // ORB / MIST
            ctx.fillStyle = p.color;
            ctx.shadowColor = p.color;
            ctx.shadowBlur = p.type === 'ORB' ? 10 : 0;
            ctx.beginPath();
            ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
            ctx.fill();
        }
        ctx.restore();
      }
    }
  };

  const spawnParticles = (x: number, y: number, element: string, theme: Theme) => {
    // Check if it's a combo
    const isCombo = activeComboRef.current !== null;
    const count = isCombo ? 12 : 3;

    // Specific particle settings
    let type: ParticleType = 'ORB';
    let speed = Math.random() * 5;
    let spread = 20;

    // Customize Spawn based on Element
    if (element === 'WIND' || element === 'BLIZZARD') {
        type = Math.random() > 0.5 ? 'LEAF' : 'MIST';
        count = isCombo ? 15 : 4;
    } else if (element === 'WATER' || element === 'STEAM') {
        type = Math.random() > 0.7 ? 'MIST' : 'DROP';
        count = isCombo ? 20 : 5;
        spread = 40; 
    } else if (element === 'THUNDER' || element === 'TEMPEST' || element === 'VOID') {
        type = 'SPARK';
        count = isCombo ? 6 : 2; 
        speed = 8;
    } else if (element === 'FIRE' || element === 'INFERNO') {
        type = Math.random() > 0.8 ? 'MIST' : 'EMBER';
        count = isCombo ? 12 : 4;
    }

    for (let i = 0; i < count; i++) {
      const angle = Math.random() * Math.PI * 2;
      let vx = Math.cos(angle) * speed;
      let vy = Math.sin(angle) * speed;

      // Initial velocity overrides
      if (element === 'WATER' || element === 'STEAM') { vx *= 0.2; vy = Math.random() * 2; } 

      // Color tweaks
      let color = Math.random() > 0.5 ? theme.primary : theme.secondary;
      if (element === 'WIND') color = Math.random() > 0.5 ? '#00FFFF' : '#F0FFF0'; 
      if (element === 'THUNDER') color = Math.random() > 0.5 ? '#FFFF00' : '#9400D3';

      let spawnX = x;
      let spawnY = y;

      // FULL SCREEN SPAWN LOGIC
      if (isCombo || element === 'WATER') {
          spawnX = Math.random() * width;

          if (element === 'WATER' || element === 'TEMPEST') {
             // Falling Rain/Storm: Spawn Top
             spawnY = Math.random() * -100;
          } else {
             // Other Combos (Blizzard, Inferno, Plasma, Steam, Void): Full Field
             spawnY = Math.random() * height;
          }
      } else {
          // Hand localized spawn (Fire, Thunder, Wind)
          spawnX = x + (Math.random() - 0.5) * spread;
          spawnY = y + (Math.random() - 0.5) * spread;
      }

      particlesRef.current.push({
        x: spawnX,
        y: spawnY,
        vx, vy,
        life: 40 + Math.random() * 40,
        maxLife: 80,
        size: 3 + Math.random() * 5,
        color,
        element: element as Particle['element'],
        type,
        angle: Math.random() * Math.PI * 2,
        angularVelocity: (Math.random() - 0.5) * 0.2
      });
    }
  };

  const animate = useCallback((time: number) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (highlightRef.current > 0.01) highlightRef.current *= 0.9;
    else highlightRef.current = 0;
    const flash = highlightRef.current;

    // Use 'lighter' for high-energy anime look
    ctx.globalCompositeOperation = 'lighter'; 

    let lastCenterX = width / 2;
    let lastCenterY = height / 2;
    const t = time * 0.001;

    // Check for active combo
    const comboName = activeComboRef.current;

    if (comboName && handDataRef.current.length === 2) {
        // --- COMBO MODE ---
        const h1 = handDataRef.current[0];
        const h2 = handDataRef.current[1];
        const theme = COMBO_THEMES[comboName];

        const midX = (h1.middleBase.x + h2.middleBase.x) / 2;
        const midY = (h1.middleBase.y + h2.middleBase.y) / 2;
        lastCenterX = midX;
        lastCenterY = midY;

        // 1. Base Beam
        ctx.save();
        ctx.beginPath();
        ctx.moveTo(h1.middleBase.x, h1.middleBase.y);
        ctx.lineTo(h2.middleBase.x, h2.middleBase.y);
        ctx.strokeStyle = theme.primary;
        ctx.lineWidth = 20 + Math.sin(t * 10) * 5; 
        ctx.lineCap = 'round';
        ctx.shadowBlur = 40;
        ctx.shadowColor = theme.secondary;
        ctx.globalAlpha = 0.4;
        ctx.stroke();
        ctx.restore();

        // 2. Converging Energy
        ctx.save();
        ctx.beginPath();
        ctx.moveTo(h1.middleBase.x, h1.middleBase.y);
        ctx.lineTo(h2.middleBase.x, h2.middleBase.y);
        ctx.strokeStyle = '#FFFFFF';
        ctx.lineWidth = 3;
        ctx.setLineDash([10, 40]);
        ctx.lineDashOffset = -t * 200; 
        ctx.globalCompositeOperation = 'overlay';
        ctx.stroke();
        ctx.restore();

        // 3. Electric Arcs
        ctx.save();
        ctx.beginPath();
        ctx.moveTo(h1.middleBase.x, h1.middleBase.y);
        const dist = Math.hypot(h2.middleBase.x - h1.middleBase.x, h2.middleBase.y - h1.middleBase.y);
        const angle = Math.atan2(h2.middleBase.y - h1.middleBase.y, h2.middleBase.x - h1.middleBase.x);
        for(let i=0; i<=20; i++) {
             const p = i/20;
             const perp = Math.sin(p * Math.PI * 4 + t * 20) * (15 + Math.random() * 5);
             const bx = h1.middleBase.x + (h2.middleBase.x - h1.middleBase.x) * p + Math.cos(angle + Math.PI/2)*perp;
             const by = h1.middleBase.y + (h2.middleBase.y - h1.middleBase.y) * p + Math.sin(angle + Math.PI/2)*perp;
             ctx.lineTo(bx, by);
        }
        ctx.strokeStyle = theme.secondary;
        ctx.lineWidth = 2;
        ctx.shadowBlur = 10;
        ctx.shadowColor = theme.core;
        ctx.stroke();
        ctx.restore();

        // Array
        ctx.globalAlpha = 1;
        drawRuneRing(ctx, midX, midY, 180, t, theme);
        drawSacredGeometry(ctx, midX, midY, 140, -t * 2, theme);
        drawSquareLayer(ctx, midX, midY, 100, t * 3, theme);
        drawPentagram(ctx, midX, midY, 60, -t, 1, theme);

        spawnParticles(midX, midY, comboName, theme);

        handDataRef.current.forEach(h => {
             drawSkeleton(ctx, h);
             const auraSize = 50 + Math.sin(t * 20) * 10;
             const grad = ctx.createRadialGradient(h.middleBase.x, h.middleBase.y, 10, h.middleBase.x, h.middleBase.y, auraSize);
             grad.addColorStop(0, theme.core);
             grad.addColorStop(0.4, theme.primary);
             grad.addColorStop(1, 'rgba(0,0,0,0)');
             ctx.save();
             ctx.fillStyle = grad;
             ctx.globalAlpha = 0.5;
             ctx.beginPath();
             ctx.arc(h.middleBase.x, h.middleBase.y, auraSize, 0, Math.PI * 2);
             ctx.fill();
             ctx.restore();
             drawRuneRing(ctx, h.middleBase.x, h.middleBase.y, 40, t*5, theme);
        });

    } else {
        // --- INDIVIDUAL MODE ---
        handDataRef.current.forEach((hand) => {
           drawSkeleton(ctx, hand);
           const element = hand.gesture;
           const theme = (element !== 'NEUTRAL' && THEMES[element]) ? THEMES[element] : THEMES['NEUTRAL'];
           const centerX = hand.middleBase.x; 
           const centerY = hand.middleBase.y; 

           if (element !== 'NEUTRAL') {
               if (flash > 0.05 && highlightRef.current > 0.05) {
                   ctx.save();
                   ctx.translate(centerX, centerY);
                   const waveSize = 120 + (1 - flash) * 100;
                   ctx.beginPath();
                   ctx.arc(0, 0, waveSize, 0, Math.PI * 2);
                   ctx.lineWidth = 10 * flash;
                   ctx.strokeStyle = theme.core;
                   ctx.shadowBlur = 20;
                   ctx.shadowColor = theme.secondary;
                   ctx.globalAlpha = flash;
                   ctx.stroke();
                   ctx.restore();
               }

               drawRuneRing(ctx, centerX, centerY, 120, t * 0.5, theme);
               drawSacredGeometry(ctx, centerX, centerY, 90, -t * 1.5, theme);
               drawSquareLayer(ctx, centerX, centerY, 65, t * 2.5, theme);
               const pulse = Math.sin(time * 0.005) * 0.5 + 0.5;
               drawPentagram(ctx, centerX, centerY, 40, t, pulse, theme);

               spawnParticles(centerX, centerY, element, theme);
               lastCenterX = centerX;
               lastCenterY = centerY;
           } else {
               ctx.globalAlpha = 0.3;
               drawRuneRing(ctx, centerX, centerY, 50, t * 0.2, theme);
           }
        });
    }

    updateParticles(ctx, canvas.width, canvas.height, lastCenterX, lastCenterY);
    requestRef.current = requestAnimationFrame(animate);
  }, [width, height]);

  useEffect(() => {
    requestRef.current = requestAnimationFrame(animate);
    return () => { if (requestRef.current) cancelAnimationFrame(requestRef.current); };
  }, [animate]);

  return (
    <div className="relative w-full h-full bg-black overflow-hidden flex items-center justify-center">
        <Webcam ref={webcamRef} audio={false} width={width} height={height} mirrored={true} screenshotFormat="image/jpeg" className="absolute opacity-0 pointer-events-none" />
        <Webcam audio={false} width={width} height={height} mirrored={true} className="absolute top-0 left-0 w-full h-full object-cover opacity-80" />
        <canvas ref={canvasRef} width={width} height={height} className="absolute top-0 left-0 w-full h-full object-cover z-10" />
        {!isModelLoaded && (
            <div className="absolute inset-0 flex items-center justify-center bg-black bg-opacity-80 z-50">
                <div className="text-amber-500 font-mono text-xl animate-pulse">Summoning Grimoire... (Loading Models)</div>
            </div>
        )}
        <div className="absolute top-4 right-4 text-right z-20 font-mono pointer-events-none">
            <div className={`text-2xl font-bold mb-2 tracking-widest transition-all duration-300 ${highlightRef.current > 0.1 ? 'scale-110' : ''} ${
                currentElement === 'FIRE' ? 'text-orange-500' :
                currentElement === 'WATER' ? 'text-blue-500' :
                currentElement === 'WIND' ? 'text-cyan-300' :
                currentElement === 'THUNDER' ? 'text-purple-500' : 
                currentElement === 'INFERNO' ? 'text-red-600' :
                currentElement === 'BLIZZARD' ? 'text-cyan-100' :
                currentElement === 'VOID' ? 'text-violet-900' : 'text-amber-500'
            }`}>SPELL: {currentElement}</div>
            <div className="text-xs text-white opacity-70 space-y-1 mb-2"><p>Status: {debugInfo}</p></div>
            <div className="text-xs text-white opacity-70 space-y-1">
                <p>✋ Palm Up: FIRE</p>
                <p>👇 Palm Down: WATER (RAIN)</p>
                <p>👊 Fist: THUNDER</p>
                <p>✌️ Victory: WIND</p>
            </div>
        </div>
    </div>
  );
};

export default MagicOverlay;

import React, { useEffect, useRef, useCallback, useState } from 'react';
import Webcam from 'react-webcam';
import { Particle, HandData, ElementType, Theme, ParticleType } from '../types';
import { 
  drawRuneRing, 
  drawSacredGeometry, 
  drawSquareLayer, 
  drawPentagram,
  THEMES
} from '../utils/geometry';

interface MagicOverlayProps {
  width: number;
  height: number;
}

const COMBO_THEMES: Record<string, Theme> = {
  'BLIZZARD': { primary: '#00FFFF', secondary: '#E0FFFF', core: '#FFFFFF', shadow: '#008B8B' }, // Ice/Wind
  'PLASMA': { primary: '#FF00FF', secondary: '#00FFFF', core: '#FFFFFF', shadow: '#9400D3' }, // Fire/Wind
  'STEAM': { primary: '#F0F8FF', secondary: '#B0C4DE', core: '#FFFFFF', shadow: '#778899' }, // Fire/Water
  'TEMPEST': { primary: '#000080', secondary: '#8A2BE2', core: '#FFFF00', shadow: '#191970' }, // Thunder/Water
  'INFERNO': { primary: '#FF0000', secondary: '#FF4500', core: '#FFFF00', shadow: '#8B0000' }, // Fire/Fire
  'VOID': { primary: '#000000', secondary: '#4B0082', core: '#FFFFFF', shadow: '#9400D3' }, // Thunder/Thunder
};

const getCombo = (g1: ElementType, g2: ElementType): string | null => {
    const sorted = [g1, g2].sort().join('_');
    switch(sorted) {
        case 'WATER_WIND': return 'BLIZZARD';
        case 'FIRE_WIND': return 'PLASMA';
        case 'FIRE_WATER': return 'STEAM';
        case 'THUNDER_WATER': return 'TEMPEST';
        case 'FIRE_FIRE': return 'INFERNO';
        case 'THUNDER_THUNDER': return 'VOID';
        default: return null;
    }
};

const MagicOverlay: React.FC<MagicOverlayProps> = ({ width, height }) => {
  const webcamRef = useRef<Webcam>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>(0);
  const particlesRef = useRef<Particle[]>([]);
  const handDataRef = useRef<HandData[]>([]);
  const [currentElement, setCurrentElement] = useState<string>('NEUTRAL');
  const [isModelLoaded, setIsModelLoaded] = useState(false);
  const [debugInfo, setDebugInfo] = useState<string>("Initializing...");

  // Visual Feedback State
  const highlightRef = useRef<number>(0);
  const prevElementRef = useRef<string>('NEUTRAL');
  const activeComboRef = useRef<string | null>(null);

  // Audio Context
  const audioContextRef = useRef<AudioContext | null>(null);

  useEffect(() => {
    const AudioContextClass = (window as any).AudioContext || (window as any).webkitAudioContext;
    if (AudioContextClass) {
        audioContextRef.current = new AudioContextClass();
    }
  }, []);

  const playChime = useCallback((element: string) => {
    if (!audioContextRef.current) return;
    const ctx = audioContextRef.current;
    if (ctx.state === 'suspended') {
        ctx.resume().catch(console.error);
    }

    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.connect(gain);
    gain.connect(ctx.destination);

    let freq = 440;
    let type: OscillatorType = 'sine';
    let duration = 0.5;

    switch (element) {
        case 'FIRE': 
        case 'INFERNO':
            freq = 220; type = 'sawtooth'; 
            osc.frequency.setValueAtTime(freq, ctx.currentTime);
            osc.frequency.exponentialRampToValueAtTime(freq * 3, ctx.currentTime + 0.3);
            break;
        case 'WATER': 
        case 'STEAM':
            freq = 600; type = 'sine';
            osc.frequency.setValueAtTime(freq, ctx.currentTime);
            osc.frequency.exponentialRampToValueAtTime(200, ctx.currentTime + 0.2);
            duration = 0.3;
            break;
        case 'THUNDER': 
        case 'TEMPEST':
        case 'VOID':
            freq = 150; type = 'square';
            osc.frequency.setValueAtTime(freq, ctx.currentTime);
            osc.frequency.linearRampToValueAtTime(freq * 0.8, ctx.currentTime + 0.1);
            break;
        case 'WIND': 
        case 'BLIZZARD':
        case 'PLASMA':
            freq = 880; type = 'triangle';
            osc.frequency.setValueAtTime(freq, ctx.currentTime);
            break;
    }

    osc.type = type;
    const now = ctx.currentTime;
    gain.gain.setValueAtTime(0, now);
    gain.gain.linearRampToValueAtTime(0.05, now + 0.05);
    gain.gain.exponentialRampToValueAtTime(0.001, now + duration);
    osc.start(now);
    osc.stop(now + duration);
  }, []);

  const detectGesture = (landmarks: any[], videoWidth: number, videoHeight: number): ElementType => {
    const mapPt = (idx: number) => ({ x: (1 - landmarks[idx].x) * videoWidth, y: landmarks[idx].y * videoHeight });
    const wrist = mapPt(0);
    const indexTip = mapPt(8);
    const middleTip = mapPt(12);
    const ringTip = mapPt(16);
    const pinkyTip = mapPt(20);
    const indexMCP = mapPt(5);
    const middleMCP = mapPt(9);
    const ringMCP = mapPt(13); // Fixed missing ringMCP
    const pinkyMCP = mapPt(17);

    const dist = (p1: any, p2: any) => Math.hypot(p1.x - p2.x, p1.y - p2.y);

    // Check if finger is open (tip further from wrist than base)
    const isFingerOpen = (tip: any, mcp: any) => dist(tip, wrist) > dist(mcp, wrist) * 1.1;

    const indexOpen = isFingerOpen(indexTip, indexMCP);
    const middleOpen = isFingerOpen(middleTip, middleMCP);
    const ringOpen = isFingerOpen(ringTip, ringMCP);
    const pinkyOpen = isFingerOpen(pinkyTip, pinkyMCP);

    // Orientation: Y grows downwards. 
    // If Wrist Y < Middle MCP Y, the wrist is ABOVE the hand -> Hand Pointing DOWN
    const isPointingDown = wrist.y < middleMCP.y;

    if (isPointingDown) {
        // Rain/Water: Hand pointing down (even if closed or open, as long as pointing down)
        // Adding a check for at least some fingers open to avoid false positives during transitions
        if (indexOpen || middleOpen) return 'WATER';
    } else {
        // Pointing Up
        if (!indexOpen && !middleOpen && !ringOpen && !pinkyOpen) return 'THUNDER'; // Fist
        if (indexOpen && middleOpen && !ringOpen && !pinkyOpen) return 'WIND'; // Victory Sign
        if (indexOpen && middleOpen && ringOpen) return 'FIRE'; // Open Hand (Palm Up)
    }

    return 'NEUTRAL';
  };

  const drawSkeleton = (ctx: CanvasRenderingContext2D, hand: HandData) => {
      ctx.strokeStyle = "rgba(255, 255, 255, 0.2)";
      ctx.lineWidth = 1;
      ctx.fillStyle = "rgba(255, 255, 255, 0.4)";
      const points = [hand.wrist, hand.indexBase, hand.indexTip, hand.middleBase, hand.middleTip, hand.ringBase, hand.ringTip, hand.pinkyBase, hand.pinkyTip, hand.thumbTip];

      const drawLine = (p1: any, p2: any) => { ctx.beginPath(); ctx.moveTo(p1.x, p1.y); ctx.lineTo(p2.x, p2.y); ctx.stroke(); }
      drawLine(hand.wrist, hand.indexBase); drawLine(hand.indexBase, hand.indexTip);
      drawLine(hand.wrist, hand.middleBase); drawLine(hand.middleBase, hand.middleTip);
      drawLine(hand.wrist, hand.pinkyBase); drawLine(hand.pinkyBase, hand.pinkyTip);

      points.forEach(p => { ctx.beginPath(); ctx.arc(p.x, p.y, 2, 0, Math.PI * 2); ctx.fill(); });
  };

  const onResults = useCallback((results: any) => {
    const videoWidth = webcamRef.current?.video?.videoWidth || width;
    const videoHeight = webcamRef.current?.video?.videoHeight || height;

    if (results.multiHandLandmarks && results.multiHandLandmarks.length > 0) {
      setDebugInfo(`Hands: ${results.multiHandLandmarks.length}`);
      const newHandData: HandData[] = results.multiHandLandmarks.map((landmarks: any[]) => {
        const gesture = detectGesture(landmarks, videoWidth, videoHeight);
        const mapPt = (idx: number) => ({ x: (1 - landmarks[idx].x) * videoWidth, y: landmarks[idx].y * videoHeight });
        return {
          wrist: mapPt(0), indexTip: mapPt(8), middleTip: mapPt(12), ringTip: mapPt(16), pinkyTip: mapPt(20), thumbTip: mapPt(4),
          indexBase: mapPt(5), middleBase: mapPt(9), ringBase: mapPt(13), pinkyBase: mapPt(17),
          isOpen: gesture !== 'THUNDER', gesture, opacity: 1,
        };
      });

      handDataRef.current = newHandData;
      let newElement = 'NEUTRAL';
      let activeCombo = null;

      if (newHandData.length === 2) {
          const g1 = newHandData[0].gesture;
          const g2 = newHandData[1].gesture;
          if (g1 !== 'NEUTRAL' && g2 !== 'NEUTRAL') activeCombo = getCombo(g1, g2);
      }

      if (activeCombo) newElement = activeCombo;
      else {
          const activeHand = newHandData.find(h => h.gesture !== 'NEUTRAL');
          if (activeHand) newElement = activeHand.gesture;
      }
      activeComboRef.current = activeCombo;

      if (newElement !== prevElementRef.current) {
          if (newElement !== 'NEUTRAL') { highlightRef.current = 1.0; playChime(newElement); }
          prevElementRef.current = newElement;
      }
      setCurrentElement(newElement);
    } else {
      handDataRef.current = [];
      setDebugInfo("No Hands");
      activeComboRef.current = null;
      if (prevElementRef.current !== 'NEUTRAL') { prevElementRef.current = 'NEUTRAL'; setCurrentElement('NEUTRAL'); }
    }
  }, [width, height, playChime]);

  useEffect(() => {
    let hands: any = null;
    let isActive = true;
    let frameId: number;
    let lastVideoTime = -1;

    const initHands = async () => {
       if (!(window as any).Hands) { setTimeout(initHands, 500); return; }
       hands = new (window as any).Hands({ locateFile: (file: string) => `https://cdn.jsdelivr.net/npm/@mediapipe/hands@0.4.1675469240/${file}` });
       hands.setOptions({ maxNumHands: 2, modelComplexity: 1, minDetectionConfidence: 0.5, minTrackingConfidence: 0.5 });
       hands.onResults(onResults);
       setIsModelLoaded(true);
       const processVideo = async () => {
         if (!isActive) return;
         if (webcamRef.current && webcamRef.current.video && webcamRef.current.video.readyState === 4) {
             const video = webcamRef.current.video;
             if (video.currentTime !== lastVideoTime) {
                 lastVideoTime = video.currentTime;
                 try { await hands.send({ image: video }); } catch (e) { console.error("MediaPipe error:", e); }
             }
         }
         frameId = requestAnimationFrame(processVideo);
       };
       processVideo();
    };
    initHands();
    return () => { isActive = false; if (frameId) cancelAnimationFrame(frameId); if (hands) hands.close(); };
  }, [onResults]);

  // --- PHYSICS ENGINE ---
  const updateParticles = (ctx: CanvasRenderingContext2D, width: number, height: number, centerX: number, centerY: number) => {
    for (let i = particlesRef.current.length - 1; i >= 0; i--) {
      const p = particlesRef.current[i];

      // General Drag
      p.vx *= 0.95;
      p.vy *= 0.95;

      // Element Specific Physics
      switch (p.element) {
          case 'WIND':
          case 'BLIZZARD':
              // Vortex/Spiral Physics
              const dx = p.x - centerX;
              const dy = p.y - centerY;
              const dist = Math.sqrt(dx*dx + dy*dy) + 1;
              const angle = Math.atan2(dy, dx);
              // Tangential force (Rotation)
              p.vx += Math.cos(angle + Math.PI/2) * 1.5;
              p.vy += Math.sin(angle + Math.PI/2) * 1.5;
              // Centripetal force (Suck in)
              p.vx -= (dx / dist) * 0.5;
              p.vy -= (dy / dist) * 0.5;
              p.angle += p.angularVelocity; // Spin the leaf
              break;

          case 'WATER':
          case 'STEAM':
              // Gravity & Rain
              p.vy += 1.2; // Strong gravity
              p.x += Math.sin(p.life * 0.1) * 0.5; // Slight waver
              break;

          case 'THUNDER':
          case 'TEMPEST':
          case 'VOID':
              // Chaotic / Jitter
              p.vx += (Math.random() - 0.5) * 4;
              p.vy += (Math.random() - 0.5) * 4;
              if (Math.random() < 0.1) { // Lightning jump
                  p.x += (Math.random() - 0.5) * 20;
                  p.y += (Math.random() - 0.5) * 20;
              }
              break;

          case 'FIRE':
          case 'INFERNO':
              // Thermal Lift / Turbulence
              p.vy -= 0.6; // Rise
              p.vx += (Math.random() - 0.5) * 1.5; // Turbulence
              p.size *= 0.96; // Shrink faster
              break;

          default:
              p.vy -= 0.1; // Neutral float
      }

      p.x += p.vx;
      p.y += p.vy;
      p.life -= 1;
      if (p.element !== 'FIRE') p.size *= 0.98;

      if (p.life <= 0 || p.size < 0.2 || p.y > height + 50) {
        particlesRef.current.splice(i, 1);
      } else {
        // --- RENDERER ---
        ctx.save();
        // Fade in and out
        ctx.globalAlpha = Math.min(1, p.life / 20, (p.maxLife - p.life) / 10);

        if (p.type === 'LEAF') {
            ctx.translate(p.x, p.y);
            ctx.rotate(p.angle);
            ctx.fillStyle = p.color;
            ctx.beginPath();
            ctx.ellipse(0, 0, p.size, p.size * 0.4, 0, 0, Math.PI * 2);
            ctx.fill();
        } 
        else if (p.type === 'DROP') {
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 2;
            ctx.lineCap = 'round';
            ctx.beginPath();
            ctx.moveTo(p.x, p.y);
            // Stretch rain drop based on velocity
            ctx.lineTo(p.x - p.vx, p.y - p.vy * 3); 
            ctx.stroke();
        }
        else if (p.type === 'SPARK') {
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 2;
            ctx.shadowColor = p.color;
            ctx.shadowBlur = 10;
            ctx.beginPath();
            ctx.moveTo(p.x - p.vx, p.y - p.vy);
            ctx.lineTo(p.x + p.vx, p.y + p.vy);
            ctx.stroke();
            // Occasional cross-bolt
            if (Math.random() > 0.5) {
                ctx.beginPath();
                ctx.moveTo(p.x, p.y);
                ctx.lineTo(p.x + (Math.random()-0.5)*20, p.y + (Math.random()-0.5)*20);
                ctx.stroke();
            }
        }
        else if (p.type === 'EMBER') {
            ctx.fillStyle = p.color;
            ctx.shadowColor = 'orange';
            ctx.shadowBlur = 15;
            ctx.beginPath();
            ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
            ctx.fill();
        }
        else { // ORB / MIST
            ctx.fillStyle = p.color;
            ctx.shadowColor = p.color;
            ctx.shadowBlur = p.type === 'ORB' ? 10 : 0;
            ctx.beginPath();
            ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
            ctx.fill();
        }
        ctx.restore();
      }
    }
  };

  const spawnParticles = (x: number, y: number, element: string, theme: Theme) => {
    // Check if it's a combo
    const isCombo = activeComboRef.current !== null;
    let count = isCombo ? 12 : 3;

    // Specific particle settings
    let type: ParticleType = 'ORB';
    let speed = Math.random() * 5;
    let spread = 20;

    // Customize Spawn based on Element
    if (element === 'WIND' || element === 'BLIZZARD') {
        type = Math.random() > 0.5 ? 'LEAF' : 'MIST';
        count = isCombo ? 15 : 4;
    } else if (element === 'WATER' || element === 'STEAM') {
        type = Math.random() > 0.7 ? 'MIST' : 'DROP';
        count = isCombo ? 20 : 5;
        spread = 40; 
    } else if (element === 'THUNDER' || element === 'TEMPEST' || element === 'VOID') {
        type = 'SPARK';
        count = isCombo ? 6 : 2; 
        speed = 8;
    } else if (element === 'FIRE' || element === 'INFERNO') {
        type = Math.random() > 0.8 ? 'MIST' : 'EMBER';
        count = isCombo ? 12 : 4;
    }

    for (let i = 0; i < count; i++) {
      const angle = Math.random() * Math.PI * 2;
      let vx = Math.cos(angle) * speed;
      let vy = Math.sin(angle) * speed;

      // Initial velocity overrides
      if (element === 'WATER' || element === 'STEAM') { vx *= 0.2; vy = Math.random() * 2; } 

      // Color tweaks
      let color = Math.random() > 0.5 ? theme.primary : theme.secondary;
      if (element === 'WIND') color = Math.random() > 0.5 ? '#00FFFF' : '#F0FFF0'; 
      if (element === 'THUNDER') color = Math.random() > 0.5 ? '#FFFF00' : '#9400D3';

      let spawnX = x;
      let spawnY = y;

      // FULL SCREEN SPAWN LOGIC
      if (isCombo || element === 'WATER') {
          spawnX = Math.random() * width;

          if (element === 'WATER' || element === 'TEMPEST') {
             // Falling Rain/Storm: Spawn Top
             spawnY = Math.random() * -100;
          } else {
             // Other Combos (Blizzard, Inferno, Plasma, Steam, Void): Full Field
             spawnY = Math.random() * height;
          }
      } else {
          // Hand localized spawn (Fire, Thunder, Wind)
          spawnX = x + (Math.random() - 0.5) * spread;
          spawnY = y + (Math.random() - 0.5) * spread;
      }

      particlesRef.current.push({
        x: spawnX,
        y: spawnY,
        vx, vy,
        life: 40 + Math.random() * 40,
        maxLife: 80,
        size: 3 + Math.random() * 5,
        color,
        element: element as Particle['element'],
        type,
        angle: Math.random() * Math.PI * 2,
        angularVelocity: (Math.random() - 0.5) * 0.2
      });
    }
  };

  const animate = useCallback((time: number) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (highlightRef.current > 0.01) highlightRef.current *= 0.9;
    else highlightRef.current = 0;
    const flash = highlightRef.current;

    // Use 'lighter' for high-energy anime look
    ctx.globalCompositeOperation = 'lighter'; 

    let lastCenterX = width / 2;
    let lastCenterY = height / 2;
    const t = time * 0.001;

    // Check for active combo
    const comboName = activeComboRef.current;

    if (comboName && handDataRef.current.length === 2) {
        // --- COMBO MODE ---
        const h1 = handDataRef.current[0];
        const h2 = handDataRef.current[1];
        const theme = COMBO_THEMES[comboName];

        const midX = (h1.middleBase.x + h2.middleBase.x) / 2;
        const midY = (h1.middleBase.y + h2.middleBase.y) / 2;
        lastCenterX = midX;
        lastCenterY = midY;

        // 1. Base Beam
        ctx.save();
        ctx.beginPath();
        ctx.moveTo(h1.middleBase.x, h1.middleBase.y);
        ctx.lineTo(h2.middleBase.x, h2.middleBase.y);
        ctx.strokeStyle = theme.primary;
        ctx.lineWidth = 20 + Math.sin(t * 10) * 5; 
        ctx.lineCap = 'round';
        ctx.shadowBlur = 40;
        ctx.shadowColor = theme.secondary;
        ctx.globalAlpha = 0.4;
        ctx.stroke();
        ctx.restore();

        // 2. Converging Energy
        ctx.save();
        ctx.beginPath();
        ctx.moveTo(h1.middleBase.x, h1.middleBase.y);
        ctx.lineTo(h2.middleBase.x, h2.middleBase.y);
        ctx.strokeStyle = '#FFFFFF';
        ctx.lineWidth = 3;
        ctx.setLineDash([10, 40]);
        ctx.lineDashOffset = -t * 200; 
        ctx.globalCompositeOperation = 'overlay';
        ctx.stroke();
        ctx.restore();

        // 3. Electric Arcs
        ctx.save();
        ctx.beginPath();
        ctx.moveTo(h1.middleBase.x, h1.middleBase.y);
        const dist = Math.hypot(h2.middleBase.x - h1.middleBase.x, h2.middleBase.y - h1.middleBase.y);
        const angle = Math.atan2(h2.middleBase.y - h1.middleBase.y, h2.middleBase.x - h1.middleBase.x);
        for(let i=0; i<=20; i++) {
             const p = i/20;
             const perp = Math.sin(p * Math.PI * 4 + t * 20) * (15 + Math.random() * 5);
             const bx = h1.middleBase.x + (h2.middleBase.x - h1.middleBase.x) * p + Math.cos(angle + Math.PI/2)*perp;
             const by = h1.middleBase.y + (h2.middleBase.y - h1.middleBase.y) * p + Math.sin(angle + Math.PI/2)*perp;
             ctx.lineTo(bx, by);
        }
        ctx.strokeStyle = theme.secondary;
        ctx.lineWidth = 2;
        ctx.shadowBlur = 10;
        ctx.shadowColor = theme.core;
        ctx.stroke();
        ctx.restore();

        // Array
        ctx.globalAlpha = 1;
        drawRuneRing(ctx, midX, midY, 180, t, theme);
        drawSacredGeometry(ctx, midX, midY, 140, -t * 2, theme);
        drawSquareLayer(ctx, midX, midY, 100, t * 3, theme);
        drawPentagram(ctx, midX, midY, 60, -t, 1, theme);

        spawnParticles(midX, midY, comboName, theme);

        handDataRef.current.forEach(h => {
             drawSkeleton(ctx, h);
             const auraSize = 50 + Math.sin(t * 20) * 10;
             const grad = ctx.createRadialGradient(h.middleBase.x, h.middleBase.y, 10, h.middleBase.x, h.middleBase.y, auraSize);
             grad.addColorStop(0, theme.core);
             grad.addColorStop(0.4, theme.primary);
             grad.addColorStop(1, 'rgba(0,0,0,0)');
             ctx.save();
             ctx.fillStyle = grad;
             ctx.globalAlpha = 0.5;
             ctx.beginPath();
             ctx.arc(h.middleBase.x, h.middleBase.y, auraSize, 0, Math.PI * 2);
             ctx.fill();
             ctx.restore();
             drawRuneRing(ctx, h.middleBase.x, h.middleBase.y, 40, t*5, theme);
        });

    } else {
        // --- INDIVIDUAL MODE ---
        handDataRef.current.forEach((hand) => {
           drawSkeleton(ctx, hand);
           const element = hand.gesture;
           const theme = (element !== 'NEUTRAL' && THEMES[element]) ? THEMES[element] : THEMES['NEUTRAL'];
           const centerX = hand.middleBase.x; 
           const centerY = hand.middleBase.y; 

           if (element !== 'NEUTRAL') {
               if (flash > 0.05 && highlightRef.current > 0.05) {
                   ctx.save();
                   ctx.translate(centerX, centerY);
                   const waveSize = 120 + (1 - flash) * 100;
                   ctx.beginPath();
                   ctx.arc(0, 0, waveSize, 0, Math.PI * 2);
                   ctx.lineWidth = 10 * flash;
                   ctx.strokeStyle = theme.core;
                   ctx.shadowBlur = 20;
                   ctx.shadowColor = theme.secondary;
                   ctx.globalAlpha = flash;
                   ctx.stroke();
                   ctx.restore();
               }

               drawRuneRing(ctx, centerX, centerY, 120, t * 0.5, theme);
               drawSacredGeometry(ctx, centerX, centerY, 90, -t * 1.5, theme);
               drawSquareLayer(ctx, centerX, centerY, 65, t * 2.5, theme);
               const pulse = Math.sin(time * 0.005) * 0.5 + 0.5;
               drawPentagram(ctx, centerX, centerY, 40, t, pulse, theme);

               spawnParticles(centerX, centerY, element, theme);
               lastCenterX = centerX;
               lastCenterY = centerY;
           } else {
               ctx.globalAlpha = 0.3;
               drawRuneRing(ctx, centerX, centerY, 50, t * 0.2, theme);
           }
        });
    }

    updateParticles(ctx, canvas.width, canvas.height, lastCenterX, lastCenterY);
    requestRef.current = requestAnimationFrame(animate);
  }, [width, height]);

  useEffect(() => {
    requestRef.current = requestAnimationFrame(animate);
    return () => { if (requestRef.current) cancelAnimationFrame(requestRef.current); };
  }, [animate]);

  return (
    <div className="relative w-full h-full bg-black overflow-hidden flex items-center justify-center">
        <Webcam ref={webcamRef} audio={false} width={width} height={height} mirrored={true} screenshotFormat="image/jpeg" className="absolute opacity-0 pointer-events-none" />
        <Webcam audio={false} width={width} height={height} mirrored={true} className="absolute top-0 left-0 w-full h-full object-cover opacity-80" />
        <canvas ref={canvasRef} width={width} height={height} className="absolute top-0 left-0 w-full h-full object-cover z-10" />
        {!isModelLoaded && (
            <div className="absolute inset-0 flex items-center justify-center bg-black bg-opacity-80 z-50">
                <div className="text-amber-500 font-mono text-xl animate-pulse">Summoning Grimoire... (Loading Models)</div>
            </div>
        )}
        <div className="absolute top-4 right-4 text-right z-20 font-mono pointer-events-none">
            <div className={`text-2xl font-bold mb-2 tracking-widest transition-all duration-300 ${highlightRef.current > 0.1 ? 'scale-110' : ''} ${
                currentElement === 'FIRE' ? 'text-orange-500' :
                currentElement === 'WATER' ? 'text-blue-500' :
                currentElement === 'WIND' ? 'text-cyan-300' :
                currentElement === 'THUNDER' ? 'text-purple-500' : 
                currentElement === 'INFERNO' ? 'text-red-600' :
                currentElement === 'BLIZZARD' ? 'text-cyan-100' :
                currentElement === 'VOID' ? 'text-violet-900' : 'text-amber-500'
            }`}>SPELL: {currentElement}</div>
            <div className="text-xs text-white opacity-70 space-y-1 mb-2"><p>Status: {debugInfo}</p></div>
            <div className="text-xs text-white opacity-70 space-y-1">
                <p>✋ Palm Up: FIRE</p>
                <p>👇 Palm Down: WATER (RAIN)</p>
                <p>👊 Fist: THUNDER</p>
                <p>✌️ Victory: WIND</p>
            </div>
        </div>
    </div>
  );
};

export default MagicOverlay;

import React, { useEffect, useRef, useCallback, useState } from 'react';
import Webcam from 'react-webcam';
import { Particle, HandData, ElementType, Theme, ParticleType } from '../types';
import { 
  drawRuneRing, 
  drawSacredGeometry, 
  drawSquareLayer, 
  drawPentagram,
  THEMES
} from '../utils/geometry';

interface MagicOverlayProps {
  width: number;
  height: number;
}

const COMBO_THEMES: Record<string, Theme> = {
  'BLIZZARD': { primary: '#00FFFF', secondary: '#E0FFFF', core: '#FFFFFF', shadow: '#008B8B' }, // Ice/Wind
  'PLASMA': { primary: '#FF00FF', secondary: '#00FFFF', core: '#FFFFFF', shadow: '#9400D3' }, // Fire/Wind
  'STEAM': { primary: '#F0F8FF', secondary: '#B0C4DE', core: '#FFFFFF', shadow: '#778899' }, // Fire/Water
  'TEMPEST': { primary: '#000080', secondary: '#8A2BE2', core: '#FFFF00', shadow: '#191970' }, // Thunder/Water
  'INFERNO': { primary: '#FF0000', secondary: '#FF4500', core: '#FFFF00', shadow: '#8B0000' }, // Fire/Fire
  'VOID': { primary: '#000000', secondary: '#4B0082', core: '#FFFFFF', shadow: '#9400D3' }, // Thunder/Thunder
};

const getCombo = (g1: ElementType, g2: ElementType): string | null => {
    const sorted = [g1, g2].sort().join('_');
    switch(sorted) {
        case 'WATER_WIND': return 'BLIZZARD';
        case 'FIRE_WIND': return 'PLASMA';
        case 'FIRE_WATER': return 'STEAM';
        case 'THUNDER_WATER': return 'TEMPEST';
        case 'FIRE_FIRE': return 'INFERNO';
        case 'THUNDER_THUNDER': return 'VOID';
        default: return null;
    }
};

const MagicOverlay: React.FC<MagicOverlayProps> = ({ width, height }) => {
  const webcamRef = useRef<Webcam>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>(0);
  const particlesRef = useRef<Particle[]>([]);
  const handDataRef = useRef<HandData[]>([]);
  const [currentElement, setCurrentElement] = useState<string>('NEUTRAL');
  const [isModelLoaded, setIsModelLoaded] = useState(false);
  const [debugInfo, setDebugInfo] = useState<string>("Initializing...");

  // Visual Feedback State
  const highlightRef = useRef<number>(0);
  const prevElementRef = useRef<string>('NEUTRAL');
  const activeComboRef = useRef<string | null>(null);

  // Audio Context
  const audioContextRef = useRef<AudioContext | null>(null);

  useEffect(() => {
    const AudioContextClass = (window as any).AudioContext || (window as any).webkitAudioContext;
    if (AudioContextClass) {
        audioContextRef.current = new AudioContextClass();
    }
  }, []);

  const playChime = useCallback((element: string) => {
    if (!audioContextRef.current) return;
    const ctx = audioContextRef.current;
    if (ctx.state === 'suspended') {
        ctx.resume().catch(console.error);
    }

    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.connect(gain);
    gain.connect(ctx.destination);

    let freq = 440;
    let type: OscillatorType = 'sine';
    let duration = 0.5;

    switch (element) {
        case 'FIRE': 
        case 'INFERNO':
            freq = 220; type = 'sawtooth'; 
            osc.frequency.setValueAtTime(freq, ctx.currentTime);
            osc.frequency.exponentialRampToValueAtTime(freq * 3, ctx.currentTime + 0.3);
            break;
        case 'WATER': 
        case 'STEAM':
            freq = 600; type = 'sine';
            osc.frequency.setValueAtTime(freq, ctx.currentTime);
            osc.frequency.exponentialRampToValueAtTime(200, ctx.currentTime + 0.2);
            duration = 0.3;
            break;
        case 'THUNDER': 
        case 'TEMPEST':
        case 'VOID':
            freq = 150; type = 'square';
            osc.frequency.setValueAtTime(freq, ctx.currentTime);
            osc.frequency.linearRampToValueAtTime(freq * 0.8, ctx.currentTime + 0.1);
            break;
        case 'WIND': 
        case 'BLIZZARD':
        case 'PLASMA':
            freq = 880; type = 'triangle';
            osc.frequency.setValueAtTime(freq, ctx.currentTime);
            break;
    }

    osc.type = type;
    const now = ctx.currentTime;
    gain.gain.setValueAtTime(0, now);
    gain.gain.linearRampToValueAtTime(0.05, now + 0.05);
    gain.gain.exponentialRampToValueAtTime(0.001, now + duration);
    osc.start(now);
    osc.stop(now + duration);
  }, []);

  const detectGesture = (landmarks: any[], videoWidth: number, videoHeight: number): ElementType => {
    const mapPt = (idx: number) => ({ x: (1 - landmarks[idx].x) * videoWidth, y: landmarks[idx].y * videoHeight });
    const wrist = mapPt(0);
    const indexTip = mapPt(8);
    const middleTip = mapPt(12);
    const ringTip = mapPt(16);
    const pinkyTip = mapPt(20);
    const indexMCP = mapPt(5);
    const middleMCP = mapPt(9);
    const ringMCP = mapPt(13); 
    const pinkyMCP = mapPt(17);

    const dist = (p1: any, p2: any) => Math.hypot(p1.x - p2.x, p1.y - p2.y);

    // Check if finger is open (tip further from wrist than base/MCP)
    // Relaxed threshold: No multiplier. If tip is further than knuckle, it's open.
    const isFingerOpen = (tip: any, mcp: any) => dist(tip, wrist) > dist(mcp, wrist);

    const indexOpen = isFingerOpen(indexTip, indexMCP);
    const middleOpen = isFingerOpen(middleTip, middleMCP);
    const ringOpen = isFingerOpen(ringTip, ringMCP);
    const pinkyOpen = isFingerOpen(pinkyTip, pinkyMCP);

    // Orientation: Y grows downwards. 
    // If Wrist Y < Middle MCP Y, the wrist is ABOVE the hand -> Hand Pointing DOWN
    const isPointingDown = wrist.y < middleMCP.y;

    if (isPointingDown) {
        // Rain/Water: Hand pointing down (Forgiving: any state as long as pointing down)
        return 'WATER';
    } else {
        // Pointing Up

        // Fist: Index and Middle closed. (We ignore Ring/Pinky to be forgiving for people who can't fully curl)
        if (!indexOpen && !middleOpen) return 'THUNDER';

        // Victory: Index & Middle Open, Ring Closed.
        if (indexOpen && middleOpen && !ringOpen) return 'WIND';

        // Open Hand: Index & Middle & Ring Open. (Pinky optional)
        if (indexOpen && middleOpen && ringOpen) return 'FIRE';
    }

    return 'NEUTRAL';
  };

  const drawSkeleton = (ctx: CanvasRenderingContext2D, hand: HandData) => {
      ctx.strokeStyle = "rgba(255, 255, 255, 0.2)";
      ctx.lineWidth = 1;
      ctx.fillStyle = "rgba(255, 255, 255, 0.4)";
      const points = [hand.wrist, hand.indexBase, hand.indexTip, hand.middleBase, hand.middleTip, hand.ringBase, hand.ringTip, hand.pinkyBase, hand.pinkyTip, hand.thumbTip];

      const drawLine = (p1: any, p2: any) => { ctx.beginPath(); ctx.moveTo(p1.x, p1.y); ctx.lineTo(p2.x, p2.y); ctx.stroke(); }
      drawLine(hand.wrist, hand.indexBase); drawLine(hand.indexBase, hand.indexTip);
      drawLine(hand.wrist, hand.middleBase); drawLine(hand.middleBase, hand.middleTip);
      drawLine(hand.wrist, hand.pinkyBase); drawLine(hand.pinkyBase, hand.pinkyTip);

      points.forEach(p => { ctx.beginPath(); ctx.arc(p.x, p.y, 2, 0, Math.PI * 2); ctx.fill(); });
  };

  const onResults = useCallback((results: any) => {
    const videoWidth = webcamRef.current?.video?.videoWidth || width;
    const videoHeight = webcamRef.current?.video?.videoHeight || height;

    if (results.multiHandLandmarks && results.multiHandLandmarks.length > 0) {
      setDebugInfo(`Hands: ${results.multiHandLandmarks.length}`);
      const newHandData: HandData[] = results.multiHandLandmarks.map((landmarks: any[]) => {
        const gesture = detectGesture(landmarks, videoWidth, videoHeight);
        const mapPt = (idx: number) => ({ x: (1 - landmarks[idx].x) * videoWidth, y: landmarks[idx].y * videoHeight });
        return {
          wrist: mapPt(0), indexTip: mapPt(8), middleTip: mapPt(12), ringTip: mapPt(16), pinkyTip: mapPt(20), thumbTip: mapPt(4),
          indexBase: mapPt(5), middleBase: mapPt(9), ringBase: mapPt(13), pinkyBase: mapPt(17),
          isOpen: gesture !== 'THUNDER', gesture, opacity: 1,
        };
      });

      handDataRef.current = newHandData;
      let newElement = 'NEUTRAL';
      let activeCombo = null;

      if (newHandData.length === 2) {
          const g1 = newHandData[0].gesture;
          const g2 = newHandData[1].gesture;
          if (g1 !== 'NEUTRAL' && g2 !== 'NEUTRAL') activeCombo = getCombo(g1, g2);
      }

      if (activeCombo) newElement = activeCombo;
      else {
          const activeHand = newHandData.find(h => h.gesture !== 'NEUTRAL');
          if (activeHand) newElement = activeHand.gesture;
      }
      activeComboRef.current = activeCombo;

      if (newElement !== prevElementRef.current) {
          if (newElement !== 'NEUTRAL') { highlightRef.current = 1.0; playChime(newElement); }
          prevElementRef.current = newElement;
      }
      setCurrentElement(newElement);
    } else {
      handDataRef.current = [];
      setDebugInfo("No Hands");
      activeComboRef.current = null;
      if (prevElementRef.current !== 'NEUTRAL') { prevElementRef.current = 'NEUTRAL'; setCurrentElement('NEUTRAL'); }
    }
  }, [width, height, playChime]);

  useEffect(() => {
    let hands: any = null;
    let isActive = true;
    let frameId: number;
    let lastVideoTime = -1;

    const initHands = async () => {
       if (!(window as any).Hands) { setTimeout(initHands, 500); return; }
       hands = new (window as any).Hands({ locateFile: (file: string) => `https://cdn.jsdelivr.net/npm/@mediapipe/hands@0.4.1675469240/${file}` });
       hands.setOptions({ maxNumHands: 2, modelComplexity: 1, minDetectionConfidence: 0.5, minTrackingConfidence: 0.5 });
       hands.onResults(onResults);
       setIsModelLoaded(true);
       const processVideo = async () => {
         if (!isActive) return;
         if (webcamRef.current && webcamRef.current.video && webcamRef.current.video.readyState === 4) {
             const video = webcamRef.current.video;
             if (video.currentTime !== lastVideoTime) {
                 lastVideoTime = video.currentTime;
                 try { await hands.send({ image: video }); } catch (e) { console.error("MediaPipe error:", e); }
             }
         }
         frameId = requestAnimationFrame(processVideo);
       };
       processVideo();
    };
    initHands();
    return () => { isActive = false; if (frameId) cancelAnimationFrame(frameId); if (hands) hands.close(); };
  }, [onResults]);

  // --- PHYSICS ENGINE ---
  const updateParticles = (ctx: CanvasRenderingContext2D, width: number, height: number, centerX: number, centerY: number) => {
    for (let i = particlesRef.current.length - 1; i >= 0; i--) {
      const p = particlesRef.current[i];

      // General Drag
      p.vx *= 0.95;
      p.vy *= 0.95;

      // Element Specific Physics
      switch (p.element) {
          case 'WIND':
          case 'BLIZZARD':
              // Vortex/Spiral Physics
              const dx = p.x - centerX;
              const dy = p.y - centerY;
              const dist = Math.sqrt(dx*dx + dy*dy) + 1;
              const angle = Math.atan2(dy, dx);
              // Tangential force (Rotation)
              p.vx += Math.cos(angle + Math.PI/2) * 1.5;
              p.vy += Math.sin(angle + Math.PI/2) * 1.5;
              // Centripetal force (Suck in)
              p.vx -= (dx / dist) * 0.5;
              p.vy -= (dy / dist) * 0.5;
              p.angle += p.angularVelocity; // Spin the leaf
              break;

          case 'WATER':
          case 'STEAM':
              // Gravity & Rain
              p.vy += 1.2; // Strong gravity
              p.x += Math.sin(p.life * 0.1) * 0.5; // Slight waver
              break;

          case 'THUNDER':
          case 'TEMPEST':
          case 'VOID':
              // Chaotic / Jitter
              p.vx += (Math.random() - 0.5) * 4;
              p.vy += (Math.random() - 0.5) * 4;
              if (Math.random() < 0.1) { // Lightning jump
                  p.x += (Math.random() - 0.5) * 20;
                  p.y += (Math.random() - 0.5) * 20;
              }
              break;

          case 'FIRE':
          case 'INFERNO':
              // Thermal Lift / Turbulence
              p.vy -= 0.6; // Rise
              p.vx += (Math.random() - 0.5) * 1.5; // Turbulence
              p.size *= 0.96; // Shrink faster
              break;

          default:
              p.vy -= 0.1; // Neutral float
      }

      p.x += p.vx;
      p.y += p.vy;
      p.life -= 1;
      if (p.element !== 'FIRE') p.size *= 0.98;

      if (p.life <= 0 || p.size < 0.2 || p.y > height + 50) {
        particlesRef.current.splice(i, 1);
      } else {
        // --- RENDERER ---
        ctx.save();
        // Fade in and out
        ctx.globalAlpha = Math.min(1, p.life / 20, (p.maxLife - p.life) / 10);

        if (p.type === 'LEAF') {
            ctx.translate(p.x, p.y);
            ctx.rotate(p.angle);
            ctx.fillStyle = p.color;
            ctx.beginPath();
            ctx.ellipse(0, 0, p.size, p.size * 0.4, 0, 0, Math.PI * 2);
            ctx.fill();
        } 
        else if (p.type === 'DROP') {
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 2;
            ctx.lineCap = 'round';
            ctx.beginPath();
            ctx.moveTo(p.x, p.y);
            // Stretch rain drop based on velocity
            ctx.lineTo(p.x - p.vx, p.y - p.vy * 3); 
            ctx.stroke();
        }
        else if (p.type === 'SPARK') {
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 2;
            ctx.shadowColor = p.color;
            ctx.shadowBlur = 10;
            ctx.beginPath();
            ctx.moveTo(p.x - p.vx, p.y - p.vy);
            ctx.lineTo(p.x + p.vx, p.y + p.vy);
            ctx.stroke();
            // Occasional cross-bolt
            if (Math.random() > 0.5) {
                ctx.beginPath();
                ctx.moveTo(p.x, p.y);
                ctx.lineTo(p.x + (Math.random()-0.5)*20, p.y + (Math.random()-0.5)*20);
                ctx.stroke();
            }
        }
        else if (p.type === 'EMBER') {
            ctx.fillStyle = p.color;
            ctx.shadowColor = 'orange';
            ctx.shadowBlur = 15;
            ctx.beginPath();
            ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
            ctx.fill();
        }
        else { // ORB / MIST
            ctx.fillStyle = p.color;
            ctx.shadowColor = p.color;
            ctx.shadowBlur = p.type === 'ORB' ? 10 : 0;
            ctx.beginPath();
            ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
            ctx.fill();
        }
        ctx.restore();
      }
    }
  };

  const spawnParticles = (x: number, y: number, element: string, theme: Theme) => {
    const isCombo = activeComboRef.current !== null;
    let count = isCombo ? 12 : 3;

    let type: ParticleType = 'ORB';
    let speed = Math.random() * 5;
    let spread = 20;

    // Customize Spawn based on Element
    if (element === 'WIND' || element === 'BLIZZARD') {
        type = Math.random() > 0.5 ? 'LEAF' : 'MIST';
        count = isCombo ? 15 : 4;
    } else if (element === 'WATER' || element === 'STEAM') {
        type = Math.random() > 0.7 ? 'MIST' : 'DROP';
        count = isCombo ? 20 : 5;
        spread = 40; 
    } else if (element === 'THUNDER' || element === 'TEMPEST' || element === 'VOID') {
        type = 'SPARK';
        count = isCombo ? 6 : 2; 
        speed = 8;
    } else if (element === 'FIRE' || element === 'INFERNO') {
        type = Math.random() > 0.8 ? 'MIST' : 'EMBER';
        count = isCombo ? 12 : 4;
    }

    for (let i = 0; i < count; i++) {
      const angle = Math.random() * Math.PI * 2;
      let vx = Math.cos(angle) * speed;
      let vy = Math.sin(angle) * speed;

      // Initial velocity overrides
      if (element === 'WATER' || element === 'STEAM') { vx *= 0.2; vy = Math.random() * 2; } 

      // Color tweaks
      let color = Math.random() > 0.5 ? theme.primary : theme.secondary;
      if (element === 'WIND') color = Math.random() > 0.5 ? '#00FFFF' : '#F0FFF0'; 
      if (element === 'THUNDER') color = Math.random() > 0.5 ? '#FFFF00' : '#9400D3';

      let spawnX = x;
      let spawnY = y;

      // FULL SCREEN SPAWN LOGIC
      if (isCombo || element === 'WATER') {
          spawnX = Math.random() * width;

          if (element === 'WATER' || element === 'TEMPEST') {
             // Falling Rain/Storm: Spawn Top
             spawnY = Math.random() * -100;
          } else {
             // Other Combos (Blizzard, Inferno, Plasma, Steam, Void): Full Field
             spawnY = Math.random() * height;
          }
      } else {
          // Hand localized spawn (Fire, Thunder, Wind)
          spawnX = x + (Math.random() - 0.5) * spread;
          spawnY = y + (Math.random() - 0.5) * spread;
      }

      particlesRef.current.push({
        x: spawnX,
        y: spawnY,
        vx, vy,
        life: 40 + Math.random() * 40,
        maxLife: 80,
        size: 3 + Math.random() * 5,
        color,
        element: element as Particle['element'],
        type,
        angle: Math.random() * Math.PI * 2,
        angularVelocity: (Math.random() - 0.5) * 0.2
      });
    }
  };

  const animate = useCallback((time: number) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (highlightRef.current > 0.01) highlightRef.current *= 0.9;
    else highlightRef.current = 0;
    const flash = highlightRef.current;

    // Use 'lighter' for high-energy anime look
    ctx.globalCompositeOperation = 'lighter'; 

    let lastCenterX = width / 2;
    let lastCenterY = height / 2;
    const t = time * 0.001;

    // Check for active combo
    const comboName = activeComboRef.current;

    if (comboName && handDataRef.current.length === 2) {
        // --- COMBO MODE ---
        const h1 = handDataRef.current[0];
        const h2 = handDataRef.current[1];
        const theme = COMBO_THEMES[comboName];

        const midX = (h1.middleBase.x + h2.middleBase.x) / 2;
        const midY = (h1.middleBase.y + h2.middleBase.y) / 2;
        lastCenterX = midX;
        lastCenterY = midY;

        // 1. Base Beam
        ctx.save();
        ctx.beginPath();
        ctx.moveTo(h1.middleBase.x, h1.middleBase.y);
        ctx.lineTo(h2.middleBase.x, h2.middleBase.y);
        ctx.strokeStyle = theme.primary;
        ctx.lineWidth = 20 + Math.sin(t * 10) * 5; 
        ctx.lineCap = 'round';
        ctx.shadowBlur = 40;
        ctx.shadowColor = theme.secondary;
        ctx.globalAlpha = 0.4;
        ctx.stroke();
        ctx.restore();

        // 2. Converging Energy
        ctx.save();
        ctx.beginPath();
        ctx.moveTo(h1.middleBase.x, h1.middleBase.y);
        ctx.lineTo(h2.middleBase.x, h2.middleBase.y);
        ctx.strokeStyle = '#FFFFFF';
        ctx.lineWidth = 3;
        ctx.setLineDash([10, 40]);
        ctx.lineDashOffset = -t * 200; 
        ctx.globalCompositeOperation = 'overlay';
        ctx.stroke();
        ctx.restore();

        // 3. Electric Arcs
        ctx.save();
        ctx.beginPath();
        ctx.moveTo(h1.middleBase.x, h1.middleBase.y);
        const dist = Math.hypot(h2.middleBase.x - h1.middleBase.x, h2.middleBase.y - h1.middleBase.y);
        const angle = Math.atan2(h2.middleBase.y - h1.middleBase.y, h2.middleBase.x - h1.middleBase.x);
        for(let i=0; i<=20; i++) {
             const p = i/20;
             const perp = Math.sin(p * Math.PI * 4 + t * 20) * (15 + Math.random() * 5);
             const bx = h1.middleBase.x + (h2.middleBase.x - h1.middleBase.x) * p + Math.cos(angle + Math.PI/2)*perp;
             const by = h1.middleBase.y + (h2.middleBase.y - h1.middleBase.y) * p + Math.sin(angle + Math.PI/2)*perp;
             ctx.lineTo(bx, by);
        }
        ctx.strokeStyle = theme.secondary;
        ctx.lineWidth = 2;
        ctx.shadowBlur = 10;
        ctx.shadowColor = theme.core;
        ctx.stroke();
        ctx.restore();

        // Array
        ctx.globalAlpha = 1;
        drawRuneRing(ctx, midX, midY, 180, t, theme);
        drawSacredGeometry(ctx, midX, midY, 140, -t * 2, theme);
        drawSquareLayer(ctx, midX, midY, 100, t * 3, theme);
        drawPentagram(ctx, midX, midY, 60, -t, 1, theme);

        spawnParticles(midX, midY, comboName, theme);

        handDataRef.current.forEach(h => {
             drawSkeleton(ctx, h);
             const auraSize = 50 + Math.sin(t * 20) * 10;
             const grad = ctx.createRadialGradient(h.middleBase.x, h.middleBase.y, 10, h.middleBase.x, h.middleBase.y, auraSize);
             grad.addColorStop(0, theme.core);
             grad.addColorStop(0.4, theme.primary);
             grad.addColorStop(1, 'rgba(0,0,0,0)');
             ctx.save();
             ctx.fillStyle = grad;
             ctx.globalAlpha = 0.5;
             ctx.beginPath();
             ctx.arc(h.middleBase.x, h.middleBase.y, auraSize, 0, Math.PI * 2);
             ctx.fill();
             ctx.restore();
             drawRuneRing(ctx, h.middleBase.x, h.middleBase.y, 40, t*5, theme);
        });

    } else {
        // --- INDIVIDUAL MODE ---
        handDataRef.current.forEach((hand) => {
           drawSkeleton(ctx, hand);
           const element = hand.gesture;
           const theme = (element !== 'NEUTRAL' && THEMES[element]) ? THEMES[element] : THEMES['NEUTRAL'];
           const centerX = hand.middleBase.x; 
           const centerY = hand.middleBase.y; 

           if (element !== 'NEUTRAL') {
               if (flash > 0.05 && highlightRef.current > 0.05) {
                   ctx.save();
                   ctx.translate(centerX, centerY);
                   const waveSize = 120 + (1 - flash) * 100;
                   ctx.beginPath();
                   ctx.arc(0, 0, waveSize, 0, Math.PI * 2);
                   ctx.lineWidth = 10 * flash;
                   ctx.strokeStyle = theme.core;
                   ctx.shadowBlur = 20;
                   ctx.shadowColor = theme.secondary;
                   ctx.globalAlpha = flash;
                   ctx.stroke();
                   ctx.restore();
               }

               drawRuneRing(ctx, centerX, centerY, 120, t * 0.5, theme);
               drawSacredGeometry(ctx, centerX, centerY, 90, -t * 1.5, theme);
               drawSquareLayer(ctx, centerX, centerY, 65, t * 2.5, theme);
               const pulse = Math.sin(time * 0.005) * 0.5 + 0.5;
               drawPentagram(ctx, centerX, centerY, 40, t, pulse, theme);

               spawnParticles(centerX, centerY, element, theme);
               lastCenterX = centerX;
               lastCenterY = centerY;
           } else {
               ctx.globalAlpha = 0.3;
               drawRuneRing(ctx, centerX, centerY, 50, t * 0.2, theme);
           }
        });
    }

    updateParticles(ctx, canvas.width, canvas.height, lastCenterX, lastCenterY);
    requestRef.current = requestAnimationFrame(animate);
  }, [width, height]);

  useEffect(() => {
    requestRef.current = requestAnimationFrame(animate);
    return () => { if (requestRef.current) cancelAnimationFrame(requestRef.current); };
  }, [animate]);

  return (
    <div className="relative w-full h-full bg-black overflow-hidden flex items-center justify-center">
        <Webcam ref={webcamRef} audio={false} width={width} height={height} mirrored={true} screenshotFormat="image/jpeg" className="absolute opacity-0 pointer-events-none" />
        <Webcam audio={false} width={width} height={height} mirrored={true} className="absolute top-0 left-0 w-full h-full object-cover opacity-80" />
        <canvas ref={canvasRef} width={width} height={height} className="absolute top-0 left-0 w-full h-full object-cover z-10" />
        {!isModelLoaded && (
            <div className="absolute inset-0 flex items-center justify-center bg-black bg-opacity-80 z-50">
                <div className="text-amber-500 font-mono text-xl animate-pulse">Summoning Grimoire... (Loading Models)</div>
            </div>
        )}
        <div className="absolute top-4 right-4 text-right z-20 font-mono pointer-events-none">
            <div className={`text-2xl font-bold mb-2 tracking-widest transition-all duration-300 ${highlightRef.current > 0.1 ? 'scale-110' : ''} ${
                currentElement === 'FIRE' ? 'text-orange-500' :
                currentElement === 'WATER' ? 'text-blue-500' :
                currentElement === 'WIND' ? 'text-cyan-300' :
                currentElement === 'THUNDER' ? 'text-purple-500' : 
                currentElement === 'INFERNO' ? 'text-red-600' :
                currentElement === 'BLIZZARD' ? 'text-cyan-100' :
                currentElement === 'VOID' ? 'text-violet-900' : 'text-amber-500'
            }`}>SPELL: {currentElement}</div>
            <div className="text-xs text-white opacity-70 space-y-1 mb-2"><p>Status: {debugInfo}</p></div>
            <div className="text-xs text-white opacity-70 space-y-1">
                <p>✋ Palm Up: FIRE</p>
                <p>👇 Palm Down: WATER (RAIN)</p>
                <p>👊 Fist: THUNDER</p>
                <p>✌️ Victory: WIND</p>
            </div>
        </div>
    </div>
  );
};

export default MagicOverlay;

import React, { useEffect, useRef, useCallback, useState } from 'react';
import Webcam from 'react-webcam';
import { Particle, HandData, ElementType, Theme, ParticleType } from '../types';
import { 
  drawRuneRing, 
  drawSacredGeometry, 
  drawSquareLayer, 
  drawPentagram,
  THEMES
} from '../utils/geometry';

interface MagicOverlayProps {
  width: number;
  height: number;
}

const COMBO_THEMES: Record<string, Theme> = {
  'BLIZZARD': { primary: '#00FFFF', secondary: '#E0FFFF', core: '#FFFFFF', shadow: '#008B8B' }, // Ice/Wind
  'PLASMA': { primary: '#FF00FF', secondary: '#00FFFF', core: '#FFFFFF', shadow: '#9400D3' }, // Fire/Wind
  'STEAM': { primary: '#F0F8FF', secondary: '#B0C4DE', core: '#FFFFFF', shadow: '#778899' }, // Fire/Water
  'TEMPEST': { primary: '#000080', secondary: '#8A2BE2', core: '#FFFF00', shadow: '#191970' }, // Thunder/Water
  'INFERNO': { primary: '#FF0000', secondary: '#FF4500', core: '#FFFF00', shadow: '#8B0000' }, // Fire/Fire
  'VOID': { primary: '#000000', secondary: '#4B0082', core: '#FFFFFF', shadow: '#9400D3' }, // Thunder/Thunder
};

const getCombo = (g1: ElementType, g2: ElementType): string | null => {
    const sorted = [g1, g2].sort().join('_');
    switch(sorted) {
        case 'WATER_WIND': return 'BLIZZARD';
        case 'FIRE_WIND': return 'PLASMA';
        case 'FIRE_WATER': return 'STEAM';
        case 'THUNDER_WATER': return 'TEMPEST';
        case 'FIRE_FIRE': return 'INFERNO';
        case 'THUNDER_THUNDER': return 'VOID';
        default: return null;
    }
};

const MagicOverlay: React.FC<MagicOverlayProps> = ({ width, height }) => {
  const webcamRef = useRef<Webcam>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>(0);
  const particlesRef = useRef<Particle[]>([]);
  const handDataRef = useRef<HandData[]>([]);
  const [currentElement, setCurrentElement] = useState<string>('NEUTRAL');
  const [isModelLoaded, setIsModelLoaded] = useState(false);
  const [debugInfo, setDebugInfo] = useState<string>("Initializing...");

  // Visual Feedback State
  const highlightRef = useRef<number>(0);
  const prevElementRef = useRef<string>('NEUTRAL');
  const activeComboRef = useRef<string | null>(null);

  // Audio Context
  const audioContextRef = useRef<AudioContext | null>(null);
  const noiseBufferRef = useRef<AudioBuffer | null>(null);

  useEffect(() => {
    const AudioContextClass = (window as any).AudioContext || (window as any).webkitAudioContext;
    if (AudioContextClass) {
        const ctx = new AudioContextClass();
        audioContextRef.current = ctx;

        // Generate White Noise Buffer for procedural effects
        const bufferSize = ctx.sampleRate * 2; // 2 seconds
        const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
        const data = buffer.getChannelData(0);
        for (let i = 0; i < bufferSize; i++) {
            data[i] = Math.random() * 2 - 1;
        }
        noiseBufferRef.current = buffer;
    }
  }, []);

  const playChime = useCallback((element: string) => {
    const ctx = audioContextRef.current;
    if (!ctx) return;
    if (ctx.state === 'suspended') {
        ctx.resume().catch(console.error);
    }

    // Fallback if noise buffer isn't ready, though it should be fast
    if (!noiseBufferRef.current) return;

    const now = ctx.currentTime;
    const masterGain = ctx.createGain();
    masterGain.connect(ctx.destination);
    masterGain.gain.setValueAtTime(0.3, now); // Master Volume

    // Helper: Play Noise (Wind, Water, Fire textures)
    const playNoise = (filterType: BiquadFilterType, freqStart: number, freqEnd: number, duration: number, vol: number = 1, delay: number = 0) => {
        const src = ctx.createBufferSource();
        src.buffer = noiseBufferRef.current;
        src.loop = true;

        const filter = ctx.createBiquadFilter();
        filter.type = filterType;
        filter.frequency.setValueAtTime(freqStart, now + delay);
        filter.frequency.exponentialRampToValueAtTime(freqEnd, now + delay + duration);
        filter.Q.value = 1;

        const amp = ctx.createGain();
        amp.gain.setValueAtTime(0, now + delay);
        amp.gain.linearRampToValueAtTime(vol, now + delay + 0.05); // Attack
        amp.gain.exponentialRampToValueAtTime(0.01, now + delay + duration); // Decay

        src.connect(filter);
        filter.connect(amp);
        amp.connect(masterGain);

        src.start(now + delay);
        src.stop(now + delay + duration + 0.2);
    };

    // Helper: Play Tone (Magic hums, zaps, tinkles)
    const playTone = (type: OscillatorType, freqStart: number, freqEnd: number, duration: number, vol: number = 1, delay: number = 0) => {
        const osc = ctx.createOscillator();
        osc.type = type;
        osc.frequency.setValueAtTime(freqStart, now + delay);
        if (freqStart !== freqEnd) {
             osc.frequency.exponentialRampToValueAtTime(freqEnd, now + delay + duration);
        }

        const amp = ctx.createGain();
        amp.gain.setValueAtTime(0, now + delay);
        amp.gain.linearRampToValueAtTime(vol, now + delay + 0.05);
        amp.gain.exponentialRampToValueAtTime(0.01, now + delay + duration);

        osc.connect(amp);
        amp.connect(masterGain);

        osc.start(now + delay);
        osc.stop(now + delay + duration + 0.2);
    };

    switch (element) {
        case 'FIRE':
            // Crackling Fire: Low rumble + high frequency clicks (simulated by noise)
            playNoise('lowpass', 500, 100, 1.0, 0.5);
            playTone('sawtooth', 80, 120, 0.8, 0.2); // Low growl
            break;

        case 'WATER':
            // Splash: Bandpass sweep
            playNoise('bandpass', 800, 300, 0.6, 0.4);
            playTone('sine', 600, 300, 0.4, 0.3, 0.1); // Droplet
            break;

        case 'WIND':
            // Whoosh: Lowpass sweep up then down
            playNoise('lowpass', 200, 800, 0.4, 0.3);
            playNoise('highpass', 400, 1000, 0.5, 0.2, 0.1);
            break;

        case 'THUNDER':
            // Thunder: Zap (Sawtooth drop) + Boom (Lowpass noise)
            playTone('sawtooth', 800, 50, 0.3, 0.2);
            playNoise('lowpass', 1000, 50, 1.2, 0.6, 0.1); 
            break;

        // COMBOS
        case 'BLIZZARD': // Wind + Ice
            playNoise('highpass', 1000, 3000, 1.5, 0.4); // Icy Wind
            playTone('sine', 1500, 2000, 0.3, 0.1, 0.1); // Crystal chime
            playTone('sine', 2000, 2500, 0.3, 0.1, 0.3);
            break;

        case 'INFERNO': // Intense Fire
            playNoise('lowpass', 800, 50, 1.5, 0.8); // Explosion
            playTone('square', 60, 40, 1.5, 0.2); // Rumble
            break;

        case 'TEMPEST': // Thunder + Water
            playNoise('lowpass', 200, 50, 2.0, 0.8); // Deep Thunder
            playTone('sawtooth', 1200, 100, 0.5, 0.2, 0.1); // Crack
            playNoise('bandpass', 1000, 500, 1.0, 0.3); // Rain hiss
            break;

        case 'VOID': // Dark energy
            playTone('sine', 50, 40, 2.5, 0.6); // Sub bass
            playNoise('bandpass', 100, 200, 2.5, 0.4); // Eerie atmosphere
            playTone('sine', 300, 290, 1.0, 0.1, 0.5); // Interference beat
            break;

        case 'PLASMA': // Fire + Wind
            playTone('sawtooth', 200, 800, 1.0, 0.2); // Rising energy
            playNoise('bandpass', 400, 1200, 1.0, 0.4);
            break;

        case 'STEAM': // Fire + Water
            playNoise('highpass', 500, 1000, 1.0, 0.3); // Hiss
            break;

        default:
            // Generic activation
            playTone('triangle', 440, 880, 0.3, 0.1);
    }
  }, []);

  const detectGesture = (landmarks: any[], videoWidth: number, videoHeight: number): ElementType => {
    const mapPt = (idx: number) => ({ x: (1 - landmarks[idx].x) * videoWidth, y: landmarks[idx].y * videoHeight });
    const wrist = mapPt(0);
    const indexTip = mapPt(8);
    const middleTip = mapPt(12);
    const ringTip = mapPt(16);
    const pinkyTip = mapPt(20);
    const indexMCP = mapPt(5);
    const middleMCP = mapPt(9);
    const ringMCP = mapPt(13); 
    const pinkyMCP = mapPt(17);

    const dist = (p1: any, p2: any) => Math.hypot(p1.x - p2.x, p1.y - p2.y);

    // Check if finger is open (tip further from wrist than base/MCP)
    // Relaxed threshold: No multiplier. If tip is further than knuckle, it's open.
    const isFingerOpen = (tip: any, mcp: any) => dist(tip, wrist) > dist(mcp, wrist);

    const indexOpen = isFingerOpen(indexTip, indexMCP);
    const middleOpen = isFingerOpen(middleTip, middleMCP);
    const ringOpen = isFingerOpen(ringTip, ringMCP);
    const pinkyOpen = isFingerOpen(pinkyTip, pinkyMCP);

    // Orientation: Y grows downwards. 
    // If Wrist Y < Middle MCP Y, the wrist is ABOVE the hand -> Hand Pointing DOWN
    const isPointingDown = wrist.y < middleMCP.y;

    if (isPointingDown) {
        // Rain/Water: Hand pointing down (Forgiving: any state as long as pointing down)
        return 'WATER';
    } else {
        // Pointing Up

        // Fist: Index and Middle closed. (We ignore Ring/Pinky to be forgiving for people who can't fully curl)
        if (!indexOpen && !middleOpen) return 'THUNDER';

        // Victory: Index & Middle Open, Ring Closed.
        if (indexOpen && middleOpen && !ringOpen) return 'WIND';

        // Open Hand: Index & Middle & Ring Open. (Pinky optional)
        if (indexOpen && middleOpen && ringOpen) return 'FIRE';
    }

    return 'NEUTRAL';
  };

  const drawSkeleton = (ctx: CanvasRenderingContext2D, hand: HandData) => {
      ctx.strokeStyle = "rgba(255, 255, 255, 0.2)";
      ctx.lineWidth = 1;
      ctx.fillStyle = "rgba(255, 255, 255, 0.4)";
      const points = [hand.wrist, hand.indexBase, hand.indexTip, hand.middleBase, hand.middleTip, hand.ringBase, hand.ringTip, hand.pinkyBase, hand.pinkyTip, hand.thumbTip];

      const drawLine = (p1: any, p2: any) => { ctx.beginPath(); ctx.moveTo(p1.x, p1.y); ctx.lineTo(p2.x, p2.y); ctx.stroke(); }
      drawLine(hand.wrist, hand.indexBase); drawLine(hand.indexBase, hand.indexTip);
      drawLine(hand.wrist, hand.middleBase); drawLine(hand.middleBase, hand.middleTip);
      drawLine(hand.wrist, hand.pinkyBase); drawLine(hand.pinkyBase, hand.pinkyTip);

      points.forEach(p => { ctx.beginPath(); ctx.arc(p.x, p.y, 2, 0, Math.PI * 2); ctx.fill(); });
  };

  const onResults = useCallback((results: any) => {
    const videoWidth = webcamRef.current?.video?.videoWidth || width;
    const videoHeight = webcamRef.current?.video?.videoHeight || height;

    if (results.multiHandLandmarks && results.multiHandLandmarks.length > 0) {
      setDebugInfo(`Hands: ${results.multiHandLandmarks.length}`);
      const newHandData: HandData[] = results.multiHandLandmarks.map((landmarks: any[]) => {
        const gesture = detectGesture(landmarks, videoWidth, videoHeight);
        const mapPt = (idx: number) => ({ x: (1 - landmarks[idx].x) * videoWidth, y: landmarks[idx].y * videoHeight });
        return {
          wrist: mapPt(0), indexTip: mapPt(8), middleTip: mapPt(12), ringTip: mapPt(16), pinkyTip: mapPt(20), thumbTip: mapPt(4),
          indexBase: mapPt(5), middleBase: mapPt(9), ringBase: mapPt(13), pinkyBase: mapPt(17),
          isOpen: gesture !== 'THUNDER', gesture, opacity: 1,
        };
      });

      handDataRef.current = newHandData;
      let newElement = 'NEUTRAL';
      let activeCombo = null;

      if (newHandData.length === 2) {
          const g1 = newHandData[0].gesture;
          const g2 = newHandData[1].gesture;
          if (g1 !== 'NEUTRAL' && g2 !== 'NEUTRAL') activeCombo = getCombo(g1, g2);
      }

      if (activeCombo) newElement = activeCombo;
      else {
          const activeHand = newHandData.find(h => h.gesture !== 'NEUTRAL');
          if (activeHand) newElement = activeHand.gesture;
      }
      activeComboRef.current = activeCombo;

      if (newElement !== prevElementRef.current) {
          if (newElement !== 'NEUTRAL') { highlightRef.current = 1.0; playChime(newElement); }
          prevElementRef.current = newElement;
      }
      setCurrentElement(newElement);
    } else {
      handDataRef.current = [];
      setDebugInfo("No Hands");
      activeComboRef.current = null;
      if (prevElementRef.current !== 'NEUTRAL') { prevElementRef.current = 'NEUTRAL'; setCurrentElement('NEUTRAL'); }
    }
  }, [width, height, playChime]);

  useEffect(() => {
    let hands: any = null;
    let isActive = true;
    let frameId: number;
    let lastVideoTime = -1;

    const initHands = async () => {
       if (!(window as any).Hands) { setTimeout(initHands, 500); return; }
       hands = new (window as any).Hands({ locateFile: (file: string) => `https://cdn.jsdelivr.net/npm/@mediapipe/hands@0.4.1675469240/${file}` });
       hands.setOptions({ maxNumHands: 2, modelComplexity: 1, minDetectionConfidence: 0.5, minTrackingConfidence: 0.5 });
       hands.onResults(onResults);
       setIsModelLoaded(true);
       const processVideo = async () => {
         if (!isActive) return;
         if (webcamRef.current && webcamRef.current.video && webcamRef.current.video.readyState === 4) {
             const video = webcamRef.current.video;
             if (video.currentTime !== lastVideoTime) {
                 lastVideoTime = video.currentTime;
                 try { await hands.send({ image: video }); } catch (e) { console.error("MediaPipe error:", e); }
             }
         }
         frameId = requestAnimationFrame(processVideo);
       };
       processVideo();
    };
    initHands();
    return () => { isActive = false; if (frameId) cancelAnimationFrame(frameId); if (hands) hands.close(); };
  }, [onResults]);

  // --- PHYSICS ENGINE ---
  const updateParticles = (ctx: CanvasRenderingContext2D, width: number, height: number, centerX: number, centerY: number) => {
    for (let i = particlesRef.current.length - 1; i >= 0; i--) {
      const p = particlesRef.current[i];

      // General Drag
      p.vx *= 0.95;
      p.vy *= 0.95;

      // Element Specific Physics
      switch (p.element) {
          case 'WIND':
          case 'BLIZZARD':
              // Vortex/Spiral Physics
              const dx = p.x - centerX;
              const dy = p.y - centerY;
              const dist = Math.sqrt(dx*dx + dy*dy) + 1;
              const angle = Math.atan2(dy, dx);
              // Tangential force (Rotation)
              p.vx += Math.cos(angle + Math.PI/2) * 1.5;
              p.vy += Math.sin(angle + Math.PI/2) * 1.5;
              // Centripetal force (Suck in)
              p.vx -= (dx / dist) * 0.5;
              p.vy -= (dy / dist) * 0.5;
              p.angle += p.angularVelocity; // Spin the leaf
              break;

          case 'WATER':
          case 'STEAM':
              // Gravity & Rain
              p.vy += 1.2; // Strong gravity
              p.x += Math.sin(p.life * 0.1) * 0.5; // Slight waver
              break;

          case 'THUNDER':
          case 'TEMPEST':
          case 'VOID':
              // Chaotic / Jitter
              p.vx += (Math.random() - 0.5) * 4;
              p.vy += (Math.random() - 0.5) * 4;
              if (Math.random() < 0.1) { // Lightning jump
                  p.x += (Math.random() - 0.5) * 20;
                  p.y += (Math.random() - 0.5) * 20;
              }
              break;

          case 'FIRE':
          case 'INFERNO':
              // Thermal Lift / Turbulence
              p.vy -= 0.6; // Rise
              p.vx += (Math.random() - 0.5) * 1.5; // Turbulence
              p.size *= 0.96; // Shrink faster
              break;

          default:
              p.vy -= 0.1; // Neutral float
      }

      p.x += p.vx;
      p.y += p.vy;
      p.life -= 1;
      if (p.element !== 'FIRE') p.size *= 0.98;

      if (p.life <= 0 || p.size < 0.2 || p.y > height + 50) {
        particlesRef.current.splice(i, 1);
      } else {
        // --- RENDERER ---
        ctx.save();
        // Fade in and out
        ctx.globalAlpha = Math.min(1, p.life / 20, (p.maxLife - p.life) / 10);

        if (p.type === 'LEAF') {
            ctx.translate(p.x, p.y);
            ctx.rotate(p.angle);
            ctx.fillStyle = p.color;
            ctx.beginPath();
            ctx.ellipse(0, 0, p.size, p.size * 0.4, 0, 0, Math.PI * 2);
            ctx.fill();
        } 
        else if (p.type === 'DROP') {
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 2;
            ctx.lineCap = 'round';
            ctx.beginPath();
            ctx.moveTo(p.x, p.y);
            // Stretch rain drop based on velocity
            ctx.lineTo(p.x - p.vx, p.y - p.vy * 3); 
            ctx.stroke();
        }
        else if (p.type === 'SPARK') {
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 2;
            ctx.shadowColor = p.color;
            ctx.shadowBlur = 10;
            ctx.beginPath();
            ctx.moveTo(p.x - p.vx, p.y - p.vy);
            ctx.lineTo(p.x + p.vx, p.y + p.vy);
            ctx.stroke();
            // Occasional cross-bolt
            if (Math.random() > 0.5) {
                ctx.beginPath();
                ctx.moveTo(p.x, p.y);
                ctx.lineTo(p.x + (Math.random()-0.5)*20, p.y + (Math.random()-0.5)*20);
                ctx.stroke();
            }
        }
        else if (p.type === 'EMBER') {
            ctx.fillStyle = p.color;
            ctx.shadowColor = 'orange';
            ctx.shadowBlur = 15;
            ctx.beginPath();
            ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
            ctx.fill();
        }
        else { // ORB / MIST
            ctx.fillStyle = p.color;
            ctx.shadowColor = p.color;
            ctx.shadowBlur = p.type === 'ORB' ? 10 : 0;
            ctx.beginPath();
            ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
            ctx.fill();
        }
        ctx.restore();
      }
    }
  };

  const spawnParticles = (x: number, y: number, element: string, theme: Theme) => {
    const isCombo = activeComboRef.current !== null;
    let count = isCombo ? 12 : 3;

    let type: ParticleType = 'ORB';
    let speed = Math.random() * 5;
    let spread = 20;

    // Customize Spawn based on Element
    if (element === 'WIND' || element === 'BLIZZARD') {
        type = Math.random() > 0.5 ? 'LEAF' : 'MIST';
        count = isCombo ? 15 : 4;
    } else if (element === 'WATER' || element === 'STEAM') {
        type = Math.random() > 0.7 ? 'MIST' : 'DROP';
        count = isCombo ? 20 : 5;
        spread = 40; 
    } else if (element === 'THUNDER' || element === 'TEMPEST' || element === 'VOID') {
        type = 'SPARK';
        count = isCombo ? 6 : 2; 
        speed = 8;
    } else if (element === 'FIRE' || element === 'INFERNO') {
        type = Math.random() > 0.8 ? 'MIST' : 'EMBER';
        count = isCombo ? 12 : 4;
    }

    for (let i = 0; i < count; i++) {
      const angle = Math.random() * Math.PI * 2;
      let vx = Math.cos(angle) * speed;
      let vy = Math.sin(angle) * speed;

      // Initial velocity overrides
      if (element === 'WATER' || element === 'STEAM') { vx *= 0.2; vy = Math.random() * 2; } 

      // Color tweaks
      let color = Math.random() > 0.5 ? theme.primary : theme.secondary;
      if (element === 'WIND') color = Math.random() > 0.5 ? '#00FFFF' : '#F0FFF0'; 
      if (element === 'THUNDER') color = Math.random() > 0.5 ? '#FFFF00' : '#9400D3';

      let spawnX = x;
      let spawnY = y;

      // FULL SCREEN SPAWN LOGIC
      if (isCombo || element === 'WATER') {
          spawnX = Math.random() * width;

          if (element === 'WATER' || element === 'TEMPEST') {
             // Falling Rain/Storm: Spawn Top
             spawnY = Math.random() * -100;
          } else {
             // Other Combos (Blizzard, Inferno, Plasma, Steam, Void): Full Field
             spawnY = Math.random() * height;
          }
      } else {
          // Hand localized spawn (Fire, Thunder, Wind)
          spawnX = x + (Math.random() - 0.5) * spread;
          spawnY = y + (Math.random() - 0.5) * spread;
      }

      particlesRef.current.push({
        x: spawnX,
        y: spawnY,
        vx, vy,
        life: 40 + Math.random() * 40,
        maxLife: 80,
        size: 3 + Math.random() * 5,
        color,
        element: element as Particle['element'],
        type,
        angle: Math.random() * Math.PI * 2,
        angularVelocity: (Math.random() - 0.5) * 0.2
      });
    }
  };

  const animate = useCallback((time: number) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (highlightRef.current > 0.01) highlightRef.current *= 0.9;
    else highlightRef.current = 0;
    const flash = highlightRef.current;

    // Use 'lighter' for high-energy anime look
    ctx.globalCompositeOperation = 'lighter'; 

    let lastCenterX = width / 2;
    let lastCenterY = height / 2;
    const t = time * 0.001;

    // Check for active combo
    const comboName = activeComboRef.current;

    if (comboName && handDataRef.current.length === 2) {
        // --- COMBO MODE ---
        const h1 = handDataRef.current[0];
        const h2 = handDataRef.current[1];
        const theme = COMBO_THEMES[comboName];

        const midX = (h1.middleBase.x + h2.middleBase.x) / 2;
        const midY = (h1.middleBase.y + h2.middleBase.y) / 2;
        lastCenterX = midX;
        lastCenterY = midY;

        // 1. Base Beam
        ctx.save();
        ctx.beginPath();
        ctx.moveTo(h1.middleBase.x, h1.middleBase.y);
        ctx.lineTo(h2.middleBase.x, h2.middleBase.y);
        ctx.strokeStyle = theme.primary;
        ctx.lineWidth = 20 + Math.sin(t * 10) * 5; 
        ctx.lineCap = 'round';
        ctx.shadowBlur = 40;
        ctx.shadowColor = theme.secondary;
        ctx.globalAlpha = 0.4;
        ctx.stroke();
        ctx.restore();

        // 2. Converging Energy
        ctx.save();
        ctx.beginPath();
        ctx.moveTo(h1.middleBase.x, h1.middleBase.y);
        ctx.lineTo(h2.middleBase.x, h2.middleBase.y);
        ctx.strokeStyle = '#FFFFFF';
        ctx.lineWidth = 3;
        ctx.setLineDash([10, 40]);
        ctx.lineDashOffset = -t * 200; 
        ctx.globalCompositeOperation = 'overlay';
        ctx.stroke();
        ctx.restore();

        // 3. Electric Arcs
        ctx.save();
        ctx.beginPath();
        ctx.moveTo(h1.middleBase.x, h1.middleBase.y);
        const dist = Math.hypot(h2.middleBase.x - h1.middleBase.x, h2.middleBase.y - h1.middleBase.y);
        const angle = Math.atan2(h2.middleBase.y - h1.middleBase.y, h2.middleBase.x - h1.middleBase.x);
        for(let i=0; i<=20; i++) {
             const p = i/20;
             const perp = Math.sin(p * Math.PI * 4 + t * 20) * (15 + Math.random() * 5);
             const bx = h1.middleBase.x + (h2.middleBase.x - h1.middleBase.x) * p + Math.cos(angle + Math.PI/2)*perp;
             const by = h1.middleBase.y + (h2.middleBase.y - h1.middleBase.y) * p + Math.sin(angle + Math.PI/2)*perp;
             ctx.lineTo(bx, by);
        }
        ctx.strokeStyle = theme.secondary;
        ctx.lineWidth = 2;
        ctx.shadowBlur = 10;
        ctx.shadowColor = theme.core;
        ctx.stroke();
        ctx.restore();

        // Array
        ctx.globalAlpha = 1;
        drawRuneRing(ctx, midX, midY, 180, t, theme);
        drawSacredGeometry(ctx, midX, midY, 140, -t * 2, theme);
        drawSquareLayer(ctx, midX, midY, 100, t * 3, theme);
        drawPentagram(ctx, midX, midY, 60, -t, 1, theme);

        spawnParticles(midX, midY, comboName, theme);

        handDataRef.current.forEach(h => {
             drawSkeleton(ctx, h);
             const auraSize = 50 + Math.sin(t * 20) * 10;
             const grad = ctx.createRadialGradient(h.middleBase.x, h.middleBase.y, 10, h.middleBase.x, h.middleBase.y, auraSize);
             grad.addColorStop(0, theme.core);
             grad.addColorStop(0.4, theme.primary);
             grad.addColorStop(1, 'rgba(0,0,0,0)');
             ctx.save();
             ctx.fillStyle = grad;
             ctx.globalAlpha = 0.5;
             ctx.beginPath();
             ctx.arc(h.middleBase.x, h.middleBase.y, auraSize, 0, Math.PI * 2);
             ctx.fill();
             ctx.restore();
             drawRuneRing(ctx, h.middleBase.x, h.middleBase.y, 40, t*5, theme);
        });

    } else {
        // --- INDIVIDUAL MODE ---
        handDataRef.current.forEach((hand) => {
           drawSkeleton(ctx, hand);
           const element = hand.gesture;
           const theme = (element !== 'NEUTRAL' && THEMES[element]) ? THEMES[element] : THEMES['NEUTRAL'];
           const centerX = hand.middleBase.x; 
           const centerY = hand.middleBase.y; 

           if (element !== 'NEUTRAL') {
               if (flash > 0.05 && highlightRef.current > 0.05) {
                   ctx.save();
                   ctx.translate(centerX, centerY);
                   const waveSize = 120 + (1 - flash) * 100;
                   ctx.beginPath();
                   ctx.arc(0, 0, waveSize, 0, Math.PI * 2);
                   ctx.lineWidth = 10 * flash;
                   ctx.strokeStyle = theme.core;
                   ctx.shadowBlur = 20;
                   ctx.shadowColor = theme.secondary;
                   ctx.globalAlpha = flash;
                   ctx.stroke();
                   ctx.restore();
               }

               drawRuneRing(ctx, centerX, centerY, 120, t * 0.5, theme);
               drawSacredGeometry(ctx, centerX, centerY, 90, -t * 1.5, theme);
               drawSquareLayer(ctx, centerX, centerY, 65, t * 2.5, theme);
               const pulse = Math.sin(time * 0.005) * 0.5 + 0.5;
               drawPentagram(ctx, centerX, centerY, 40, t, pulse, theme);

               spawnParticles(centerX, centerY, element, theme);
               lastCenterX = centerX;
               lastCenterY = centerY;
           } else {
               ctx.globalAlpha = 0.3;
               drawRuneRing(ctx, centerX, centerY, 50, t * 0.2, theme);
           }
        });
    }

    updateParticles(ctx, canvas.width, canvas.height, lastCenterX, lastCenterY);
    requestRef.current = requestAnimationFrame(animate);
  }, [width, height]);

  useEffect(() => {
    requestRef.current = requestAnimationFrame(animate);
    return () => { if (requestRef.current) cancelAnimationFrame(requestRef.current); };
  }, [animate]);

  return (
    <div className="relative w-full h-full bg-black overflow-hidden flex items-center justify-center">
        <Webcam ref={webcamRef} audio={false} width={width} height={height} mirrored={true} screenshotFormat="image/jpeg" className="absolute opacity-0 pointer-events-none" />
        <Webcam audio={false} width={width} height={height} mirrored={true} className="absolute top-0 left-0 w-full h-full object-cover opacity-80" />
        <canvas ref={canvasRef} width={width} height={height} className="absolute top-0 left-0 w-full h-full object-cover z-10" />
        {!isModelLoaded && (
            <div className="absolute inset-0 flex items-center justify-center bg-black bg-opacity-80 z-50">
                <div className="text-amber-500 font-mono text-xl animate-pulse">Summoning Grimoire... (Loading Models)</div>
            </div>
        )}
        <div className="absolute top-4 right-4 text-right z-20 font-mono pointer-events-none">
            <div className={`text-2xl font-bold mb-2 tracking-widest transition-all duration-300 ${highlightRef.current > 0.1 ? 'scale-110' : ''} ${
                currentElement === 'FIRE' ? 'text-orange-500' :
                currentElement === 'WATER' ? 'text-blue-500' :
                currentElement === 'WIND' ? 'text-cyan-300' :
                currentElement === 'THUNDER' ? 'text-purple-500' : 
                currentElement === 'INFERNO' ? 'text-red-600' :
                currentElement === 'BLIZZARD' ? 'text-cyan-100' :
                currentElement === 'VOID' ? 'text-violet-900' : 'text-amber-500'
            }`}>SPELL: {currentElement}</div>
            <div className="text-xs text-white opacity-70 space-y-1 mb-2"><p>Status: {debugInfo}</p></div>
            <div className="text-xs text-white opacity-70 space-y-1">
                <p>✋ Palm Up: FIRE</p>
                <p>👇 Palm Down: WATER (RAIN)</p>
                <p>👊 Fist: THUNDER</p>
                <p>✌️ Victory: WIND</p>
            </div>
        </div>
    </div>
  );
};

export default MagicOverlay;

import React, { useEffect, useRef, useCallback, useState } from 'react';
import Webcam from 'react-webcam';
import { Particle, HandData, ElementType, Theme, ParticleType } from '../types';
import { 
  drawRuneRing, 
  drawSacredGeometry, 
  drawSquareLayer, 
  drawPentagram,
  THEMES
} from '../utils/geometry';

interface MagicOverlayProps {
  width: number;
  height: number;
}

const COMBO_THEMES: Record<string, Theme> = {
  'BLIZZARD': { primary: '#00FFFF', secondary: '#E0FFFF', core: '#FFFFFF', shadow: '#008B8B' }, // Ice/Wind
  'PLASMA': { primary: '#FF00FF', secondary: '#00FFFF', core: '#FFFFFF', shadow: '#9400D3' }, // Fire/Wind
  'STEAM': { primary: '#F0F8FF', secondary: '#B0C4DE', core: '#FFFFFF', shadow: '#778899' }, // Fire/Water
  'TEMPEST': { primary: '#000080', secondary: '#8A2BE2', core: '#FFFF00', shadow: '#191970' }, // Thunder/Water
  'INFERNO': { primary: '#FF0000', secondary: '#FF4500', core: '#FFFF00', shadow: '#8B0000' }, // Fire/Fire
  'VOID': { primary: '#000000', secondary: '#4B0082', core: '#FFFFFF', shadow: '#9400D3' }, // Thunder/Thunder
};

const ELEMENT_NAMES_CN: Record<string, string> = {
    'NEUTRAL': '蕴量中...',
    'FIRE': '烈焰 (FIRE)',
    'WATER': '流水 (WATER)',
    'THUNDER': '雷霆 (THUNDER)',
    'WIND': '疾风 (WIND)',
    'BLIZZARD': '极寒暴雪',
    'PLASMA': '等离子态',
    'STEAM': '灼热蒸汽',
    'TEMPEST': '雷暴风眼',
    'INFERNO': '地狱烈火',
    'VOID': '虚空奇点'
};

const getCombo = (g1: ElementType, g2: ElementType): string | null => {
    const sorted = [g1, g2].sort().join('_');
    switch(sorted) {
        case 'WATER_WIND': return 'BLIZZARD';
        case 'FIRE_WIND': return 'PLASMA';
        case 'FIRE_WATER': return 'STEAM';
        case 'THUNDER_WATER': return 'TEMPEST';
        case 'FIRE_FIRE': return 'INFERNO';
        case 'THUNDER_THUNDER': return 'VOID';
        default: return null;
    }
};

const MagicOverlay: React.FC<MagicOverlayProps> = ({ width, height }) => {
  const webcamRef = useRef<Webcam>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>(0);
  const particlesRef = useRef<Particle[]>([]);
  const handDataRef = useRef<HandData[]>([]);
  const [currentElement, setCurrentElement] = useState<string>('NEUTRAL');
  const [isModelLoaded, setIsModelLoaded] = useState(false);
  const [debugInfo, setDebugInfo] = useState<string>("正在初始化...");

  // Visual Feedback State
  const highlightRef = useRef<number>(0);
  const prevElementRef = useRef<string>('NEUTRAL');
  const activeComboRef = useRef<string | null>(null);

  // Audio Context
  const audioContextRef = useRef<AudioContext | null>(null);
  const noiseBufferRef = useRef<AudioBuffer | null>(null);

  useEffect(() => {
    const AudioContextClass = (window as any).AudioContext || (window as any).webkitAudioContext;
    if (AudioContextClass) {
        const ctx = new AudioContextClass();
        audioContextRef.current = ctx;

        // Generate White Noise Buffer for procedural effects
        const bufferSize = ctx.sampleRate * 2; // 2 seconds
        const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
        const data = buffer.getChannelData(0);
        for (let i = 0; i < bufferSize; i++) {
            data[i] = Math.random() * 2 - 1;
        }
        noiseBufferRef.current = buffer;
    }

    // Resume audio context on user interaction
    const resumeAudio = () => {
        if (audioContextRef.current?.state === 'suspended') {
            audioContextRef.current.resume();
        }
    };
    window.addEventListener('click', resumeAudio);
    window.addEventListener('touchstart', resumeAudio);
    return () => {
        window.removeEventListener('click', resumeAudio);
        window.removeEventListener('touchstart', resumeAudio);
    };
  }, []);

  const playChime = useCallback((element: string) => {
    const ctx = audioContextRef.current;
    if (!ctx) return;
    if (ctx.state === 'suspended') {
        ctx.resume().catch(console.error);
    }

    // Fallback if noise buffer isn't ready, though it should be fast
    if (!noiseBufferRef.current) return;

    const now = ctx.currentTime;
    const masterGain = ctx.createGain();
    masterGain.connect(ctx.destination);
    masterGain.gain.setValueAtTime(0.3, now); // Master Volume

    // Helper: Play Noise (Wind, Water, Fire textures)
    const playNoise = (filterType: BiquadFilterType, freqStart: number, freqEnd: number, duration: number, vol: number = 1, delay: number = 0) => {
        const src = ctx.createBufferSource();
        src.buffer = noiseBufferRef.current;
        src.loop = true;

        const filter = ctx.createBiquadFilter();
        filter.type = filterType;
        filter.frequency.setValueAtTime(freqStart, now + delay);
        filter.frequency.exponentialRampToValueAtTime(freqEnd, now + delay + duration);
        filter.Q.value = 1;

        const amp = ctx.createGain();
        amp.gain.setValueAtTime(0, now + delay);
        amp.gain.linearRampToValueAtTime(vol, now + delay + 0.05); // Attack
        amp.gain.exponentialRampToValueAtTime(0.01, now + delay + duration); // Decay

        src.connect(filter);
        filter.connect(amp);
        amp.connect(masterGain);

        src.start(now + delay);
        src.stop(now + delay + duration + 0.2);
    };

    // Helper: Play Tone (Magic hums, zaps, tinkles)
    const playTone = (type: OscillatorType, freqStart: number, freqEnd: number, duration: number, vol: number = 1, delay: number = 0) => {
        const osc = ctx.createOscillator();
        osc.type = type;
        osc.frequency.setValueAtTime(freqStart, now + delay);
        if (freqStart !== freqEnd) {
             osc.frequency.exponentialRampToValueAtTime(freqEnd, now + delay + duration);
        }

        const amp = ctx.createGain();
        amp.gain.setValueAtTime(0, now + delay);
        amp.gain.linearRampToValueAtTime(vol, now + delay + 0.05);
        amp.gain.exponentialRampToValueAtTime(0.01, now + delay + duration);

        osc.connect(amp);
        amp.connect(masterGain);

        osc.start(now + delay);
        osc.stop(now + delay + duration + 0.2);
    };

    switch (element) {
        case 'FIRE':
            // Crackling Fire: Low rumble + high frequency clicks (simulated by noise)
            playNoise('lowpass', 500, 100, 1.0, 0.5);
            playTone('sawtooth', 80, 120, 0.8, 0.2); // Low growl
            break;

        case 'WATER':
            // Splash: Bandpass sweep
            playNoise('bandpass', 800, 300, 0.6, 0.4);
            playTone('sine', 600, 300, 0.4, 0.3, 0.1); // Droplet
            break;

        case 'WIND':
            // Whoosh: Lowpass sweep up then down
            playNoise('lowpass', 200, 800, 0.4, 0.3);
            playNoise('highpass', 400, 1000, 0.5, 0.2, 0.1);
            break;

        case 'THUNDER':
            // Thunder: Zap (Sawtooth drop) + Boom (Lowpass noise)
            playTone('sawtooth', 800, 50, 0.3, 0.2);
            playNoise('lowpass', 1000, 50, 1.2, 0.6, 0.1); 
            break;

        // COMBOS
        case 'BLIZZARD': // Wind + Ice
            playNoise('highpass', 1000, 3000, 1.5, 0.4); // Icy Wind
            playTone('sine', 1500, 2000, 0.3, 0.1, 0.1); // Crystal chime
            playTone('sine', 2000, 2500, 0.3, 0.1, 0.3);
            break;

        case 'INFERNO': // Intense Fire
            playNoise('lowpass', 800, 50, 1.5, 0.8); // Explosion
            playTone('square', 60, 40, 1.5, 0.2); // Rumble
            break;

        case 'TEMPEST': // Thunder + Water
            playNoise('lowpass', 200, 50, 2.0, 0.8); // Deep Thunder
            playTone('sawtooth', 1200, 100, 0.5, 0.2, 0.1); // Crack
            playNoise('bandpass', 1000, 500, 1.0, 0.3); // Rain hiss
            break;

        case 'VOID': // Dark energy
            playTone('sine', 50, 40, 2.5, 0.6); // Sub bass
            playNoise('bandpass', 100, 200, 2.5, 0.4); // Eerie atmosphere
            playTone('sine', 300, 290, 1.0, 0.1, 0.5); // Interference beat
            break;

        case 'PLASMA': // Fire + Wind
            playTone('sawtooth', 200, 800, 1.0, 0.2); // Rising energy
            playNoise('bandpass', 400, 1200, 1.0, 0.4);
            break;

        case 'STEAM': // Fire + Water
            playNoise('highpass', 500, 1000, 1.0, 0.3); // Hiss
            break;

        default:
            // Generic activation
            playTone('triangle', 440, 880, 0.3, 0.1);
    }
  }, []);

  const detectGesture = (landmarks: any[], videoWidth: number, videoHeight: number): ElementType => {
    const mapPt = (idx: number) => ({ x: (1 - landmarks[idx].x) * videoWidth, y: landmarks[idx].y * videoHeight });
    const wrist = mapPt(0);
    const indexTip = mapPt(8);
    const middleTip = mapPt(12);
    const ringTip = mapPt(16);
    const pinkyTip = mapPt(20);
    const indexMCP = mapPt(5);
    const middleMCP = mapPt(9);
    const ringMCP = mapPt(13); 
    const pinkyMCP = mapPt(17);

    const dist = (p1: any, p2: any) => Math.hypot(p1.x - p2.x, p1.y - p2.y);
    const isFingerOpen = (tip: any, mcp: any) => dist(tip, wrist) > dist(mcp, wrist);

    // Orientation: If Wrist Y < Middle MCP Y, the wrist is ABOVE the hand -> Hand Pointing DOWN
    const isPointingDown = wrist.y < middleMCP.y;

    if (isPointingDown) {
        return 'WATER';
    } 

    // Count open fingers for upward gestures
    let openCount = 0;
    if (isFingerOpen(indexTip, indexMCP)) openCount++;
    if (isFingerOpen(middleTip, middleMCP)) openCount++;
    if (isFingerOpen(ringTip, ringMCP)) openCount++;
    if (isFingerOpen(pinkyTip, pinkyMCP)) openCount++;

    if (openCount >= 4) return 'FIRE'; // Open Palm
    if (openCount >= 2) return 'WIND'; // Victory or 3 fingers

    // Default / Fist
    return 'THUNDER';
  };

  const drawSkeleton = (ctx: CanvasRenderingContext2D, hand: HandData) => {
      ctx.strokeStyle = "rgba(255, 255, 255, 0.2)";
      ctx.lineWidth = 1;
      ctx.fillStyle = "rgba(255, 255, 255, 0.4)";
      const points = [hand.wrist, hand.indexBase, hand.indexTip, hand.middleBase, hand.middleTip, hand.ringBase, hand.ringTip, hand.pinkyBase, hand.pinkyTip, hand.thumbTip];

      const drawLine = (p1: any, p2: any) => { ctx.beginPath(); ctx.moveTo(p1.x, p1.y); ctx.lineTo(p2.x, p2.y); ctx.stroke(); }
      drawLine(hand.wrist, hand.indexBase); drawLine(hand.indexBase, hand.indexTip);
      drawLine(hand.wrist, hand.middleBase); drawLine(hand.middleBase, hand.middleTip);
      drawLine(hand.wrist, hand.pinkyBase); drawLine(hand.pinkyBase, hand.pinkyTip);

      points.forEach(p => { ctx.beginPath(); ctx.arc(p.x, p.y, 2, 0, Math.PI * 2); ctx.fill(); });
  };

  const onResults = useCallback((results: any) => {
    // Safety check for dimensions
    let videoWidth = width;
    let videoHeight = height;
    if (webcamRef.current?.video?.videoWidth) {
        videoWidth = webcamRef.current.video.videoWidth;
        videoHeight = webcamRef.current.video.videoHeight;
    }

    if (results.multiHandLandmarks && results.multiHandLandmarks.length > 0) {
      setDebugInfo(`检测到: ${results.multiHandLandmarks.length} 只手`);
      const newHandData: HandData[] = results.multiHandLandmarks.map((landmarks: any[]) => {
        const gesture = detectGesture(landmarks, videoWidth, videoHeight);
        const mapPt = (idx: number) => ({ x: (1 - landmarks[idx].x) * videoWidth, y: landmarks[idx].y * videoHeight });
        return {
          wrist: mapPt(0), indexTip: mapPt(8), middleTip: mapPt(12), ringTip: mapPt(16), pinkyTip: mapPt(20), thumbTip: mapPt(4),
          indexBase: mapPt(5), middleBase: mapPt(9), ringBase: mapPt(13), pinkyBase: mapPt(17),
          isOpen: gesture !== 'THUNDER', gesture, opacity: 1,
        };
      });

      handDataRef.current = newHandData;
      let newElement = 'NEUTRAL';
      let activeCombo = null;

      if (newHandData.length === 2) {
          const g1 = newHandData[0].gesture;
          const g2 = newHandData[1].gesture;
          if (g1 !== 'NEUTRAL' && g2 !== 'NEUTRAL') activeCombo = getCombo(g1, g2);
      }

      if (activeCombo) newElement = activeCombo;
      else {
          const activeHand = newHandData.find(h => h.gesture !== 'NEUTRAL');
          if (activeHand) newElement = activeHand.gesture;
      }
      activeComboRef.current = activeCombo;

      if (newElement !== prevElementRef.current) {
          if (newElement !== 'NEUTRAL') { highlightRef.current = 1.0; playChime(newElement); }
          prevElementRef.current = newElement;
      }
      setCurrentElement(newElement);
    } else {
      handDataRef.current = [];
      setDebugInfo("未检测到手部");
      activeComboRef.current = null;
      if (prevElementRef.current !== 'NEUTRAL') { prevElementRef.current = 'NEUTRAL'; setCurrentElement('NEUTRAL'); }
    }
  }, [width, height, playChime]);

  useEffect(() => {
    let hands: any = null;
    let isActive = true;
    let frameId: number;
    let lastVideoTime = -1;

    const initHands = async () => {
       if (!(window as any).Hands) { setTimeout(initHands, 500); return; }

       hands = new (window as any).Hands({ 
           locateFile: (file: string) => `https://cdn.jsdelivr.net/npm/@mediapipe/hands/${file}` 
       });

       hands.setOptions({ maxNumHands: 2, modelComplexity: 1, minDetectionConfidence: 0.5, minTrackingConfidence: 0.5 });
       hands.onResults(onResults);

       setIsModelLoaded(true);

       const processVideo = async () => {
         if (!isActive) return;
         if (webcamRef.current && webcamRef.current.video && webcamRef.current.video.readyState === 4) {
             const video = webcamRef.current.video;
             // STRICT CHECK: Ensure video has dimensions to prevent 'buffer' read error
             if (video.videoWidth > 0 && video.videoHeight > 0) {
                 if (video.currentTime !== lastVideoTime) {
                     lastVideoTime = video.currentTime;
                     try { await hands.send({ image: video }); } catch (e) { console.error("MediaPipe processing error:", e); }
                 }
             }
         }
         frameId = requestAnimationFrame(processVideo);
       };
       processVideo();
    };
    initHands();
    return () => { isActive = false; if (frameId) cancelAnimationFrame(frameId); if (hands) hands.close(); };
  }, [onResults]);

  // --- PHYSICS ENGINE ---
  const updateParticles = (ctx: CanvasRenderingContext2D, width: number, height: number, centerX: number, centerY: number) => {
    for (let i = particlesRef.current.length - 1; i >= 0; i--) {
      const p = particlesRef.current[i];

      // General Drag
      p.vx *= 0.95;
      p.vy *= 0.95;

      // Element Specific Physics
      switch (p.element) {
          case 'WIND':
          case 'BLIZZARD':
              // Vortex/Spiral Physics
              const dx = p.x - centerX;
              const dy = p.y - centerY;
              const dist = Math.sqrt(dx*dx + dy*dy) + 1;
              const angle = Math.atan2(dy, dx);
              // Tangential force (Rotation)
              p.vx += Math.cos(angle + Math.PI/2) * 1.5;
              p.vy += Math.sin(angle + Math.PI/2) * 1.5;
              // Centripetal force (Suck in)
              p.vx -= (dx / dist) * 0.5;
              p.vy -= (dy / dist) * 0.5;
              p.angle += p.angularVelocity; // Spin the leaf
              break;

          case 'WATER':
          case 'STEAM':
              // Gravity & Rain
              p.vy += 1.2; // Strong gravity
              p.x += Math.sin(p.life * 0.1) * 0.5; // Slight waver
              break;

          case 'THUNDER':
          case 'TEMPEST':
          case 'VOID':
              // Chaotic / Jitter
              p.vx += (Math.random() - 0.5) * 4;
              p.vy += (Math.random() - 0.5) * 4;
              if (Math.random() < 0.1) { // Lightning jump
                  p.x += (Math.random() - 0.5) * 20;
                  p.y += (Math.random() - 0.5) * 20;
              }
              break;

          case 'FIRE':
          case 'INFERNO':
              // Thermal Lift / Turbulence
              p.vy -= 0.6; // Rise
              p.vx += (Math.random() - 0.5) * 1.5; // Turbulence
              p.size *= 0.96; // Shrink faster
              break;

          default:
              p.vy -= 0.1; // Neutral float
      }

      p.x += p.vx;
      p.y += p.vy;
      p.life -= 1;
      if (p.element !== 'FIRE') p.size *= 0.98;

      if (p.life <= 0 || p.size < 0.2 || p.y > height + 50) {
        particlesRef.current.splice(i, 1);
      } else {
        // --- RENDERER ---
        ctx.save();
        // Fade in and out
        ctx.globalAlpha = Math.min(1, p.life / 20, (p.maxLife - p.life) / 10);

        if (p.type === 'LEAF') {
            ctx.translate(p.x, p.y);
            ctx.rotate(p.angle);
            ctx.fillStyle = p.color;
            ctx.beginPath();
            ctx.ellipse(0, 0, p.size, p.size * 0.4, 0, 0, Math.PI * 2);
            ctx.fill();
        } 
        else if (p.type === 'DROP') {
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 2;
            ctx.lineCap = 'round';
            ctx.beginPath();
            ctx.moveTo(p.x, p.y);
            // Stretch rain drop based on velocity
            ctx.lineTo(p.x - p.vx, p.y - p.vy * 3); 
            ctx.stroke();
        }
        else if (p.type === 'SPARK') {
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 2;
            ctx.shadowColor = p.color;
            ctx.shadowBlur = 10;
            ctx.beginPath();
            ctx.moveTo(p.x - p.vx, p.y - p.vy);
            ctx.lineTo(p.x + p.vx, p.y + p.vy);
            ctx.stroke();
            // Occasional cross-bolt
            if (Math.random() > 0.5) {
                ctx.beginPath();
                ctx.moveTo(p.x, p.y);
                ctx.lineTo(p.x + (Math.random()-0.5)*20, p.y + (Math.random()-0.5)*20);
                ctx.stroke();
            }
        }
        else if (p.type === 'EMBER') {
            ctx.fillStyle = p.color;
            ctx.shadowColor = 'orange';
            ctx.shadowBlur = 15;
            ctx.beginPath();
            ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
            ctx.fill();
        }
        else { // ORB / MIST
            ctx.fillStyle = p.color;
            ctx.shadowColor = p.color;
            ctx.shadowBlur = p.type === 'ORB' ? 10 : 0;
            ctx.beginPath();
            ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
            ctx.fill();
        }
        ctx.restore();
      }
    }
  };

  const spawnParticles = (x: number, y: number, element: string, theme: Theme) => {
    const isCombo = activeComboRef.current !== null;
    let count = isCombo ? 12 : 3;

    let type: ParticleType = 'ORB';
    let speed = Math.random() * 5;
    let spread = 20;

    // Customize Spawn based on Element
    if (element === 'WIND' || element === 'BLIZZARD') {
        type = Math.random() > 0.5 ? 'LEAF' : 'MIST';
        count = isCombo ? 15 : 4;
    } else if (element === 'WATER' || element === 'STEAM') {
        type = Math.random() > 0.7 ? 'MIST' : 'DROP';
        count = isCombo ? 20 : 5;
        spread = 40; 
    } else if (element === 'THUNDER' || element === 'TEMPEST' || element === 'VOID') {
        type = 'SPARK';
        count = isCombo ? 6 : 2; 
        speed = 8;
    } else if (element === 'FIRE' || element === 'INFERNO') {
        type = Math.random() > 0.8 ? 'MIST' : 'EMBER';
        count = isCombo ? 12 : 4;
    }

    for (let i = 0; i < count; i++) {
      const angle = Math.random() * Math.PI * 2;
      let vx = Math.cos(angle) * speed;
      let vy = Math.sin(angle) * speed;

      // Initial velocity overrides
      if (element === 'WATER' || element === 'STEAM') { vx *= 0.2; vy = Math.random() * 2; } 

      // Color tweaks
      let color = Math.random() > 0.5 ? theme.primary : theme.secondary;
      if (element === 'WIND') color = Math.random() > 0.5 ? '#00FFFF' : '#F0FFF0'; 
      if (element === 'THUNDER') color = Math.random() > 0.5 ? '#FFFF00' : '#9400D3';

      let spawnX = x;
      let spawnY = y;

      // FULL SCREEN SPAWN LOGIC
      if (isCombo || element === 'WATER') {
          spawnX = Math.random() * width;

          if (element === 'WATER' || element === 'TEMPEST') {
             // Falling Rain/Storm: Spawn Top
             spawnY = Math.random() * -100;
          } else {
             // Other Combos (Blizzard, Inferno, Plasma, Steam, Void): Full Field
             spawnY = Math.random() * height;
          }
      } else {
          // Hand localized spawn (Fire, Thunder, Wind)
          spawnX = x + (Math.random() - 0.5) * spread;
          spawnY = y + (Math.random() - 0.5) * spread;
      }

      particlesRef.current.push({
        x: spawnX,
        y: spawnY,
        vx, vy,
        life: 40 + Math.random() * 40,
        maxLife: 80,
        size: 3 + Math.random() * 5,
        color,
        element: element as Particle['element'],
        type,
        angle: Math.random() * Math.PI * 2,
        angularVelocity: (Math.random() - 0.5) * 0.2
      });
    }
  };

  const animate = useCallback((time: number) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (highlightRef.current > 0.01) highlightRef.current *= 0.9;
    else highlightRef.current = 0;
    const flash = highlightRef.current;

    // Use 'lighter' for high-energy anime look
    ctx.globalCompositeOperation = 'lighter'; 

    let lastCenterX = width / 2;
    let lastCenterY = height / 2;
    const t = time * 0.001;

    // Check for active combo
    const comboName = activeComboRef.current;

    if (comboName && handDataRef.current.length === 2) {
        // --- COMBO MODE ---
        const h1 = handDataRef.current[0];
        const h2 = handDataRef.current[1];
        const theme = COMBO_THEMES[comboName];

        const midX = (h1.middleBase.x + h2.middleBase.x) / 2;
        const midY = (h1.middleBase.y + h2.middleBase.y) / 2;
        lastCenterX = midX;
        lastCenterY = midY;

        // 1. Base Beam
        ctx.save();
        ctx.beginPath();
        ctx.moveTo(h1.middleBase.x, h1.middleBase.y);
        ctx.lineTo(h2.middleBase.x, h2.middleBase.y);
        ctx.strokeStyle = theme.primary;
        ctx.lineWidth = 20 + Math.sin(t * 10) * 5; 
        ctx.lineCap = 'round';
        ctx.shadowBlur = 40;
        ctx.shadowColor = theme.secondary;
        ctx.globalAlpha = 0.4;
        ctx.stroke();
        ctx.restore();

        // 2. Converging Energy
        ctx.save();
        ctx.beginPath();
        ctx.moveTo(h1.middleBase.x, h1.middleBase.y);
        ctx.lineTo(h2.middleBase.x, h2.middleBase.y);
        ctx.strokeStyle = '#FFFFFF';
        ctx.lineWidth = 3;
        ctx.setLineDash([10, 40]);
        ctx.lineDashOffset = -t * 200; 
        ctx.globalCompositeOperation = 'overlay';
        ctx.stroke();
        ctx.restore();

        // 3. Electric Arcs
        ctx.save();
        ctx.beginPath();
        ctx.moveTo(h1.middleBase.x, h1.middleBase.y);
        const dist = Math.hypot(h2.middleBase.x - h1.middleBase.x, h2.middleBase.y - h1.middleBase.y);
        const angle = Math.atan2(h2.middleBase.y - h1.middleBase.y, h2.middleBase.x - h1.middleBase.x);
        for(let i=0; i<=20; i++) {
             const p = i/20;
             const perp = Math.sin(p * Math.PI * 4 + t * 20) * (15 + Math.random() * 5);
             const bx = h1.middleBase.x + (h2.middleBase.x - h1.middleBase.x) * p + Math.cos(angle + Math.PI/2)*perp;
             const by = h1.middleBase.y + (h2.middleBase.y - h1.middleBase.y) * p + Math.sin(angle + Math.PI/2)*perp;
             ctx.lineTo(bx, by);
        }
        ctx.strokeStyle = theme.secondary;
        ctx.lineWidth = 2;
        ctx.shadowBlur = 10;
        ctx.shadowColor = theme.core;
        ctx.stroke();
        ctx.restore();

        // Array
        ctx.globalAlpha = 1;
        drawRuneRing(ctx, midX, midY, 180, t, theme);
        drawSacredGeometry(ctx, midX, midY, 140, -t * 2, theme);
        drawSquareLayer(ctx, midX, midY, 100, t * 3, theme);
        drawPentagram(ctx, midX, midY, 60, -t, 1, theme);

        spawnParticles(midX, midY, comboName, theme);

        handDataRef.current.forEach(h => {
             drawSkeleton(ctx, h);
             const auraSize = 50 + Math.sin(t * 20) * 10;
             const grad = ctx.createRadialGradient(h.middleBase.x, h.middleBase.y, 10, h.middleBase.x, h.middleBase.y, auraSize);
             grad.addColorStop(0, theme.core);
             grad.addColorStop(0.4, theme.primary);
             grad.addColorStop(1, 'rgba(0,0,0,0)');
             ctx.save();
             ctx.fillStyle = grad;
             ctx.globalAlpha = 0.5;
             ctx.beginPath();
             ctx.arc(h.middleBase.x, h.middleBase.y, auraSize, 0, Math.PI * 2);
             ctx.fill();
             ctx.restore();
             drawRuneRing(ctx, h.middleBase.x, h.middleBase.y, 40, t*5, theme);
        });

    } else {
        // --- INDIVIDUAL MODE ---
        handDataRef.current.forEach((hand) => {
           drawSkeleton(ctx, hand);
           const element = hand.gesture;
           const theme = (element !== 'NEUTRAL' && THEMES[element]) ? THEMES[element] : THEMES['NEUTRAL'];
           const centerX = hand.middleBase.x; 
           const centerY = hand.middleBase.y; 

           if (element !== 'NEUTRAL') {
               if (flash > 0.05 && highlightRef.current > 0.05) {
                   ctx.save();
                   ctx.translate(centerX, centerY);
                   const waveSize = 120 + (1 - flash) * 100;
                   ctx.beginPath();
                   ctx.arc(0, 0, waveSize, 0, Math.PI * 2);
                   ctx.lineWidth = 10 * flash;
                   ctx.strokeStyle = theme.core;
                   ctx.shadowBlur = 20;
                   ctx.shadowColor = theme.secondary;
                   ctx.globalAlpha = flash;
                   ctx.stroke();
                   ctx.restore();
               }

               drawRuneRing(ctx, centerX, centerY, 120, t * 0.5, theme);
               drawSacredGeometry(ctx, centerX, centerY, 90, -t * 1.5, theme);
               drawSquareLayer(ctx, centerX, centerY, 65, t * 2.5, theme);
               const pulse = Math.sin(time * 0.005) * 0.5 + 0.5;
               drawPentagram(ctx, centerX, centerY, 40, t, pulse, theme);

               spawnParticles(centerX, centerY, element, theme);
               lastCenterX = centerX;
               lastCenterY = centerY;
           } else {
               ctx.globalAlpha = 0.3;
               drawRuneRing(ctx, centerX, centerY, 50, t * 0.2, theme);
           }
        });
    }

    updateParticles(ctx, canvas.width, canvas.height, lastCenterX, lastCenterY);
    requestRef.current = requestAnimationFrame(animate);
  }, [width, height]);

  useEffect(() => {
    requestRef.current = requestAnimationFrame(animate);
    return () => { if (requestRef.current) cancelAnimationFrame(requestRef.current); };
  }, [animate]);

  return (
    <div className="relative w-full h-full bg-black overflow-hidden flex items-center justify-center font-sans">
        <Webcam ref={webcamRef} audio={false} width={width} height={height} mirrored={true} screenshotFormat="image/jpeg" className="absolute opacity-0 pointer-events-none" />
        <Webcam audio={false} width={width} height={height} mirrored={true} className="absolute top-0 left-0 w-full h-full object-cover opacity-80" />
        <canvas ref={canvasRef} width={width} height={height} className="absolute top-0 left-0 w-full h-full object-cover z-10" />

        {!isModelLoaded && (
            <div className="absolute inset-0 flex items-center justify-center bg-black bg-opacity-80 z-50">
                <div className="text-amber-500 font-mono text-xl animate-pulse">正在校准魔法维度... (Loading)</div>
            </div>
        )}

        <div className="absolute top-8 right-8 text-right z-20 pointer-events-none flex flex-col items-end">
             <div className="text-xs text-amber-500 opacity-60 font-mono mb-1">{debugInfo}</div>
             <div className={`text-4xl font-bold tracking-widest transition-all duration-300 drop-shadow-[0_0_10px_rgba(255,255,255,0.5)] ${highlightRef.current > 0.1 ? 'scale-110' : ''} ${
                currentElement === 'FIRE' ? 'text-orange-500' :
                currentElement === 'WATER' ? 'text-blue-500' :
                currentElement === 'WIND' ? 'text-cyan-300' :
                currentElement === 'THUNDER' ? 'text-purple-500' : 
                currentElement === 'INFERNO' ? 'text-red-600' :
                currentElement === 'BLIZZARD' ? 'text-cyan-100' :
                currentElement === 'VOID' ? 'text-violet-900' : 'text-amber-400'
            }`}>
                {ELEMENT_NAMES_CN[currentElement] || currentElement}
            </div>
        </div>

        <div className="absolute bottom-0 left-0 w-full p-4 z-20 bg-gradient-to-t from-black via-black/80 to-transparent">
            <div className="flex justify-center items-center gap-6 text-white text-sm font-medium opacity-80">
                <div className="flex items-center gap-2">
                    <span className="text-2xl">✋</span> 
                    <span className="text-orange-400">火焰 (5指)</span>
                </div>
                <div className="w-px h-6 bg-white/20"></div>
                <div className="flex items-center gap-2">
                    <span className="text-2xl">👇</span>
                    <span className="text-blue-400">流水 (掌心向下)</span>
                </div>
                <div className="w-px h-6 bg-white/20"></div>
                <div className="flex items-center gap-2">
                    <span className="text-2xl">👊</span>
                    <span className="text-purple-400">雷电 (握拳)</span>
                </div>
                <div className="w-px h-6 bg-white/20"></div>
                <div className="flex items-center gap-2">
                    <span className="text-2xl">✌️</span>
                    <span className="text-teal-300">疾风 (2-3指)</span>
                </div>
                <div className="hidden md:flex ml-4 text-xs text-gray-400 italic">
                    * 双手组合可触发强力法术
                </div>
            </div>
        </div>
    </div>
  );
};

