export default App;

import React, { useEffect, useRef, useCallback, useState } from 'react';
import Webcam from 'react-webcam';
import { Particle, HandData, ElementType, Theme, ParticleType } from '../types';
import { 
  drawRuneRing, 
  drawSacredGeometry, 
  drawSquareLayer, 
  drawPentagram,
  THEMES
} from '../utils/geometry';

interface MagicOverlayProps {
  width: number;
  height: number;
}

const COMBO_THEMES: Record<string, Theme> = {
  'BLIZZARD': { primary: '#00FFFF', secondary: '#E0FFFF', core: '#FFFFFF', shadow: '#008B8B' }, // Ice/Wind
  'PLASMA': { primary: '#FF00FF', secondary: '#00FFFF', core: '#FFFFFF', shadow: '#9400D3' }, // Fire/Wind
  'STEAM': { primary: '#F0F8FF', secondary: '#B0C4DE', core: '#FFFFFF', shadow: '#778899' }, // Fire/Water
  'TEMPEST': { primary: '#000080', secondary: '#8A2BE2', core: '#FFFF00', shadow: '#191970' }, // Thunder/Water
  'INFERNO': { primary: '#FF0000', secondary: '#FF4500', core: '#FFFF00', shadow: '#8B0000' }, // Fire/Fire
  'VOID': { primary: '#000000', secondary: '#4B0082', core: '#FFFFFF', shadow: '#9400D3' }, // Thunder/Thunder
};

const ELEMENT_NAMES_CN: Record<string, string> = {
    'NEUTRAL': '等待施法...',
    'FIRE': '🔥 烈焰术 (FIRE)',
    'WATER': '💧 唤雨术 (WATER)',
    'THUNDER': '⚡ 雷霆术 (THUNDER)',
    'WIND': '🌪️ 疾风术 (WIND)',
    'BLIZZARD': '❄️ 极寒风暴 (BLIZZARD)',
    'PLASMA': '⚛️ 等离子破 (PLASMA)',
    'STEAM': '♨️ 灼热蒸汽 (STEAM)',
    'TEMPEST': '⛈️ 雷暴风眼 (TEMPEST)',
    'INFERNO': '🌋 地狱烈火 (INFERNO)',
    'VOID': '🌌 虚空奇点 (VOID)'
};

const getCombo = (g1: ElementType, g2: ElementType): string | null => {
    const sorted = [g1, g2].sort().join('_');
    switch(sorted) {
        case 'WATER_WIND': return 'BLIZZARD';
        case 'FIRE_WIND': return 'PLASMA';
        case 'FIRE_WATER': return 'STEAM';
        case 'THUNDER_WATER': return 'TEMPEST';
        case 'FIRE_FIRE': return 'INFERNO';
        case 'THUNDER_THUNDER': return 'VOID';
        default: return null;
    }
};

const MagicOverlay: React.FC<MagicOverlayProps> = ({ width, height }) => {
  const webcamRef = useRef<Webcam>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>(0);
  const particlesRef = useRef<Particle[]>([]);
  const handDataRef = useRef<HandData[]>([]);
  const [currentElement, setCurrentElement] = useState<string>('NEUTRAL');
  const [isModelLoaded, setIsModelLoaded] = useState(false);
  const [debugInfo, setDebugInfo] = useState<string>("初始化系统...");
  const [hasStarted, setHasStarted] = useState(false);

  // Visual Feedback State
  const highlightRef = useRef<number>(0);
  const prevElementRef = useRef<string>('NEUTRAL');
  const activeComboRef = useRef<string | null>(null);

  // Audio Context
  const audioContextRef = useRef<AudioContext | null>(null);
  const noiseBufferRef = useRef<AudioBuffer | null>(null);

  useEffect(() => {
    const AudioContextClass = (window as any).AudioContext || (window as any).webkitAudioContext;
    if (AudioContextClass) {
        const ctx = new AudioContextClass();
        audioContextRef.current = ctx;

        // Generate White Noise Buffer for procedural effects
        const bufferSize = ctx.sampleRate * 2; // 2 seconds
        const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
        const data = buffer.getChannelData(0);
        for (let i = 0; i < bufferSize; i++) {
            data[i] = Math.random() * 2 - 1;
        }
        noiseBufferRef.current = buffer;
    }
  }, []);

  const startExperience = () => {
      setHasStarted(true);
      if (audioContextRef.current?.state === 'suspended') {
          audioContextRef.current.resume();
      }
  };

  const playChime = useCallback((element: string) => {
    const ctx = audioContextRef.current;
    if (!ctx) return;
    if (ctx.state === 'suspended') {
        ctx.resume().catch(console.error);
    }

    // Fallback if noise buffer isn't ready
    if (!noiseBufferRef.current) return;

    const now = ctx.currentTime;
    const masterGain = ctx.createGain();
    masterGain.connect(ctx.destination);
    masterGain.gain.setValueAtTime(0.3, now); // Master Volume

    // Helper: Play Noise
    const playNoise = (filterType: BiquadFilterType, freqStart: number, freqEnd: number, duration: number, vol: number = 1, delay: number = 0) => {
        const src = ctx.createBufferSource();
        src.buffer = noiseBufferRef.current;
        src.loop = true;

        const filter = ctx.createBiquadFilter();
        filter.type = filterType;
        filter.frequency.setValueAtTime(freqStart, now + delay);
        filter.frequency.exponentialRampToValueAtTime(freqEnd, now + delay + duration);
        filter.Q.value = 1;

        const amp = ctx.createGain();
        amp.gain.setValueAtTime(0, now + delay);
        amp.gain.linearRampToValueAtTime(vol, now + delay + 0.05); // Attack
        amp.gain.exponentialRampToValueAtTime(0.01, now + delay + duration); // Decay

        src.connect(filter);
        filter.connect(amp);
        amp.connect(masterGain);

        src.start(now + delay);
        src.stop(now + delay + duration + 0.2);
    };

    // Helper: Play Tone
    const playTone = (type: OscillatorType, freqStart: number, freqEnd: number, duration: number, vol: number = 1, delay: number = 0) => {
        const osc = ctx.createOscillator();
        osc.type = type;
        osc.frequency.setValueAtTime(freqStart, now + delay);
        if (freqStart !== freqEnd) {
             osc.frequency.exponentialRampToValueAtTime(freqEnd, now + delay + duration);
        }

        const amp = ctx.createGain();
        amp.gain.setValueAtTime(0, now + delay);
        amp.gain.linearRampToValueAtTime(vol, now + delay + 0.05);
        amp.gain.exponentialRampToValueAtTime(0.01, now + delay + duration);

        osc.connect(amp);
        amp.connect(masterGain);

        osc.start(now + delay);
        osc.stop(now + delay + duration + 0.2);
    };

    switch (element) {
        case 'FIRE':
            playNoise('lowpass', 500, 100, 1.0, 0.5);
            playTone('sawtooth', 80, 120, 0.8, 0.2); 
            break;

        case 'WATER':
            playNoise('bandpass', 800, 300, 0.6, 0.4);
            playTone('sine', 600, 300, 0.4, 0.3, 0.1); 
            break;

        case 'WIND':
            playNoise('lowpass', 200, 800, 0.4, 0.3);
            playNoise('highpass', 400, 1000, 0.5, 0.2, 0.1);
            break;

        case 'THUNDER':
            playTone('sawtooth', 800, 50, 0.3, 0.2);
            playNoise('lowpass', 1000, 50, 1.2, 0.6, 0.1); 
            break;

        case 'BLIZZARD': 
            playNoise('highpass', 1000, 3000, 1.5, 0.4);
            playTone('sine', 1500, 2000, 0.3, 0.1, 0.1);
            break;

        case 'INFERNO':
            playNoise('lowpass', 800, 50, 1.5, 0.8);
            playTone('square', 60, 40, 1.5, 0.2);
            break;

        case 'TEMPEST': 
            playNoise('lowpass', 200, 50, 2.0, 0.8);
            playTone('sawtooth', 1200, 100, 0.5, 0.2, 0.1);
            playNoise('bandpass', 1000, 500, 1.0, 0.3);
            break;

        case 'VOID':
            playTone('sine', 50, 40, 2.5, 0.6);
            playNoise('bandpass', 100, 200, 2.5, 0.4);
            playTone('sine', 300, 290, 1.0, 0.1, 0.5);
            break;

        case 'PLASMA':
            playTone('sawtooth', 200, 800, 1.0, 0.2);
            playNoise('bandpass', 400, 1200, 1.0, 0.4);
            break;

        case 'STEAM':
            playNoise('highpass', 500, 1000, 1.0, 0.3);
            break;

        default:
            playTone('triangle', 440, 880, 0.3, 0.1);
    }
  }, []);

  const detectGesture = (landmarks: any[], videoWidth: number, videoHeight: number): ElementType => {
    const mapPt = (idx: number) => ({ x: (1 - landmarks[idx].x) * videoWidth, y: landmarks[idx].y * videoHeight });
    const wrist = mapPt(0);
    const indexTip = mapPt(8);
    const middleTip = mapPt(12);
    const ringTip = mapPt(16);
    const pinkyTip = mapPt(20);
    const indexMCP = mapPt(5);
    const middleMCP = mapPt(9);
    const ringMCP = mapPt(13); 
    const pinkyMCP = mapPt(17);

    const dist = (p1: any, p2: any) => Math.hypot(p1.x - p2.x, p1.y - p2.y);
    // Robust Open Detection: Tip is farther from wrist than knuckle is
    const isFingerOpen = (tip: any, mcp: any) => dist(tip, wrist) > dist(mcp, wrist) * 1.1;

    // Orientation: If Wrist Y < Middle MCP Y (Screen coordinates), wrist is higher than knuckles => Hand pointing DOWN
    // Note: Canvas Y increases downwards. Top is 0. 
    // Pointing Down: Wrist (Y=100) < Knuckles (Y=200). 
    const isPointingDown = wrist.y < middleMCP.y;

    if (isPointingDown) {
        return 'WATER';
    } 

    // Count open fingers for upward gestures
    let openCount = 0;
    if (isFingerOpen(indexTip, indexMCP)) openCount++;
    if (isFingerOpen(middleTip, middleMCP)) openCount++;
    if (isFingerOpen(ringTip, ringMCP)) openCount++;
    if (isFingerOpen(pinkyTip, pinkyMCP)) openCount++;

    if (openCount >= 4) return 'FIRE'; // Open Palm
    if (openCount >= 2) return 'WIND'; // Victory or 3 fingers

    // 0 or 1 finger open usually means fist or pointing (lightning)
    return 'THUNDER';
  };

  const drawSkeleton = (ctx: CanvasRenderingContext2D, hand: HandData) => {
      ctx.strokeStyle = "rgba(255, 255, 255, 0.2)";
      ctx.lineWidth = 1;
      ctx.fillStyle = "rgba(255, 255, 255, 0.4)";
      const points = [hand.wrist, hand.indexBase, hand.indexTip, hand.middleBase, hand.middleTip, hand.ringBase, hand.ringTip, hand.pinkyBase, hand.pinkyTip, hand.thumbTip];

      const drawLine = (p1: any, p2: any) => { ctx.beginPath(); ctx.moveTo(p1.x, p1.y); ctx.lineTo(p2.x, p2.y); ctx.stroke(); }
      drawLine(hand.wrist, hand.indexBase); drawLine(hand.indexBase, hand.indexTip);
      drawLine(hand.wrist, hand.middleBase); drawLine(hand.middleBase, hand.middleTip);
      drawLine(hand.wrist, hand.pinkyBase); drawLine(hand.pinkyBase, hand.pinkyTip);

      points.forEach(p => { ctx.beginPath(); ctx.arc(p.x, p.y, 2, 0, Math.PI * 2); ctx.fill(); });
  };

  const onResults = useCallback((results: any) => {
    // Robust video dimension check
    let videoWidth = width;
    let videoHeight = height;
    if (webcamRef.current?.video?.videoWidth) {
        videoWidth = webcamRef.current.video.videoWidth;
        videoHeight = webcamRef.current.video.videoHeight;
    }

    if (results.multiHandLandmarks && results.multiHandLandmarks.length > 0) {
      setDebugInfo(`⚡ 系统就绪 | 检测到 ${results.multiHandLandmarks.length} 只手`);
      const newHandData: HandData[] = results.multiHandLandmarks.map((landmarks: any[]) => {
        const gesture = detectGesture(landmarks, videoWidth, videoHeight);
        const mapPt = (idx: number) => ({ x: (1 - landmarks[idx].x) * videoWidth, y: landmarks[idx].y * videoHeight });
        return {
          wrist: mapPt(0), indexTip: mapPt(8), middleTip: mapPt(12), ringTip: mapPt(16), pinkyTip: mapPt(20), thumbTip: mapPt(4),
          indexBase: mapPt(5), middleBase: mapPt(9), ringBase: mapPt(13), pinkyBase: mapPt(17),
          isOpen: gesture !== 'THUNDER', gesture, opacity: 1,
        };
      });

      handDataRef.current = newHandData;
      let newElement = 'NEUTRAL';
      let activeCombo = null;

      if (newHandData.length === 2) {
          const g1 = newHandData[0].gesture;
          const g2 = newHandData[1].gesture;
          if (g1 !== 'NEUTRAL' && g2 !== 'NEUTRAL') activeCombo = getCombo(g1, g2);
      }

      if (activeCombo) newElement = activeCombo;
      else {
          const activeHand = newHandData.find(h => h.gesture !== 'NEUTRAL');
          if (activeHand) newElement = activeHand.gesture;
      }
      activeComboRef.current = activeCombo;

      if (newElement !== prevElementRef.current) {
          if (newElement !== 'NEUTRAL') { highlightRef.current = 1.0; playChime(newElement); }
          prevElementRef.current = newElement;
      }
      setCurrentElement(newElement);
    } else {
      handDataRef.current = [];
      setDebugInfo("🔍 正在搜索手部信号...");
      activeComboRef.current = null;
      if (prevElementRef.current !== 'NEUTRAL') { prevElementRef.current = 'NEUTRAL'; setCurrentElement('NEUTRAL'); }
    }
  }, [width, height, playChime]);

  useEffect(() => {
    let hands: any = null;
    let isActive = true;
    let frameId: number;
    let lastVideoTime = -1;

    const initHands = async () => {
       if (!(window as any).Hands) { setTimeout(initHands, 500); return; }

       // CRITICAL: Explicitly use the version matching the script tag in index.html
       // This prevents version mismatches for the WASM/binary assets
       hands = new (window as any).Hands({ 
           locateFile: (file: string) => `https://cdn.jsdelivr.net/npm/@mediapipe/hands@0.4.1675469240/${file}` 
       });

       hands.setOptions({ 
           maxNumHands: 2, 
           modelComplexity: 1, 
           minDetectionConfidence: 0.5, 
           minTrackingConfidence: 0.5 
       });
       hands.onResults(onResults);

       setIsModelLoaded(true);

       const processVideo = async () => {
         if (!isActive) return;
         if (webcamRef.current && webcamRef.current.video && webcamRef.current.video.readyState === 4) {
             const video = webcamRef.current.video;
             // STRICT CHECK: Ensure video has dimensions to prevent 'buffer' read error
             if (video.videoWidth > 0 && video.videoHeight > 0) {
                 if (video.currentTime !== lastVideoTime) {
                     lastVideoTime = video.currentTime;
                     try { await hands.send({ image: video }); } catch (e) { 
                         console.error("MediaPipe processing error:", e); 
                         setDebugInfo("MediaPipe 错误: 刷新页面重试");
                     }
                 }
             }
         }
         frameId = requestAnimationFrame(processVideo);
       };
       processVideo();
    };
    initHands();
    return () => { isActive = false; if (frameId) cancelAnimationFrame(frameId); if (hands) hands.close(); };
  }, [onResults]);

  // --- PHYSICS ENGINE ---
  const updateParticles = (ctx: CanvasRenderingContext2D, width: number, height: number, centerX: number, centerY: number) => {
    for (let i = particlesRef.current.length - 1; i >= 0; i--) {
      const p = particlesRef.current[i];
      p.vx *= 0.95;
      p.vy *= 0.95;

      switch (p.element) {
          case 'WIND':
          case 'BLIZZARD':
              const dx = p.x - centerX;
              const dy = p.y - centerY;
              const dist = Math.sqrt(dx*dx + dy*dy) + 1;
              const angle = Math.atan2(dy, dx);
              p.vx += Math.cos(angle + Math.PI/2) * 1.5;
              p.vy += Math.sin(angle + Math.PI/2) * 1.5;
              p.vx -= (dx / dist) * 0.5;
              p.vy -= (dy / dist) * 0.5;
              p.angle += p.angularVelocity; 
              break;

          case 'WATER':
          case 'STEAM':
              p.vy += 1.2; 
              p.x += Math.sin(p.life * 0.1) * 0.5;
              break;

          case 'THUNDER':
          case 'TEMPEST':
          case 'VOID':
              p.vx += (Math.random() - 0.5) * 4;
              p.vy += (Math.random() - 0.5) * 4;
              if (Math.random() < 0.1) {
                  p.x += (Math.random() - 0.5) * 20;
                  p.y += (Math.random() - 0.5) * 20;
              }
              break;

          case 'FIRE':
          case 'INFERNO':
              p.vy -= 0.6; 
              p.vx += (Math.random() - 0.5) * 1.5;
              p.size *= 0.96; 
              break;

          default:
              p.vy -= 0.1;
      }

      p.x += p.vx;
      p.y += p.vy;
      p.life -= 1;
      if (p.element !== 'FIRE') p.size *= 0.98;

      if (p.life <= 0 || p.size < 0.2 || p.y > height + 50) {
        particlesRef.current.splice(i, 1);
      } else {
        ctx.save();
        ctx.globalAlpha = Math.min(1, p.life / 20, (p.maxLife - p.life) / 10);

        if (p.type === 'LEAF') {
            ctx.translate(p.x, p.y);
            ctx.rotate(p.angle);
            ctx.fillStyle = p.color;
            ctx.beginPath();
            ctx.ellipse(0, 0, p.size, p.size * 0.4, 0, 0, Math.PI * 2);
            ctx.fill();
        } 
        else if (p.type === 'DROP') {
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 2;
            ctx.lineCap = 'round';
            ctx.beginPath();
            ctx.moveTo(p.x, p.y);
            ctx.lineTo(p.x - p.vx, p.y - p.vy * 3); 
            ctx.stroke();
        }
        else if (p.type === 'SPARK') {
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 2;
            ctx.shadowColor = p.color;
            ctx.shadowBlur = 10;
            ctx.beginPath();
            ctx.moveTo(p.x - p.vx, p.y - p.vy);
            ctx.lineTo(p.x + p.vx, p.y + p.vy);
            ctx.stroke();
            if (Math.random() > 0.5) {
                ctx.beginPath();
                ctx.moveTo(p.x, p.y);
                ctx.lineTo(p.x + (Math.random()-0.5)*20, p.y + (Math.random()-0.5)*20);
                ctx.stroke();
            }
        }
        else if (p.type === 'EMBER') {
            ctx.fillStyle = p.color;
            ctx.shadowColor = 'orange';
            ctx.shadowBlur = 15;
            ctx.beginPath();
            ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
            ctx.fill();
        }
        else {
            ctx.fillStyle = p.color;
            ctx.shadowColor = p.color;
            ctx.shadowBlur = p.type === 'ORB' ? 10 : 0;
            ctx.beginPath();
            ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
            ctx.fill();
        }
        ctx.restore();
      }
    }
  };

  const spawnParticles = (x: number, y: number, element: string, theme: Theme) => {
    const isCombo = activeComboRef.current !== null;
    let count = isCombo ? 12 : 3;

    let type: ParticleType = 'ORB';
    let speed = Math.random() * 5;
    let spread = 20;

    if (element === 'WIND' || element === 'BLIZZARD') {
        type = Math.random() > 0.5 ? 'LEAF' : 'MIST';
        count = isCombo ? 15 : 4;
    } else if (element === 'WATER' || element === 'STEAM') {
        type = Math.random() > 0.7 ? 'MIST' : 'DROP';
        count = isCombo ? 20 : 5;
        spread = 40; 
    } else if (element === 'THUNDER' || element === 'TEMPEST' || element === 'VOID') {
        type = 'SPARK';
        count = isCombo ? 6 : 2; 
        speed = 8;
    } else if (element === 'FIRE' || element === 'INFERNO') {
        type = Math.random() > 0.8 ? 'MIST' : 'EMBER';
        count = isCombo ? 12 : 4;
    }

    for (let i = 0; i < count; i++) {
      const angle = Math.random() * Math.PI * 2;
      let vx = Math.cos(angle) * speed;
      let vy = Math.sin(angle) * speed;

      if (element === 'WATER' || element === 'STEAM') { vx *= 0.2; vy = Math.random() * 2; } 

      let color = Math.random() > 0.5 ? theme.primary : theme.secondary;
      if (element === 'WIND') color = Math.random() > 0.5 ? '#00FFFF' : '#F0FFF0'; 
      if (element === 'THUNDER') color = Math.random() > 0.5 ? '#FFFF00' : '#9400D3';

      let spawnX = x;
      let spawnY = y;

      if (isCombo || element === 'WATER') {
          spawnX = Math.random() * width;
          if (element === 'WATER' || element === 'TEMPEST') {
             spawnY = Math.random() * -100;
          } else {
             spawnY = Math.random() * height;
          }
      } else {
          spawnX = x + (Math.random() - 0.5) * spread;
          spawnY = y + (Math.random() - 0.5) * spread;
      }

      particlesRef.current.push({
        x: spawnX,
        y: spawnY,
        vx, vy,
        life: 40 + Math.random() * 40,
        maxLife: 80,
        size: 3 + Math.random() * 5,
        color,
        element: element as Particle['element'],
        type,
        angle: Math.random() * Math.PI * 2,
        angularVelocity: (Math.random() - 0.5) * 0.2
      });
    }
  };

  const animate = useCallback((time: number) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (highlightRef.current > 0.01) highlightRef.current *= 0.9;
    else highlightRef.current = 0;
    const flash = highlightRef.current;

    ctx.globalCompositeOperation = 'lighter'; 

    let lastCenterX = width / 2;
    let lastCenterY = height / 2;
    const t = time * 0.001;

    const comboName = activeComboRef.current;

    if (comboName && handDataRef.current.length === 2) {
        // --- COMBO MODE ---
        const h1 = handDataRef.current[0];
        const h2 = handDataRef.current[1];
        const theme = COMBO_THEMES[comboName];

        const midX = (h1.middleBase.x + h2.middleBase.x) / 2;
        const midY = (h1.middleBase.y + h2.middleBase.y) / 2;
        lastCenterX = midX;
        lastCenterY = midY;

        ctx.save();
        ctx.beginPath();
        ctx.moveTo(h1.middleBase.x, h1.middleBase.y);
        ctx.lineTo(h2.middleBase.x, h2.middleBase.y);
        ctx.strokeStyle = theme.primary;
        ctx.lineWidth = 20 + Math.sin(t * 10) * 5; 
        ctx.lineCap = 'round';
        ctx.shadowBlur = 40;
        ctx.shadowColor = theme.secondary;
        ctx.globalAlpha = 0.4;
        ctx.stroke();
        ctx.restore();

        ctx.save();
        ctx.beginPath();
        ctx.moveTo(h1.middleBase.x, h1.middleBase.y);
        ctx.lineTo(h2.middleBase.x, h2.middleBase.y);
        ctx.strokeStyle = '#FFFFFF';
        ctx.lineWidth = 3;
        ctx.setLineDash([10, 40]);
        ctx.lineDashOffset = -t * 200; 
        ctx.globalCompositeOperation = 'overlay';
        ctx.stroke();
        ctx.restore();

        ctx.save();
        ctx.beginPath();
        ctx.moveTo(h1.middleBase.x, h1.middleBase.y);
        const dist = Math.hypot(h2.middleBase.x - h1.middleBase.x, h2.middleBase.y - h1.middleBase.y);
        const angle = Math.atan2(h2.middleBase.y - h1.middleBase.y, h2.middleBase.x - h1.middleBase.x);
        for(let i=0; i<=20; i++) {
             const p = i/20;
             const perp = Math.sin(p * Math.PI * 4 + t * 20) * (15 + Math.random() * 5);
             const bx = h1.middleBase.x + (h2.middleBase.x - h1.middleBase.x) * p + Math.cos(angle + Math.PI/2)*perp;
             const by = h1.middleBase.y + (h2.middleBase.y - h1.middleBase.y) * p + Math.sin(angle + Math.PI/2)*perp;
             ctx.lineTo(bx, by);
        }
        ctx.strokeStyle = theme.secondary;
        ctx.lineWidth = 2;
        ctx.shadowBlur = 10;
        ctx.shadowColor = theme.core;
        ctx.stroke();
        ctx.restore();

        ctx.globalAlpha = 1;
        drawRuneRing(ctx, midX, midY, 180, t, theme);
        drawSacredGeometry(ctx, midX, midY, 140, -t * 2, theme);
        drawSquareLayer(ctx, midX, midY, 100, t * 3, theme);
        drawPentagram(ctx, midX, midY, 60, -t, 1, theme);

        spawnParticles(midX, midY, comboName, theme);

        handDataRef.current.forEach(h => {
             drawSkeleton(ctx, h);
             const auraSize = 50 + Math.sin(t * 20) * 10;
             const grad = ctx.createRadialGradient(h.middleBase.x, h.middleBase.y, 10, h.middleBase.x, h.middleBase.y, auraSize);
             grad.addColorStop(0, theme.core);
             grad.addColorStop(0.4, theme.primary);
             grad.addColorStop(1, 'rgba(0,0,0,0)');
             ctx.save();
             ctx.fillStyle = grad;
             ctx.globalAlpha = 0.5;
             ctx.beginPath();
             ctx.arc(h.middleBase.x, h.middleBase.y, auraSize, 0, Math.PI * 2);
             ctx.fill();
             ctx.restore();
             drawRuneRing(ctx, h.middleBase.x, h.middleBase.y, 40, t*5, theme);
        });

    } else {
        // --- INDIVIDUAL MODE ---
        handDataRef.current.forEach((hand) => {
           drawSkeleton(ctx, hand);
           const element = hand.gesture;
           const theme = (element !== 'NEUTRAL' && THEMES[element]) ? THEMES[element] : THEMES['NEUTRAL'];
           const centerX = hand.middleBase.x; 
           const centerY = hand.middleBase.y; 

           if (element !== 'NEUTRAL') {
               if (flash > 0.05 && highlightRef.current > 0.05) {
                   ctx.save();
                   ctx.translate(centerX, centerY);
                   const waveSize = 120 + (1 - flash) * 100;
                   ctx.beginPath();
                   ctx.arc(0, 0, waveSize, 0, Math.PI * 2);
                   ctx.lineWidth = 10 * flash;
                   ctx.strokeStyle = theme.core;
                   ctx.shadowBlur = 20;
                   ctx.shadowColor = theme.secondary;
                   ctx.globalAlpha = flash;
                   ctx.stroke();
                   ctx.restore();
               }

               drawRuneRing(ctx, centerX, centerY, 120, t * 0.5, theme);
               drawSacredGeometry(ctx, centerX, centerY, 90, -t * 1.5, theme);
               drawSquareLayer(ctx, centerX, centerY, 65, t * 2.5, theme);
               const pulse = Math.sin(time * 0.005) * 0.5 + 0.5;
               drawPentagram(ctx, centerX, centerY, 40, t, pulse, theme);

               spawnParticles(centerX, centerY, element, theme);
               lastCenterX = centerX;
               lastCenterY = centerY;
           } else {
               ctx.globalAlpha = 0.3;
               drawRuneRing(ctx, centerX, centerY, 50, t * 0.2, theme);
           }
        });
    }

    updateParticles(ctx, canvas.width, canvas.height, lastCenterX, lastCenterY);
    requestRef.current = requestAnimationFrame(animate);
  }, [width, height]);

  useEffect(() => {
    requestRef.current = requestAnimationFrame(animate);
    return () => { if (requestRef.current) cancelAnimationFrame(requestRef.current); };
  }, [animate]);

  return (
    <div className="relative w-full h-full bg-black overflow-hidden flex items-center justify-center font-sans">
        <Webcam ref={webcamRef} audio={false} width={width} height={height} mirrored={true} screenshotFormat="image/jpeg" className="absolute opacity-0 pointer-events-none" />
        <Webcam audio={false} width={width} height={height} mirrored={true} className="absolute top-0 left-0 w-full h-full object-cover opacity-80" />
        <canvas ref={canvasRef} width={width} height={height} className="absolute top-0 left-0 w-full h-full object-cover z-10" />

        {!isModelLoaded && (
            <div className="absolute inset-0 flex items-center justify-center bg-black bg-opacity-90 z-50">
                <div className="flex flex-col items-center">
                    <div className="text-amber-500 font-mono text-xl animate-pulse tracking-widest mb-4">🔮 正在校准魔法维度...</div>
                    <div className="w-64 h-1 bg-gray-800 rounded-full overflow-hidden">
                        <div className="h-full bg-amber-500 animate-[width_1s_ease-in-out_infinite]" style={{width: '50%'}}></div>
                    </div>
                </div>
            </div>
        )}

        {!hasStarted && isModelLoaded && (
            <div className="absolute inset-0 flex items-center justify-center bg-black/60 z-50 cursor-pointer backdrop-blur-sm" onClick={startExperience}>
                <div className="border border-amber-500/50 bg-black/80 p-8 rounded-lg text-center shadow-[0_0_30px_rgba(255,160,20,0.3)] hover:scale-105 transition-transform duration-300">
                    <h2 className="text-3xl font-bold text-amber-500 mb-2">准备就绪</h2>
                    <p className="text-white/80 mb-6">点击屏幕开启秘术工坊</p>
                    <button className="px-6 py-2 bg-amber-600 hover:bg-amber-500 text-black font-bold rounded">进入</button>
                </div>
            </div>
        )}

        {/* Dynamic Spell Name - Center Top/Middle */}
        <div className="absolute top-20 left-0 w-full flex justify-center z-20 pointer-events-none">
             <div className={`text-4xl md:text-5xl font-bold tracking-widest transition-all duration-300 drop-shadow-[0_0_15px_rgba(255,255,255,0.4)] px-8 py-2 rounded-full ${highlightRef.current > 0.1 ? 'scale-110 bg-black/20 backdrop-blur-sm' : ''} ${
                currentElement === 'FIRE' ? 'text-orange-500' :
                currentElement === 'WATER' ? 'text-blue-500' :
                currentElement === 'WIND' ? 'text-cyan-300' :
                currentElement === 'THUNDER' ? 'text-purple-500' : 
                currentElement === 'INFERNO' ? 'text-red-600' :
                currentElement === 'BLIZZARD' ? 'text-cyan-100' :
                currentElement === 'VOID' ? 'text-violet-400' : 'text-amber-400'
            }`}>
                {ELEMENT_NAMES_CN[currentElement]}
            </div>
        </div>

        {/* Debug Info */}
        <div className="absolute top-4 right-4 z-20 text-right opacity-50 pointer-events-none">
             <div className="text-xs text-amber-200 font-mono">{debugInfo}</div>
        </div>

        {/* Gesture Guide - Bottom */}
        <div className="absolute bottom-0 left-0 w-full p-6 z-20">
            <div className="max-w-4xl mx-auto bg-black/40 backdrop-blur-md border border-white/10 rounded-2xl p-4 shadow-2xl">
                <div className="flex flex-wrap justify-center items-center gap-4 md:gap-8 text-white/90 text-sm font-medium">
                    <div className="flex items-center gap-3 bg-white/5 px-4 py-2 rounded-lg border border-white/5">
                        <span className="text-2xl">✋</span> 
                        <div className="flex flex-col leading-tight">
                            <span className="text-orange-400 font-bold">火焰</span>
                            <span className="text-[10px] text-gray-400">五指张开</span>
                        </div>
                    </div>
                    <div className="flex items-center gap-3 bg-white/5 px-4 py-2 rounded-lg border border-white/5">
                        <span className="text-2xl">👇</span>
                        <div className="flex flex-col leading-tight">
                            <span className="text-blue-400 font-bold">流水</span>
                            <span className="text-[10px] text-gray-400">掌心向下</span>
                        </div>
                    </div>
                    <div className="flex items-center gap-3 bg-white/5 px-4 py-2 rounded-lg border border-white/5">
                        <span className="text-2xl">👊</span>
                        <div className="flex flex-col leading-tight">
                            <span className="text-purple-400 font-bold">雷霆</span>
                            <span className="text-[10px] text-gray-400">握紧拳头</span>
                        </div>
                    </div>
                    <div className="flex items-center gap-3 bg-white/5 px-4 py-2 rounded-lg border border-white/5">
                        <span className="text-2xl">✌️</span>
                        <div className="flex flex-col leading-tight">
                            <span className="text-teal-300 font-bold">疾风</span>
                            <span className="text-[10px] text-gray-400">食指中指 (剪刀手)</span>
                        </div>
                    </div>
                </div>
                <div className="text-center mt-3 text-xs text-amber-500/60 tracking-wider uppercase font-mono">
                    ✦ 双手结印触发高阶法术 ✦
                </div>
            </div>
        </div>
    </div>
  );
};

export default MagicOverlay;

export type ElementType = 'NEUTRAL' | 'FIRE' | 'WATER' | 'THUNDER' | 'WIND';
export type ComboType = 'BLIZZARD' | 'PLASMA' | 'STEAM' | 'TEMPEST' | 'INFERNO' | 'VOID';
export type ParticleType = 'ORB' | 'LEAF' | 'SPARK' | 'DROP' | 'MIST' | 'EMBER';

export interface Point {
  x: number;
  y: number;
  z?: number;
}

export interface Particle {
  x: number;
  y: number;
  vx: number;
  vy: number;
  life: number;
  maxLife: number;
  size: number;
  color: string;
  element: ElementType | ComboType;
  type: ParticleType;
  angle: number;           // For rotation (leaves)
  angularVelocity: number; // For rotation speed
}

export interface HandData {
  wrist: Point;
  indexTip: Point;
  middleTip: Point;
  ringTip: Point;
  pinkyTip: Point;
  thumbTip: Point;
  indexBase: Point; 
  middleBase: Point;
  ringBase: Point;
  pinkyBase: Point;
  isOpen: boolean;
  gesture: ElementType;
  opacity: number;
}

export interface Theme {
  primary: string;
  secondary: string;
  core: string;
  shadow: string;
  background: string; // New field for solid background color
}

import { Point, ElementType, Theme } from '../types';

// Element Themes
export const THEMES: Record<ElementType, Theme> = {
  NEUTRAL: { primary: '#FFA014', secondary: '#FFC832', core: '#FFFFFF', shadow: '#FFA014', background: '#121212' }, // Dark Grey
  FIRE: { primary: '#FF4500', secondary: '#FF8C00', core: '#FFFF00', shadow: '#FF0000', background: '#220a05' }, // Deep Red/Brown
  WATER: { primary: '#1E90FF', secondary: '#00BFFF', core: '#E0FFFF', shadow: '#0000FF', background: '#051022' }, // Deep Navy
  THUNDER: { primary: '#9400D3', secondary: '#FF00FF', core: '#FFFFE0', shadow: '#4B0082', background: '#150522' }, // Deep Purple
  WIND: { primary: '#00FA9A', secondary: '#98FB98', core: '#F0FFF0', shadow: '#006400', background: '#051812' }, // Deep Green
};

// Layer 1: Runes Ring
export const drawRuneRing = (
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  radius: number,
  rotation: number,
  theme: Theme
) => {
  const segments = 24;
  ctx.strokeStyle = theme.primary;
  ctx.lineWidth = 2;

  // Outer circle
  ctx.beginPath();
  ctx.arc(x, y, radius, 0, Math.PI * 2);
  ctx.stroke();

  // Inner border for runes
  ctx.beginPath();
  ctx.arc(x, y, radius * 0.85, 0, Math.PI * 2);
  ctx.stroke();

  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(rotation);

  for (let i = 0; i < segments; i++) {
    const angle = (Math.PI * 2) / segments;
    ctx.save();
    ctx.rotate(i * angle);
    ctx.translate(radius * 0.925, 0); 

    // Procedural Rune Glyph
    const seed = i * 13.37;
    const size = radius * 0.05;

    ctx.beginPath();
    ctx.moveTo(-size, -size + Math.sin(seed) * size);
    ctx.lineTo(size, size - Math.cos(seed) * size);
    ctx.moveTo(-size, size);
    ctx.lineTo(size + Math.sin(seed * 2) * 5, -size);
    if (i % 3 === 0) ctx.rect(-size / 2, -size / 2, size, size);

    ctx.strokeStyle = theme.secondary;
    ctx.lineWidth = 1.5;
    ctx.stroke();

    ctx.restore();
  }
  ctx.restore();
};

// Layer 2: Sacred Geometry (Hexagram/Triangle)
export const drawSacredGeometry = (
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  radius: number,
  rotation: number,
  theme: Theme
) => {
  ctx.strokeStyle = theme.primary;
  ctx.lineWidth = 3;
  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(rotation);

  // Triangle 1
  ctx.beginPath();
  for (let i = 0; i < 3; i++) {
    const theta = (i * 2 * Math.PI) / 3;
    const px = radius * Math.cos(theta);
    const py = radius * Math.sin(theta);
    if (i === 0) ctx.moveTo(px, py);
    else ctx.lineTo(px, py);
  }
  ctx.closePath();
  ctx.stroke();

  // Triangle 2 (Inverted)
  ctx.beginPath();
  for (let i = 0; i < 3; i++) {
    const theta = (i * 2 * Math.PI) / 3 + Math.PI; 
    const px = radius * Math.cos(theta);
    const py = radius * Math.sin(theta);
    if (i === 0) ctx.moveTo(px, py);
    else ctx.lineTo(px, py);
  }
  ctx.closePath();
  ctx.stroke();

  // Inner Circle
  ctx.beginPath();
  ctx.arc(0, 0, radius * 0.5, 0, Math.PI * 2);
  ctx.strokeStyle = theme.secondary;
  ctx.lineWidth = 1;
  ctx.stroke();

  ctx.restore();
};

// Layer 3: Rotating Square (Diamond)
export const drawSquareLayer = (
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  radius: number,
  rotation: number,
  theme: Theme
) => {
  ctx.strokeStyle = theme.secondary;
  ctx.lineWidth = 4;

  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(rotation);

  ctx.beginPath();
  const size = radius;
  ctx.rect(-size / 2, -size / 2, size, size);
  ctx.stroke();

  // Decorative corners
  ctx.fillStyle = theme.core;
  const cornerSize = 4;
  ctx.fillRect(-size / 2 - cornerSize, -size / 2 - cornerSize, cornerSize * 2, cornerSize * 2);
  ctx.fillRect(size / 2 - cornerSize, -size / 2 - cornerSize, cornerSize * 2, cornerSize * 2);
  ctx.fillRect(size / 2 - cornerSize, size / 2 - cornerSize, cornerSize * 2, cornerSize * 2);
  ctx.fillRect(-size / 2 - cornerSize, size / 2 - cornerSize, cornerSize * 2, cornerSize * 2);

  ctx.restore();
};

// Layer 4: Pulsing Pentagram
export const drawPentagram = (
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  radius: number,
  rotation: number,
  pulse: number,
  theme: Theme
) => {
  const r = radius * (0.8 + pulse * 0.2); 
  ctx.strokeStyle = theme.core;
  ctx.lineWidth = 2 + pulse * 2;
  ctx.shadowBlur = 10 + pulse * 10;
  ctx.shadowColor = theme.shadow;

  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(rotation);

  ctx.beginPath();
  for (let i = 0; i < 5; i++) {
    const theta = (i * 4 * Math.PI) / 5 - Math.PI / 2;
    const px = r * Math.cos(theta);
    const py = r * Math.sin(theta);
    if (i === 0) ctx.moveTo(px, py);
    else ctx.lineTo(px, py);
  }
  ctx.closePath();
  ctx.stroke();

  ctx.shadowBlur = 0; 
  ctx.restore();
};

import React, { useEffect, useRef, useCallback, useState } from 'react';
import Webcam from 'react-webcam';
import { Particle, HandData, ElementType, Theme, ParticleType } from '../types';
import { 
  drawRuneRing, 
  drawSacredGeometry, 
  drawSquareLayer, 
  drawPentagram,
  THEMES
} from '../utils/geometry';

interface MagicOverlayProps {
  width: number;
  height: number;
}

const COMBO_THEMES: Record<string, Theme> = {
  'BLIZZARD': { primary: '#00FFFF', secondary: '#E0FFFF', core: '#FFFFFF', shadow: '#008B8B', background: '#0a1a20' }, 
  'PLASMA': { primary: '#FF00FF', secondary: '#00FFFF', core: '#FFFFFF', shadow: '#9400D3', background: '#1a051a' }, 
  'STEAM': { primary: '#F0F8FF', secondary: '#B0C4DE', core: '#FFFFFF', shadow: '#778899', background: '#10151a' }, 
  'TEMPEST': { primary: '#000080', secondary: '#8A2BE2', core: '#FFFF00', shadow: '#191970', background: '#05051a' }, 
  'INFERNO': { primary: '#FF0000', secondary: '#FF4500', core: '#FFFF00', shadow: '#8B0000', background: '#2a0500' }, 
  'VOID': { primary: '#000000', secondary: '#4B0082', core: '#FFFFFF', shadow: '#9400D3', background: '#000000' }, 
};

const ELEMENT_NAMES_CN: Record<string, string> = {
    'NEUTRAL': '等待施法...',
    'FIRE': '🔥 烈焰术 (FIRE)',
    'WATER': '💧 唤雨术 (WATER)',
    'THUNDER': '⚡ 雷霆术 (THUNDER)',
    'WIND': '🌪️ 疾风术 (WIND)',
    'BLIZZARD': '❄️ 极寒风暴 (BLIZZARD)',
    'PLASMA': '⚛️ 等离子破 (PLASMA)',
    'STEAM': '♨️ 灼热蒸汽 (STEAM)',
    'TEMPEST': '⛈️ 雷暴风眼 (TEMPEST)',
    'INFERNO': '🌋 地狱烈火 (INFERNO)',
    'VOID': '🌌 虚空奇点 (VOID)'
};

const getCombo = (g1: ElementType, g2: ElementType): string | null => {
    const sorted = [g1, g2].sort().join('_');
    switch(sorted) {
        case 'WATER_WIND': return 'BLIZZARD';
        case 'FIRE_WIND': return 'PLASMA';
        case 'FIRE_WATER': return 'STEAM';
        case 'THUNDER_WATER': return 'TEMPEST';
        case 'FIRE_FIRE': return 'INFERNO';
        case 'THUNDER_THUNDER': return 'VOID';
        default: return null;
    }
};

const MagicOverlay: React.FC<MagicOverlayProps> = ({ width, height }) => {
  const webcamRef = useRef<Webcam>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>(0);
  const particlesRef = useRef<Particle[]>([]);
  const handDataRef = useRef<HandData[]>([]);
  const [currentElement, setCurrentElement] = useState<string>('NEUTRAL');
  const [isModelLoaded, setIsModelLoaded] = useState(false);
  const [debugInfo, setDebugInfo] = useState<string>("初始化系统...");
  const [hasStarted, setHasStarted] = useState(false);

  // Visual Feedback State
  const highlightRef = useRef<number>(0);
  const prevElementRef = useRef<string>('NEUTRAL');
  const activeComboRef = useRef<string | null>(null);

  // Audio Context
  const audioContextRef = useRef<AudioContext | null>(null);
  const noiseBufferRef = useRef<AudioBuffer | null>(null);

  // Get current Theme for background
  const currentTheme = activeComboRef.current 
    ? COMBO_THEMES[activeComboRef.current] 
    : (THEMES[currentElement as ElementType] || THEMES['NEUTRAL']);

  useEffect(() => {
    const AudioContextClass = (window as any).AudioContext || (window as any).webkitAudioContext;
    if (AudioContextClass) {
        const ctx = new AudioContextClass();
        audioContextRef.current = ctx;

        // Generate White Noise Buffer for procedural effects
        const bufferSize = ctx.sampleRate * 2; // 2 seconds
        const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
        const data = buffer.getChannelData(0);
        for (let i = 0; i < bufferSize; i++) {
            data[i] = Math.random() * 2 - 1;
        }
        noiseBufferRef.current = buffer;
    }
  }, []);

  const startExperience = () => {
      setHasStarted(true);
      if (audioContextRef.current?.state === 'suspended') {
          audioContextRef.current.resume();
      }
  };

  const playChime = useCallback((element: string) => {
    const ctx = audioContextRef.current;
    if (!ctx) return;
    if (ctx.state === 'suspended') {
        ctx.resume().catch(console.error);
    }

    // Fallback if noise buffer isn't ready
    if (!noiseBufferRef.current) return;

    const now = ctx.currentTime;
    const masterGain = ctx.createGain();
    masterGain.connect(ctx.destination);
    masterGain.gain.setValueAtTime(0.3, now); // Master Volume

    // Helper: Play Noise
    const playNoise = (filterType: BiquadFilterType, freqStart: number, freqEnd: number, duration: number, vol: number = 1, delay: number = 0) => {
        const src = ctx.createBufferSource();
        src.buffer = noiseBufferRef.current;
        src.loop = true;

        const filter = ctx.createBiquadFilter();
        filter.type = filterType;
        filter.frequency.setValueAtTime(freqStart, now + delay);
        filter.frequency.exponentialRampToValueAtTime(freqEnd, now + delay + duration);
        filter.Q.value = 1;

        const amp = ctx.createGain();
        amp.gain.setValueAtTime(0, now + delay);
        amp.gain.linearRampToValueAtTime(vol, now + delay + 0.05); // Attack
        amp.gain.exponentialRampToValueAtTime(0.01, now + delay + duration); // Decay

        src.connect(filter);
        filter.connect(amp);
        amp.connect(masterGain);

        src.start(now + delay);
        src.stop(now + delay + duration + 0.2);
    };

    // Helper: Play Tone
    const playTone = (type: OscillatorType, freqStart: number, freqEnd: number, duration: number, vol: number = 1, delay: number = 0) => {
        const osc = ctx.createOscillator();
        osc.type = type;
        osc.frequency.setValueAtTime(freqStart, now + delay);
        if (freqStart !== freqEnd) {
             osc.frequency.exponentialRampToValueAtTime(freqEnd, now + delay + duration);
        }

        const amp = ctx.createGain();
        amp.gain.setValueAtTime(0, now + delay);
        amp.gain.linearRampToValueAtTime(vol, now + delay + 0.05);
        amp.gain.exponentialRampToValueAtTime(0.01, now + delay + duration);

        osc.connect(amp);
        amp.connect(masterGain);

        osc.start(now + delay);
        osc.stop(now + delay + duration + 0.2);
    };

    switch (element) {
        case 'FIRE':
            playNoise('lowpass', 500, 100, 1.0, 0.5);
            playTone('sawtooth', 80, 120, 0.8, 0.2); 
            break;

        case 'WATER':
            playNoise('bandpass', 800, 300, 0.6, 0.4);
            playTone('sine', 600, 300, 0.4, 0.3, 0.1); 
            break;

        case 'WIND':
            playNoise('lowpass', 200, 800, 0.4, 0.3);
            playNoise('highpass', 400, 1000, 0.5, 0.2, 0.1);
            break;

        case 'THUNDER':
            playTone('sawtooth', 800, 50, 0.3, 0.2);
            playNoise('lowpass', 1000, 50, 1.2, 0.6, 0.1); 
            break;

        case 'BLIZZARD': 
            playNoise('highpass', 1000, 3000, 1.5, 0.4);
            playTone('sine', 1500, 2000, 0.3, 0.1, 0.1);
            break;

        case 'INFERNO':
            playNoise('lowpass', 800, 50, 1.5, 0.8);
            playTone('square', 60, 40, 1.5, 0.2);
            break;

        case 'TEMPEST': 
            playNoise('lowpass', 200, 50, 2.0, 0.8);
            playTone('sawtooth', 1200, 100, 0.5, 0.2, 0.1);
            playNoise('bandpass', 1000, 500, 1.0, 0.3);
            break;

        case 'VOID':
            playTone('sine', 50, 40, 2.5, 0.6);
            playNoise('bandpass', 100, 200, 2.5, 0.4);
            playTone('sine', 300, 290, 1.0, 0.1, 0.5);
            break;

        case 'PLASMA':
            playTone('sawtooth', 200, 800, 1.0, 0.2);
            playNoise('bandpass', 400, 1200, 1.0, 0.4);
            break;

        case 'STEAM':
            playNoise('highpass', 500, 1000, 1.0, 0.3);
            break;

        default:
            playTone('triangle', 440, 880, 0.3, 0.1);
    }
  }, []);

  const detectGesture = (landmarks: any[], videoWidth: number, videoHeight: number): ElementType => {
    const mapPt = (idx: number) => ({ x: (1 - landmarks[idx].x) * videoWidth, y: landmarks[idx].y * videoHeight });
    const wrist = mapPt(0);
    const indexTip = mapPt(8);
    const middleTip = mapPt(12);
    const ringTip = mapPt(16);
    const pinkyTip = mapPt(20);
    const indexMCP = mapPt(5);
    const middleMCP = mapPt(9);
    const ringMCP = mapPt(13); 
    const pinkyMCP = mapPt(17);

    const dist = (p1: any, p2: any) => Math.hypot(p1.x - p2.x, p1.y - p2.y);
    const isFingerOpen = (tip: any, mcp: any) => dist(tip, wrist) > dist(mcp, wrist) * 1.1;

    // Orientation: If Wrist Y < Middle MCP Y (Screen coordinates), wrist is higher than knuckles => Hand pointing DOWN
    const isPointingDown = wrist.y < middleMCP.y;

    if (isPointingDown) {
        return 'WATER';
    } 

    let openCount = 0;
    if (isFingerOpen(indexTip, indexMCP)) openCount++;
    if (isFingerOpen(middleTip, middleMCP)) openCount++;
    if (isFingerOpen(ringTip, ringMCP)) openCount++;
    if (isFingerOpen(pinkyTip, pinkyMCP)) openCount++;

    if (openCount >= 4) return 'FIRE'; // Open Palm
    if (openCount >= 2) return 'WIND'; // Victory or 3 fingers

    return 'THUNDER';
  };

  const drawSkeleton = (ctx: CanvasRenderingContext2D, hand: HandData) => {
      ctx.strokeStyle = "rgba(255, 255, 255, 0.1)";
      ctx.lineWidth = 1;
      ctx.fillStyle = "rgba(255, 255, 255, 0.3)";
      const points = [hand.wrist, hand.indexBase, hand.indexTip, hand.middleBase, hand.middleTip, hand.ringBase, hand.ringTip, hand.pinkyBase, hand.pinkyTip, hand.thumbTip];

      const drawLine = (p1: any, p2: any) => { ctx.beginPath(); ctx.moveTo(p1.x, p1.y); ctx.lineTo(p2.x, p2.y); ctx.stroke(); }
      drawLine(hand.wrist, hand.indexBase); drawLine(hand.indexBase, hand.indexTip);
      drawLine(hand.wrist, hand.middleBase); drawLine(hand.middleBase, hand.middleTip);
      drawLine(hand.wrist, hand.pinkyBase); drawLine(hand.pinkyBase, hand.pinkyTip);

      points.forEach(p => { ctx.beginPath(); ctx.arc(p.x, p.y, 2, 0, Math.PI * 2); ctx.fill(); });
  };

  const onResults = useCallback((results: any) => {
    let videoWidth = width;
    let videoHeight = height;
    if (webcamRef.current?.video?.videoWidth) {
        videoWidth = webcamRef.current.video.videoWidth;
        videoHeight = webcamRef.current.video.videoHeight;
    }

    if (results.multiHandLandmarks && results.multiHandLandmarks.length > 0) {
      setDebugInfo(`⚡ 系统就绪 | 检测到 ${results.multiHandLandmarks.length} 只手`);
      const newHandData: HandData[] = results.multiHandLandmarks.map((landmarks: any[]) => {
        const gesture = detectGesture(landmarks, videoWidth, videoHeight);
        const mapPt = (idx: number) => ({ x: (1 - landmarks[idx].x) * videoWidth, y: landmarks[idx].y * videoHeight });
        return {
          wrist: mapPt(0), indexTip: mapPt(8), middleTip: mapPt(12), ringTip: mapPt(16), pinkyTip: mapPt(20), thumbTip: mapPt(4),
          indexBase: mapPt(5), middleBase: mapPt(9), ringBase: mapPt(13), pinkyBase: mapPt(17),
          isOpen: gesture !== 'THUNDER', gesture, opacity: 1,
        };
      });

      handDataRef.current = newHandData;
      let newElement = 'NEUTRAL';
      let activeCombo = null;

      if (newHandData.length === 2) {
          const g1 = newHandData[0].gesture;
          const g2 = newHandData[1].gesture;
          if (g1 !== 'NEUTRAL' && g2 !== 'NEUTRAL') activeCombo = getCombo(g1, g2);
      }

      if (activeCombo) newElement = activeCombo;
      else {
          const activeHand = newHandData.find(h => h.gesture !== 'NEUTRAL');
          if (activeHand) newElement = activeHand.gesture;
      }
      activeComboRef.current = activeCombo;

      if (newElement !== prevElementRef.current) {
          if (newElement !== 'NEUTRAL') { highlightRef.current = 1.0; playChime(newElement); }
          prevElementRef.current = newElement;
      }
      setCurrentElement(newElement);
    } else {
      handDataRef.current = [];
      setDebugInfo("🔍 正在搜索手部信号...");
      activeComboRef.current = null;
      if (prevElementRef.current !== 'NEUTRAL') { prevElementRef.current = 'NEUTRAL'; setCurrentElement('NEUTRAL'); }
    }
  }, [width, height, playChime]);

  useEffect(() => {
    let hands: any = null;
    let isActive = true;
    let frameId: number;
    let lastVideoTime = -1;

    const initHands = async () => {
       if (!(window as any).Hands) { setTimeout(initHands, 500); return; }

       hands = new (window as any).Hands({ 
           locateFile: (file: string) => `https://cdn.jsdelivr.net/npm/@mediapipe/hands@0.4.1675469240/${file}` 
       });

       hands.setOptions({ 
           maxNumHands: 2, 
           modelComplexity: 1, 
           minDetectionConfidence: 0.5, 
           minTrackingConfidence: 0.5 
       });
       hands.onResults(onResults);

       setIsModelLoaded(true);

       const processVideo = async () => {
         if (!isActive) return;
         if (webcamRef.current && webcamRef.current.video && webcamRef.current.video.readyState === 4) {
             const video = webcamRef.current.video;
             if (video.videoWidth > 0 && video.videoHeight > 0) {
                 if (video.currentTime !== lastVideoTime) {
                     lastVideoTime = video.currentTime;
                     try { await hands.send({ image: video }); } catch (e) { 
                         console.error("MediaPipe processing error:", e); 
                         setDebugInfo("MediaPipe 错误: 刷新页面重试");
                     }
                 }
             }
         }
         frameId = requestAnimationFrame(processVideo);
       };
       processVideo();
    };
    initHands();
    return () => { isActive = false; if (frameId) cancelAnimationFrame(frameId); if (hands) hands.close(); };
  }, [onResults]);

  // --- PHYSICS ENGINE ---
  const updateParticles = (ctx: CanvasRenderingContext2D, width: number, height: number, centerX: number, centerY: number) => {
    for (let i = particlesRef.current.length - 1; i >= 0; i--) {
      const p = particlesRef.current[i];
      p.vx *= 0.95;
      p.vy *= 0.95;

      switch (p.element) {
          case 'WIND':
          case 'BLIZZARD':
              const dx = p.x - centerX;
              const dy = p.y - centerY;
              const dist = Math.sqrt(dx*dx + dy*dy) + 1;
              const angle = Math.atan2(dy, dx);
              p.vx += Math.cos(angle + Math.PI/2) * 1.5;
              p.vy += Math.sin(angle + Math.PI/2) * 1.5;
              p.vx -= (dx / dist) * 0.5;
              p.vy -= (dy / dist) * 0.5;
              p.angle += p.angularVelocity; 
              break;

          case 'WATER':
          case 'STEAM':
              p.vy += 1.2; 
              p.x += Math.sin(p.life * 0.1) * 0.5;
              break;

          case 'THUNDER':
          case 'TEMPEST':
          case 'VOID':
              p.vx += (Math.random() - 0.5) * 4;
              p.vy += (Math.random() - 0.5) * 4;
              if (Math.random() < 0.1) {
                  p.x += (Math.random() - 0.5) * 20;
                  p.y += (Math.random() - 0.5) * 20;
              }
              break;

          case 'FIRE':
          case 'INFERNO':
              p.vy -= 0.6; 
              p.vx += (Math.random() - 0.5) * 1.5;
              p.size *= 0.96; 
              break;

          default:
              p.vy -= 0.1;
      }

      p.x += p.vx;
      p.y += p.vy;
      p.life -= 1;
      if (p.element !== 'FIRE') p.size *= 0.98;

      if (p.life <= 0 || p.size < 0.2 || p.y > height + 50) {
        particlesRef.current.splice(i, 1);
      } else {
        ctx.save();
        ctx.globalAlpha = Math.min(1, p.life / 20, (p.maxLife - p.life) / 10);

        if (p.type === 'LEAF') {
            ctx.translate(p.x, p.y);
            ctx.rotate(p.angle);
            ctx.fillStyle = p.color;
            ctx.beginPath();
            ctx.ellipse(0, 0, p.size, p.size * 0.4, 0, 0, Math.PI * 2);
            ctx.fill();
        } 
        else if (p.type === 'DROP') {
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 2;
            ctx.lineCap = 'round';
            ctx.beginPath();
            ctx.moveTo(p.x, p.y);
            ctx.lineTo(p.x - p.vx, p.y - p.vy * 3); 
            ctx.stroke();
        }
        else if (p.type === 'SPARK') {
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 2;
            ctx.shadowColor = p.color;
            ctx.shadowBlur = 10;
            ctx.beginPath();
            ctx.moveTo(p.x - p.vx, p.y - p.vy);
            ctx.lineTo(p.x + p.vx, p.y + p.vy);
            ctx.stroke();
            if (Math.random() > 0.5) {
                ctx.beginPath();
                ctx.moveTo(p.x, p.y);
                ctx.lineTo(p.x + (Math.random()-0.5)*20, p.y + (Math.random()-0.5)*20);
                ctx.stroke();
            }
        }
        else if (p.type === 'EMBER') {
            ctx.fillStyle = p.color;
            ctx.shadowColor = 'orange';
            ctx.shadowBlur = 15;
            ctx.beginPath();
            ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
            ctx.fill();
        }
        else {
            ctx.fillStyle = p.color;
            ctx.shadowColor = p.color;
            ctx.shadowBlur = p.type === 'ORB' ? 10 : 0;
            ctx.beginPath();
            ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
            ctx.fill();
        }
        ctx.restore();
      }
    }
  };

  const spawnParticles = (x: number, y: number, element: string, theme: Theme) => {
    const isCombo = activeComboRef.current !== null;
    let count = isCombo ? 12 : 3;

    let type: ParticleType = 'ORB';
    let speed = Math.random() * 5;
    let spread = 20;

    if (element === 'WIND' || element === 'BLIZZARD') {
        type = Math.random() > 0.5 ? 'LEAF' : 'MIST';
        count = isCombo ? 15 : 4;
    } else if (element === 'WATER' || element === 'STEAM') {
        type = Math.random() > 0.7 ? 'MIST' : 'DROP';
        count = isCombo ? 20 : 5;
        spread = 40; 
    } else if (element === 'THUNDER' || element === 'TEMPEST' || element === 'VOID') {
        type = 'SPARK';
        count = isCombo ? 6 : 2; 
        speed = 8;
    } else if (element === 'FIRE' || element === 'INFERNO') {
        type = Math.random() > 0.8 ? 'MIST' : 'EMBER';
        count = isCombo ? 12 : 4;
    }

    for (let i = 0; i < count; i++) {
      const angle = Math.random() * Math.PI * 2;
      let vx = Math.cos(angle) * speed;
      let vy = Math.sin(angle) * speed;

      if (element === 'WATER' || element === 'STEAM') { vx *= 0.2; vy = Math.random() * 2; } 

      let color = Math.random() > 0.5 ? theme.primary : theme.secondary;
      if (element === 'WIND') color = Math.random() > 0.5 ? '#00FFFF' : '#F0FFF0'; 
      if (element === 'THUNDER') color = Math.random() > 0.5 ? '#FFFF00' : '#9400D3';

      let spawnX = x;
      let spawnY = y;

      if (isCombo || element === 'WATER') {
          spawnX = Math.random() * width;
          if (element === 'WATER' || element === 'TEMPEST') {
             spawnY = Math.random() * -100;
          } else {
             spawnY = Math.random() * height;
          }
      } else {
          spawnX = x + (Math.random() - 0.5) * spread;
          spawnY = y + (Math.random() - 0.5) * spread;
      }

      particlesRef.current.push({
        x: spawnX,
        y: spawnY,
        vx, vy,
        life: 40 + Math.random() * 40,
        maxLife: 80,
        size: 3 + Math.random() * 5,
        color,
        element: element as Particle['element'],
        type,
        angle: Math.random() * Math.PI * 2,
        angularVelocity: (Math.random() - 0.5) * 0.2
      });
    }
  };

  const animate = useCallback((time: number) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // HIGH DPI SCALING
    const dpr = window.devicePixelRatio || 1;
    // Set internal dimensions to match physical pixels
    if (canvas.width !== width * dpr || canvas.height !== height * dpr) {
        canvas.width = width * dpr;
        canvas.height = height * dpr;
    }
    // Set scale so logical drawing operations remain valid
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

    // Clear Logic (Clear the whole canvas)
    ctx.clearRect(0, 0, width, height);

    if (highlightRef.current > 0.01) highlightRef.current *= 0.9;
    else highlightRef.current = 0;
    const flash = highlightRef.current;

    ctx.globalCompositeOperation = 'lighter'; 

    let lastCenterX = width / 2;
    let lastCenterY = height / 2;
    const t = time * 0.001;

    const comboName = activeComboRef.current;

    if (comboName && handDataRef.current.length === 2) {
        // --- COMBO MODE ---
        const h1 = handDataRef.current[0];
        const h2 = handDataRef.current[1];
        const theme = COMBO_THEMES[comboName];

        const midX = (h1.middleBase.x + h2.middleBase.x) / 2;
        const midY = (h1.middleBase.y + h2.middleBase.y) / 2;
        lastCenterX = midX;
        lastCenterY = midY;

        ctx.save();
        ctx.beginPath();
        ctx.moveTo(h1.middleBase.x, h1.middleBase.y);
        ctx.lineTo(h2.middleBase.x, h2.middleBase.y);
        ctx.strokeStyle = theme.primary;
        ctx.lineWidth = 20 + Math.sin(t * 10) * 5; 
        ctx.lineCap = 'round';
        ctx.shadowBlur = 40;
        ctx.shadowColor = theme.secondary;
        ctx.globalAlpha = 0.4;
        ctx.stroke();
        ctx.restore();

        ctx.save();
        ctx.beginPath();
        ctx.moveTo(h1.middleBase.x, h1.middleBase.y);
        ctx.lineTo(h2.middleBase.x, h2.middleBase.y);
        ctx.strokeStyle = '#FFFFFF';
        ctx.lineWidth = 3;
        ctx.setLineDash([10, 40]);
        ctx.lineDashOffset = -t * 200; 
        ctx.globalCompositeOperation = 'overlay';
        ctx.stroke();
        ctx.restore();

        ctx.save();
        ctx.beginPath();
        ctx.moveTo(h1.middleBase.x, h1.middleBase.y);
        const dist = Math.hypot(h2.middleBase.x - h1.middleBase.x, h2.middleBase.y - h1.middleBase.y);
        const angle = Math.atan2(h2.middleBase.y - h1.middleBase.y, h2.middleBase.x - h1.middleBase.x);
        for(let i=0; i<=20; i++) {
             const p = i/20;
             const perp = Math.sin(p * Math.PI * 4 + t * 20) * (15 + Math.random() * 5);
             const bx = h1.middleBase.x + (h2.middleBase.x - h1.middleBase.x) * p + Math.cos(angle + Math.PI/2)*perp;
             const by = h1.middleBase.y + (h2.middleBase.y - h1.middleBase.y) * p + Math.sin(angle + Math.PI/2)*perp;
             ctx.lineTo(bx, by);
        }
        ctx.strokeStyle = theme.secondary;
        ctx.lineWidth = 2;
        ctx.shadowBlur = 10;
        ctx.shadowColor = theme.core;
        ctx.stroke();
        ctx.restore();

        ctx.globalAlpha = 1;
        drawRuneRing(ctx, midX, midY, 180, t, theme);
        drawSacredGeometry(ctx, midX, midY, 140, -t * 2, theme);
        drawSquareLayer(ctx, midX, midY, 100, t * 3, theme);
        drawPentagram(ctx, midX, midY, 60, -t, 1, theme);

        spawnParticles(midX, midY, comboName, theme);

        handDataRef.current.forEach(h => {
             drawSkeleton(ctx, h);
             const auraSize = 50 + Math.sin(t * 20) * 10;
             const grad = ctx.createRadialGradient(h.middleBase.x, h.middleBase.y, 10, h.middleBase.x, h.middleBase.y, auraSize);
             grad.addColorStop(0, theme.core);
             grad.addColorStop(0.4, theme.primary);
             grad.addColorStop(1, 'rgba(0,0,0,0)');
             ctx.save();
             ctx.fillStyle = grad;
             ctx.globalAlpha = 0.5;
             ctx.beginPath();
             ctx.arc(h.middleBase.x, h.middleBase.y, auraSize, 0, Math.PI * 2);
             ctx.fill();
             ctx.restore();
             drawRuneRing(ctx, h.middleBase.x, h.middleBase.y, 40, t*5, theme);
        });

    } else {
        // --- INDIVIDUAL MODE ---
        handDataRef.current.forEach((hand) => {
           drawSkeleton(ctx, hand);
           const element = hand.gesture;
           const theme = (element !== 'NEUTRAL' && THEMES[element]) ? THEMES[element] : THEMES['NEUTRAL'];
           const centerX = hand.middleBase.x; 
           const centerY = hand.middleBase.y; 

           if (element !== 'NEUTRAL') {
               if (flash > 0.05 && highlightRef.current > 0.05) {
                   ctx.save();
                   ctx.translate(centerX, centerY);
                   const waveSize = 120 + (1 - flash) * 100;
                   ctx.beginPath();
                   ctx.arc(0, 0, waveSize, 0, Math.PI * 2);
                   ctx.lineWidth = 10 * flash;
                   ctx.strokeStyle = theme.core;
                   ctx.shadowBlur = 20;
                   ctx.shadowColor = theme.secondary;
                   ctx.globalAlpha = flash;
                   ctx.stroke();
                   ctx.restore();
               }

               drawRuneRing(ctx, centerX, centerY, 120, t * 0.5, theme);
               drawSacredGeometry(ctx, centerX, centerY, 90, -t * 1.5, theme);
               drawSquareLayer(ctx, centerX, centerY, 65, t * 2.5, theme);
               const pulse = Math.sin(time * 0.005) * 0.5 + 0.5;
               drawPentagram(ctx, centerX, centerY, 40, t, pulse, theme);

               spawnParticles(centerX, centerY, element, theme);
               lastCenterX = centerX;
               lastCenterY = centerY;
           } else {
               ctx.globalAlpha = 0.3;
               drawRuneRing(ctx, centerX, centerY, 50, t * 0.2, theme);
           }
        });
    }

    updateParticles(ctx, canvas.width / dpr, canvas.height / dpr, lastCenterX, lastCenterY);
    requestRef.current = requestAnimationFrame(animate);
  }, [width, height]);

  useEffect(() => {
    requestRef.current = requestAnimationFrame(animate);
    return () => { if (requestRef.current) cancelAnimationFrame(requestRef.current); };
  }, [animate]);

  return (
    <div className="relative w-full h-full overflow-hidden flex items-center justify-center font-sans">

        {/* Dynamic Solid Background */}
        <div 
            className="absolute inset-0 transition-colors duration-1000 ease-in-out z-0"
            style={{ backgroundColor: currentTheme.background }}
        />

        {/* Hidden Webcam for Logic */}
        <Webcam ref={webcamRef} audio={false} width={width} height={height} mirrored={true} screenshotFormat="image/jpeg" className="absolute opacity-0 pointer-events-none" />

        {/* Canvas Layer */}
        <canvas ref={canvasRef} style={{ width, height }} className="absolute top-0 left-0 z-10" />

        {!isModelLoaded && (
            <div className="absolute inset-0 flex items-center justify-center bg-black bg-opacity-90 z-50">
                <div className="flex flex-col items-center">
                    <div className="text-amber-500 font-mono text-xl animate-pulse tracking-widest mb-4">🔮 正在校准魔法维度...</div>
                    <div className="w-64 h-1 bg-gray-800 rounded-full overflow-hidden">
                        <div className="h-full bg-amber-500 animate-[width_1s_ease-in-out_infinite]" style={{width: '50%'}}></div>
                    </div>
                </div>
            </div>
        )}

        {!hasStarted && isModelLoaded && (
            <div className="absolute inset-0 flex items-center justify-center bg-black/60 z-50 cursor-pointer backdrop-blur-sm" onClick={startExperience}>
                <div className="border border-amber-500/50 bg-black/80 p-8 rounded-lg text-center shadow-[0_0_30px_rgba(255,160,20,0.3)] hover:scale-105 transition-transform duration-300">
                    <h2 className="text-3xl font-bold text-amber-500 mb-2">准备就绪</h2>
                    <p className="text-white/80 mb-6">点击屏幕开启秘术工坊</p>
                    <button className="px-6 py-2 bg-amber-600 hover:bg-amber-500 text-black font-bold rounded">进入</button>
                </div>
            </div>
        )}

        {/* Dynamic Spell Name - Center Top/Middle */}
        <div className="absolute top-20 left-0 w-full flex justify-center z-20 pointer-events-none">
             <div className={`text-4xl md:text-5xl font-bold tracking-widest transition-all duration-300 drop-shadow-[0_0_15px_rgba(255,255,255,0.4)] px-8 py-2 rounded-full ${highlightRef.current > 0.1 ? 'scale-110 bg-black/20 backdrop-blur-sm' : ''} ${
                currentElement === 'FIRE' ? 'text-orange-500' :
                currentElement === 'WATER' ? 'text-blue-500' :
                currentElement === 'WIND' ? 'text-cyan-300' :
                currentElement === 'THUNDER' ? 'text-purple-500' : 
                currentElement === 'INFERNO' ? 'text-red-600' :
                currentElement === 'BLIZZARD' ? 'text-cyan-100' :
                currentElement === 'VOID' ? 'text-violet-400' : 'text-amber-400'
            }`}>
                {ELEMENT_NAMES_CN[currentElement]}
            </div>
        </div>

        {/* Debug Info */}
        <div className="absolute top-4 right-4 z-20 text-right opacity-50 pointer-events-none">
             <div className="text-xs text-amber-200 font-mono">{debugInfo}</div>
        </div>

        {/* Gesture Guide - Bottom */}
        <div className="absolute bottom-0 left-0 w-full p-6 z-20">
            <div className="max-w-4xl mx-auto bg-black/40 backdrop-blur-md border border-white/10 rounded-2xl p-4 shadow-2xl">
                <div className="flex flex-wrap justify-center items-center gap-4 md:gap-8 text-white/90 text-sm font-medium">
                    <div className="flex items-center gap-3 bg-white/5 px-4 py-2 rounded-lg border border-white/5">
                        <span className="text-2xl">✋</span> 
                        <div className="flex flex-col leading-tight">
                            <span className="text-orange-400 font-bold">火焰</span>
                            <span className="text-[10px] text-gray-400">五指张开</span>
                        </div>
                    </div>
                    <div className="flex items-center gap-3 bg-white/5 px-4 py-2 rounded-lg border border-white/5">
                        <span className="text-2xl">👇</span>
                        <div className="flex flex-col leading-tight">
                            <span className="text-blue-400 font-bold">流水</span>
                            <span className="text-[10px] text-gray-400">掌心向下</span>
                        </div>
                    </div>
                    <div className="flex items-center gap-3 bg-white/5 px-4 py-2 rounded-lg border border-white/5">
                        <span className="text-2xl">👊</span>
                        <div className="flex flex-col leading-tight">
                            <span className="text-purple-400 font-bold">雷霆</span>
                            <span className="text-[10px] text-gray-400">握紧拳头</span>
                        </div>
                    </div>
                    <div className="flex items-center gap-3 bg-white/5 px-4 py-2 rounded-lg border border-white/5">
                        <span className="text-2xl">✌️</span>
                        <div className="flex flex-col leading-tight">
                            <span className="text-teal-300 font-bold">疾风</span>
                            <span className="text-[10px] text-gray-400">食指中指 (剪刀手)</span>
                        </div>
                    </div>
                </div>
                <div className="text-center mt-3 text-xs text-amber-500/60 tracking-wider uppercase font-mono">
                    ✦ 双手结印触发高阶法术 ✦
                </div>
            </div>
        </div>
    </div>
  );
};

export default MagicOverlay;

import React, { useEffect, useRef, useCallback, useState } from 'react';
import Webcam from 'react-webcam';
import { Particle, HandData, ElementType, Theme, ParticleType } from '../types';
import { 
  drawRuneRing, 
  drawSacredGeometry, 
  drawSquareLayer, 
  drawPentagram,
  THEMES
} from '../utils/geometry';

interface MagicOverlayProps {
  width: number;
  height: number;
}

const COMBO_THEMES: Record<string, Theme> = {
  'BLIZZARD': { primary: '#00FFFF', secondary: '#E0FFFF', core: '#FFFFFF', shadow: '#008B8B', background: '#0a1a20' }, 
  'PLASMA': { primary: '#FF00FF', secondary: '#00FFFF', core: '#FFFFFF', shadow: '#9400D3', background: '#1a051a' }, 
  'STEAM': { primary: '#F0F8FF', secondary: '#B0C4DE', core: '#FFFFFF', shadow: '#778899', background: '#10151a' }, 
  'TEMPEST': { primary: '#000080', secondary: '#8A2BE2', core: '#FFFF00', shadow: '#191970', background: '#05051a' }, 
  'INFERNO': { primary: '#FF0000', secondary: '#FF4500', core: '#FFFF00', shadow: '#8B0000', background: '#2a0500' }, 
  'VOID': { primary: '#000000', secondary: '#4B0082', core: '#FFFFFF', shadow: '#9400D3', background: '#000000' }, 
};

const ELEMENT_NAMES_CN: Record<string, string> = {
    'NEUTRAL': '等待施法...',
    'FIRE': '🔥 烈焰术 (FIRE)',
    'WATER': '💧 唤雨术 (WATER)',
    'THUNDER': '⚡ 雷霆术 (THUNDER)',
    'WIND': '🌪️ 疾风术 (WIND)',
    'BLIZZARD': '❄️ 极寒风暴 (BLIZZARD)',
    'PLASMA': '⚛️ 等离子破 (PLASMA)',
    'STEAM': '♨️ 灼热蒸汽 (STEAM)',
    'TEMPEST': '⛈️ 雷暴风眼 (TEMPEST)',
    'INFERNO': '🌋 地狱烈火 (INFERNO)',
    'VOID': '🌌 虚空奇点 (VOID)'
};

const getCombo = (g1: ElementType, g2: ElementType): string | null => {
    const sorted = [g1, g2].sort().join('_');
    switch(sorted) {
        case 'WATER_WIND': return 'BLIZZARD';
        case 'FIRE_WIND': return 'PLASMA';
        case 'FIRE_WATER': return 'STEAM';
        case 'THUNDER_WATER': return 'TEMPEST';
        case 'FIRE_FIRE': return 'INFERNO';
        case 'THUNDER_THUNDER': return 'VOID';
        default: return null;
    }
};

const MagicOverlay: React.FC<MagicOverlayProps> = ({ width, height }) => {
  const webcamRef = useRef<Webcam>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>(0);
  const particlesRef = useRef<Particle[]>([]);
  const handDataRef = useRef<HandData[]>([]);
  const [currentElement, setCurrentElement] = useState<string>('NEUTRAL');
  const [isModelLoaded, setIsModelLoaded] = useState(false);
  const [debugInfo, setDebugInfo] = useState<string>("初始化系统...");
  const [hasStarted, setHasStarted] = useState(false);

  // Visual Feedback State
  const highlightRef = useRef<number>(0);
  const prevElementRef = useRef<string>('NEUTRAL');
  const activeComboRef = useRef<string | null>(null);

  // Audio Context
  const audioContextRef = useRef<AudioContext | null>(null);
  const noiseBufferRef = useRef<AudioBuffer | null>(null);

  // Get current Theme for background
  const currentTheme = activeComboRef.current 
    ? COMBO_THEMES[activeComboRef.current] 
    : (THEMES[currentElement as ElementType] || THEMES['NEUTRAL']);

  useEffect(() => {
    const AudioContextClass = (window as any).AudioContext || (window as any).webkitAudioContext;
    if (AudioContextClass) {
        const ctx = new AudioContextClass();
        audioContextRef.current = ctx;

        const bufferSize = ctx.sampleRate * 2; 
        const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
        const data = buffer.getChannelData(0);
        for (let i = 0; i < bufferSize; i++) {
            data[i] = Math.random() * 2 - 1;
        }
        noiseBufferRef.current = buffer;
    }
  }, []);

  const startExperience = () => {
      setHasStarted(true);
      if (audioContextRef.current?.state === 'suspended') {
          audioContextRef.current.resume();
      }
  };

  const playChime = useCallback((element: string) => {
    const ctx = audioContextRef.current;
    if (!ctx || !noiseBufferRef.current) return;
    if (ctx.state === 'suspended') ctx.resume().catch(console.error);

    const now = ctx.currentTime;
    const masterGain = ctx.createGain();
    masterGain.connect(ctx.destination);
    masterGain.gain.setValueAtTime(0.3, now); 

    const playNoise = (filterType: BiquadFilterType, freqStart: number, freqEnd: number, duration: number, vol: number = 1, delay: number = 0) => {
        const src = ctx.createBufferSource();
        src.buffer = noiseBufferRef.current;
        src.loop = true;
        const filter = ctx.createBiquadFilter();
        filter.type = filterType;
        filter.frequency.setValueAtTime(freqStart, now + delay);
        filter.frequency.exponentialRampToValueAtTime(freqEnd, now + delay + duration);
        filter.Q.value = 1;
        const amp = ctx.createGain();
        amp.gain.setValueAtTime(0, now + delay);
        amp.gain.linearRampToValueAtTime(vol, now + delay + 0.05);
        amp.gain.exponentialRampToValueAtTime(0.01, now + delay + duration);
        src.connect(filter);
        filter.connect(amp);
        amp.connect(masterGain);
        src.start(now + delay);
        src.stop(now + delay + duration + 0.2);
    };

    const playTone = (type: OscillatorType, freqStart: number, freqEnd: number, duration: number, vol: number = 1, delay: number = 0) => {
        const osc = ctx.createOscillator();
        osc.type = type;
        osc.frequency.setValueAtTime(freqStart, now + delay);
        if (freqStart !== freqEnd) osc.frequency.exponentialRampToValueAtTime(freqEnd, now + delay + duration);
        const amp = ctx.createGain();
        amp.gain.setValueAtTime(0, now + delay);
        amp.gain.linearRampToValueAtTime(vol, now + delay + 0.05);
        amp.gain.exponentialRampToValueAtTime(0.01, now + delay + duration);
        osc.connect(amp);
        amp.connect(masterGain);
        osc.start(now + delay);
        osc.stop(now + delay + duration + 0.2);
    };

    switch (element) {
        case 'FIRE': playNoise('lowpass', 500, 100, 1.0, 0.5); playTone('sawtooth', 80, 120, 0.8, 0.2); break;
        case 'WATER': playNoise('bandpass', 800, 300, 0.6, 0.4); playTone('sine', 600, 300, 0.4, 0.3, 0.1); break;
        case 'WIND': playNoise('lowpass', 200, 800, 0.4, 0.3); playNoise('highpass', 400, 1000, 0.5, 0.2, 0.1); break;
        case 'THUNDER': playTone('sawtooth', 800, 50, 0.3, 0.2); playNoise('lowpass', 1000, 50, 1.2, 0.6, 0.1); break;
        case 'BLIZZARD': playNoise('highpass', 1000, 3000, 1.5, 0.4); playTone('sine', 1500, 2000, 0.3, 0.1, 0.1); break;
        case 'INFERNO': playNoise('lowpass', 800, 50, 1.5, 0.8); playTone('square', 60, 40, 1.5, 0.2); break;
        case 'TEMPEST': playNoise('lowpass', 200, 50, 2.0, 0.8); playTone('sawtooth', 1200, 100, 0.5, 0.2, 0.1); playNoise('bandpass', 1000, 500, 1.0, 0.3); break;
        case 'VOID': playTone('sine', 50, 40, 2.5, 0.6); playNoise('bandpass', 100, 200, 2.5, 0.4); playTone('sine', 300, 290, 1.0, 0.1, 0.5); break;
        case 'PLASMA': playTone('sawtooth', 200, 800, 1.0, 0.2); playNoise('bandpass', 400, 1200, 1.0, 0.4); break;
        case 'STEAM': playNoise('highpass', 500, 1000, 1.0, 0.3); break;
        default: playTone('triangle', 440, 880, 0.3, 0.1);
    }
  }, []);

  const detectGesture = (landmarks: any[], videoWidth: number, videoHeight: number): ElementType => {
    const mapPt = (idx: number) => ({ x: (1 - landmarks[idx].x) * videoWidth, y: landmarks[idx].y * videoHeight });
    const wrist = mapPt(0);
    const indexTip = mapPt(8);
    const middleTip = mapPt(12);
    const middleMCP = mapPt(9);

    // Optimized Distances
    const distSq = (p1: any, p2: any) => (p1.x - p2.x)**2 + (p1.y - p2.y)**2;
    const isFingerOpen = (tip: any, mcp: any) => distSq(tip, wrist) > distSq(mcp, wrist) * 1.2;

    const isPointingDown = wrist.y < middleMCP.y;
    if (isPointingDown) return 'WATER';

    let openCount = 0;
    if (isFingerOpen(indexTip, mapPt(5))) openCount++;
    if (isFingerOpen(middleTip, mapPt(9))) openCount++;
    if (isFingerOpen(mapPt(16), mapPt(13))) openCount++;
    if (isFingerOpen(mapPt(20), mapPt(17))) openCount++;

    if (openCount >= 4) return 'FIRE';
    if (openCount >= 2) return 'WIND';
    return 'THUNDER';
  };

  const drawSkeleton = (ctx: CanvasRenderingContext2D, hand: HandData) => {
      ctx.strokeStyle = "rgba(255, 255, 255, 0.15)";
      ctx.lineWidth = 1.5;
      ctx.fillStyle = "rgba(255, 255, 255, 0.5)";
      const points = [hand.wrist, hand.indexBase, hand.indexTip, hand.middleBase, hand.middleTip, hand.ringBase, hand.ringTip, hand.pinkyBase, hand.pinkyTip, hand.thumbTip];

      const drawLine = (p1: any, p2: any) => { ctx.beginPath(); ctx.moveTo(p1.x, p1.y); ctx.lineTo(p2.x, p2.y); ctx.stroke(); }
      drawLine(hand.wrist, hand.indexBase); drawLine(hand.indexBase, hand.indexTip);
      drawLine(hand.wrist, hand.middleBase); drawLine(hand.middleBase, hand.middleTip);
      drawLine(hand.wrist, hand.pinkyBase); drawLine(hand.pinkyBase, hand.pinkyTip);

      points.forEach(p => { ctx.beginPath(); ctx.arc(p.x, p.y, 2.5, 0, Math.PI * 2); ctx.fill(); });
  };

  const onResults = useCallback((results: any) => {
    let videoWidth = width;
    let videoHeight = height;
    if (webcamRef.current?.video?.videoWidth) {
        videoWidth = webcamRef.current.video.videoWidth;
        videoHeight = webcamRef.current.video.videoHeight;
    }

    if (results.multiHandLandmarks && results.multiHandLandmarks.length > 0) {
      setDebugInfo(`⚡ 系统就绪 | 检测到 ${results.multiHandLandmarks.length} 只手`);
      const newHandData: HandData[] = results.multiHandLandmarks.map((landmarks: any[]) => {
        const gesture = detectGesture(landmarks, videoWidth, videoHeight);
        const mapPt = (idx: number) => ({ x: (1 - landmarks[idx].x) * videoWidth, y: landmarks[idx].y * videoHeight });
        return {
          wrist: mapPt(0), indexTip: mapPt(8), middleTip: mapPt(12), ringTip: mapPt(16), pinkyTip: mapPt(20), thumbTip: mapPt(4),
          indexBase: mapPt(5), middleBase: mapPt(9), ringBase: mapPt(13), pinkyBase: mapPt(17),
          isOpen: gesture !== 'THUNDER', gesture, opacity: 1,
        };
      });

      handDataRef.current = newHandData;
      let newElement = 'NEUTRAL';
      let activeCombo = null;

      if (newHandData.length === 2) {
          const g1 = newHandData[0].gesture;
          const g2 = newHandData[1].gesture;
          if (g1 !== 'NEUTRAL' && g2 !== 'NEUTRAL') activeCombo = getCombo(g1, g2);
      }

      if (activeCombo) newElement = activeCombo;
      else {
          const activeHand = newHandData.find(h => h.gesture !== 'NEUTRAL');
          if (activeHand) newElement = activeHand.gesture;
      }
      activeComboRef.current = activeCombo;

      if (newElement !== prevElementRef.current) {
          if (newElement !== 'NEUTRAL') { highlightRef.current = 1.0; playChime(newElement); }
          prevElementRef.current = newElement;
      }
      setCurrentElement(newElement);
    } else {
      handDataRef.current = [];
      setDebugInfo("🔍 正在搜索手部信号...");
      activeComboRef.current = null;
      if (prevElementRef.current !== 'NEUTRAL') { prevElementRef.current = 'NEUTRAL'; setCurrentElement('NEUTRAL'); }
    }
  }, [width, height, playChime]);

  useEffect(() => {
    let hands: any = null;
    let isActive = true;
    let frameId: number;
    let lastVideoTime = -1;

    const initHands = async () => {
       if (!(window as any).Hands) { setTimeout(initHands, 500); return; }
       hands = new (window as any).Hands({ locateFile: (file: string) => `https://cdn.jsdelivr.net/npm/@mediapipe/hands@0.4.1675469240/${file}` });
       hands.setOptions({ maxNumHands: 2, modelComplexity: 1, minDetectionConfidence: 0.5, minTrackingConfidence: 0.5 });
       hands.onResults(onResults);
       setIsModelLoaded(true);

       const processVideo = async () => {
         if (!isActive) return;
         if (webcamRef.current && webcamRef.current.video && webcamRef.current.video.readyState === 4) {
             const video = webcamRef.current.video;
             if (video.videoWidth > 0 && video.videoHeight > 0) {
                 if (video.currentTime !== lastVideoTime) {
                     lastVideoTime = video.currentTime;
                     try { await hands.send({ image: video }); } catch (e) { 
                         console.error(e); setDebugInfo("MediaPipe 错误: 刷新页面重试");
                     }
                 }
             }
         }
         frameId = requestAnimationFrame(processVideo);
       };
       processVideo();
    };
    initHands();
    return () => { isActive = false; if (frameId) cancelAnimationFrame(frameId); if (hands) hands.close(); };
  }, [onResults]);

  // --- PHYSICS ENGINE (Optimized) ---
  const updateParticles = (ctx: CanvasRenderingContext2D, width: number, height: number, centerX: number, centerY: number) => {
    // PERFORMANCE: Limit global composite changes inside loop
    ctx.shadowBlur = 0; // Disable shadow blur for particles to increase FPS

    for (let i = particlesRef.current.length - 1; i >= 0; i--) {
      const p = particlesRef.current[i];

      // Speed Increase: Reduced drag
      p.vx *= 0.98; 
      p.vy *= 0.98;

      switch (p.element) {
          case 'WIND':
          case 'BLIZZARD':
              const dx = p.x - centerX;
              const dy = p.y - centerY;
              const dist = Math.sqrt(dx*dx + dy*dy) + 1;
              const angle = Math.atan2(dy, dx);
              p.vx += Math.cos(angle + Math.PI/2) * 2.5; // Faster rotation
              p.vy += Math.sin(angle + Math.PI/2) * 2.5;
              p.vx -= (dx / dist) * 0.8;
              p.vy -= (dy / dist) * 0.8;
              p.angle += p.angularVelocity * 1.5; 
              break;

          case 'WATER':
          case 'STEAM':
              p.vy += 1.5; // Heavier gravity
              p.x += Math.sin(p.life * 0.2) * 1.0;
              break;

          case 'THUNDER':
          case 'TEMPEST':
          case 'VOID':
              p.vx += (Math.random() - 0.5) * 6; // More chaos
              p.vy += (Math.random() - 0.5) * 6;
              if (Math.random() < 0.15) {
                  p.x += (Math.random() - 0.5) * 40;
                  p.y += (Math.random() - 0.5) * 40;
              }
              break;

          case 'FIRE':
          case 'INFERNO':
              p.vy -= 1.0; // Faster rise
              p.vx += (Math.random() - 0.5) * 2.0;
              p.size *= 0.95; 
              break;

          default:
              p.vy -= 0.2;
      }

      p.x += p.vx;
      p.y += p.vy;
      p.life -= 1;
      if (p.element !== 'FIRE') p.size *= 0.98;

      if (p.life <= 0 || p.size < 0.1 || p.y > height + 50 || p.y < -50 || p.x < -50 || p.x > width + 50) {
        particlesRef.current.splice(i, 1);
      } else {
        ctx.save();

        // --- DYNAMIC SHADOWS (Fake 3D) ---
        // Calculate offset direction away from light source (centerX, centerY)
        if (p.size > 2) {
             const shadowOffsetX = (p.x - centerX) * 0.05;
             const shadowOffsetY = (p.y - centerY) * 0.05;
             ctx.fillStyle = "rgba(0,0,0,0.3)";
             ctx.beginPath();
             ctx.arc(p.x + shadowOffsetX, p.y + shadowOffsetY, p.size, 0, Math.PI*2);
             ctx.fill();
        }

        ctx.globalAlpha = Math.min(1, p.life / 10, (p.maxLife - p.life) / 5);

        if (p.type === 'LEAF') {
            ctx.translate(p.x, p.y);
            ctx.rotate(p.angle);
            ctx.fillStyle = p.color;
            ctx.beginPath();
            ctx.ellipse(0, 0, p.size, p.size * 0.4, 0, 0, Math.PI * 2);
            ctx.fill();
        } 
        else if (p.type === 'DROP') {
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 2.5;
            ctx.lineCap = 'round';
            ctx.beginPath();
            ctx.moveTo(p.x, p.y);
            ctx.lineTo(p.x - p.vx * 1.5, p.y - p.vy * 4); // Longer streaks
            ctx.stroke();
        }
        else if (p.type === 'SPARK') {
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 2;
            ctx.beginPath();
            ctx.moveTo(p.x - p.vx, p.y - p.vy);
            ctx.lineTo(p.x + p.vx, p.y + p.vy);
            ctx.stroke();
        }
        else {
            ctx.fillStyle = p.color;
            ctx.beginPath();
            ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
            ctx.fill();
        }
        ctx.restore();
      }
    }
  };

  const spawnParticles = (x: number, y: number, element: string, theme: Theme) => {
    const isCombo = activeComboRef.current !== null;
    let count = isCombo ? 10 : 3;

    let type: ParticleType = 'ORB';
    // Increased base speed
    let speed = Math.random() * 8 + 4; 
    let spread = 30;

    if (element === 'WIND' || element === 'BLIZZARD') {
        type = Math.random() > 0.5 ? 'LEAF' : 'MIST';
        count = isCombo ? 12 : 5;
    } else if (element === 'WATER' || element === 'STEAM') {
        type = Math.random() > 0.7 ? 'MIST' : 'DROP';
        count = isCombo ? 15 : 6;
        spread = 50; 
    } else if (element === 'THUNDER' || element === 'TEMPEST' || element === 'VOID') {
        type = 'SPARK';
        count = isCombo ? 8 : 4; 
        speed = 12; // Very fast sparks
    } else if (element === 'FIRE' || element === 'INFERNO') {
        type = Math.random() > 0.8 ? 'MIST' : 'EMBER';
        count = isCombo ? 10 : 5;
    }

    for (let i = 0; i < count; i++) {
      const angle = Math.random() * Math.PI * 2;
      let vx = Math.cos(angle) * speed;
      let vy = Math.sin(angle) * speed;

      if (element === 'WATER' || element === 'STEAM') { vx *= 0.3; vy = Math.random() * 5 + 5; } // Faster rain

      let color = Math.random() > 0.5 ? theme.primary : theme.secondary;
      if (element === 'WIND') color = Math.random() > 0.5 ? '#00FFFF' : '#F0FFF0'; 
      if (element === 'THUNDER') color = Math.random() > 0.5 ? '#FFFF00' : '#9400D3';

      let spawnX = x;
      let spawnY = y;

      if (isCombo || element === 'WATER') {
          spawnX = Math.random() * width;
          if (element === 'WATER' || element === 'TEMPEST') {
             spawnY = Math.random() * -100;
          } else {
             spawnY = Math.random() * height;
          }
      } else {
          spawnX = x + (Math.random() - 0.5) * spread;
          spawnY = y + (Math.random() - 0.5) * spread;
      }

      particlesRef.current.push({
        x: spawnX,
        y: spawnY,
        vx, vy,
        life: 30 + Math.random() * 30, // Shorter life for snappier feel
        maxLife: 60,
        size: 4 + Math.random() * 6, // Slightly larger
        color,
        element: element as Particle['element'],
        type,
        angle: Math.random() * Math.PI * 2,
        angularVelocity: (Math.random() - 0.5) * 0.4
      });
    }
  };

  const drawDynamicLighting = (ctx: CanvasRenderingContext2D, width: number, height: number, lightX: number, lightY: number, theme: Theme) => {
    // 1. Base Ambient Light (Radial Gradient)
    // Acts as a light source coming from the hand/geometry
    const gradient = ctx.createRadialGradient(lightX, lightY, 0, lightX, lightY, width * 0.7);
    gradient.addColorStop(0, theme.primary + '33'); // 20% opacity at center
    gradient.addColorStop(0.4, theme.secondary + '11');
    gradient.addColorStop(1, 'transparent');

    ctx.save();
    ctx.globalCompositeOperation = 'screen'; // Blends additively with background
    ctx.fillStyle = gradient;
    ctx.fillRect(0, 0, width, height);
    ctx.restore();

    // 2. Vignette (Dark Edges)
    // Adds focus to the center/light source
    const vignette = ctx.createRadialGradient(width/2, height/2, width * 0.4, width/2, height/2, width * 0.8);
    vignette.addColorStop(0, 'transparent');
    vignette.addColorStop(1, 'rgba(0,0,0,0.6)');

    ctx.save();
    ctx.globalCompositeOperation = 'multiply';
    ctx.fillStyle = vignette;
    ctx.fillRect(0, 0, width, height);
    ctx.restore();
  };

  const animate = useCallback((time: number) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d', { alpha: false }); // Optimization: alpha false
    if (!ctx) return;

    // HIGH DPI SCALING
    const dpr = window.devicePixelRatio || 1;
    if (canvas.width !== width * dpr || canvas.height !== height * dpr) {
        canvas.width = width * dpr;
        canvas.height = height * dpr;
    }
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

    // 1. Draw Background (Clear)
    // Use the Theme Background variable directly for canvas fill
    const theme = activeComboRef.current 
        ? COMBO_THEMES[activeComboRef.current] 
        : (THEMES[currentElement as ElementType] || THEMES['NEUTRAL']);

    ctx.fillStyle = theme.background;
    ctx.fillRect(0, 0, width, height);

    if (highlightRef.current > 0.01) highlightRef.current *= 0.9;
    else highlightRef.current = 0;
    const flash = highlightRef.current;

    let lastCenterX = width / 2;
    let lastCenterY = height / 2;
    const t = time * 0.001;
    const comboName = activeComboRef.current;

    // --- DETERMINE CENTER FOR LIGHTING ---
    if (comboName && handDataRef.current.length === 2) {
         lastCenterX = (handDataRef.current[0].middleBase.x + handDataRef.current[1].middleBase.x) / 2;
         lastCenterY = (handDataRef.current[0].middleBase.y + handDataRef.current[1].middleBase.y) / 2;
    } else if (handDataRef.current.length > 0) {
        // Find active hand or just first hand
        const active = handDataRef.current.find(h => h.gesture !== 'NEUTRAL') || handDataRef.current[0];
        lastCenterX = active.middleBase.x;
        lastCenterY = active.middleBase.y;
    }

    // 2. Dynamic Lighting Layer
    drawDynamicLighting(ctx, width, height, lastCenterX, lastCenterY, theme);

    // 3. Geometry & Particles
    ctx.globalCompositeOperation = 'lighter'; 

    if (comboName && handDataRef.current.length === 2) {
        // --- COMBO MODE ---
        const h1 = handDataRef.current[0];
        const h2 = handDataRef.current[1];

        const midX = lastCenterX;
        const midY = lastCenterY;

        ctx.save();
        ctx.beginPath();
        ctx.moveTo(h1.middleBase.x, h1.middleBase.y);
        ctx.lineTo(h2.middleBase.x, h2.middleBase.y);
        ctx.strokeStyle = theme.primary;
        ctx.lineWidth = 20 + Math.sin(t * 10) * 5; 
        ctx.lineCap = 'round';
        ctx.shadowBlur = 20; // Reduced blur
        ctx.shadowColor = theme.secondary;
        ctx.globalAlpha = 0.4;
        ctx.stroke();
        ctx.restore();

        ctx.save();
        ctx.beginPath();
        ctx.moveTo(h1.middleBase.x, h1.middleBase.y);
        ctx.lineTo(h2.middleBase.x, h2.middleBase.y);
        ctx.strokeStyle = '#FFFFFF';
        ctx.lineWidth = 3;
        ctx.setLineDash([10, 40]);
        ctx.lineDashOffset = -t * 200; 
        ctx.globalCompositeOperation = 'overlay';
        ctx.stroke();
        ctx.restore();

        // Arcs
        ctx.save();
        ctx.beginPath();
        ctx.moveTo(h1.middleBase.x, h1.middleBase.y);
        const dist = Math.hypot(h2.middleBase.x - h1.middleBase.x, h2.middleBase.y - h1.middleBase.y);
        const angle = Math.atan2(h2.middleBase.y - h1.middleBase.y, h2.middleBase.x - h1.middleBase.x);
        for(let i=0; i<=10; i++) { // Reduced segments
             const p = i/10;
             const perp = Math.sin(p * Math.PI * 4 + t * 20) * (15 + Math.random() * 5);
             const bx = h1.middleBase.x + (h2.middleBase.x - h1.middleBase.x) * p + Math.cos(angle + Math.PI/2)*perp;
             const by = h1.middleBase.y + (h2.middleBase.y - h1.middleBase.y) * p + Math.sin(angle + Math.PI/2)*perp;
             ctx.lineTo(bx, by);
        }
        ctx.strokeStyle = theme.secondary;
        ctx.lineWidth = 2;
        ctx.stroke();
        ctx.restore();

        ctx.globalAlpha = 1;
        drawRuneRing(ctx, midX, midY, 180, t, theme);
        drawSacredGeometry(ctx, midX, midY, 140, -t * 2, theme);
        drawSquareLayer(ctx, midX, midY, 100, t * 3, theme);
        drawPentagram(ctx, midX, midY, 60, -t, 1, theme);

        spawnParticles(midX, midY, comboName, theme);

        handDataRef.current.forEach(h => {
             drawSkeleton(ctx, h);
             const auraSize = 50 + Math.sin(t * 20) * 10;
             const grad = ctx.createRadialGradient(h.middleBase.x, h.middleBase.y, 10, h.middleBase.x, h.middleBase.y, auraSize);
             grad.addColorStop(0, theme.core);
             grad.addColorStop(0.4, theme.primary);
             grad.addColorStop(1, 'rgba(0,0,0,0)');
             ctx.save();
             ctx.fillStyle = grad;
             ctx.globalAlpha = 0.5;
             ctx.beginPath();
             ctx.arc(h.middleBase.x, h.middleBase.y, auraSize, 0, Math.PI * 2);
             ctx.fill();
             ctx.restore();
             drawRuneRing(ctx, h.middleBase.x, h.middleBase.y, 40, t*5, theme);
        });

    } else {
        // --- INDIVIDUAL MODE ---
        handDataRef.current.forEach((hand) => {
           drawSkeleton(ctx, hand);
           const element = hand.gesture;
           const handTheme = (element !== 'NEUTRAL' && THEMES[element]) ? THEMES[element] : THEMES['NEUTRAL'];
           const centerX = hand.middleBase.x; 
           const centerY = hand.middleBase.y; 

           if (element !== 'NEUTRAL') {
               if (flash > 0.05 && highlightRef.current > 0.05) {
                   ctx.save();
                   ctx.translate(centerX, centerY);
                   const waveSize = 120 + (1 - flash) * 100;
                   ctx.beginPath();
                   ctx.arc(0, 0, waveSize, 0, Math.PI * 2);
                   ctx.lineWidth = 10 * flash;
                   ctx.strokeStyle = handTheme.core;
                   ctx.shadowBlur = 20;
                   ctx.shadowColor = handTheme.secondary;
                   ctx.globalAlpha = flash;
                   ctx.stroke();
                   ctx.restore();
               }

               drawRuneRing(ctx, centerX, centerY, 120, t * 0.5, handTheme);
               drawSacredGeometry(ctx, centerX, centerY, 90, -t * 1.5, handTheme);
               drawSquareLayer(ctx, centerX, centerY, 65, t * 2.5, handTheme);
               const pulse = Math.sin(time * 0.005) * 0.5 + 0.5;
               drawPentagram(ctx, centerX, centerY, 40, t, pulse, handTheme);

               spawnParticles(centerX, centerY, element, handTheme);
           } else {
               ctx.globalAlpha = 0.3;
               drawRuneRing(ctx, centerX, centerY, 50, t * 0.2, handTheme);
           }
        });
    }

    updateParticles(ctx, width, height, lastCenterX, lastCenterY);
    requestRef.current = requestAnimationFrame(animate);
  }, [width, height, currentElement]);

  useEffect(() => {
    requestRef.current = requestAnimationFrame(animate);
    return () => { if (requestRef.current) cancelAnimationFrame(requestRef.current); };
  }, [animate]);

  return (
    <div className="relative w-full h-full overflow-hidden flex items-center justify-center font-sans">

        {/* Dynamic Background Transition (CSS for smooth color fades, Canvas covers for lighting) */}
        <div 
            className="absolute inset-0 transition-colors duration-700 ease-in-out z-0"
            style={{ backgroundColor: currentTheme.background }}
        />

        {/* Hidden Webcam for Logic */}
        <Webcam ref={webcamRef} audio={false} width={width} height={height} mirrored={true} screenshotFormat="image/jpeg" className="absolute opacity-0 pointer-events-none" />

        {/* Canvas Layer */}
        <canvas ref={canvasRef} style={{ width, height }} className="absolute top-0 left-0 z-10" />

        {!isModelLoaded && (
            <div className="absolute inset-0 flex items-center justify-center bg-black bg-opacity-90 z-50">
                <div className="flex flex-col items-center">
                    <div className="text-amber-500 font-mono text-xl animate-pulse tracking-widest mb-4">🔮 正在校准魔法维度...</div>
                    <div className="w-64 h-1 bg-gray-800 rounded-full overflow-hidden">
                        <div className="h-full bg-amber-500 animate-[width_1s_ease-in-out_infinite]" style={{width: '50%'}}></div>
                    </div>
                </div>
            </div>
        )}

        {!hasStarted && isModelLoaded && (
            <div className="absolute inset-0 flex items-center justify-center bg-black/60 z-50 cursor-pointer backdrop-blur-sm" onClick={startExperience}>
                <div className="border border-amber-500/50 bg-black/80 p-8 rounded-lg text-center shadow-[0_0_30px_rgba(255,160,20,0.3)] hover:scale-105 transition-transform duration-300">
                    <h2 className="text-3xl font-bold text-amber-500 mb-2">准备就绪</h2>
                    <p className="text-white/80 mb-6">点击屏幕开启秘术工坊</p>
                    <button className="px-6 py-2 bg-amber-600 hover:bg-amber-500 text-black font-bold rounded">进入</button>
                </div>
            </div>
        )}

        {/* Dynamic Spell Name */}
        <div className="absolute top-20 left-0 w-full flex justify-center z-20 pointer-events-none">
             <div className={`text-4xl md:text-5xl font-bold tracking-widest transition-all duration-300 drop-shadow-[0_0_15px_rgba(255,255,255,0.4)] px-8 py-2 rounded-full ${highlightRef.current > 0.1 ? 'scale-110 bg-black/20 backdrop-blur-sm' : ''} ${
                currentElement === 'FIRE' ? 'text-orange-500' :
                currentElement === 'WATER' ? 'text-blue-500' :
                currentElement === 'WIND' ? 'text-cyan-300' :
                currentElement === 'THUNDER' ? 'text-purple-500' : 
                currentElement === 'INFERNO' ? 'text-red-600' :
                currentElement === 'BLIZZARD' ? 'text-cyan-100' :
                currentElement === 'VOID' ? 'text-violet-400' : 'text-amber-400'
            }`}>
                {ELEMENT_NAMES_CN[currentElement]}
            </div>
        </div>

        {/* Debug Info */}
        <div className="absolute top-4 right-4 z-20 text-right opacity-50 pointer-events-none">
             <div className="text-xs text-amber-200 font-mono">{debugInfo}</div>
        </div>

        {/* Gesture Guide */}
        <div className="absolute bottom-0 left-0 w-full p-6 z-20">
            <div className="max-w-4xl mx-auto bg-black/40 backdrop-blur-md border border-white/10 rounded-2xl p-4 shadow-2xl">
                <div className="flex flex-wrap justify-center items-center gap-4 md:gap-8 text-white/90 text-sm font-medium">
                    <div className="flex items-center gap-3 bg-white/5 px-4 py-2 rounded-lg border border-white/5">
                        <span className="text-2xl">✋</span> 
                        <div className="flex flex-col leading-tight">
                            <span className="text-orange-400 font-bold">火焰</span>
                            <span className="text-[10px] text-gray-400">五指张开</span>
                        </div>
                    </div>
                    <div className="flex items-center gap-3 bg-white/5 px-4 py-2 rounded-lg border border-white/5">
                        <span className="text-2xl">👇</span>
                        <div className="flex flex-col leading-tight">
                            <span className="text-blue-400 font-bold">流水</span>
                            <span className="text-[10px] text-gray-400">掌心向下</span>
                        </div>
                    </div>
                    <div className="flex items-center gap-3 bg-white/5 px-4 py-2 rounded-lg border border-white/5">
                        <span className="text-2xl">👊</span>
                        <div className="flex flex-col leading-tight">
                            <span className="text-purple-400 font-bold">雷霆</span>
                            <span className="text-[10px] text-gray-400">握紧拳头</span>
                        </div>
                    </div>
                    <div className="flex items-center gap-3 bg-white/5 px-4 py-2 rounded-lg border border-white/5">
                        <span className="text-2xl">✌️</span>
                        <div className="flex flex-col leading-tight">
                            <span className="text-teal-300 font-bold">疾风</span>
                            <span className="text-[10px] text-gray-400">食指中指 (剪刀手)</span>
                        </div>
                    </div>
                </div>
                <div className="text-center mt-3 text-xs text-amber-500/60 tracking-wider uppercase font-mono">
                    ✦ 双手结印触发高阶法术 ✦
                </div>
            </div>
        </div>
    </div>
  );
};

export default MagicOverlay;

import React, { useEffect, useRef, useCallback, useState } from 'react';
import Webcam from 'react-webcam';
import { Particle, HandData, ElementType, Theme, ParticleType } from '../types';
import { 
  drawRuneRing, 
  drawSacredGeometry, 
  drawSquareLayer, 
  drawPentagram,
  THEMES
} from '../utils/geometry';

interface MagicOverlayProps {
  width: number;
  height: number;
}

const COMBO_THEMES: Record<string, Theme> = {
  'BLIZZARD': { primary: '#00FFFF', secondary: '#E0FFFF', core: '#FFFFFF', shadow: '#008B8B', background: '#0a1a20' }, 
  'PLASMA': { primary: '#FF00FF', secondary: '#00FFFF', core: '#FFFFFF', shadow: '#9400D3', background: '#1a051a' }, 
  'STEAM': { primary: '#F0F8FF', secondary: '#B0C4DE', core: '#FFFFFF', shadow: '#778899', background: '#10151a' }, 
  'TEMPEST': { primary: '#000080', secondary: '#8A2BE2', core: '#FFFF00', shadow: '#191970', background: '#05051a' }, 
  'INFERNO': { primary: '#FF0000', secondary: '#FF4500', core: '#FFFF00', shadow: '#8B0000', background: '#2a0500' }, 
  'VOID': { primary: '#000000', secondary: '#4B0082', core: '#FFFFFF', shadow: '#9400D3', background: '#000000' }, 
};

const ELEMENT_NAMES_CN: Record<string, string> = {
    'NEUTRAL': '等待施法...',
    'FIRE': '🔥 烈焰术 (FIRE)',
    'WATER': '💧 唤雨术 (WATER)',
    'THUNDER': '⚡ 雷霆术 (THUNDER)',
    'WIND': '🌪️ 疾风术 (WIND)',
    'BLIZZARD': '❄️ 极寒风暴 (BLIZZARD)',
    'PLASMA': '⚛️ 等离子破 (PLASMA)',
    'STEAM': '♨️ 灼热蒸汽 (STEAM)',
    'TEMPEST': '⛈️ 雷暴风眼 (TEMPEST)',
    'INFERNO': '🌋 地狱烈火 (INFERNO)',
    'VOID': '🌌 虚空奇点 (VOID)'
};

const getCombo = (g1: ElementType, g2: ElementType): string | null => {
    const sorted = [g1, g2].sort().join('_');
    switch(sorted) {
        case 'WATER_WIND': return 'BLIZZARD';
        case 'FIRE_WIND': return 'PLASMA';
        case 'FIRE_WATER': return 'STEAM';
        case 'THUNDER_WATER': return 'TEMPEST';
        case 'FIRE_FIRE': return 'INFERNO';
        case 'THUNDER_THUNDER': return 'VOID';
        default: return null;
    }
};

const MagicOverlay: React.FC<MagicOverlayProps> = ({ width, height }) => {
  const webcamRef = useRef<Webcam>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>(0);
  const particlesRef = useRef<Particle[]>([]);
  const handDataRef = useRef<HandData[]>([]);
  const [currentElement, setCurrentElement] = useState<string>('NEUTRAL');
  const [isModelLoaded, setIsModelLoaded] = useState(false);
  const [debugInfo, setDebugInfo] = useState<string>("初始化系统...");
  const [hasStarted, setHasStarted] = useState(false);
  const [showControls, setShowControls] = useState(true);

  // Settings State
  const [settings, setSettings] = useState({
      speed: 1.5,   // Base speed multiplier
      count: 1.2,   // Particle count multiplier
      glow: 1.2,    // Glow/Size intensity
  });

  // Settings Ref (for access inside animation loop without stale closures)
  const settingsRef = useRef(settings);
  useEffect(() => { settingsRef.current = settings; }, [settings]);

  // Visual Feedback State
  const highlightRef = useRef<number>(0);
  const prevElementRef = useRef<string>('NEUTRAL');
  const activeComboRef = useRef<string | null>(null);

  // Audio Context
  const audioContextRef = useRef<AudioContext | null>(null);
  const noiseBufferRef = useRef<AudioBuffer | null>(null);

  // Get current Theme for background
  const currentTheme = activeComboRef.current 
    ? COMBO_THEMES[activeComboRef.current] 
    : (THEMES[currentElement as ElementType] || THEMES['NEUTRAL']);

  useEffect(() => {
    const AudioContextClass = (window as any).AudioContext || (window as any).webkitAudioContext;
    if (AudioContextClass) {
        const ctx = new AudioContextClass();
        audioContextRef.current = ctx;

        const bufferSize = ctx.sampleRate * 2; 
        const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
        const data = buffer.getChannelData(0);
        for (let i = 0; i < bufferSize; i++) {
            data[i] = Math.random() * 2 - 1;
        }
        noiseBufferRef.current = buffer;
    }
  }, []);

  const startExperience = () => {
      setHasStarted(true);
      if (audioContextRef.current?.state === 'suspended') {
          audioContextRef.current.resume();
      }
  };

  const playChime = useCallback((element: string) => {
    const ctx = audioContextRef.current;
    if (!ctx || !noiseBufferRef.current) return;
    if (ctx.state === 'suspended') ctx.resume().catch(console.error);

    const now = ctx.currentTime;
    const masterGain = ctx.createGain();
    masterGain.connect(ctx.destination);
    masterGain.gain.setValueAtTime(0.3, now); 

    const playNoise = (filterType: BiquadFilterType, freqStart: number, freqEnd: number, duration: number, vol: number = 1, delay: number = 0) => {
        const src = ctx.createBufferSource();
        src.buffer = noiseBufferRef.current;
        src.loop = true;
        const filter = ctx.createBiquadFilter();
        filter.type = filterType;
        filter.frequency.setValueAtTime(freqStart, now + delay);
        filter.frequency.exponentialRampToValueAtTime(freqEnd, now + delay + duration);
        filter.Q.value = 1;
        const amp = ctx.createGain();
        amp.gain.setValueAtTime(0, now + delay);
        amp.gain.linearRampToValueAtTime(vol, now + delay + 0.05);
        amp.gain.exponentialRampToValueAtTime(0.01, now + delay + duration);
        src.connect(filter);
        filter.connect(amp);
        amp.connect(masterGain);
        src.start(now + delay);
        src.stop(now + delay + duration + 0.2);
    };

    const playTone = (type: OscillatorType, freqStart: number, freqEnd: number, duration: number, vol: number = 1, delay: number = 0) => {
        const osc = ctx.createOscillator();
        osc.type = type;
        osc.frequency.setValueAtTime(freqStart, now + delay);
        if (freqStart !== freqEnd) osc.frequency.exponentialRampToValueAtTime(freqEnd, now + delay + duration);
        const amp = ctx.createGain();
        amp.gain.setValueAtTime(0, now + delay);
        amp.gain.linearRampToValueAtTime(vol, now + delay + 0.05);
        amp.gain.exponentialRampToValueAtTime(0.01, now + delay + duration);
        osc.connect(amp);
        amp.connect(masterGain);
        osc.start(now + delay);
        osc.stop(now + delay + duration + 0.2);
    };

    switch (element) {
        case 'FIRE': playNoise('lowpass', 500, 100, 1.0, 0.5); playTone('sawtooth', 80, 120, 0.8, 0.2); break;
        case 'WATER': playNoise('bandpass', 800, 300, 0.6, 0.4); playTone('sine', 600, 300, 0.4, 0.3, 0.1); break;
        case 'WIND': playNoise('lowpass', 200, 800, 0.4, 0.3); playNoise('highpass', 400, 1000, 0.5, 0.2, 0.1); break;
        case 'THUNDER': playTone('sawtooth', 800, 50, 0.3, 0.2); playNoise('lowpass', 1000, 50, 1.2, 0.6, 0.1); break;
        case 'BLIZZARD': playNoise('highpass', 1000, 3000, 1.5, 0.4); playTone('sine', 1500, 2000, 0.3, 0.1, 0.1); break;
        case 'INFERNO': playNoise('lowpass', 800, 50, 1.5, 0.8); playTone('square', 60, 40, 1.5, 0.2); break;
        case 'TEMPEST': playNoise('lowpass', 200, 50, 2.0, 0.8); playTone('sawtooth', 1200, 100, 0.5, 0.2, 0.1); playNoise('bandpass', 1000, 500, 1.0, 0.3); break;
        case 'VOID': playTone('sine', 50, 40, 2.5, 0.6); playNoise('bandpass', 100, 200, 2.5, 0.4); playTone('sine', 300, 290, 1.0, 0.1, 0.5); break;
        case 'PLASMA': playTone('sawtooth', 200, 800, 1.0, 0.2); playNoise('bandpass', 400, 1200, 1.0, 0.4); break;
        case 'STEAM': playNoise('highpass', 500, 1000, 1.0, 0.3); break;
        default: playTone('triangle', 440, 880, 0.3, 0.1);
    }
  }, []);

  const detectGesture = (landmarks: any[], videoWidth: number, videoHeight: number): ElementType => {
    const mapPt = (idx: number) => ({ x: (1 - landmarks[idx].x) * videoWidth, y: landmarks[idx].y * videoHeight });
    const wrist = mapPt(0);
    const indexTip = mapPt(8);
    const middleTip = mapPt(12);
    const middleMCP = mapPt(9);

    // Optimized Distances
    const distSq = (p1: any, p2: any) => (p1.x - p2.x)**2 + (p1.y - p2.y)**2;
    const isFingerOpen = (tip: any, mcp: any) => distSq(tip, wrist) > distSq(mcp, wrist) * 1.2;

    const isPointingDown = wrist.y < middleMCP.y;
    if (isPointingDown) return 'WATER';

    let openCount = 0;
    if (isFingerOpen(indexTip, mapPt(5))) openCount++;
    if (isFingerOpen(middleTip, mapPt(9))) openCount++;
    if (isFingerOpen(mapPt(16), mapPt(13))) openCount++;
    if (isFingerOpen(mapPt(20), mapPt(17))) openCount++;

    if (openCount >= 4) return 'FIRE';
    if (openCount >= 2) return 'WIND';
    return 'THUNDER';
  };

  const drawSkeleton = (ctx: CanvasRenderingContext2D, hand: HandData) => {
      ctx.strokeStyle = "rgba(255, 255, 255, 0.15)";
      ctx.lineWidth = 1.5;
      ctx.fillStyle = "rgba(255, 255, 255, 0.5)";
      const points = [hand.wrist, hand.indexBase, hand.indexTip, hand.middleBase, hand.middleTip, hand.ringBase, hand.ringTip, hand.pinkyBase, hand.pinkyTip, hand.thumbTip];

      const drawLine = (p1: any, p2: any) => { ctx.beginPath(); ctx.moveTo(p1.x, p1.y); ctx.lineTo(p2.x, p2.y); ctx.stroke(); }
      drawLine(hand.wrist, hand.indexBase); drawLine(hand.indexBase, hand.indexTip);
      drawLine(hand.wrist, hand.middleBase); drawLine(hand.middleBase, hand.middleTip);
      drawLine(hand.wrist, hand.pinkyBase); drawLine(hand.pinkyBase, hand.pinkyTip);

      points.forEach(p => { ctx.beginPath(); ctx.arc(p.x, p.y, 2.5, 0, Math.PI * 2); ctx.fill(); });
  };

  const onResults = useCallback((results: any) => {
    let videoWidth = width;
    let videoHeight = height;
    if (webcamRef.current?.video?.videoWidth) {
        videoWidth = webcamRef.current.video.videoWidth;
        videoHeight = webcamRef.current.video.videoHeight;
    }

    if (results.multiHandLandmarks && results.multiHandLandmarks.length > 0) {
      setDebugInfo(`⚡ 系统就绪 | 检测到 ${results.multiHandLandmarks.length} 只手`);
      const newHandData: HandData[] = results.multiHandLandmarks.map((landmarks: any[]) => {
        const gesture = detectGesture(landmarks, videoWidth, videoHeight);
        const mapPt = (idx: number) => ({ x: (1 - landmarks[idx].x) * videoWidth, y: landmarks[idx].y * videoHeight });
        return {
          wrist: mapPt(0), indexTip: mapPt(8), middleTip: mapPt(12), ringTip: mapPt(16), pinkyTip: mapPt(20), thumbTip: mapPt(4),
          indexBase: mapPt(5), middleBase: mapPt(9), ringBase: mapPt(13), pinkyBase: mapPt(17),
          isOpen: gesture !== 'THUNDER', gesture, opacity: 1,
        };
      });

      handDataRef.current = newHandData;
      let newElement = 'NEUTRAL';
      let activeCombo = null;

      if (newHandData.length === 2) {
          const g1 = newHandData[0].gesture;
          const g2 = newHandData[1].gesture;
          if (g1 !== 'NEUTRAL' && g2 !== 'NEUTRAL') activeCombo = getCombo(g1, g2);
      }

      if (activeCombo) newElement = activeCombo;
      else {
          const activeHand = newHandData.find(h => h.gesture !== 'NEUTRAL');
          if (activeHand) newElement = activeHand.gesture;
      }
      activeComboRef.current = activeCombo;

      if (newElement !== prevElementRef.current) {
          if (newElement !== 'NEUTRAL') { highlightRef.current = 1.0; playChime(newElement); }
          prevElementRef.current = newElement;
      }
      setCurrentElement(newElement);
    } else {
      handDataRef.current = [];
      setDebugInfo("🔍 正在搜索手部信号...");
      activeComboRef.current = null;
      if (prevElementRef.current !== 'NEUTRAL') { prevElementRef.current = 'NEUTRAL'; setCurrentElement('NEUTRAL'); }
    }
  }, [width, height, playChime]);

  useEffect(() => {
    let hands: any = null;
    let isActive = true;
    let frameId: number;
    let lastVideoTime = -1;

    const initHands = async () => {
       if (!(window as any).Hands) { setTimeout(initHands, 500); return; }
       hands = new (window as any).Hands({ locateFile: (file: string) => `https://cdn.jsdelivr.net/npm/@mediapipe/hands@0.4.1675469240/${file}` });
       hands.setOptions({ maxNumHands: 2, modelComplexity: 1, minDetectionConfidence: 0.5, minTrackingConfidence: 0.5 });
       hands.onResults(onResults);
       setIsModelLoaded(true);

       const processVideo = async () => {
         if (!isActive) return;
         if (webcamRef.current && webcamRef.current.video && webcamRef.current.video.readyState === 4) {
             const video = webcamRef.current.video;
             if (video.videoWidth > 0 && video.videoHeight > 0) {
                 if (video.currentTime !== lastVideoTime) {
                     lastVideoTime = video.currentTime;
                     try { await hands.send({ image: video }); } catch (e) { 
                         console.error(e); setDebugInfo("MediaPipe 错误: 刷新页面重试");
                     }
                 }
             }
         }
         frameId = requestAnimationFrame(processVideo);
       };
       processVideo();
    };
    initHands();
    return () => { isActive = false; if (frameId) cancelAnimationFrame(frameId); if (hands) hands.close(); };
  }, [onResults]);

  // --- PHYSICS ENGINE (Optimized) ---
  const updateParticles = (ctx: CanvasRenderingContext2D, width: number, height: number, centerX: number, centerY: number) => {
    // PERFORMANCE: Limit global composite changes inside loop
    ctx.shadowBlur = 0; // Disable shadow blur for particles to increase FPS

    // Get current settings from ref to avoid stale closures in animation loop
    const { glow } = settingsRef.current;

    for (let i = particlesRef.current.length - 1; i >= 0; i--) {
      const p = particlesRef.current[i];

      // Speed Increase: Reduced drag
      p.vx *= 0.98; 
      p.vy *= 0.98;

      switch (p.element) {
          case 'WIND':
          case 'BLIZZARD':
              const dx = p.x - centerX;
              const dy = p.y - centerY;
              const dist = Math.sqrt(dx*dx + dy*dy) + 1;
              const angle = Math.atan2(dy, dx);
              p.vx += Math.cos(angle + Math.PI/2) * 2.5; // Faster rotation
              p.vy += Math.sin(angle + Math.PI/2) * 2.5;
              p.vx -= (dx / dist) * 0.8;
              p.vy -= (dy / dist) * 0.8;
              p.angle += p.angularVelocity * 1.5; 
              break;

          case 'WATER':
          case 'STEAM':
              p.vy += 1.5; // Heavier gravity
              p.x += Math.sin(p.life * 0.2) * 1.0;
              break;

          case 'THUNDER':
          case 'TEMPEST':
          case 'VOID':
              p.vx += (Math.random() - 0.5) * 6; // More chaos
              p.vy += (Math.random() - 0.5) * 6;
              if (Math.random() < 0.15) {
                  p.x += (Math.random() - 0.5) * 40;
                  p.y += (Math.random() - 0.5) * 40;
              }
              break;

          case 'FIRE':
          case 'INFERNO':
              p.vy -= 1.0; // Faster rise
              p.vx += (Math.random() - 0.5) * 2.0;
              p.size *= 0.95; 
              break;

          default:
              p.vy -= 0.2;
      }

      p.x += p.vx;
      p.y += p.vy;
      p.life -= 1;
      if (p.element !== 'FIRE') p.size *= 0.98;

      if (p.life <= 0 || p.size < 0.1 || p.y > height + 50 || p.y < -50 || p.x < -50 || p.x > width + 50) {
        particlesRef.current.splice(i, 1);
      } else {
        ctx.save();

        // --- DYNAMIC SHADOWS (Fake 3D) ---
        if (p.size > 2) {
             const shadowOffsetX = (p.x - centerX) * 0.05;
             const shadowOffsetY = (p.y - centerY) * 0.05;
             ctx.fillStyle = "rgba(0,0,0,0.3)";
             ctx.beginPath();
             ctx.arc(p.x + shadowOffsetX, p.y + shadowOffsetY, p.size * glow, 0, Math.PI*2);
             ctx.fill();
        }

        ctx.globalAlpha = Math.min(1, p.life / 10, (p.maxLife - p.life) / 5);

        // Apply GLOW multiplier to size or line width
        const renderSize = p.size * glow;

        if (p.type === 'LEAF') {
            ctx.translate(p.x, p.y);
            ctx.rotate(p.angle);
            ctx.fillStyle = p.color;
            ctx.beginPath();
            ctx.ellipse(0, 0, renderSize, renderSize * 0.4, 0, 0, Math.PI * 2);
            ctx.fill();
        } 
        else if (p.type === 'DROP') {
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 2.5 * glow;
            ctx.lineCap = 'round';
            ctx.beginPath();
            ctx.moveTo(p.x, p.y);
            ctx.lineTo(p.x - p.vx * 1.5, p.y - p.vy * 4); // Longer streaks
            ctx.stroke();
        }
        else if (p.type === 'SPARK') {
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 2 * glow;
            ctx.beginPath();
            ctx.moveTo(p.x - p.vx, p.y - p.vy);
            ctx.lineTo(p.x + p.vx, p.y + p.vy);
            ctx.stroke();
        }
        else {
            ctx.fillStyle = p.color;
            ctx.beginPath();
            ctx.arc(p.x, p.y, renderSize, 0, Math.PI * 2);
            ctx.fill();
        }
        ctx.restore();
      }
    }
  };

  const spawnParticles = (x: number, y: number, element: string, theme: Theme) => {
    // Get current settings
    const { speed: speedMulti, count: countMulti } = settingsRef.current;

    const isCombo = activeComboRef.current !== null;
    let baseCount = isCombo ? 10 : 3;
    let count = Math.ceil(baseCount * countMulti);

    let type: ParticleType = 'ORB';
    // Increased base speed multiplied by user setting
    let speed = (Math.random() * 8 + 4) * speedMulti; 
    let spread = 30;

    if (element === 'WIND' || element === 'BLIZZARD') {
        type = Math.random() > 0.5 ? 'LEAF' : 'MIST';
        if (isCombo) count += 5;
    } else if (element === 'WATER' || element === 'STEAM') {
        type = Math.random() > 0.7 ? 'MIST' : 'DROP';
        if (isCombo) count += 8;
        spread = 50; 
    } else if (element === 'THUNDER' || element === 'TEMPEST' || element === 'VOID') {
        type = 'SPARK';
        if (isCombo) count += 4;
        speed = 12 * speedMulti; // Very fast sparks
    } else if (element === 'FIRE' || element === 'INFERNO') {
        type = Math.random() > 0.8 ? 'MIST' : 'EMBER';
        if (isCombo) count += 5;
    }

    // Limit max particles per frame to prevent freezing
    count = Math.min(count, 50);

    for (let i = 0; i < count; i++) {
      const angle = Math.random() * Math.PI * 2;
      let vx = Math.cos(angle) * speed;
      let vy = Math.sin(angle) * speed;

      if (element === 'WATER' || element === 'STEAM') { vx *= 0.3; vy = Math.random() * 5 * speedMulti + 5; } 

      let color = Math.random() > 0.5 ? theme.primary : theme.secondary;
      if (element === 'WIND') color = Math.random() > 0.5 ? '#00FFFF' : '#F0FFF0'; 
      if (element === 'THUNDER') color = Math.random() > 0.5 ? '#FFFF00' : '#9400D3';

      let spawnX = x;
      let spawnY = y;

      if (isCombo || element === 'WATER') {
          spawnX = Math.random() * width;
          if (element === 'WATER' || element === 'TEMPEST') {
             spawnY = Math.random() * -100;
          } else {
             spawnY = Math.random() * height;
          }
      } else {
          spawnX = x + (Math.random() - 0.5) * spread;
          spawnY = y + (Math.random() - 0.5) * spread;
      }

      particlesRef.current.push({
        x: spawnX,
        y: spawnY,
        vx, vy,
        life: 30 + Math.random() * 30, // Shorter life for snappier feel
        maxLife: 60,
        size: 4 + Math.random() * 6, // Slightly larger
        color,
        element: element as Particle['element'],
        type,
        angle: Math.random() * Math.PI * 2,
        angularVelocity: (Math.random() - 0.5) * 0.4
      });
    }
  };

  const animate = useCallback((time: number) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d', { alpha: false }); // Optimization: alpha false
    if (!ctx) return;

    // HIGH DPI SCALING
    const dpr = window.devicePixelRatio || 1;
    if (canvas.width !== width * dpr || canvas.height !== height * dpr) {
        canvas.width = width * dpr;
        canvas.height = height * dpr;
    }
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

    // 1. Draw Background (Clear)
    // Use the Theme Background variable directly for canvas fill
    const theme = activeComboRef.current 
        ? COMBO_THEMES[activeComboRef.current] 
        : (THEMES[currentElement as ElementType] || THEMES['NEUTRAL']);

    ctx.fillStyle = theme.background;
    ctx.fillRect(0, 0, width, height);

    if (highlightRef.current > 0.01) highlightRef.current *= 0.9;
    else highlightRef.current = 0;
    const flash = highlightRef.current;

    let lastCenterX = width / 2;
    let lastCenterY = height / 2;
    const t = time * 0.001;
    const comboName = activeComboRef.current;

    // --- DETERMINE CENTER ---
    if (comboName && handDataRef.current.length === 2) {
         lastCenterX = (handDataRef.current[0].middleBase.x + handDataRef.current[1].middleBase.x) / 2;
         lastCenterY = (handDataRef.current[0].middleBase.y + handDataRef.current[1].middleBase.y) / 2;
    } else if (handDataRef.current.length > 0) {
        // Find active hand or just first hand
        const active = handDataRef.current.find(h => h.gesture !== 'NEUTRAL') || handDataRef.current[0];
        lastCenterX = active.middleBase.x;
        lastCenterY = active.middleBase.y;
    }

    // REMOVED: drawDynamicLighting call to prevent white circle overlay

    // 3. Geometry & Particles
    ctx.globalCompositeOperation = 'lighter'; 

    if (comboName && handDataRef.current.length === 2) {
        // --- COMBO MODE ---
        const h1 = handDataRef.current[0];
        const h2 = handDataRef.current[1];

        const midX = lastCenterX;
        const midY = lastCenterY;

        ctx.save();
        ctx.beginPath();
        ctx.moveTo(h1.middleBase.x, h1.middleBase.y);
        ctx.lineTo(h2.middleBase.x, h2.middleBase.y);
        ctx.strokeStyle = theme.primary;
        ctx.lineWidth = 20 + Math.sin(t * 10) * 5; 
        ctx.lineCap = 'round';
        ctx.shadowBlur = 20; // Reduced blur
        ctx.shadowColor = theme.secondary;
        ctx.globalAlpha = 0.4;
        ctx.stroke();
        ctx.restore();

        ctx.save();
        ctx.beginPath();
        ctx.moveTo(h1.middleBase.x, h1.middleBase.y);
        ctx.lineTo(h2.middleBase.x, h2.middleBase.y);
        ctx.strokeStyle = '#FFFFFF';
        ctx.lineWidth = 3;
        ctx.setLineDash([10, 40]);
        ctx.lineDashOffset = -t * 200; 
        ctx.globalCompositeOperation = 'overlay';
        ctx.stroke();
        ctx.restore();

        // Arcs
        ctx.save();
        ctx.beginPath();
        ctx.moveTo(h1.middleBase.x, h1.middleBase.y);
        const dist = Math.hypot(h2.middleBase.x - h1.middleBase.x, h2.middleBase.y - h1.middleBase.y);
        const angle = Math.atan2(h2.middleBase.y - h1.middleBase.y, h2.middleBase.x - h1.middleBase.x);
        for(let i=0; i<=10; i++) { // Reduced segments
             const p = i/10;
             const perp = Math.sin(p * Math.PI * 4 + t * 20) * (15 + Math.random() * 5);
             const bx = h1.middleBase.x + (h2.middleBase.x - h1.middleBase.x) * p + Math.cos(angle + Math.PI/2)*perp;
             const by = h1.middleBase.y + (h2.middleBase.y - h1.middleBase.y) * p + Math.sin(angle + Math.PI/2)*perp;
             ctx.lineTo(bx, by);
        }
        ctx.strokeStyle = theme.secondary;
        ctx.lineWidth = 2;
        ctx.stroke();
        ctx.restore();

        ctx.globalAlpha = 1;
        drawRuneRing(ctx, midX, midY, 180, t, theme);
        drawSacredGeometry(ctx, midX, midY, 140, -t * 2, theme);
        drawSquareLayer(ctx, midX, midY, 100, t * 3, theme);
        drawPentagram(ctx, midX, midY, 60, -t, 1, theme);

        spawnParticles(midX, midY, comboName, theme);

        handDataRef.current.forEach(h => {
             drawSkeleton(ctx, h);
             const auraSize = 50 + Math.sin(t * 20) * 10;
             const grad = ctx.createRadialGradient(h.middleBase.x, h.middleBase.y, 10, h.middleBase.x, h.middleBase.y, auraSize);
             grad.addColorStop(0, theme.core);
             grad.addColorStop(0.4, theme.primary);
             grad.addColorStop(1, 'rgba(0,0,0,0)');
             ctx.save();
             ctx.fillStyle = grad;
             ctx.globalAlpha = 0.5;
             ctx.beginPath();
             ctx.arc(h.middleBase.x, h.middleBase.y, auraSize, 0, Math.PI * 2);
             ctx.fill();
             ctx.restore();
             drawRuneRing(ctx, h.middleBase.x, h.middleBase.y, 40, t*5, theme);
        });

    } else {
        // --- INDIVIDUAL MODE ---
        handDataRef.current.forEach((hand) => {
           drawSkeleton(ctx, hand);
           const element = hand.gesture;
           const handTheme = (element !== 'NEUTRAL' && THEMES[element]) ? THEMES[element] : THEMES['NEUTRAL'];
           const centerX = hand.middleBase.x; 
           const centerY = hand.middleBase.y; 

           if (element !== 'NEUTRAL') {
               if (flash > 0.05 && highlightRef.current > 0.05) {
                   ctx.save();
                   ctx.translate(centerX, centerY);
                   const waveSize = 120 + (1 - flash) * 100;
                   ctx.beginPath();
                   ctx.arc(0, 0, waveSize, 0, Math.PI * 2);
                   ctx.lineWidth = 10 * flash;
                   ctx.strokeStyle = handTheme.core;
                   ctx.shadowBlur = 20;
                   ctx.shadowColor = handTheme.secondary;
                   ctx.globalAlpha = flash;
                   ctx.stroke();
                   ctx.restore();
               }

               drawRuneRing(ctx, centerX, centerY, 120, t * 0.5, handTheme);
               drawSacredGeometry(ctx, centerX, centerY, 90, -t * 1.5, handTheme);
               drawSquareLayer(ctx, centerX, centerY, 65, t * 2.5, handTheme);
               const pulse = Math.sin(time * 0.005) * 0.5 + 0.5;
               drawPentagram(ctx, centerX, centerY, 40, t, pulse, handTheme);

               spawnParticles(centerX, centerY, element, handTheme);
           } else {
               ctx.globalAlpha = 0.3;
               drawRuneRing(ctx, centerX, centerY, 50, t * 0.2, handTheme);
           }
        });
    }

    updateParticles(ctx, width, height, lastCenterX, lastCenterY);
    requestRef.current = requestAnimationFrame(animate);
  }, [width, height, currentElement]);

  useEffect(() => {
    requestRef.current = requestAnimationFrame(animate);
    return () => { if (requestRef.current) cancelAnimationFrame(requestRef.current); };
  }, [animate]);

  return (
    <div className="relative w-full h-full overflow-hidden flex items-center justify-center font-sans">

        {/* Dynamic Background */}
        <div 
            className="absolute inset-0 transition-colors duration-700 ease-in-out z-0"
            style={{ backgroundColor: currentTheme.background }}
        />

        {/* Hidden Webcam */}
