import React, { useEffect, useRef, useCallback, useState } from 'react';
import Webcam from 'react-webcam';
import { Particle, HandData, ElementType, Theme, ParticleType } from '../types';
import { 
  drawRuneRing, 
  drawSacredGeometry, 
  drawSquareLayer, 
  drawPentagram,
  THEMES
} from '../utils/geometry';

interface MagicOverlayProps {
  width: number;
  height: number;
}

const COMBO_THEMES: Record<string, Theme> = {
  'BLIZZARD': { primary: '#00FFFF', secondary: '#E0FFFF', core: '#FFFFFF', shadow: '#008B8B', background: '#0a1a20' }, 
  'PLASMA': { primary: '#FF00FF', secondary: '#00FFFF', core: '#FFFFFF', shadow: '#9400D3', background: '#1a051a' }, 
  'STEAM': { primary: '#F0F8FF', secondary: '#B0C4DE', core: '#FFFFFF', shadow: '#778899', background: '#10151a' }, 
  'TEMPEST': { primary: '#000080', secondary: '#8A2BE2', core: '#FFFF00', shadow: '#191970', background: '#05051a' }, 
  'INFERNO': { primary: '#FF0000', secondary: '#FF4500', core: '#FFFF00', shadow: '#8B0000', background: '#2a0500' }, 
  'VOID': { primary: '#000000', secondary: '#4B0082', core: '#FFFFFF', shadow: '#9400D3', background: '#000000' }, 
};

const ELEMENT_NAMES_CN: Record<string, string> = {
    'NEUTRAL': '等待施法...',
    'FIRE': '🔥 烈焰术 (FIRE)',
    'WATER': '💧 唤雨术 (WATER)',
    'THUNDER': '⚡ 雷霆术 (THUNDER)',
    'WIND': '🌪️ 疾风术 (WIND)',
    'BLIZZARD': '❄️ 极寒风暴 (BLIZZARD)',
    'PLASMA': '⚛️ 等离子破 (PLASMA)',
    'STEAM': '♨️ 灼热蒸汽 (STEAM)',
    'TEMPEST': '⛈️ 雷暴风眼 (TEMPEST)',
    'INFERNO': '🌋 地狱烈火 (INFERNO)',
    'VOID': '🌌 虚空奇点 (VOID)'
};

const getCombo = (g1: ElementType, g2: ElementType): string | null => {
    const sorted = [g1, g2].sort().join('_');
    switch(sorted) {
        case 'WATER_WIND': return 'BLIZZARD';
        case 'FIRE_WIND': return 'PLASMA';
        case 'FIRE_WATER': return 'STEAM';
        case 'THUNDER_WATER': return 'TEMPEST';
        case 'FIRE_FIRE': return 'INFERNO';
        case 'THUNDER_THUNDER': return 'VOID';
        default: return null;
    }
};

const MagicOverlay: React.FC<MagicOverlayProps> = ({ width, height }) => {
  const webcamRef = useRef<Webcam>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>(0);
  const particlesRef = useRef<Particle[]>([]);
  const handDataRef = useRef<HandData[]>([]);
  const [currentElement, setCurrentElement] = useState<string>('NEUTRAL');
  const [isModelLoaded, setIsModelLoaded] = useState(false);
  const [loadingError, setLoadingError] = useState<string | null>(null);
  const [debugInfo, setDebugInfo] = useState<string>("初始化系统...");
  const [hasStarted, setHasStarted] = useState(false);
  const [showControls, setShowControls] = useState(true);
  const [isCameraReady, setCameraReady] = useState(false);

  // Settings State
  const [settings, setSettings] = useState({
      speed: 1.5,   // Base speed multiplier
      count: 1.2,   // Particle count multiplier
      glow: 1.2,    // Glow/Size intensity
  });

  // Settings Ref (for access inside animation loop without stale closures)
  const settingsRef = useRef(settings);
  useEffect(() => { settingsRef.current = settings; }, [settings]);

  // Visual Feedback State
  const highlightRef = useRef<number>(0);
  const prevElementRef = useRef<string>('NEUTRAL');
  const activeComboRef = useRef<string | null>(null);

  // Audio Context
  const audioContextRef = useRef<AudioContext | null>(null);
  const noiseBufferRef = useRef<AudioBuffer | null>(null);

  // Get current Theme for background
  const currentTheme = activeComboRef.current 
    ? COMBO_THEMES[activeComboRef.current] 
    : (THEMES[currentElement as ElementType] || THEMES['NEUTRAL']);

  useEffect(() => {
    const AudioContextClass = (window as any).AudioContext || (window as any).webkitAudioContext;
    if (AudioContextClass) {
        const ctx = new AudioContextClass();
        audioContextRef.current = ctx;

        const bufferSize = ctx.sampleRate * 2; 
        const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
        const data = buffer.getChannelData(0);
        for (let i = 0; i < bufferSize; i++) {
            data[i] = Math.random() * 2 - 1;
        }
        noiseBufferRef.current = buffer;
    }
  }, []);

  const startExperience = () => {
      setHasStarted(true);
      if (audioContextRef.current?.state === 'suspended') {
          audioContextRef.current.resume();
      }
  };

  const playChime = useCallback((element: string) => {
    const ctx = audioContextRef.current;
    if (!ctx || !noiseBufferRef.current) return;
    if (ctx.state === 'suspended') ctx.resume().catch(console.error);

    const now = ctx.currentTime;
    const masterGain = ctx.createGain();
    masterGain.connect(ctx.destination);
    masterGain.gain.setValueAtTime(0.3, now); 

    const playNoise = (filterType: BiquadFilterType, freqStart: number, freqEnd: number, duration: number, vol: number = 1, delay: number = 0) => {
        const src = ctx.createBufferSource();
        src.buffer = noiseBufferRef.current;
        src.loop = true;
        const filter = ctx.createBiquadFilter();
        filter.type = filterType;
        filter.frequency.setValueAtTime(freqStart, now + delay);
        filter.frequency.exponentialRampToValueAtTime(freqEnd, now + delay + duration);
        filter.Q.value = 1;
        const amp = ctx.createGain();
        amp.gain.setValueAtTime(0, now + delay);
        amp.gain.linearRampToValueAtTime(vol, now + delay + 0.05);
        amp.gain.exponentialRampToValueAtTime(0.01, now + delay + duration);
        src.connect(filter);
        filter.connect(amp);
        amp.connect(masterGain);
        src.start(now + delay);
        src.stop(now + delay + duration + 0.2);
    };

    const playTone = (type: OscillatorType, freqStart: number, freqEnd: number, duration: number, vol: number = 1, delay: number = 0) => {
        const osc = ctx.createOscillator();
        osc.type = type;
        osc.frequency.setValueAtTime(freqStart, now + delay);
        if (freqStart !== freqEnd) osc.frequency.exponentialRampToValueAtTime(freqEnd, now + delay + duration);
        const amp = ctx.createGain();
        amp.gain.setValueAtTime(0, now + delay);
        amp.gain.linearRampToValueAtTime(vol, now + delay + 0.05);
        amp.gain.exponentialRampToValueAtTime(0.01, now + delay + duration);
        osc.connect(amp);
        amp.connect(masterGain);
        osc.start(now + delay);
        osc.stop(now + delay + duration + 0.2);
    };

    switch (element) {
        case 'FIRE': playNoise('lowpass', 500, 100, 1.0, 0.5); playTone('sawtooth', 80, 120, 0.8, 0.2); break;
        case 'WATER': playNoise('bandpass', 800, 300, 0.6, 0.4); playTone('sine', 600, 300, 0.4, 0.3, 0.1); break;
        case 'WIND': playNoise('lowpass', 200, 800, 0.4, 0.3); playNoise('highpass', 400, 1000, 0.5, 0.2, 0.1); break;
        case 'THUNDER': playTone('sawtooth', 800, 50, 0.3, 0.2); playNoise('lowpass', 1000, 50, 1.2, 0.6, 0.1); break;
        case 'BLIZZARD': playNoise('highpass', 1000, 3000, 1.5, 0.4); playTone('sine', 1500, 2000, 0.3, 0.1, 0.1); break;
        case 'INFERNO': playNoise('lowpass', 800, 50, 1.5, 0.8); playTone('square', 60, 40, 1.5, 0.2); break;
        case 'TEMPEST': playNoise('lowpass', 200, 50, 2.0, 0.8); playTone('sawtooth', 1200, 100, 0.5, 0.2, 0.1); playNoise('bandpass', 1000, 500, 1.0, 0.3); break;
        case 'VOID': playTone('sine', 50, 40, 2.5, 0.6); playNoise('bandpass', 100, 200, 2.5, 0.4); playTone('sine', 300, 290, 1.0, 0.1, 0.5); break;
        case 'PLASMA': playTone('sawtooth', 200, 800, 1.0, 0.2); playNoise('bandpass', 400, 1200, 1.0, 0.4); break;
        case 'STEAM': playNoise('highpass', 500, 1000, 1.0, 0.3); break;
        default: playTone('triangle', 440, 880, 0.3, 0.1);
    }
  }, []);

  const detectGesture = (landmarks: any[], videoWidth: number, videoHeight: number): ElementType => {
    const mapPt = (idx: number) => ({ x: (1 - landmarks[idx].x) * videoWidth, y: landmarks[idx].y * videoHeight });
    const wrist = mapPt(0);
    const indexTip = mapPt(8);
    const middleTip = mapPt(12);
    const middleMCP = mapPt(9);

    // Optimized Distances
    const distSq = (p1: any, p2: any) => (p1.x - p2.x)**2 + (p1.y - p2.y)**2;
    const isFingerOpen = (tip: any, mcp: any) => distSq(tip, wrist) > distSq(mcp, wrist) * 1.2;

    const isPointingDown = wrist.y < middleMCP.y;
    if (isPointingDown) return 'WATER';

    let openCount = 0;
    if (isFingerOpen(indexTip, mapPt(5))) openCount++;
    if (isFingerOpen(middleTip, mapPt(9))) openCount++;
    if (isFingerOpen(mapPt(16), mapPt(13))) openCount++;
    if (isFingerOpen(mapPt(20), mapPt(17))) openCount++;

    if (openCount >= 4) return 'FIRE';
    if (openCount >= 2) return 'WIND';
    return 'THUNDER';
  };

  const drawSkeleton = (ctx: CanvasRenderingContext2D, hand: HandData) => {
      ctx.strokeStyle = "rgba(255, 255, 255, 0.15)";
      ctx.lineWidth = 1.5;
      ctx.fillStyle = "rgba(255, 255, 255, 0.5)";
      const points = [hand.wrist, hand.indexBase, hand.indexTip, hand.middleBase, hand.middleTip, hand.ringBase, hand.ringTip, hand.pinkyBase, hand.pinkyTip, hand.thumbTip];

      const drawLine = (p1: any, p2: any) => { ctx.beginPath(); ctx.moveTo(p1.x, p1.y); ctx.lineTo(p2.x, p2.y); ctx.stroke(); }
      drawLine(hand.wrist, hand.indexBase); drawLine(hand.indexBase, hand.indexTip);
      drawLine(hand.wrist, hand.middleBase); drawLine(hand.middleBase, hand.middleTip);
      drawLine(hand.wrist, hand.pinkyBase); drawLine(hand.pinkyBase, hand.pinkyTip);

      points.forEach(p => { ctx.beginPath(); ctx.arc(p.x, p.y, 2.5, 0, Math.PI * 2); ctx.fill(); });
  };

  const onResults = useCallback((results: any) => {
    // Force use of full canvas/window dimensions for coordinate mapping
    // This fixes the issue where interactions were limited to the left side 
    // if the webcam source resolution (e.g. 640x480) was smaller than the screen.
    const displayWidth = width;
    const displayHeight = height;

    // Lift the loading curtain on first successful result
    setIsModelLoaded((prev) => {
        if (!prev) return true;
        return prev;
    });

    if (results.multiHandLandmarks && results.multiHandLandmarks.length > 0) {
      setDebugInfo(`⚡ 系统就绪 | 检测到 ${results.multiHandLandmarks.length} 只手`);
      const newHandData: HandData[] = results.multiHandLandmarks.map((landmarks: any[]) => {
        const gesture = detectGesture(landmarks, displayWidth, displayHeight);
        // Map normalized coordinates (0-1) directly to screen dimensions
        const mapPt = (idx: number) => ({ x: (1 - landmarks[idx].x) * displayWidth, y: landmarks[idx].y * displayHeight });
        return {
          wrist: mapPt(0), indexTip: mapPt(8), middleTip: mapPt(12), ringTip: mapPt(16), pinkyTip: mapPt(20), thumbTip: mapPt(4),
          indexBase: mapPt(5), middleBase: mapPt(9), ringBase: mapPt(13), pinkyBase: mapPt(17),
          isOpen: gesture !== 'THUNDER', gesture, opacity: 1,
        };
      });

      handDataRef.current = newHandData;
      let newElement = 'NEUTRAL';
      let activeCombo = null;

      if (newHandData.length === 2) {
          const g1 = newHandData[0].gesture;
          const g2 = newHandData[1].gesture;
          if (g1 !== 'NEUTRAL' && g2 !== 'NEUTRAL') activeCombo = getCombo(g1, g2);
      }

      if (activeCombo) newElement = activeCombo;
      else {
          const activeHand = newHandData.find(h => h.gesture !== 'NEUTRAL');
          if (activeHand) newElement = activeHand.gesture;
      }
      activeComboRef.current = activeCombo;

      if (newElement !== prevElementRef.current) {
          if (newElement !== 'NEUTRAL') { highlightRef.current = 1.0; playChime(newElement); }
          prevElementRef.current = newElement;
      }
      setCurrentElement(newElement);
    } else {
      handDataRef.current = [];
      setDebugInfo("🔍 正在搜索手部信号...");
      activeComboRef.current = null;
      if (prevElementRef.current !== 'NEUTRAL') { prevElementRef.current = 'NEUTRAL'; setCurrentElement('NEUTRAL'); }
    }
  }, [width, height, playChime]);

  useEffect(() => {
    let hands: any = null;
    let isActive = true;
    let frameId: number;
    let lastVideoTime = -1;

    // PINNED VERSION to ensure compatibility between JS and WASM
    const MP_VERSION = "0.4.1675469240";

    const initHands = async () => {
       try {
           setDebugInfo("正在加载 AI 核心 (1/3)...");
           if (!(window as any).Hands) { 
               // Retry logic if script hasn't loaded yet
               setTimeout(initHands, 500); 
               return; 
           }

           setDebugInfo("初始化视觉模型 (2/3)...");
           hands = new (window as any).Hands({ 
               locateFile: (file: string) => `https://cdn.jsdelivr.net/npm/@mediapipe/hands@${MP_VERSION}/${file}` 
           });

           hands.setOptions({ 
               maxNumHands: 2, 
               modelComplexity: 1, 
               minDetectionConfidence: 0.5, 
               minTrackingConfidence: 0.5 
           });

           hands.onResults(onResults);

           setDebugInfo("等待摄像头许可...");

           const processVideo = async () => {
             if (!isActive) return;
             if (webcamRef.current && webcamRef.current.video && webcamRef.current.video.readyState === 4) {
                 const video = webcamRef.current.video;
                 if (video.videoWidth > 0 && video.videoHeight > 0) {
                     if (video.currentTime !== lastVideoTime) {
                         lastVideoTime = video.currentTime;
                         try { 
                             setDebugInfo("正在处理视频流...");
                             await hands.send({ image: video }); 
                         } catch (e) { 
                             console.warn("Processing warning", e); 
                         }
                     }
                 }
             }
             frameId = requestAnimationFrame(processVideo);
           };
           processVideo();
       } catch (error: any) {
           console.error("Initialization Error:", error);
           setLoadingError("AI 模型加载失败: " + error.message);
           setDebugInfo("系统错误");
       }
    };

    // Small delay to ensure script tag in index.html has started loading
    setTimeout(initHands, 500);

    return () => { isActive = false; if (frameId) cancelAnimationFrame(frameId); if (hands) hands.close(); };
  }, [onResults]);

  // --- PHYSICS ENGINE (Optimized) ---
  const updateParticles = (ctx: CanvasRenderingContext2D, width: number, height: number, centerX: number, centerY: number) => {
    // PERFORMANCE: Limit global composite changes inside loop
    ctx.shadowBlur = 0; // Disable shadow blur for particles to increase FPS

    // Get current settings from ref to avoid stale closures in animation loop
    const { glow } = settingsRef.current;

    for (let i = particlesRef.current.length - 1; i >= 0; i--) {
      const p = particlesRef.current[i];

      // Speed Increase & Drag Logic
      if (p.element === 'WIND' || p.element === 'BLIZZARD') {
          // Less drag for wind elements so they travel further
          p.vx *= 0.995; 
          p.vy *= 0.995;
      } else {
          // Standard drag
          p.vx *= 0.98; 
          p.vy *= 0.98;
      }

      switch (p.element) {
          case 'WIND':
          case 'BLIZZARD':
              const dx = p.x - centerX;
              const dy = p.y - centerY;
              const dist = Math.sqrt(dx*dx + dy*dy) + 1;
              const angle = Math.atan2(dy, dx);
              p.vx += Math.cos(angle + Math.PI/2) * 2.5; // Faster rotation
              p.vy += Math.sin(angle + Math.PI/2) * 2.5;
              p.vx -= (dx / dist) * 0.8;
              p.vy -= (dy / dist) * 0.8;
              p.angle += p.angularVelocity * 1.5; 
              break;

          case 'WATER':
          case 'STEAM':
              p.vy += 1.5; // Heavier gravity
              p.x += Math.sin(p.life * 0.2) * 1.0;
              break;

          case 'THUNDER':
          case 'TEMPEST':
          case 'VOID':
              p.vx += (Math.random() - 0.5) * 6; // More chaos
              p.vy += (Math.random() - 0.5) * 6;
              if (Math.random() < 0.15) {
                  p.x += (Math.random() - 0.5) * 40;
                  p.y += (Math.random() - 0.5) * 40;
              }
              break;

          case 'FIRE':
          case 'INFERNO':
              p.vy -= 1.5; // Increased upward velocity (was 1.0)
              p.vx += (Math.random() - 0.5) * 2.0;
              p.size *= 0.95; 
              break;

          default:
              p.vy -= 0.2;
      }

      p.x += p.vx;
      p.y += p.vy;
      p.life -= 1;
      if (p.element !== 'FIRE') p.size *= 0.98;

      if (p.life <= 0 || p.size < 0.1 || p.y > height + 50 || p.y < -50 || p.x < -50 || p.x > width + 50) {
        particlesRef.current.splice(i, 1);
      } else {
        ctx.save();

        // --- DYNAMIC SHADOWS (Fake 3D) ---
        if (p.size > 2) {
             const shadowOffsetX = (p.x - centerX) * 0.05;
             const shadowOffsetY = (p.y - centerY) * 0.05;
             ctx.fillStyle = "rgba(0,0,0,0.3)";
             ctx.beginPath();
             ctx.arc(p.x + shadowOffsetX, p.y + shadowOffsetY, p.size * glow, 0, Math.PI*2);
             ctx.fill();
        }

        // Calculate opacity
        let alpha = Math.min(1, p.life / 10, (p.maxLife - p.life) / 5);

        // Add flickering for small FIRE embers
        if ((p.element === 'FIRE' || p.element === 'INFERNO') && p.size < 3.5 && p.type === 'EMBER') {
             alpha *= (0.5 + Math.random() * 0.5);
        }

        ctx.globalAlpha = alpha;

        // Apply GLOW multiplier to size or line width
        const renderSize = p.size * glow;

        if (p.type === 'LEAF') {
            ctx.translate(p.x, p.y);
            ctx.rotate(p.angle);
            ctx.fillStyle = p.color;
            ctx.beginPath();
            ctx.ellipse(0, 0, renderSize, renderSize * 0.4, 0, 0, Math.PI * 2);
            ctx.fill();
        } 
        else if (p.type === 'DROP') {
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 2.5 * glow;
            ctx.lineCap = 'round';
            ctx.beginPath();
            ctx.moveTo(p.x, p.y);
            ctx.lineTo(p.x - p.vx * 1.5, p.y - p.vy * 4); // Longer streaks
            ctx.stroke();
        }
        else if (p.type === 'SPARK') {
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 2 * glow;
            ctx.beginPath();
            ctx.moveTo(p.x - p.vx, p.y - p.vy);
            ctx.lineTo(p.x + p.vx, p.y + p.vy);
            ctx.stroke();
        }
        else {
            ctx.fillStyle = p.color;
            ctx.beginPath();
            ctx.arc(p.x, p.y, renderSize, 0, Math.PI * 2);
            ctx.fill();
        }
        ctx.restore();
      }
    }
  };

  const spawnParticles = (x: number, y: number, element: string, theme: Theme) => {
    // Get current settings
    const { speed: speedMulti, count: countMulti } = settingsRef.current;

    const isCombo = activeComboRef.current !== null;
    let baseCount = isCombo ? 10 : 3;
    let count = Math.ceil(baseCount * countMulti);

    // Limit max particles per frame to prevent freezing
    count = Math.min(count, 50);

    for (let i = 0; i < count; i++) {
        // Defaults
        let type: ParticleType = 'ORB';
        // Increased base speed multiplied by user setting
        let speed = (Math.random() * 8 + 4) * speedMulti; 
        let spread = 30;
        let pColor = Math.random() > 0.5 ? theme.primary : theme.secondary;
        let pSize = 4 + Math.random() * 6;
        let pLife = 30 + Math.random() * 30;

        // Determine properties based on element (MIXING logic moved inside loop)
        if (element === 'WIND' || element === 'BLIZZARD') {
            type = Math.random() > 0.5 ? 'LEAF' : 'MIST';
            if (isCombo) pColor = Math.random() > 0.5 ? '#00FFFF' : '#F0FFF0';
            else if (element === 'WIND') pColor = Math.random() > 0.5 ? '#00FFFF' : '#F0FFF0'; 
        } else if (element === 'WATER' || element === 'STEAM') {
            type = Math.random() > 0.7 ? 'MIST' : 'DROP';
            spread = 50; 
        } else if (element === 'THUNDER' || element === 'TEMPEST' || element === 'VOID') {
            type = 'SPARK';
            speed = 12 * speedMulti; // Very fast sparks
            if (element === 'THUNDER') pColor = Math.random() > 0.5 ? '#FFFF00' : '#9400D3';
        } else if (element === 'FIRE' || element === 'INFERNO') {
            // FIRE LOGIC MIX: Mist (Smoke), Ember (Flame), Ember (Sparks)
            const r = Math.random();
            if (r < 0.3) {
                 // Fast, small, bright embers (New flickering particles)
                 type = 'EMBER';
                 pColor = Math.random() > 0.5 ? '#FFD700' : '#FFFFFF'; // Gold/White
                 pSize = 1 + Math.random() * 3;
                 pLife = 15 + Math.random() * 20; // Shorter life
                 speed *= 1.5; // Faster
            } else if (r < 0.6) {
                 type = 'MIST'; // Smoke
            } else {
                 type = 'EMBER'; // Main flame
            }
        }

        const angle = Math.random() * Math.PI * 2;
        let vx = Math.cos(angle) * speed;
        let vy = Math.sin(angle) * speed;

        if (element === 'WATER' || element === 'STEAM') { vx *= 0.3; vy = Math.random() * 5 * speedMulti + 5; } 
        // Embers float up faster
        if ((element === 'FIRE' || element === 'INFERNO') && pSize < 4 && type === 'EMBER') {
            vy -= 2.0; 
        }

        let spawnX = x;
        let spawnY = y;

        // Custom spread logic
        if (element === 'WATER' || element === 'STEAM') {
             spawnX = x + (Math.random() - 0.5) * spread;
             spawnY = y + (Math.random() - 0.5) * spread;
        } else {
             spawnX = x + (Math.random() - 0.5) * spread;
             spawnY = y + (Math.random() - 0.5) * spread;
        }

        if (isCombo || element === 'WATER') {
            spawnX = Math.random() * width;
            if (element === 'WATER' || element === 'TEMPEST') {
               spawnY = Math.random() * -100;
            } else {
               spawnY = Math.random() * height;
            }
        }

        particlesRef.current.push({
            x: spawnX,
            y: spawnY,
            vx, vy,
            life: pLife,
            maxLife: 60,
            size: pSize,
            color: pColor,
            element: element as Particle['element'],
            type,
            angle: Math.random() * Math.PI * 2,
            angularVelocity: (Math.random() - 0.5) * 0.4
        });
    }
  };

  const animate = useCallback((time: number) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d', { alpha: false }); // Optimization: alpha false
    if (!ctx) return;

    // HIGH DPI SCALING
    const dpr = window.devicePixelRatio || 1;
    if (canvas.width !== width * dpr || canvas.height !== height * dpr) {
        canvas.width = width * dpr;
        canvas.height = height * dpr;
    }
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

    // 1. Draw Background (Clear)
    // Use the Theme Background variable directly for canvas fill
    const theme = activeComboRef.current 
        ? COMBO_THEMES[activeComboRef.current] 
        : (THEMES[currentElement as ElementType] || THEMES['NEUTRAL']);

    // CRITICAL FIX: Reset composite operation to default before clearing/drawing background
    // This prevents the 'lighter' blending from accumulating indefinitely into white.
    ctx.globalCompositeOperation = 'source-over';

    ctx.fillStyle = theme.background;
    ctx.fillRect(0, 0, width, height);

    if (highlightRef.current > 0.01) highlightRef.current *= 0.925; // approx 1s duration
    else highlightRef.current = 0;
    const flash = highlightRef.current;

    // --- SCREEN BORDER FLASH EFFECT ---
    if (flash > 0.01) {
        ctx.save();
        ctx.globalCompositeOperation = 'lighter';
        ctx.strokeStyle = theme.primary;
        ctx.lineWidth = 30 * flash; // Border gets thinner as it fades
        ctx.shadowBlur = 40;
        ctx.shadowColor = theme.secondary;
        ctx.globalAlpha = flash; // Fade out opacity

        // Draw Outer Border
        ctx.strokeRect(0, 0, width, height);

        // Draw Inner Decorative Border
        ctx.strokeStyle = theme.core;
        ctx.lineWidth = 2;
        ctx.globalAlpha = flash * 0.7;
        const inset = 20 * (2 - flash); // Inset animation
        ctx.strokeRect(inset, inset, width - inset * 2, height - inset * 2);

        ctx.restore();
    }

    let lastCenterX = width / 2;
    let lastCenterY = height / 2;
    const t = time * 0.001;
    const comboName = activeComboRef.current;

    // --- DETERMINE CENTER ---
    if (comboName && handDataRef.current.length === 2) {
         lastCenterX = (handDataRef.current[0].middleBase.x + handDataRef.current[1].middleBase.x) / 2;
         lastCenterY = (handDataRef.current[0].middleBase.y + handDataRef.current[1].middleBase.y) / 2;
    } else if (handDataRef.current.length > 0) {
        // Find active hand or just first hand
        const active = handDataRef.current.find(h => h.gesture !== 'NEUTRAL') || handDataRef.current[0];
        lastCenterX = active.middleBase.x;
        lastCenterY = active.middleBase.y;
    }

    // 2. Geometry & Particles
    // Enable additive blending for glowing magic effects
    ctx.globalCompositeOperation = 'lighter'; 

    if (comboName && handDataRef.current.length === 2) {
        // --- COMBO MODE ---
        const h1 = handDataRef.current[0];
        const h2 = handDataRef.current[1];

        const midX = lastCenterX;
        const midY = lastCenterY;

        ctx.save();
        ctx.beginPath();
        ctx.moveTo(h1.middleBase.x, h1.middleBase.y);
        ctx.lineTo(h2.middleBase.x, h2.middleBase.y);
        ctx.strokeStyle = theme.primary;
        ctx.lineWidth = 20 + Math.sin(t * 10) * 5; 
        ctx.lineCap = 'round';
        ctx.shadowBlur = 20; // Reduced blur
        ctx.shadowColor = theme.secondary;
        ctx.globalAlpha = 0.4;
        ctx.stroke();
        ctx.restore();

        ctx.save();
        ctx.beginPath();
        ctx.moveTo(h1.middleBase.x, h1.middleBase.y);
        ctx.lineTo(h2.middleBase.x, h2.middleBase.y);
        ctx.strokeStyle = '#FFFFFF';
        ctx.lineWidth = 3;
        ctx.setLineDash([10, 40]);
        ctx.lineDashOffset = -t * 200; 
        ctx.globalCompositeOperation = 'overlay';
        ctx.stroke();
        ctx.restore();

        // Arcs
        ctx.save();
        ctx.beginPath();
        ctx.moveTo(h1.middleBase.x, h1.middleBase.y);
        const dist = Math.hypot(h2.middleBase.x - h1.middleBase.x, h2.middleBase.y - h1.middleBase.y);
        const angle = Math.atan2(h2.middleBase.y - h1.middleBase.y, h2.middleBase.x - h1.middleBase.x);
        for(let i=0; i<=10; i++) { // Reduced segments
             const p = i/10;
             const perp = Math.sin(p * Math.PI * 4 + t * 20) * (15 + Math.random() * 5);
             const bx = h1.middleBase.x + (h2.middleBase.x - h1.middleBase.x) * p + Math.cos(angle + Math.PI/2)*perp;
             const by = h1.middleBase.y + (h2.middleBase.y - h1.middleBase.y) * p + Math.sin(angle + Math.PI/2)*perp;
             ctx.lineTo(bx, by);
        }
        ctx.strokeStyle = theme.secondary;
        ctx.lineWidth = 2;
        ctx.stroke();
        ctx.restore();

        ctx.globalAlpha = 1;
        drawRuneRing(ctx, midX, midY, 180, t, theme);
        drawSacredGeometry(ctx, midX, midY, 140, -t * 2, theme);
        drawSquareLayer(ctx, midX, midY, 100, t * 3, theme);
        drawPentagram(ctx, midX, midY, 60, -t, 1, theme);

        spawnParticles(midX, midY, comboName, theme);

        handDataRef.current.forEach(h => {
             drawSkeleton(ctx, h);
             const auraSize = 50 + Math.sin(t * 20) * 10;
             const grad = ctx.createRadialGradient(h.middleBase.x, h.middleBase.y, 10, h.middleBase.x, h.middleBase.y, auraSize);
             grad.addColorStop(0, theme.core);
             grad.addColorStop(0.4, theme.primary);
             grad.addColorStop(1, 'rgba(0,0,0,0)');
             ctx.save();
             ctx.fillStyle = grad;
             ctx.globalAlpha = 0.5;
             ctx.beginPath();
             ctx.arc(h.middleBase.x, h.middleBase.y, auraSize, 0, Math.PI * 2);
             ctx.fill();
             ctx.restore();
             drawRuneRing(ctx, h.middleBase.x, h.middleBase.y, 40, t*5, theme);
        });

    } else {
        // --- INDIVIDUAL MODE ---
        handDataRef.current.forEach((hand) => {
           drawSkeleton(ctx, hand);
           const element = hand.gesture;
           const handTheme = (element !== 'NEUTRAL' && THEMES[element]) ? THEMES[element] : THEMES['NEUTRAL'];
           const centerX = hand.middleBase.x; 
           const centerY = hand.middleBase.y; 

           if (element !== 'NEUTRAL') {
               if (flash > 0.05 && highlightRef.current > 0.05) {
                   ctx.save();
                   ctx.translate(centerX, centerY);
                   const waveSize = 120 + (1 - flash) * 100;
                   ctx.beginPath();
                   ctx.arc(0, 0, waveSize, 0, Math.PI * 2);
                   ctx.lineWidth = 10 * flash;
                   ctx.strokeStyle = handTheme.core;
                   ctx.shadowBlur = 20;
                   ctx.shadowColor = handTheme.secondary;
                   ctx.globalAlpha = flash;
                   ctx.stroke();
                   ctx.restore();
               }

               drawRuneRing(ctx, centerX, centerY, 120, t * 0.5, handTheme);
               drawSacredGeometry(ctx, centerX, centerY, 90, -t * 1.5, handTheme);
               drawSquareLayer(ctx, centerX, centerY, 65, t * 2.5, handTheme);
               const pulse = Math.sin(time * 0.005) * 0.5 + 0.5;
               drawPentagram(ctx, centerX, centerY, 40, t, pulse, handTheme);

               spawnParticles(centerX, centerY, element, handTheme);
           } else {
               ctx.globalAlpha = 0.3;
               drawRuneRing(ctx, centerX, centerY, 50, t * 0.2, handTheme);
           }
        });
    }

    updateParticles(ctx, width, height, lastCenterX, lastCenterY);
    requestRef.current = requestAnimationFrame(animate);
  }, [width, height, currentElement]);

  useEffect(() => {
    requestRef.current = requestAnimationFrame(animate);
    return () => { if (requestRef.current) cancelAnimationFrame(requestRef.current); };
  }, [animate]);

  return (
    <div className="relative w-full h-full overflow-hidden flex items-center justify-center font-sans">

        {/* Dynamic Background */}
        <div 
            className="absolute inset-0 transition-colors duration-700 ease-in-out z-0"
            style={{ backgroundColor: currentTheme.background }}
        />

        {/* Hidden Webcam */}
        <Webcam 
            ref={webcamRef} 
            audio={false} 
            width={width} 
            height={height} 
            mirrored={true} 
            screenshotFormat="image/jpeg" 
            className="absolute opacity-0 pointer-events-none" 
            onUserMedia={() => setCameraReady(true)}
            onUserMediaError={(e: any) => setLoadingError("摄像头访问失败: " + e)}
        />

        {/* Canvas Layer */}
        <canvas ref={canvasRef} style={{ width, height }} className="absolute top-0 left-0 z-10" />

        {!isModelLoaded && (
            <div className="absolute inset-0 flex items-center justify-center bg-black bg-opacity-90 z-50">
                <div className="flex flex-col items-center">
                    <div className="text-amber-500 font-mono text-xl animate-pulse tracking-widest mb-4">🔮 正在校准魔法维度...</div>
                    {loadingError ? (
                        <div className="text-red-500 font-bold bg-black/50 p-2 rounded">{loadingError}</div>
                    ) : (
                        <div className="w-64 h-1 bg-gray-800 rounded-full overflow-hidden">
                            <div className="h-full bg-amber-500 animate-[width_1s_ease-in-out_infinite]" style={{width: '50%'}}></div>
                        </div>
                    )}
                    <div className="mt-4 text-xs text-gray-400 font-mono">{debugInfo}</div>
                </div>
            </div>
        )}

        {!hasStarted && isModelLoaded && (
            <div className="absolute inset-0 flex items-center justify-center bg-black/60 z-50 cursor-pointer backdrop-blur-sm" onClick={startExperience}>
                <div className="border border-amber-500/50 bg-black/80 p-8 rounded-lg text-center shadow-[0_0_30px_rgba(255,160,20,0.3)] hover:scale-105 transition-transform duration-300">
                    <h2 className="text-3xl font-bold text-amber-500 mb-2">准备就绪</h2>
                    <p className="text-white/80 mb-6">点击屏幕开启秘术工坊</p>
                    <button className="px-6 py-2 bg-amber-600 hover:bg-amber-500 text-black font-bold rounded">进入</button>
                </div>
            </div>
        )}

        {/* Dynamic Spell Name */}
        <div className="absolute top-20 left-0 w-full flex justify-center z-20 pointer-events-none">
             <div className={`text-4xl md:text-5xl font-bold tracking-widest transition-all duration-300 drop-shadow-[0_0_15px_rgba(255,255,255,0.4)] px-8 py-2 rounded-full ${highlightRef.current > 0.1 ? 'scale-110 bg-black/20 backdrop-blur-sm' : ''} ${
                currentElement === 'FIRE' ? 'text-orange-500' :
                currentElement === 'WATER' ? 'text-blue-500' :
                currentElement === 'WIND' ? 'text-cyan-300' :
                currentElement === 'THUNDER' ? 'text-purple-500' : 
                currentElement === 'INFERNO' ? 'text-red-600' :
                currentElement === 'BLIZZARD' ? 'text-cyan-100' :
                currentElement === 'VOID' ? 'text-violet-400' : 'text-amber-400'
            }`}>
                {ELEMENT_NAMES_CN[currentElement]}
            </div>
        </div>

        {/* Toggle Controls Button */}
        <div className="absolute top-4 right-4 z-30">
            <button 
                onClick={() => setShowControls(!showControls)}
                className="bg-black/40 border border-white/10 p-2 rounded hover:bg-white/10 transition-colors text-white/50 text-xs uppercase font-mono tracking-wider"
            >
                {showControls ? 'Hide Controls' : 'Show Controls'}
            </button>
        </div>

        {/* Debug Info */}
        <div className="absolute top-12 right-4 z-20 text-right opacity-50 pointer-events-none">
             <div className="text-xs text-amber-200 font-mono">{debugInfo}</div>
        </div>

        {/* PARTICLE CONTROLS PANEL */}
        {showControls && (
            <div className="absolute top-20 right-4 z-30 w-64 bg-black/60 backdrop-blur-md border border-white/10 rounded-xl p-4 shadow-2xl animate-[fadeIn_0.3s_ease-out]">
                <h3 className="text-amber-500 text-xs font-bold uppercase tracking-widest mb-4 border-b border-white/10 pb-2">粒子引擎参数</h3>

                <div className="space-y-4">
                    <div>
                        <div className="flex justify-between text-xs text-white/70 mb-1">
                            <span>速度 (Velocity)</span>
                            <span className="font-mono text-amber-400">{settings.speed.toFixed(1)}x</span>
                        </div>
                        <input 
                            type="range" min="0.1" max="10.0" step="0.1" 
                            value={settings.speed}
                            onChange={(e) => setSettings({...settings, speed: parseFloat(e.target.value)})}
                            className="w-full h-1 bg-white/20 rounded-lg appearance-none cursor-pointer accent-amber-500"
                        />
                    </div>

                    <div>
                        <div className="flex justify-between text-xs text-white/70 mb-1">
                            <span>数量 (Density)</span>
                            <span className="font-mono text-amber-400">{settings.count.toFixed(1)}x</span>
                        </div>
                        <input 
                            type="range" min="0.1" max="5.0" step="0.1" 
                            value={settings.count}
                            onChange={(e) => setSettings({...settings, count: parseFloat(e.target.value)})}
                            className="w-full h-1 bg-white/20 rounded-lg appearance-none cursor-pointer accent-amber-500"
                        />
                    </div>

                    <div>
                        <div className="flex justify-between text-xs text-white/70 mb-1">
                            <span>辉光 (Glow)</span>
                            <span className="font-mono text-amber-400">{settings.glow.toFixed(1)}x</span>
                        </div>
                        <input 
                            type="range" min="0.5" max="3.0" step="0.1" 
                            value={settings.glow}
                            onChange={(e) => setSettings({...settings, glow: parseFloat(e.target.value)})}
                            className="w-full h-1 bg-white/20 rounded-lg appearance-none cursor-pointer accent-amber-500"
                        />
                    </div>
                </div>
            </div>
        )}

        {/* Gesture Guide */}
        <div className="absolute bottom-0 left-0 w-full p-6 z-20">
            <div className="max-w-4xl mx-auto bg-black/40 backdrop-blur-md border border-white/10 rounded-2xl p-4 shadow-2xl">
                <div className="flex flex-wrap justify-center items-center gap-4 md:gap-8 text-white/90 text-sm font-medium">
                    <div className="flex items-center gap-3 bg-white/5 px-4 py-2 rounded-lg border border-white/5">
                        <span className="text-2xl">✋</span> 
                        <div className="flex flex-col leading-tight">
                            <span className="text-orange-400 font-bold">火焰</span>
                            <span className="text-[10px] text-gray-400">五指张开</span>
                        </div>
                    </div>
                    <div className="flex items-center gap-3 bg-white/5 px-4 py-2 rounded-lg border border-white/5">
                        <span className="text-2xl">👇</span>
                        <div className="flex flex-col leading-tight">
                            <span className="text-blue-400 font-bold">流水</span>
                            <span className="text-[10px] text-gray-400">掌心向下</span>
                        </div>
                    </div>
                    <div className="flex items-center gap-3 bg-white/5 px-4 py-2 rounded-lg border border-white/5">
                        <span className="text-2xl">👊</span>
                        <div className="flex flex-col leading-tight">
                            <span className="text-purple-400 font-bold">雷霆</span>
                            <span className="text-[10px] text-gray-400">握紧拳头</span>
                        </div>
                    </div>
                    <div className="flex items-center gap-3 bg-white/5 px-4 py-2 rounded-lg border border-white/5">
                        <span className="text-2xl">✌️</span>
                        <div className="flex flex-col leading-tight">
                            <span className="text-teal-300 font-bold">疾风</span>
                            <span className="text-[10px] text-gray-400">食指中指 (剪刀手)</span>
                        </div>
                    </div>
                </div>
                <div className="text-center mt-3 text-xs text-amber-500/60 tracking-wider uppercase font-mono">
                    ✦ 双手结印触发高阶法术 ✦
                </div>
            </div>
        </div>
    </div>
  );
};

export default MagicOverlay;

export type ElementType = 'NEUTRAL' | 'FIRE' | 'WATER' | 'THUNDER' | 'WIND';
export type ComboType = 'BLIZZARD' | 'PLASMA' | 'STEAM' | 'TEMPEST' | 'INFERNO' | 'VOID';
export type ParticleType = 'ORB' | 'LEAF' | 'SPARK' | 'DROP' | 'MIST' | 'EMBER';

export interface Point {
  x: number;
  y: number;
  z?: number;
}

export interface Particle {
  x: number;
  y: number;
  vx: number;
  vy: number;
  life: number;
  maxLife: number;
  size: number;
  color: string;
  element: ElementType | ComboType;
  type: ParticleType;
  angle: number;           // For rotation (leaves)
  angularVelocity: number; // For rotation speed
}

export interface Monster {
  id: number;
  x: number;
  y: number;
  vx: number;
  vy: number;
  hp: number;
  maxHp: number;
  element: ElementType;
  radius: number;
  scoreValue: number;
  pulseOffset: number;
}

export interface HandData {
  wrist: Point;
  indexTip: Point;
  middleTip: Point;
  ringTip: Point;
  pinkyTip: Point;
  thumbTip: Point;
  indexBase: Point; 
  middleBase: Point;
  ringBase: Point;
  pinkyBase: Point;
  isOpen: boolean;
  gesture: ElementType;
  opacity: number;
}

export interface Theme {
  primary: string;
  secondary: string;
  core: string;
  shadow: string;
  background: string; // New field for solid background color
}

import React, { useEffect, useRef, useCallback, useState } from 'react';
import Webcam from 'react-webcam';
import { Particle, HandData, ElementType, Theme, ParticleType, Monster } from '../types';
import { 
  drawRuneRing, 
  drawSacredGeometry, 
  drawSquareLayer, 
  drawPentagram,
  THEMES
} from '../utils/geometry';

interface MagicOverlayProps {
  width: number;
  height: number;
}

const COMBO_THEMES: Record<string, Theme> = {
  'BLIZZARD': { primary: '#00FFFF', secondary: '#E0FFFF', core: '#FFFFFF', shadow: '#008B8B', background: '#0a1a20' }, 
  'PLASMA': { primary: '#FF00FF', secondary: '#00FFFF', core: '#FFFFFF', shadow: '#9400D3', background: '#1a051a' }, 
  'STEAM': { primary: '#F0F8FF', secondary: '#B0C4DE', core: '#FFFFFF', shadow: '#778899', background: '#10151a' }, 
  'TEMPEST': { primary: '#000080', secondary: '#8A2BE2', core: '#FFFF00', shadow: '#191970', background: '#05051a' }, 
  'INFERNO': { primary: '#FF0000', secondary: '#FF4500', core: '#FFFF00', shadow: '#8B0000', background: '#2a0500' }, 
  'VOID': { primary: '#000000', secondary: '#4B0082', core: '#FFFFFF', shadow: '#9400D3', background: '#000000' }, 
};

const ELEMENT_NAMES_CN: Record<string, string> = {
    'NEUTRAL': '等待施法...',
    'FIRE': '🔥 烈焰术 (FIRE)',
    'WATER': '💧 唤雨术 (WATER)',
    'THUNDER': '⚡ 雷霆术 (THUNDER)',
    'WIND': '🌪️ 疾风术 (WIND)',
    'BLIZZARD': '❄️ 极寒风暴 (BLIZZARD)',
    'PLASMA': '⚛️ 等离子破 (PLASMA)',
    'STEAM': '♨️ 灼热蒸汽 (STEAM)',
    'TEMPEST': '⛈️ 雷暴风眼 (TEMPEST)',
    'INFERNO': '🌋 地狱烈火 (INFERNO)',
    'VOID': '🌌 虚空奇点 (VOID)'
};

const getCombo = (g1: ElementType, g2: ElementType): string | null => {
    const sorted = [g1, g2].sort().join('_');
    switch(sorted) {
        case 'WATER_WIND': return 'BLIZZARD';
        case 'FIRE_WIND': return 'PLASMA';
        case 'FIRE_WATER': return 'STEAM';
        case 'THUNDER_WATER': return 'TEMPEST';
        case 'FIRE_FIRE': return 'INFERNO';
        case 'THUNDER_THUNDER': return 'VOID';
        default: return null;
    }
};

const MagicOverlay: React.FC<MagicOverlayProps> = ({ width, height }) => {
  const webcamRef = useRef<Webcam>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>(0);

  // Game Refs
  const particlesRef = useRef<Particle[]>([]);
  const handDataRef = useRef<HandData[]>([]);
  const monstersRef = useRef<Monster[]>([]);
  const monsterSpawnTimerRef = useRef<number>(0);
  const scoreRef = useRef<number>(0);
  const coreHealthRef = useRef<number>(100);

  // App State
  const [currentElement, setCurrentElement] = useState<string>('NEUTRAL');
  const [isModelLoaded, setIsModelLoaded] = useState(false);
  const [loadingError, setLoadingError] = useState<string | null>(null);
  const [debugInfo, setDebugInfo] = useState<string>("初始化系统...");
  const [hasStarted, setHasStarted] = useState(false);
  const [showControls, setShowControls] = useState(false); 
  const [isCameraReady, setCameraReady] = useState(false);

  // Game UI State
  const [uiScore, setUiScore] = useState(0);
  const [uiHealth, setUiHealth] = useState(100);
  const [isGameOver, setIsGameOver] = useState(false);

  // Settings State - Updated Defaults per request
  const [settings, setSettings] = useState({
      speed: 1.0,   
      count: 0.5,   
      glow: 1.0,    
  });

  // Settings Ref (for access inside animation loop without stale closures)
  const settingsRef = useRef(settings);
  useEffect(() => { settingsRef.current = settings; }, [settings]);

  // Visual Feedback State
  const highlightRef = useRef<number>(0);
  const prevElementRef = useRef<string>('NEUTRAL');
  const activeComboRef = useRef<string | null>(null);

  // Audio Context
  const audioContextRef = useRef<AudioContext | null>(null);
  const noiseBufferRef = useRef<AudioBuffer | null>(null);

  // Get current Theme for background
  const currentTheme = activeComboRef.current 
    ? COMBO_THEMES[activeComboRef.current] 
    : (THEMES[currentElement as ElementType] || THEMES['NEUTRAL']);

  useEffect(() => {
    const AudioContextClass = (window as any).AudioContext || (window as any).webkitAudioContext;
    if (AudioContextClass) {
        const ctx = new AudioContextClass();
        audioContextRef.current = ctx;

        const bufferSize = ctx.sampleRate * 2; 
        const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
        const data = buffer.getChannelData(0);
        for (let i = 0; i < bufferSize; i++) {
            data[i] = Math.random() * 2 - 1;
        }
        noiseBufferRef.current = buffer;
    }
  }, []);

  const startExperience = () => {
      setHasStarted(true);
      if (audioContextRef.current?.state === 'suspended') {
          audioContextRef.current.resume();
      }
      // Reset Game
      monstersRef.current = [];
      scoreRef.current = 0;
      coreHealthRef.current = 100;
      setUiScore(0);
      setUiHealth(100);
      setIsGameOver(false);
  };

  const playChime = useCallback((element: string) => {
    const ctx = audioContextRef.current;
    if (!ctx || !noiseBufferRef.current) return;
    if (ctx.state === 'suspended') ctx.resume().catch(console.error);

    const now = ctx.currentTime;
    const masterGain = ctx.createGain();
    masterGain.connect(ctx.destination);
    masterGain.gain.setValueAtTime(0.3, now); 

    const playNoise = (filterType: BiquadFilterType, freqStart: number, freqEnd: number, duration: number, vol: number = 1, delay: number = 0) => {
        const src = ctx.createBufferSource();
        src.buffer = noiseBufferRef.current;
        src.loop = true;
        const filter = ctx.createBiquadFilter();
        filter.type = filterType;
        filter.frequency.setValueAtTime(freqStart, now + delay);
        filter.frequency.exponentialRampToValueAtTime(freqEnd, now + delay + duration);
        filter.Q.value = 1;
        const amp = ctx.createGain();
        amp.gain.setValueAtTime(0, now + delay);
        amp.gain.linearRampToValueAtTime(vol, now + delay + 0.05);
        amp.gain.exponentialRampToValueAtTime(0.01, now + delay + duration);
        src.connect(filter);
        filter.connect(amp);
        amp.connect(masterGain);
        src.start(now + delay);
        src.stop(now + delay + duration + 0.2);
    };

    const playTone = (type: OscillatorType, freqStart: number, freqEnd: number, duration: number, vol: number = 1, delay: number = 0) => {
        const osc = ctx.createOscillator();
        osc.type = type;
        osc.frequency.setValueAtTime(freqStart, now + delay);
        if (freqStart !== freqEnd) osc.frequency.exponentialRampToValueAtTime(freqEnd, now + delay + duration);
        const amp = ctx.createGain();
        amp.gain.setValueAtTime(0, now + delay);
        amp.gain.linearRampToValueAtTime(vol, now + delay + 0.05);
        amp.gain.exponentialRampToValueAtTime(0.01, now + delay + duration);
        osc.connect(amp);
        amp.connect(masterGain);
        osc.start(now + delay);
        osc.stop(now + delay + duration + 0.2);
    };

    switch (element) {
        case 'FIRE': playNoise('lowpass', 500, 100, 1.0, 0.5); playTone('sawtooth', 80, 120, 0.8, 0.2); break;
        case 'WATER': playNoise('bandpass', 800, 300, 0.6, 0.4); playTone('sine', 600, 300, 0.4, 0.3, 0.1); break;
        case 'WIND': playNoise('lowpass', 200, 800, 0.4, 0.3); playNoise('highpass', 400, 1000, 0.5, 0.2, 0.1); break;
        case 'THUNDER': playTone('sawtooth', 800, 50, 0.3, 0.2); playNoise('lowpass', 1000, 50, 1.2, 0.6, 0.1); break;
        case 'BLIZZARD': playNoise('highpass', 1000, 3000, 1.5, 0.4); playTone('sine', 1500, 2000, 0.3, 0.1, 0.1); break;
        case 'INFERNO': playNoise('lowpass', 800, 50, 1.5, 0.8); playTone('square', 60, 40, 1.5, 0.2); break;
        case 'TEMPEST': playNoise('lowpass', 200, 50, 2.0, 0.8); playTone('sawtooth', 1200, 100, 0.5, 0.2, 0.1); playNoise('bandpass', 1000, 500, 1.0, 0.3); break;
        case 'VOID': playTone('sine', 50, 40, 2.5, 0.6); playNoise('bandpass', 100, 200, 2.5, 0.4); playTone('sine', 300, 290, 1.0, 0.1, 0.5); break;
        case 'PLASMA': playTone('sawtooth', 200, 800, 1.0, 0.2); playNoise('bandpass', 400, 1200, 1.0, 0.4); break;
        case 'STEAM': playNoise('highpass', 500, 1000, 1.0, 0.3); break;
        default: playTone('triangle', 440, 880, 0.3, 0.1);
    }
  }, []);

  const detectGesture = (landmarks: any[], videoWidth: number, videoHeight: number): ElementType => {
    const mapPt = (idx: number) => ({ x: (1 - landmarks[idx].x) * videoWidth, y: landmarks[idx].y * videoHeight });
    const wrist = mapPt(0);
    const indexTip = mapPt(8);
    const middleTip = mapPt(12);
    const middleMCP = mapPt(9);

    // Optimized Distances
    const distSq = (p1: any, p2: any) => (p1.x - p2.x)**2 + (p1.y - p2.y)**2;
    const isFingerOpen = (tip: any, mcp: any) => distSq(tip, wrist) > distSq(mcp, wrist) * 1.2;

    const isPointingDown = wrist.y < middleMCP.y;
    if (isPointingDown) return 'WATER';

    let openCount = 0;
    if (isFingerOpen(indexTip, mapPt(5))) openCount++;
    if (isFingerOpen(middleTip, mapPt(9))) openCount++;
    if (isFingerOpen(mapPt(16), mapPt(13))) openCount++;
    if (isFingerOpen(mapPt(20), mapPt(17))) openCount++;

    if (openCount >= 4) return 'FIRE';
    if (openCount >= 2) return 'WIND';
    return 'THUNDER';
  };

  const drawSkeleton = (ctx: CanvasRenderingContext2D, hand: HandData) => {
      ctx.strokeStyle = "rgba(255, 255, 255, 0.15)";
      ctx.lineWidth = 1.5;
      ctx.fillStyle = "rgba(255, 255, 255, 0.5)";
      const points = [hand.wrist, hand.indexBase, hand.indexTip, hand.middleBase, hand.middleTip, hand.ringBase, hand.ringTip, hand.pinkyBase, hand.pinkyTip, hand.thumbTip];

      const drawLine = (p1: any, p2: any) => { ctx.beginPath(); ctx.moveTo(p1.x, p1.y); ctx.lineTo(p2.x, p2.y); ctx.stroke(); }
      drawLine(hand.wrist, hand.indexBase); drawLine(hand.indexBase, hand.indexTip);
      drawLine(hand.wrist, hand.middleBase); drawLine(hand.middleBase, hand.middleTip);
      drawLine(hand.wrist, hand.pinkyBase); drawLine(hand.pinkyBase, hand.pinkyTip);

      points.forEach(p => { ctx.beginPath(); ctx.arc(p.x, p.y, 2.5, 0, Math.PI * 2); ctx.fill(); });
  };

  const onResults = useCallback((results: any) => {
    const displayWidth = width;
    const displayHeight = height;

    setIsModelLoaded((prev) => {
        if (!prev) return true;
        return prev;
    });

    if (results.multiHandLandmarks && results.multiHandLandmarks.length > 0) {
      // Don't update debug info constantly to save renders
      const newHandData: HandData[] = results.multiHandLandmarks.map((landmarks: any[]) => {
        const gesture = detectGesture(landmarks, displayWidth, displayHeight);
        const mapPt = (idx: number) => ({ x: (1 - landmarks[idx].x) * displayWidth, y: landmarks[idx].y * displayHeight });
        return {
          wrist: mapPt(0), indexTip: mapPt(8), middleTip: mapPt(12), ringTip: mapPt(16), pinkyTip: mapPt(20), thumbTip: mapPt(4),
          indexBase: mapPt(5), middleBase: mapPt(9), ringBase: mapPt(13), pinkyBase: mapPt(17),
          isOpen: gesture !== 'THUNDER', gesture, opacity: 1,
          middleBase: mapPt(9)
        };
      });

      handDataRef.current = newHandData;
      let newElement = 'NEUTRAL';
      let activeCombo = null;

      if (newHandData.length === 2) {
          const g1 = newHandData[0].gesture;
          const g2 = newHandData[1].gesture;
          if (g1 !== 'NEUTRAL' && g2 !== 'NEUTRAL') activeCombo = getCombo(g1, g2);
      }

      if (activeCombo) newElement = activeCombo;
      else {
          const activeHand = newHandData.find(h => h.gesture !== 'NEUTRAL');
          if (activeHand) newElement = activeHand.gesture;
      }
      activeComboRef.current = activeCombo;

      if (newElement !== prevElementRef.current) {
          if (newElement !== 'NEUTRAL') { highlightRef.current = 1.0; playChime(newElement); }
          prevElementRef.current = newElement;
      }
      setCurrentElement(newElement);
    } else {
      handDataRef.current = [];
      activeComboRef.current = null;
      if (prevElementRef.current !== 'NEUTRAL') { prevElementRef.current = 'NEUTRAL'; setCurrentElement('NEUTRAL'); }
    }
  }, [width, height, playChime]);

  useEffect(() => {
    let hands: any = null;
    let isActive = true;
    let frameId: number;
    let lastVideoTime = -1;

    const MP_VERSION = "0.4.1675469240";

    const initHands = async () => {
       try {
           setDebugInfo("正在加载 AI 核心 (1/3)...");
           if (!(window as any).Hands) { 
               setTimeout(initHands, 500); 
               return; 
           }

           setDebugInfo("初始化视觉模型 (2/3)...");
           hands = new (window as any).Hands({ 
               locateFile: (file: string) => `https://cdn.jsdelivr.net/npm/@mediapipe/hands@${MP_VERSION}/${file}` 
           });

           hands.setOptions({ 
               maxNumHands: 2, 
               modelComplexity: 1, 
               minDetectionConfidence: 0.5, 
               minTrackingConfidence: 0.5 
           });

           hands.onResults(onResults);

           setDebugInfo("等待摄像头许可...");

           const processVideo = async () => {
             if (!isActive) return;
             if (webcamRef.current && webcamRef.current.video && webcamRef.current.video.readyState === 4) {
                 const video = webcamRef.current.video;
                 if (video.videoWidth > 0 && video.videoHeight > 0) {
                     if (video.currentTime !== lastVideoTime) {
                         lastVideoTime = video.currentTime;
                         try { 
                             setDebugInfo("正在处理视频流...");
                             await hands.send({ image: video }); 
                         } catch (e) { 
                             console.warn("Processing warning", e); 
                         }
                     }
                 }
             }
             frameId = requestAnimationFrame(processVideo);
           };
           processVideo();
       } catch (error: any) {
           console.error("Initialization Error:", error);
           setLoadingError("AI 模型加载失败: " + error.message);
           setDebugInfo("系统错误");
       }
    };

    setTimeout(initHands, 500);

    return () => { isActive = false; if (frameId) cancelAnimationFrame(frameId); if (hands) hands.close(); };
  }, [onResults]);

  // --- GAME LOGIC ---

  const spawnMonster = (width: number, height: number) => {
      const edge = Math.floor(Math.random() * 4); // 0: Top, 1: Right, 2: Bottom, 3: Left
      let x = 0, y = 0;

      switch(edge) {
          case 0: x = Math.random() * width; y = -50; break;
          case 1: x = width + 50; y = Math.random() * height; break;
          case 2: x = Math.random() * width; y = height + 50; break;
          case 3: x = -50; y = Math.random() * height; break;
      }

      const elements: ElementType[] = ['FIRE', 'WATER', 'WIND', 'THUNDER'];
      const element = elements[Math.floor(Math.random() * elements.length)];

      const monster: Monster = {
          id: Date.now() + Math.random(),
          x, y,
          vx: 0, vy: 0, // Calculated in update
          hp: 100,
          maxHp: 100,
          element,
          radius: 20 + Math.random() * 10,
          scoreValue: 100,
          pulseOffset: Math.random() * Math.PI * 2
      };
      monstersRef.current.push(monster);
  };

  const updateMonsters = (ctx: CanvasRenderingContext2D, width: number, height: number, centerX: number, centerY: number, hands: HandData[]) => {
      const monsters = monstersRef.current;

      const getMultiplier = (spell: string, monsterEl: string) => {
          // Double score for counter-elements as requested
          if (spell === 'FIRE' && monsterEl === 'WATER') return 2;
          if (spell === 'WATER' && monsterEl === 'FIRE') return 2;
          if (spell === 'THUNDER' && monsterEl === 'WIND') return 2;
          if (spell === 'WIND' && monsterEl === 'THUNDER') return 2;
          if (spell === 'BLIZZARD' || spell === 'INFERNO' || spell === 'TEMPEST' || spell === 'PLASMA') return 3;
          if (spell === 'VOID') return 5;
          return 1;
      };

      for (let i = monsters.length - 1; i >= 0; i--) {
          const m = monsters[i];
          const dx = centerX - m.x;
          const dy = centerY - m.y;
          const distToCenter = Math.sqrt(dx*dx + dy*dy);

          // Move towards center
          const angle = Math.atan2(dy, dx);
          const speed = 1.5 + (scoreRef.current / 5000); // Difficulty scaling
          m.x += Math.cos(angle) * speed;
          m.y += Math.sin(angle) * speed;

          // Draw Monster
          const mTheme = THEMES[m.element];
          ctx.save();
          ctx.translate(m.x, m.y);
          const pulse = 1 + Math.sin(Date.now() * 0.005 + m.pulseOffset) * 0.2;
          ctx.scale(pulse, pulse);

          ctx.beginPath();
          // Draw a spiky shape
          const spikes = 5;
          const outerRadius = m.radius;
          const innerRadius = m.radius / 2;
          for (let j = 0; j < spikes * 2; j++) {
             const r = j % 2 === 0 ? outerRadius : innerRadius;
             const a = (Math.PI * j) / spikes;
             ctx.lineTo(Math.cos(a) * r, Math.sin(a) * r);
          }
          ctx.closePath();
          ctx.fillStyle = mTheme.background;
          ctx.fill();
          ctx.strokeStyle = mTheme.primary;
          ctx.lineWidth = 3;
          ctx.stroke();

          // Element Icon or Glow
          ctx.shadowBlur = 15;
          ctx.shadowColor = mTheme.secondary;
          ctx.fillStyle = mTheme.core;
          ctx.beginPath();
          ctx.arc(0, 0, innerRadius * 0.5, 0, Math.PI * 2);
          ctx.fill();
          ctx.shadowBlur = 0;

          ctx.restore();

          // Check Collision with Hands
          let hit = false;
          for (const hand of hands) {
              if (hand.gesture !== 'NEUTRAL') {
                  const hx = hand.middleBase.x;
                  const hy = hand.middleBase.y;
                  const hDist = Math.hypot(hx - m.x, hy - m.y);

                  // Hitbox radius depends on spell
                  const hitRadius = activeComboRef.current ? 120 : 80;

                  if (hDist < hitRadius + m.radius) {
                      const mult = getMultiplier(activeComboRef.current || hand.gesture, m.element);
                      m.hp -= 3 * mult; // Damage per frame
                      hit = true;

                      // Spawn hit particles
                      if (Math.random() > 0.7) {
                          spawnParticles(m.x, m.y, activeComboRef.current || hand.gesture, mTheme);
                      }

                      // Visual feedback for hit
                      ctx.save();
                      ctx.globalCompositeOperation = 'lighter';
                      ctx.fillStyle = '#FFFFFF';
                      ctx.beginPath();
                      ctx.arc(m.x, m.y, m.radius * 1.5, 0, Math.PI*2);
                      ctx.globalAlpha = 0.5;
                      ctx.fill();
                      ctx.restore();

                      // Show Multiplier Text Effect (Simplified for canvas performance)
                      if (mult > 1 && Math.random() > 0.95) {
                          // Could implement floating text system here, 
                          // but for now relying on particle feedback
                      }
                  }
              }
          }

          // Death or Core Hit
          if (m.hp <= 0) {
              monsters.splice(i, 1);
              const mult = activeComboRef.current ? 2 : 1; 
              scoreRef.current += m.scoreValue * mult;
              spawnParticles(m.x, m.y, m.element, mTheme);
              spawnParticles(m.x, m.y, m.element, mTheme);
              playChime(m.element);
          } else if (distToCenter < 40) {
              // Hit Core
              monsters.splice(i, 1);
              coreHealthRef.current -= 10;
              highlightRef.current = 1.0; 
              spawnParticles(centerX, centerY, 'NEUTRAL', THEMES['NEUTRAL']);
          }
      }
  };

  // --- PHYSICS ENGINE ---
  const updateParticles = (ctx: CanvasRenderingContext2D, width: number, height: number, centerX: number, centerY: number) => {
    ctx.shadowBlur = 0; 
    const { glow } = settingsRef.current;

    for (let i = particlesRef.current.length - 1; i >= 0; i--) {
      const p = particlesRef.current[i];

      if (p.element === 'WIND' || p.element === 'BLIZZARD') {
          p.vx *= 0.995; p.vy *= 0.995;
      } else {
          p.vx *= 0.98; p.vy *= 0.98;
      }

      switch (p.element) {
          case 'WIND':
          case 'BLIZZARD':
              const dx = p.x - centerX;
              const dy = p.y - centerY;
              const dist = Math.sqrt(dx*dx + dy*dy) + 1;
              const angle = Math.atan2(dy, dx);
              p.vx += Math.cos(angle + Math.PI/2) * 2.5; 
              p.vy += Math.sin(angle + Math.PI/2) * 2.5;
              p.vx -= (dx / dist) * 0.8;
              p.vy -= (dy / dist) * 0.8;
              p.angle += p.angularVelocity * 1.5; 
              break;
          case 'WATER':
          case 'STEAM':
              p.vy += 1.5; 
              p.x += Math.sin(p.life * 0.2) * 1.0;
              break;
          case 'THUNDER':
          case 'TEMPEST':
          case 'VOID':
              p.vx += (Math.random() - 0.5) * 6; 
              p.vy += (Math.random() - 0.5) * 6;
              if (Math.random() < 0.15) {
                  p.x += (Math.random() - 0.5) * 40;
                  p.y += (Math.random() - 0.5) * 40;
              }
              break;
          case 'FIRE':
          case 'INFERNO':
              p.vy -= 1.5; 
              p.vx += (Math.random() - 0.5) * 2.0;
              p.size *= 0.95; 
              break;
          default:
              p.vy -= 0.2;
      }

      p.x += p.vx;
      p.y += p.vy;
      p.life -= 1;
      if (p.element !== 'FIRE') p.size *= 0.98;

      if (p.life <= 0 || p.size < 0.1 || p.y > height + 50 || p.y < -50 || p.x < -50 || p.x > width + 50) {
        particlesRef.current.splice(i, 1);
      } else {
        ctx.save();
        if (p.size > 2) {
             const shadowOffsetX = (p.x - centerX) * 0.05;
             const shadowOffsetY = (p.y - centerY) * 0.05;
             ctx.fillStyle = "rgba(0,0,0,0.3)";
             ctx.beginPath();
             ctx.arc(p.x + shadowOffsetX, p.y + shadowOffsetY, p.size * glow, 0, Math.PI*2);
             ctx.fill();
        }

        let alpha = Math.min(1, p.life / 10, (p.maxLife - p.life) / 5);
        if ((p.element === 'FIRE' || p.element === 'INFERNO') && p.size < 3.5 && p.type === 'EMBER') {
             alpha *= (0.5 + Math.random() * 0.5);
        }

        ctx.globalAlpha = alpha;
        const renderSize = p.size * glow;

        if (p.type === 'LEAF') {
            ctx.translate(p.x, p.y);
            ctx.rotate(p.angle);
            ctx.fillStyle = p.color;
            ctx.beginPath();
            ctx.ellipse(0, 0, renderSize, renderSize * 0.4, 0, 0, Math.PI * 2);
            ctx.fill();
        } 
        else if (p.type === 'DROP') {
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 2.5 * glow;
            ctx.lineCap = 'round';
            ctx.beginPath();
            ctx.moveTo(p.x, p.y);
            ctx.lineTo(p.x - p.vx * 1.5, p.y - p.vy * 4); 
            ctx.stroke();
        }
        else if (p.type === 'SPARK') {
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 2 * glow;
            ctx.beginPath();
            ctx.moveTo(p.x - p.vx, p.y - p.vy);
            ctx.lineTo(p.x + p.vx, p.y + p.vy);
            ctx.stroke();
        }
        else {
            ctx.fillStyle = p.color;
            ctx.beginPath();
            ctx.arc(p.x, p.y, renderSize, 0, Math.PI * 2);
            ctx.fill();
        }
        ctx.restore();
      }
    }
  };

  const spawnParticles = (x: number, y: number, element: string, theme: Theme) => {
    const { speed: speedMulti, count: countMulti } = settingsRef.current;
    const isCombo = activeComboRef.current !== null;
    let baseCount = isCombo ? 10 : 3;
    let count = Math.ceil(baseCount * countMulti);
    count = Math.min(count, 50);

    for (let i = 0; i < count; i++) {
        let type: ParticleType = 'ORB';
        let speed = (Math.random() * 8 + 4) * speedMulti; 
        let spread = 30;
        let pColor = Math.random() > 0.5 ? theme.primary : theme.secondary;
        let pSize = 4 + Math.random() * 6;
        let pLife = 30 + Math.random() * 30;

        if (element === 'WIND' || element === 'BLIZZARD') {
            type = Math.random() > 0.5 ? 'LEAF' : 'MIST';
            if (isCombo) pColor = Math.random() > 0.5 ? '#00FFFF' : '#F0FFF0';
            else if (element === 'WIND') pColor = Math.random() > 0.5 ? '#00FFFF' : '#F0FFF0'; 
        } else if (element === 'WATER' || element === 'STEAM') {
            type = Math.random() > 0.7 ? 'MIST' : 'DROP';
            spread = 50; 
        } else if (element === 'THUNDER' || element === 'TEMPEST' || element === 'VOID') {
            type = 'SPARK';
            speed = 12 * speedMulti; 
            if (element === 'THUNDER') pColor = Math.random() > 0.5 ? '#FFFF00' : '#9400D3';
        } else if (element === 'FIRE' || element === 'INFERNO') {
            const r = Math.random();
            if (r < 0.3) {
                 type = 'EMBER';
                 pColor = Math.random() > 0.5 ? '#FFD700' : '#FFFFFF';
                 pSize = 1 + Math.random() * 3;
                 pLife = 15 + Math.random() * 20; 
                 speed *= 1.5; 
            } else if (r < 0.6) {
                 type = 'MIST'; 
            } else {
                 type = 'EMBER'; 
            }
        }

        const angle = Math.random() * Math.PI * 2;
        let vx = Math.cos(angle) * speed;
        let vy = Math.sin(angle) * speed;

        if (element === 'WATER' || element === 'STEAM') { vx *= 0.3; vy = Math.random() * 5 * speedMulti + 5; } 
        if ((element === 'FIRE' || element === 'INFERNO') && pSize < 4 && type === 'EMBER') {
            vy -= 2.0; 
        }

        let spawnX = x + (Math.random() - 0.5) * spread;
        let spawnY = y + (Math.random() - 0.5) * spread;

        particlesRef.current.push({
            x: spawnX,
            y: spawnY,
            vx, vy,
            life: pLife,
            maxLife: 60,
            size: pSize,
            color: pColor,
            element: element as Particle['element'],
            type,
            angle: Math.random() * Math.PI * 2,
            angularVelocity: (Math.random() - 0.5) * 0.4
        });
    }
  };

  const animate = useCallback((time: number) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d', { alpha: false }); 
    if (!ctx) return;

    const dpr = window.devicePixelRatio || 1;
    if (canvas.width !== width * dpr || canvas.height !== height * dpr) {
        canvas.width = width * dpr;
        canvas.height = height * dpr;
    }
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

    const theme = activeComboRef.current 
        ? COMBO_THEMES[activeComboRef.current] 
        : (THEMES[currentElement as ElementType] || THEMES['NEUTRAL']);

    ctx.globalCompositeOperation = 'source-over';

    ctx.fillStyle = theme.background;
    ctx.fillRect(0, 0, width, height);

    if (highlightRef.current > 0.01) highlightRef.current *= 0.925; 
    else highlightRef.current = 0;
    const flash = highlightRef.current;

    // --- GAME LOGIC UPDATES ---
    if (hasStarted && !isGameOver) {
        monsterSpawnTimerRef.current++;
        // Spawn rate based on score
        const spawnRate = Math.max(30, 100 - Math.floor(scoreRef.current / 2000));
        if (monsterSpawnTimerRef.current > spawnRate) {
            spawnMonster(width, height);
            monsterSpawnTimerRef.current = 0;
        }

        if (coreHealthRef.current <= 0) {
            setIsGameOver(true);
        }

        // Update UI state occasionally
        if (monsterSpawnTimerRef.current % 10 === 0) {
            setUiScore(scoreRef.current);
            setUiHealth(coreHealthRef.current);
        }
    }

    if (flash > 0.01) {
        ctx.save();
        ctx.globalCompositeOperation = 'lighter';
        ctx.strokeStyle = '#FF0000'; // Damage flash
        ctx.lineWidth = 30 * flash; 
        ctx.shadowBlur = 40;
        ctx.shadowColor = '#FF0000';
        ctx.globalAlpha = flash; 
        ctx.strokeRect(0, 0, width, height);
        ctx.restore();
    }

    let centerX = width / 2;
    let centerY = height / 2;
    const t = time * 0.001;
    const comboName = activeComboRef.current;

    // Draw Core
    ctx.save();
    ctx.translate(centerX, centerY);
    // Rotating crystal/core
    ctx.rotate(t * 0.5);
    ctx.fillStyle = '#FFFFFF';
    ctx.shadowBlur = 20 + Math.sin(t * 5) * 10;
    ctx.shadowColor = '#00FFFF';
    const coreSize = 30;
    ctx.beginPath();
    ctx.moveTo(0, -coreSize);
    ctx.lineTo(coreSize, 0);
    ctx.lineTo(0, coreSize);
    ctx.lineTo(-coreSize, 0);
    ctx.fill();

    // Core Health Ring
    ctx.rotate(-t * 0.5); // Counter rotate
    ctx.beginPath();
    const hpPct = Math.max(0, coreHealthRef.current / 100);
    ctx.arc(0, 0, 50, 0, Math.PI * 2 * hpPct);
    ctx.strokeStyle = coreHealthRef.current > 30 ? '#00FF00' : '#FF0000';
    ctx.lineWidth = 5;
    ctx.lineCap = 'round';
    ctx.stroke();

    // Background circle for health ring
    ctx.beginPath();
    ctx.arc(0, 0, 50, 0, Math.PI * 2);
    ctx.strokeStyle = 'rgba(255,255,255,0.1)';
    ctx.lineWidth = 5;
    ctx.stroke();

    ctx.restore();

    // 2. Geometry & Particles
    ctx.globalCompositeOperation = 'lighter'; 

    // Render Monsters
    updateMonsters(ctx, width, height, centerX, centerY, handDataRef.current);

    if (comboName && handDataRef.current.length === 2) {
        // --- COMBO MODE ---
        const h1 = handDataRef.current[0];
        const h2 = handDataRef.current[1];

        const midX = (h1.middleBase.x + h2.middleBase.x) / 2;
        const midY = (h1.middleBase.y + h2.middleBase.y) / 2;

        ctx.save();
        ctx.beginPath();
        ctx.moveTo(h1.middleBase.x, h1.middleBase.y);
        ctx.lineTo(h2.middleBase.x, h2.middleBase.y);
        ctx.strokeStyle = theme.primary;
        ctx.lineWidth = 20 + Math.sin(t * 10) * 5; 
        ctx.lineCap = 'round';
        ctx.shadowBlur = 20; 
        ctx.shadowColor = theme.secondary;
        ctx.globalAlpha = 0.4;
        ctx.stroke();
        ctx.restore();

        drawRuneRing(ctx, midX, midY, 180, t, theme);
        drawSacredGeometry(ctx, midX, midY, 140, -t * 2, theme);
        spawnParticles(midX, midY, comboName, theme);

        handDataRef.current.forEach(h => {
             drawSkeleton(ctx, h);
             const auraSize = 50 + Math.sin(t * 20) * 10;
             const grad = ctx.createRadialGradient(h.middleBase.x, h.middleBase.y, 10, h.middleBase.x, h.middleBase.y, auraSize);
             grad.addColorStop(0, theme.core);
             grad.addColorStop(0.4, theme.primary);
             grad.addColorStop(1, 'rgba(0,0,0,0)');
             ctx.save();
             ctx.fillStyle = grad;
             ctx.globalAlpha = 0.5;
             ctx.beginPath();
             ctx.arc(h.middleBase.x, h.middleBase.y, auraSize, 0, Math.PI * 2);
             ctx.fill();
             ctx.restore();
             drawRuneRing(ctx, h.middleBase.x, h.middleBase.y, 40, t*5, theme);
        });

    } else {
        // --- INDIVIDUAL MODE ---
        handDataRef.current.forEach((hand) => {
           drawSkeleton(ctx, hand);
           const element = hand.gesture;
           const handTheme = (element !== 'NEUTRAL' && THEMES[element]) ? THEMES[element] : THEMES['NEUTRAL'];
           const centerX = hand.middleBase.x; 
           const centerY = hand.middleBase.y; 

           if (element !== 'NEUTRAL') {
               if (flash > 0.05 && highlightRef.current > 0.05) {
                   ctx.save();
                   ctx.translate(centerX, centerY);
                   const waveSize = 120 + (1 - flash) * 100;
                   ctx.beginPath();
                   ctx.arc(0, 0, waveSize, 0, Math.PI * 2);
                   ctx.lineWidth = 10 * flash;
                   ctx.strokeStyle = handTheme.core;
                   ctx.shadowBlur = 20;
                   ctx.shadowColor = handTheme.secondary;
                   ctx.globalAlpha = flash;
                   ctx.stroke();
                   ctx.restore();
               }

               drawRuneRing(ctx, centerX, centerY, 120, t * 0.5, handTheme);
               drawSacredGeometry(ctx, centerX, centerY, 90, -t * 1.5, handTheme);
               drawSquareLayer(ctx, centerX, centerY, 65, t * 2.5, handTheme);
               const pulse = Math.sin(time * 0.005) * 0.5 + 0.5;
               drawPentagram(ctx, centerX, centerY, 40, t, pulse, handTheme);

               spawnParticles(centerX, centerY, element, handTheme);
           } else {
               ctx.globalAlpha = 0.3;
               drawRuneRing(ctx, centerX, centerY, 50, t * 0.2, handTheme);
           }
        });
    }

    updateParticles(ctx, width, height, centerX, centerY);
    requestRef.current = requestAnimationFrame(animate);
  }, [width, height, currentElement, hasStarted, isGameOver]);

  useEffect(() => {
    requestRef.current = requestAnimationFrame(animate);
    return () => { if (requestRef.current) cancelAnimationFrame(requestRef.current); };
  }, [animate]);

  return (
    <div className="relative w-full h-full overflow-hidden flex items-center justify-center font-sans">

        {/* Dynamic Background */}
        <div 
            className="absolute inset-0 transition-colors duration-700 ease-in-out z-0"
            style={{ backgroundColor: currentTheme.background }}
        />

        {/* Hidden Webcam */}
        <Webcam 
            ref={webcamRef} 
            audio={false} 
            width={width} 
            height={height} 
            mirrored={true} 
            screenshotFormat="image/jpeg" 
            className="absolute opacity-0 pointer-events-none" 
            onUserMedia={() => setCameraReady(true)}
            onUserMediaError={(e: any) => setLoadingError("摄像头访问失败: " + e)}
        />

        {/* Canvas Layer */}
        <canvas ref={canvasRef} style={{ width, height }} className="absolute top-0 left-0 z-10" />

        {/* GAME OVER SCREEN */}
        {isGameOver && (
             <div className="absolute inset-0 flex items-center justify-center bg-black/80 z-50 backdrop-blur-sm">
                <div className="text-center p-8 border border-red-500/50 rounded-xl bg-black/80 shadow-[0_0_50px_rgba(255,0,0,0.3)]">
                    <h2 className="text-4xl font-bold text-red-500 mb-4 tracking-widest">能量核心崩溃</h2>
                    <div className="text-2xl text-white mb-6">最终得分: <span className="text-amber-500 font-mono">{uiScore}</span></div>
                    <button 
                        onClick={startExperience}
                        className="px-8 py-3 bg-red-900 hover:bg-red-700 text-white font-bold rounded border border-red-500 transition-colors"
                    >
                        重启时间线
                    </button>
                </div>
             </div>
        )}

        {!isModelLoaded && !isGameOver && (
            <div className="absolute inset-0 flex items-center justify-center bg-black bg-opacity-90 z-50">
                <div className="flex flex-col items-center">
                    <div className="text-amber-500 font-mono text-xl animate-pulse tracking-widest mb-4">🔮 正在校准魔法维度...</div>
                    {loadingError ? (
                        <div className="text-red-500 font-bold bg-black/50 p-2 rounded">{loadingError}</div>
                    ) : (
                        <div className="w-64 h-1 bg-gray-800 rounded-full overflow-hidden">
                            <div className="h-full bg-amber-500 animate-[width_1s_ease-in-out_infinite]" style={{width: '50%'}}></div>
                        </div>
                    )}
                    <div className="mt-4 text-xs text-gray-400 font-mono">{debugInfo}</div>
                </div>
            </div>
        )}

        {!hasStarted && isModelLoaded && !isGameOver && (
            <div className="absolute inset-0 flex items-center justify-center bg-black/60 z-50 cursor-pointer backdrop-blur-sm" onClick={startExperience}>
                <div className="border border-amber-500/50 bg-black/80 p-8 rounded-lg text-center shadow-[0_0_30px_rgba(255,160,20,0.3)] hover:scale-105 transition-transform duration-300">
                    <h2 className="text-3xl font-bold text-amber-500 mb-2">准备就绪</h2>
                    <p className="text-white/80 mb-6">点击屏幕开启守护试炼</p>
                    <button className="px-6 py-2 bg-amber-600 hover:bg-amber-500 text-black font-bold rounded">进入</button>
                </div>
            </div>
        )}

        {/* Dynamic Spell Name */}
        <div className="absolute top-20 left-0 w-full flex justify-center z-20 pointer-events-none">
             <div className={`text-4xl md:text-5xl font-bold tracking-widest transition-all duration-300 drop-shadow-[0_0_15px_rgba(255,255,255,0.4)] px-8 py-2 rounded-full ${highlightRef.current > 0.1 ? 'scale-110 bg-black/20 backdrop-blur-sm' : ''} ${
                currentElement === 'FIRE' ? 'text-orange-500' :
                currentElement === 'WATER' ? 'text-blue-500' :
                currentElement === 'WIND' ? 'text-cyan-300' :
                currentElement === 'THUNDER' ? 'text-purple-500' : 
                currentElement === 'INFERNO' ? 'text-red-600' :
                currentElement === 'BLIZZARD' ? 'text-cyan-100' :
                currentElement === 'VOID' ? 'text-violet-400' : 'text-amber-400'
            }`}>
                {ELEMENT_NAMES_CN[currentElement]}
            </div>
        </div>

        {/* RIGHT SIDE HUD - SCOREBOARD */}
        {hasStarted && (
            <div className="absolute top-1/2 right-4 -translate-y-1/2 z-20 flex flex-col gap-4 items-end">
                <div className="bg-black/60 backdrop-blur-sm border border-amber-500/30 p-4 rounded-xl text-right w-48 shadow-lg">
                    <div className="text-xs text-amber-500/80 uppercase tracking-widest mb-1">Score</div>
                    <div className="text-3xl font-mono text-white font-bold tabular-nums">
                        {uiScore.toLocaleString()}
                    </div>
                </div>

                <div className="bg-black/60 backdrop-blur-sm border border-white/20 p-4 rounded-xl text-right w-48 shadow-lg">
                    <div className="text-xs text-white/60 uppercase tracking-widest mb-2">Core Integrity</div>
                    <div className="w-full h-3 bg-gray-800 rounded-full overflow-hidden mb-1">
                        <div 
                            className={`h-full transition-all duration-300 ${uiHealth > 30 ? 'bg-green-500' : 'bg-red-500 animate-pulse'}`} 
                            style={{ width: `${Math.max(0, uiHealth)}%` }}
                        />
                    </div>
                    <div className="text-sm font-mono text-white/80">{Math.max(0, uiHealth)}%</div>
                </div>
            </div>
        )}

        {/* Toggle Controls Button */}
        <div className="absolute top-4 right-4 z-30">
            <button 
                onClick={() => setShowControls(!showControls)}
                className="bg-black/40 border border-white/10 p-2 rounded hover:bg-white/10 transition-colors text-white/50 text-xs uppercase font-mono tracking-wider"
            >
                {showControls ? 'Hide Controls' : 'Show Controls'}
            </button>
        </div>

        {/* Debug Info */}
        <div className="absolute top-12 right-4 z-20 text-right opacity-50 pointer-events-none">
             <div className="text-xs text-amber-200 font-mono">{debugInfo}</div>
        </div>

        {/* PARTICLE CONTROLS PANEL (Hidden by Default) */}
        {showControls && (
            <div className="absolute top-20 right-4 z-30 w-64 bg-black/60 backdrop-blur-md border border-white/10 rounded-xl p-4 shadow-2xl animate-[fadeIn_0.3s_ease-out]">
                <h3 className="text-amber-500 text-xs font-bold uppercase tracking-widest mb-4 border-b border-white/10 pb-2">粒子引擎参数</h3>

                <div className="space-y-4">
                    <div>
                        <div className="flex justify-between text-xs text-white/70 mb-1">
                            <span>速度 (Velocity)</span>
                            <span className="font-mono text-amber-400">{settings.speed.toFixed(1)}x</span>
                        </div>
                        <input 
                            type="range" min="0.1" max="10.0" step="0.1" 
                            value={settings.speed}
                            onChange={(e) => setSettings({...settings, speed: parseFloat(e.target.value)})}
                            className="w-full h-1 bg-white/20 rounded-lg appearance-none cursor-pointer accent-amber-500"
                        />
                    </div>

                    <div>
                        <div className="flex justify-between text-xs text-white/70 mb-1">
                            <span>数量 (Density)</span>
                            <span className="font-mono text-amber-400">{settings.count.toFixed(1)}x</span>
                        </div>
                        <input 
                            type="range" min="0.1" max="5.0" step="0.1" 
                            value={settings.count}
                            onChange={(e) => setSettings({...settings, count: parseFloat(e.target.value)})}
                            className="w-full h-1 bg-white/20 rounded-lg appearance-none cursor-pointer accent-amber-500"
                        />
                    </div>

                    <div>
                        <div className="flex justify-between text-xs text-white/70 mb-1">
                            <span>辉光 (Glow)</span>
                            <span className="font-mono text-amber-400">{settings.glow.toFixed(1)}x</span>
                        </div>
                        <input 
                            type="range" min="0.5" max="3.0" step="0.1" 
                            value={settings.glow}
                            onChange={(e) => setSettings({...settings, glow: parseFloat(e.target.value)})}
                            className="w-full h-1 bg-white/20 rounded-lg appearance-none cursor-pointer accent-amber-500"
                        />
                    </div>
                </div>
            </div>
        )}

        {/* Gesture Guide - Simplified for Game Mode */}
        {!hasStarted && (
            <div className="absolute bottom-0 left-0 w-full p-6 z-20">
                <div className="max-w-4xl mx-auto bg-black/40 backdrop-blur-md border border-white/10 rounded-2xl p-4 shadow-2xl">
                    <div className="flex flex-wrap justify-center items-center gap-4 md:gap-8 text-white/90 text-sm font-medium">
                        <div className="flex items-center gap-3 bg-white/5 px-4 py-2 rounded-lg border border-white/5">
                            <span className="text-2xl">✋</span> 
                            <div className="flex flex-col leading-tight">
                                <span className="text-orange-400 font-bold">火焰</span>
                                <span className="text-[10px] text-gray-400">克制流水</span>
                            </div>
                        </div>
                        <div className="flex items-center gap-3 bg-white/5 px-4 py-2 rounded-lg border border-white/5">
                            <span className="text-2xl">👇</span>
                            <div className="flex flex-col leading-tight">
                                <span className="text-blue-400 font-bold">流水</span>
                                <span className="text-[10px] text-gray-400">克制火焰</span>
                            </div>
                        </div>
                        <div className="flex items-center gap-3 bg-white/5 px-4 py-2 rounded-lg border border-white/5">
                            <span className="text-2xl">👊</span>
                            <div className="flex flex-col leading-tight">
                                <span className="text-purple-400 font-bold">雷霆</span>
                                <span className="text-[10px] text-gray-400">克制疾风</span>
                            </div>
                        </div>
                        <div className="flex items-center gap-3 bg-white/5 px-4 py-2 rounded-lg border border-white/5">
                            <span className="text-2xl">✌️</span>
                            <div className="flex flex-col leading-tight">
                                <span className="text-teal-300 font-bold">疾风</span>
                                <span className="text-[10px] text-gray-400">克制雷霆</span>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        )}
    </div>
  );
};

export default MagicOverlay;

import React, { useEffect, useRef, useCallback, useState } from 'react';
import Webcam from 'react-webcam';
import { Particle, HandData, ElementType, Theme, ParticleType, Monster } from '../types';
import { 
  drawRuneRing, 
  drawSacredGeometry, 
  drawSquareLayer, 
  drawPentagram,
  THEMES
} from '../utils/geometry';

interface MagicOverlayProps {
  width: number;
  height: number;
}

const COMBO_THEMES: Record<string, Theme> = {
  'BLIZZARD': { primary: '#00FFFF', secondary: '#E0FFFF', core: '#FFFFFF', shadow: '#008B8B', background: '#0a1a20' }, 
  'PLASMA': { primary: '#FF00FF', secondary: '#00FFFF', core: '#FFFFFF', shadow: '#9400D3', background: '#1a051a' }, 
  'STEAM': { primary: '#F0F8FF', secondary: '#B0C4DE', core: '#FFFFFF', shadow: '#778899', background: '#10151a' }, 
  'TEMPEST': { primary: '#000080', secondary: '#8A2BE2', core: '#FFFF00', shadow: '#191970', background: '#05051a' }, 
  'INFERNO': { primary: '#FF0000', secondary: '#FF4500', core: '#FFFF00', shadow: '#8B0000', background: '#2a0500' }, 
  'VOID': { primary: '#000000', secondary: '#4B0082', core: '#FFFFFF', shadow: '#9400D3', background: '#000000' }, 
};

const ELEMENT_NAMES_CN: Record<string, string> = {
    'NEUTRAL': '等待施法...',
    'FIRE': '🔥 烈焰术 (FIRE)',
    'WATER': '💧 唤雨术 (WATER)',
    'THUNDER': '⚡ 雷霆术 (THUNDER)',
    'WIND': '🌪️ 疾风术 (WIND)',
    'BLIZZARD': '❄️ 极寒风暴 (BLIZZARD)',
    'PLASMA': '⚛️ 等离子破 (PLASMA)',
    'STEAM': '♨️ 灼热蒸汽 (STEAM)',
    'TEMPEST': '⛈️ 雷暴风眼 (TEMPEST)',
    'INFERNO': '🌋 地狱烈火 (INFERNO)',
    'VOID': '🌌 虚空奇点 (VOID)'
};

const getCombo = (g1: ElementType, g2: ElementType): string | null => {
    const sorted = [g1, g2].sort().join('_');
    switch(sorted) {
        case 'WATER_WIND': return 'BLIZZARD';
        case 'FIRE_WIND': return 'PLASMA';
        case 'FIRE_WATER': return 'STEAM';
        case 'THUNDER_WATER': return 'TEMPEST';
        case 'FIRE_FIRE': return 'INFERNO';
        case 'THUNDER_THUNDER': return 'VOID';
        default: return null;
    }
};

const MagicOverlay: React.FC<MagicOverlayProps> = ({ width, height }) => {
  const webcamRef = useRef<Webcam>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>(0);

  // Game Refs
  const particlesRef = useRef<Particle[]>([]);
  const handDataRef = useRef<HandData[]>([]);
  const monstersRef = useRef<Monster[]>([]);
  const monsterSpawnTimerRef = useRef<number>(0);
  const scoreRef = useRef<number>(0);
  const coreHealthRef = useRef<number>(100);

  // App State
  const [currentElement, setCurrentElement] = useState<string>('NEUTRAL');
  const [isModelLoaded, setIsModelLoaded] = useState(false);
  const [loadingError, setLoadingError] = useState<string | null>(null);
  const [debugInfo, setDebugInfo] = useState<string>("初始化系统...");
  const [hasStarted, setHasStarted] = useState(false);
  const [showControls, setShowControls] = useState(false); 
  const [isCameraReady, setCameraReady] = useState(false);

  // Game UI State
  const [uiScore, setUiScore] = useState(0);
  const [uiHealth, setUiHealth] = useState(100);
  const [isGameOver, setIsGameOver] = useState(false);

  // Settings State - Updated Defaults per request
  const [settings, setSettings] = useState({
      speed: 1.0,   
      count: 0.5,   
      glow: 1.0,    
  });

  // Settings Ref (for access inside animation loop without stale closures)
  const settingsRef = useRef(settings);
  useEffect(() => { settingsRef.current = settings; }, [settings]);

  // Visual Feedback State
  const highlightRef = useRef<number>(0);
  const prevElementRef = useRef<string>('NEUTRAL');
  const activeComboRef = useRef<string | null>(null);

  // Audio Context
  const audioContextRef = useRef<AudioContext | null>(null);
  const noiseBufferRef = useRef<AudioBuffer | null>(null);

  // Get current Theme for background
  const currentTheme = activeComboRef.current 
    ? COMBO_THEMES[activeComboRef.current] 
    : (THEMES[currentElement as ElementType] || THEMES['NEUTRAL']);

  useEffect(() => {
    const AudioContextClass = (window as any).AudioContext || (window as any).webkitAudioContext;
    if (AudioContextClass) {
        const ctx = new AudioContextClass();
        audioContextRef.current = ctx;

        const bufferSize = ctx.sampleRate * 2; 
        const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
        const data = buffer.getChannelData(0);
        for (let i = 0; i < bufferSize; i++) {
            data[i] = Math.random() * 2 - 1;
        }
        noiseBufferRef.current = buffer;
    }
  }, []);

  const startExperience = () => {
      setHasStarted(true);
      if (audioContextRef.current?.state === 'suspended') {
          audioContextRef.current.resume();
      }
      // Reset Game
      monstersRef.current = [];
      scoreRef.current = 0;
      coreHealthRef.current = 100;
      setUiScore(0);
      setUiHealth(100);
      setIsGameOver(false);
  };

  const playChime = useCallback((element: string) => {
    const ctx = audioContextRef.current;
    if (!ctx || !noiseBufferRef.current) return;
    if (ctx.state === 'suspended') ctx.resume().catch(console.error);

    const now = ctx.currentTime;
    const masterGain = ctx.createGain();
    masterGain.connect(ctx.destination);
    masterGain.gain.setValueAtTime(0.3, now); 

    const playNoise = (filterType: BiquadFilterType, freqStart: number, freqEnd: number, duration: number, vol: number = 1, delay: number = 0) => {
        const src = ctx.createBufferSource();
        src.buffer = noiseBufferRef.current;
        src.loop = true;
        const filter = ctx.createBiquadFilter();
        filter.type = filterType;
        filter.frequency.setValueAtTime(freqStart, now + delay);
        filter.frequency.exponentialRampToValueAtTime(freqEnd, now + delay + duration);
        filter.Q.value = 1;
        const amp = ctx.createGain();
        amp.gain.setValueAtTime(0, now + delay);
        amp.gain.linearRampToValueAtTime(vol, now + delay + 0.05);
        amp.gain.exponentialRampToValueAtTime(0.01, now + delay + duration);
        src.connect(filter);
        filter.connect(amp);
        amp.connect(masterGain);
        src.start(now + delay);
        src.stop(now + delay + duration + 0.2);
    };

    const playTone = (type: OscillatorType, freqStart: number, freqEnd: number, duration: number, vol: number = 1, delay: number = 0) => {
        const osc = ctx.createOscillator();
        osc.type = type;
        osc.frequency.setValueAtTime(freqStart, now + delay);
        if (freqStart !== freqEnd) osc.frequency.exponentialRampToValueAtTime(freqEnd, now + delay + duration);
        const amp = ctx.createGain();
        amp.gain.setValueAtTime(0, now + delay);
        amp.gain.linearRampToValueAtTime(vol, now + delay + 0.05);
        amp.gain.exponentialRampToValueAtTime(0.01, now + delay + duration);
        osc.connect(amp);
        amp.connect(masterGain);
        osc.start(now + delay);
        osc.stop(now + delay + duration + 0.2);
    };

    switch (element) {
        case 'FIRE': playNoise('lowpass', 500, 100, 1.0, 0.5); playTone('sawtooth', 80, 120, 0.8, 0.2); break;
        case 'WATER': playNoise('bandpass', 800, 300, 0.6, 0.4); playTone('sine', 600, 300, 0.4, 0.3, 0.1); break;
        case 'WIND': playNoise('lowpass', 200, 800, 0.4, 0.3); playNoise('highpass', 400, 1000, 0.5, 0.2, 0.1); break;
        case 'THUNDER': playTone('sawtooth', 800, 50, 0.3, 0.2); playNoise('lowpass', 1000, 50, 1.2, 0.6, 0.1); break;
        case 'BLIZZARD': playNoise('highpass', 1000, 3000, 1.5, 0.4); playTone('sine', 1500, 2000, 0.3, 0.1, 0.1); break;
        case 'INFERNO': playNoise('lowpass', 800, 50, 1.5, 0.8); playTone('square', 60, 40, 1.5, 0.2); break;
        case 'TEMPEST': playNoise('lowpass', 200, 50, 2.0, 0.8); playTone('sawtooth', 1200, 100, 0.5, 0.2, 0.1); playNoise('bandpass', 1000, 500, 1.0, 0.3); break;
        case 'VOID': playTone('sine', 50, 40, 2.5, 0.6); playNoise('bandpass', 100, 200, 2.5, 0.4); playTone('sine', 300, 290, 1.0, 0.1, 0.5); break;
        case 'PLASMA': playTone('sawtooth', 200, 800, 1.0, 0.2); playNoise('bandpass', 400, 1200, 1.0, 0.4); break;
        case 'STEAM': playNoise('highpass', 500, 1000, 1.0, 0.3); break;
        default: playTone('triangle', 440, 880, 0.3, 0.1);
    }
  }, []);

  const detectGesture = (landmarks: any[], videoWidth: number, videoHeight: number): ElementType => {
    const mapPt = (idx: number) => ({ x: (1 - landmarks[idx].x) * videoWidth, y: landmarks[idx].y * videoHeight });
    const wrist = mapPt(0);
    const indexTip = mapPt(8);
    const middleTip = mapPt(12);
    const middleMCP = mapPt(9);

    // Optimized Distances
    const distSq = (p1: any, p2: any) => (p1.x - p2.x)**2 + (p1.y - p2.y)**2;
    const isFingerOpen = (tip: any, mcp: any) => distSq(tip, wrist) > distSq(mcp, wrist) * 1.2;

    const isPointingDown = wrist.y < middleMCP.y;
    if (isPointingDown) return 'WATER';

    let openCount = 0;
    if (isFingerOpen(indexTip, mapPt(5))) openCount++;
    if (isFingerOpen(middleTip, mapPt(9))) openCount++;
    if (isFingerOpen(mapPt(16), mapPt(13))) openCount++;
    if (isFingerOpen(mapPt(20), mapPt(17))) openCount++;

    if (openCount >= 4) return 'FIRE';
    if (openCount >= 2) return 'WIND';
    return 'THUNDER';
  };

  const drawSkeleton = (ctx: CanvasRenderingContext2D, hand: HandData) => {
      ctx.strokeStyle = "rgba(255, 255, 255, 0.15)";
      ctx.lineWidth = 1.5;
      ctx.fillStyle = "rgba(255, 255, 255, 0.5)";
      const points = [hand.wrist, hand.indexBase, hand.indexTip, hand.middleBase, hand.middleTip, hand.ringBase, hand.ringTip, hand.pinkyBase, hand.pinkyTip, hand.thumbTip];

      const drawLine = (p1: any, p2: any) => { ctx.beginPath(); ctx.moveTo(p1.x, p1.y); ctx.lineTo(p2.x, p2.y); ctx.stroke(); }
      drawLine(hand.wrist, hand.indexBase); drawLine(hand.indexBase, hand.indexTip);
      drawLine(hand.wrist, hand.middleBase); drawLine(hand.middleBase, hand.middleTip);
      drawLine(hand.wrist, hand.pinkyBase); drawLine(hand.pinkyBase, hand.pinkyTip);

      points.forEach(p => { ctx.beginPath(); ctx.arc(p.x, p.y, 2.5, 0, Math.PI * 2); ctx.fill(); });
  };

  const onResults = useCallback((results: any) => {
    const displayWidth = width;
    const displayHeight = height;

    setIsModelLoaded((prev) => {
        if (!prev) return true;
        return prev;
    });

    if (results.multiHandLandmarks && results.multiHandLandmarks.length > 0) {
      // Don't update debug info constantly to save renders
      const newHandData: HandData[] = results.multiHandLandmarks.map((landmarks: any[]) => {
        const gesture = detectGesture(landmarks, displayWidth, displayHeight);
        const mapPt = (idx: number) => ({ x: (1 - landmarks[idx].x) * displayWidth, y: landmarks[idx].y * displayHeight });
        return {
          wrist: mapPt(0), indexTip: mapPt(8), middleTip: mapPt(12), ringTip: mapPt(16), pinkyTip: mapPt(20), thumbTip: mapPt(4),
          indexBase: mapPt(5), middleBase: mapPt(9), ringBase: mapPt(13), pinkyBase: mapPt(17),
          isOpen: gesture !== 'THUNDER', gesture, opacity: 1
        };
      });

      handDataRef.current = newHandData;
      let newElement = 'NEUTRAL';
      let activeCombo = null;

      if (newHandData.length === 2) {
          const g1 = newHandData[0].gesture;
          const g2 = newHandData[1].gesture;
          if (g1 !== 'NEUTRAL' && g2 !== 'NEUTRAL') activeCombo = getCombo(g1, g2);
      }

      if (activeCombo) newElement = activeCombo;
      else {
          const activeHand = newHandData.find(h => h.gesture !== 'NEUTRAL');
          if (activeHand) newElement = activeHand.gesture;
      }
      activeComboRef.current = activeCombo;

      if (newElement !== prevElementRef.current) {
          if (newElement !== 'NEUTRAL') { highlightRef.current = 1.0; playChime(newElement); }
          prevElementRef.current = newElement;
      }
      setCurrentElement(newElement);
    } else {
      handDataRef.current = [];
      activeComboRef.current = null;
      if (prevElementRef.current !== 'NEUTRAL') { prevElementRef.current = 'NEUTRAL'; setCurrentElement('NEUTRAL'); }
    }
  }, [width, height, playChime]);

  useEffect(() => {
    let hands: any = null;
    let isActive = true;
    let frameId: number;
    let lastVideoTime = -1;

    const MP_VERSION = "0.4.1675469240";

    const initHands = async () => {
       try {
           setDebugInfo("正在加载 AI 核心 (1/3)...");
           if (!(window as any).Hands) { 
               setTimeout(initHands, 500); 
               return; 
           }

           setDebugInfo("初始化视觉模型 (2/3)...");
           hands = new (window as any).Hands({ 
               locateFile: (file: string) => `https://cdn.jsdelivr.net/npm/@mediapipe/hands@${MP_VERSION}/${file}` 
           });

           hands.setOptions({ 
               maxNumHands: 2, 
               modelComplexity: 1, 
               minDetectionConfidence: 0.5, 
               minTrackingConfidence: 0.5 
           });

           hands.onResults(onResults);

           setDebugInfo("等待摄像头许可...");

           const processVideo = async () => {
             if (!isActive) return;
             if (webcamRef.current && webcamRef.current.video && webcamRef.current.video.readyState === 4) {
                 const video = webcamRef.current.video;
                 if (video.videoWidth > 0 && video.videoHeight > 0) {
                     if (video.currentTime !== lastVideoTime) {
                         lastVideoTime = video.currentTime;
                         try { 
                             setDebugInfo("正在处理视频流...");
                             await hands.send({ image: video }); 
                         } catch (e) { 
                             console.warn("Processing warning", e); 
                         }
                     }
                 }
             }
             frameId = requestAnimationFrame(processVideo);
           };
           processVideo();
       } catch (error: any) {
           console.error("Initialization Error:", error);
           setLoadingError("AI 模型加载失败: " + error.message);
           setDebugInfo("系统错误");
       }
    };

    setTimeout(initHands, 500);

    return () => { isActive = false; if (frameId) cancelAnimationFrame(frameId); if (hands) hands.close(); };
  }, [onResults]);

  // --- GAME LOGIC ---

  const spawnMonster = (width: number, height: number) => {
      const edge = Math.floor(Math.random() * 4); // 0: Top, 1: Right, 2: Bottom, 3: Left
      let x = 0, y = 0;

      switch(edge) {
          case 0: x = Math.random() * width; y = -50; break;
          case 1: x = width + 50; y = Math.random() * height; break;
          case 2: x = Math.random() * width; y = height + 50; break;
          case 3: x = -50; y = Math.random() * height; break;
      }

      const elements: ElementType[] = ['FIRE', 'WATER', 'WIND', 'THUNDER'];
      const element = elements[Math.floor(Math.random() * elements.length)];

      const monster: Monster = {
          id: Date.now() + Math.random(),
          x, y,
          vx: 0, vy: 0, // Calculated in update
          hp: 100,
          maxHp: 100,
          element,
          radius: 20 + Math.random() * 10,
          scoreValue: 100,
          pulseOffset: Math.random() * Math.PI * 2
      };
      monstersRef.current.push(monster);
  };

  const updateMonsters = (ctx: CanvasRenderingContext2D, width: number, height: number, centerX: number, centerY: number, hands: HandData[]) => {
      const monsters = monstersRef.current;

      const getMultiplier = (spell: string, monsterEl: string) => {
          // Double score for counter-elements as requested
          if (spell === 'FIRE' && monsterEl === 'WATER') return 2;
          if (spell === 'WATER' && monsterEl === 'FIRE') return 2;
          if (spell === 'THUNDER' && monsterEl === 'WIND') return 2;
          if (spell === 'WIND' && monsterEl === 'THUNDER') return 2;
          if (spell === 'BLIZZARD' || spell === 'INFERNO' || spell === 'TEMPEST' || spell === 'PLASMA') return 3;
          if (spell === 'VOID') return 5;
          return 1;
      };

      for (let i = monsters.length - 1; i >= 0; i--) {
          const m = monsters[i];
          const dx = centerX - m.x;
          const dy = centerY - m.y;
          const distToCenter = Math.sqrt(dx*dx + dy*dy);

          // Move towards center
          const angle = Math.atan2(dy, dx);
          const speed = 1.5 + (scoreRef.current / 5000); // Difficulty scaling
          m.x += Math.cos(angle) * speed;
          m.y += Math.sin(angle) * speed;

          // Draw Monster
          const mTheme = THEMES[m.element];
          ctx.save();
          ctx.translate(m.x, m.y);
          const pulse = 1 + Math.sin(Date.now() * 0.005 + m.pulseOffset) * 0.2;
          ctx.scale(pulse, pulse);

          ctx.beginPath();
          // Draw a spiky shape
          const spikes = 5;
          const outerRadius = m.radius;
          const innerRadius = m.radius / 2;
          for (let j = 0; j < spikes * 2; j++) {
             const r = j % 2 === 0 ? outerRadius : innerRadius;
             const a = (Math.PI * j) / spikes;
             ctx.lineTo(Math.cos(a) * r, Math.sin(a) * r);
          }
          ctx.closePath();
          ctx.fillStyle = mTheme.background;
          ctx.fill();
          ctx.strokeStyle = mTheme.primary;
          ctx.lineWidth = 3;
          ctx.stroke();

          // Element Icon or Glow
          ctx.shadowBlur = 15;
          ctx.shadowColor = mTheme.secondary;
          ctx.fillStyle = mTheme.core;
          ctx.beginPath();
          ctx.arc(0, 0, innerRadius * 0.5, 0, Math.PI * 2);
          ctx.fill();
          ctx.shadowBlur = 0;

          ctx.restore();

          // Check Collision with Hands
          let hit = false;
          for (const hand of hands) {
              if (hand.gesture !== 'NEUTRAL') {
                  const hx = hand.middleBase.x;
                  const hy = hand.middleBase.y;
                  const hDist = Math.hypot(hx - m.x, hy - m.y);

                  // Hitbox radius depends on spell
                  const hitRadius = activeComboRef.current ? 120 : 80;

                  if (hDist < hitRadius + m.radius) {
                      const mult = getMultiplier(activeComboRef.current || hand.gesture, m.element);
                      m.hp -= 3 * mult; // Damage per frame
                      hit = true;

                      // Spawn hit particles
                      if (Math.random() > 0.7) {
                          spawnParticles(m.x, m.y, activeComboRef.current || hand.gesture, mTheme);
                      }

                      // Visual feedback for hit
                      ctx.save();
                      ctx.globalCompositeOperation = 'lighter';
                      ctx.fillStyle = '#FFFFFF';
                      ctx.beginPath();
                      ctx.arc(m.x, m.y, m.radius * 1.5, 0, Math.PI*2);
                      ctx.globalAlpha = 0.5;
                      ctx.fill();
                      ctx.restore();

                      // Show Multiplier Text Effect (Simplified for canvas performance)
                      if (mult > 1 && Math.random() > 0.95) {
                          // Could implement floating text system here, 
                          // but for now relying on particle feedback
                      }
                  }
              }
          }

          // Death or Core Hit
          if (m.hp <= 0) {
              monsters.splice(i, 1);
              const mult = activeComboRef.current ? 2 : 1; 
              scoreRef.current += m.scoreValue * mult;
              spawnParticles(m.x, m.y, m.element, mTheme);
              spawnParticles(m.x, m.y, m.element, mTheme);
              playChime(m.element);
          } else if (distToCenter < 40) {
              // Hit Core
              monsters.splice(i, 1);
              coreHealthRef.current -= 10;
              highlightRef.current = 1.0; 
              spawnParticles(centerX, centerY, 'NEUTRAL', THEMES['NEUTRAL']);
          }
      }
  };

  // --- PHYSICS ENGINE ---
  const updateParticles = (ctx: CanvasRenderingContext2D, width: number, height: number, centerX: number, centerY: number) => {
    ctx.shadowBlur = 0; 
    const { glow } = settingsRef.current;

    for (let i = particlesRef.current.length - 1; i >= 0; i--) {
      const p = particlesRef.current[i];

      if (p.element === 'WIND' || p.element === 'BLIZZARD') {
          p.vx *= 0.995; p.vy *= 0.995;
      } else {
          p.vx *= 0.98; p.vy *= 0.98;
      }

      switch (p.element) {
          case 'WIND':
          case 'BLIZZARD':
              const dx = p.x - centerX;
              const dy = p.y - centerY;
              const dist = Math.sqrt(dx*dx + dy*dy) + 1;
              const angle = Math.atan2(dy, dx);
              p.vx += Math.cos(angle + Math.PI/2) * 2.5; 
              p.vy += Math.sin(angle + Math.PI/2) * 2.5;
              p.vx -= (dx / dist) * 0.8;
              p.vy -= (dy / dist) * 0.8;
              p.angle += p.angularVelocity * 1.5; 
              break;
          case 'WATER':
          case 'STEAM':
              p.vy += 1.5; 
              p.x += Math.sin(p.life * 0.2) * 1.0;
              break;
          case 'THUNDER':
          case 'TEMPEST':
          case 'VOID':
              p.vx += (Math.random() - 0.5) * 6; 
              p.vy += (Math.random() - 0.5) * 6;
              if (Math.random() < 0.15) {
                  p.x += (Math.random() - 0.5) * 40;
                  p.y += (Math.random() - 0.5) * 40;
              }
              break;
          case 'FIRE':
          case 'INFERNO':
              p.vy -= 1.5; 
              p.vx += (Math.random() - 0.5) * 2.0;
              p.size *= 0.95; 
              break;
          default:
              p.vy -= 0.2;
      }

      p.x += p.vx;
      p.y += p.vy;
      p.life -= 1;
      if (p.element !== 'FIRE') p.size *= 0.98;

      if (p.life <= 0 || p.size < 0.1 || p.y > height + 50 || p.y < -50 || p.x < -50 || p.x > width + 50) {
        particlesRef.current.splice(i, 1);
      } else {
        ctx.save();
        if (p.size > 2) {
             const shadowOffsetX = (p.x - centerX) * 0.05;
             const shadowOffsetY = (p.y - centerY) * 0.05;
             ctx.fillStyle = "rgba(0,0,0,0.3)";
             ctx.beginPath();
             ctx.arc(p.x + shadowOffsetX, p.y + shadowOffsetY, p.size * glow, 0, Math.PI*2);
             ctx.fill();
        }

        let alpha = Math.min(1, p.life / 10, (p.maxLife - p.life) / 5);
        if ((p.element === 'FIRE' || p.element === 'INFERNO') && p.size < 3.5 && p.type === 'EMBER') {
             alpha *= (0.5 + Math.random() * 0.5);
        }

        ctx.globalAlpha = alpha;
        const renderSize = p.size * glow;

        if (p.type === 'LEAF') {
            ctx.translate(p.x, p.y);
            ctx.rotate(p.angle);
            ctx.fillStyle = p.color;
            ctx.beginPath();
            ctx.ellipse(0, 0, renderSize, renderSize * 0.4, 0, 0, Math.PI * 2);
            ctx.fill();
        } 
        else if (p.type === 'DROP') {
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 2.5 * glow;
            ctx.lineCap = 'round';
            ctx.beginPath();
            ctx.moveTo(p.x, p.y);
            ctx.lineTo(p.x - p.vx * 1.5, p.y - p.vy * 4); 
            ctx.stroke();
        }
        else if (p.type === 'SPARK') {
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 2 * glow;
            ctx.beginPath();
            ctx.moveTo(p.x - p.vx, p.y - p.vy);
            ctx.lineTo(p.x + p.vx, p.y + p.vy);
            ctx.stroke();
        }
        else {
            ctx.fillStyle = p.color;
            ctx.beginPath();
            ctx.arc(p.x, p.y, renderSize, 0, Math.PI * 2);
            ctx.fill();
        }
        ctx.restore();
      }
    }
  };

  const spawnParticles = (x: number, y: number, element: string, theme: Theme) => {
    const { speed: speedMulti, count: countMulti } = settingsRef.current;
    const isCombo = activeComboRef.current !== null;
    let baseCount = isCombo ? 10 : 3;
    let count = Math.ceil(baseCount * countMulti);
    count = Math.min(count, 50);

    for (let i = 0; i < count; i++) {
        let type: ParticleType = 'ORB';
        let speed = (Math.random() * 8 + 4) * speedMulti; 
        let spread = 30;
        let pColor = Math.random() > 0.5 ? theme.primary : theme.secondary;
        let pSize = 4 + Math.random() * 6;
        let pLife = 30 + Math.random() * 30;

        if (element === 'WIND' || element === 'BLIZZARD') {
            type = Math.random() > 0.5 ? 'LEAF' : 'MIST';
            if (isCombo) pColor = Math.random() > 0.5 ? '#00FFFF' : '#F0FFF0';
            else if (element === 'WIND') pColor = Math.random() > 0.5 ? '#00FFFF' : '#F0FFF0'; 
        } else if (element === 'WATER' || element === 'STEAM') {
            type = Math.random() > 0.7 ? 'MIST' : 'DROP';
            spread = 50; 
        } else if (element === 'THUNDER' || element === 'TEMPEST' || element === 'VOID') {
            type = 'SPARK';
            speed = 12 * speedMulti; 
            if (element === 'THUNDER') pColor = Math.random() > 0.5 ? '#FFFF00' : '#9400D3';
        } else if (element === 'FIRE' || element === 'INFERNO') {
            const r = Math.random();
            if (r < 0.3) {
                 type = 'EMBER';
                 pColor = Math.random() > 0.5 ? '#FFD700' : '#FFFFFF';
                 pSize = 1 + Math.random() * 3;
                 pLife = 15 + Math.random() * 20; 
                 speed *= 1.5; 
            } else if (r < 0.6) {
                 type = 'MIST'; 
            } else {
                 type = 'EMBER'; 
            }
        }

        const angle = Math.random() * Math.PI * 2;
        let vx = Math.cos(angle) * speed;
        let vy = Math.sin(angle) * speed;

        if (element === 'WATER' || element === 'STEAM') { vx *= 0.3; vy = Math.random() * 5 * speedMulti + 5; } 
        if ((element === 'FIRE' || element === 'INFERNO') && pSize < 4 && type === 'EMBER') {
            vy -= 2.0; 
        }

        let spawnX = x + (Math.random() - 0.5) * spread;
        let spawnY = y + (Math.random() - 0.5) * spread;

        particlesRef.current.push({
            x: spawnX,
            y: spawnY,
            vx, vy,
            life: pLife,
            maxLife: 60,
            size: pSize,
            color: pColor,
            element: element as Particle['element'],
            type,
            angle: Math.random() * Math.PI * 2,
            angularVelocity: (Math.random() - 0.5) * 0.4
        });
    }
  };

  const animate = useCallback((time: number) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d', { alpha: false }); 
    if (!ctx) return;

    const dpr = window.devicePixelRatio || 1;
    if (canvas.width !== width * dpr || canvas.height !== height * dpr) {
        canvas.width = width * dpr;
        canvas.height = height * dpr;
    }
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

    const theme = activeComboRef.current 
        ? COMBO_THEMES[activeComboRef.current] 
        : (THEMES[currentElement as ElementType] || THEMES['NEUTRAL']);

    ctx.globalCompositeOperation = 'source-over';

    ctx.fillStyle = theme.background;
    ctx.fillRect(0, 0, width, height);

    if (highlightRef.current > 0.01) highlightRef.current *= 0.925; 
    else highlightRef.current = 0;
    const flash = highlightRef.current;

    // --- GAME LOGIC UPDATES ---
    if (hasStarted && !isGameOver) {
        monsterSpawnTimerRef.current++;
        // Spawn rate based on score
        const spawnRate = Math.max(30, 100 - Math.floor(scoreRef.current / 2000));
        if (monsterSpawnTimerRef.current > spawnRate) {
            spawnMonster(width, height);
            monsterSpawnTimerRef.current = 0;
        }

        if (coreHealthRef.current <= 0) {
            setIsGameOver(true);
        }

        // Update UI state occasionally
        if (monsterSpawnTimerRef.current % 10 === 0) {
            setUiScore(scoreRef.current);
            setUiHealth(coreHealthRef.current);
        }
    }

    if (flash > 0.01) {
        ctx.save();
        ctx.globalCompositeOperation = 'lighter';
        ctx.strokeStyle = '#FF0000'; // Damage flash
        ctx.lineWidth = 30 * flash; 
        ctx.shadowBlur = 40;
        ctx.shadowColor = '#FF0000';
        ctx.globalAlpha = flash; 
        ctx.strokeRect(0, 0, width, height);
        ctx.restore();
    }

    let centerX = width / 2;
    let centerY = height / 2;
    const t = time * 0.001;
    const comboName = activeComboRef.current;

    // Draw Core
    ctx.save();
    ctx.translate(centerX, centerY);
    // Rotating crystal/core
    ctx.rotate(t * 0.5);
    ctx.fillStyle = '#FFFFFF';
    ctx.shadowBlur = 20 + Math.sin(t * 5) * 10;
    ctx.shadowColor = '#00FFFF';
    const coreSize = 30;
    ctx.beginPath();
    ctx.moveTo(0, -coreSize);
    ctx.lineTo(coreSize, 0);
    ctx.lineTo(0, coreSize);
    ctx.lineTo(-coreSize, 0);
    ctx.fill();

    // Core Health Ring
    ctx.rotate(-t * 0.5); // Counter rotate
    ctx.beginPath();
    const hpPct = Math.max(0, coreHealthRef.current / 100);
    ctx.arc(0, 0, 50, 0, Math.PI * 2 * hpPct);
    ctx.strokeStyle = coreHealthRef.current > 30 ? '#00FF00' : '#FF0000';
    ctx.lineWidth = 5;
    ctx.lineCap = 'round';
    ctx.stroke();

    // Background circle for health ring
    ctx.beginPath();
    ctx.arc(0, 0, 50, 0, Math.PI * 2);
    ctx.strokeStyle = 'rgba(255,255,255,0.1)';
    ctx.lineWidth = 5;
    ctx.stroke();

    ctx.restore();

    // 2. Geometry & Particles
    ctx.globalCompositeOperation = 'lighter'; 

    // Render Monsters
    updateMonsters(ctx, width, height, centerX, centerY, handDataRef.current);

    if (comboName && handDataRef.current.length === 2) {
        // --- COMBO MODE ---
        const h1 = handDataRef.current[0];
        const h2 = handDataRef.current[1];

        const midX = (h1.middleBase.x + h2.middleBase.x) / 2;
        const midY = (h1.middleBase.y + h2.middleBase.y) / 2;

        ctx.save();
        ctx.beginPath();
        ctx.moveTo(h1.middleBase.x, h1.middleBase.y);
        ctx.lineTo(h2.middleBase.x, h2.middleBase.y);
        ctx.strokeStyle = theme.primary;
        ctx.lineWidth = 20 + Math.sin(t * 10) * 5; 
        ctx.lineCap = 'round';
        ctx.shadowBlur = 20; 
        ctx.shadowColor = theme.secondary;
        ctx.globalAlpha = 0.4;
        ctx.stroke();
        ctx.restore();

        drawRuneRing(ctx, midX, midY, 180, t, theme);
        drawSacredGeometry(ctx, midX, midY, 140, -t * 2, theme);
        spawnParticles(midX, midY, comboName, theme);

        handDataRef.current.forEach(h => {
             drawSkeleton(ctx, h);
             const auraSize = 50 + Math.sin(t * 20) * 10;
             const grad = ctx.createRadialGradient(h.middleBase.x, h.middleBase.y, 10, h.middleBase.x, h.middleBase.y, auraSize);
             grad.addColorStop(0, theme.core);
             grad.addColorStop(0.4, theme.primary);
             grad.addColorStop(1, 'rgba(0,0,0,0)');
             ctx.save();
             ctx.fillStyle = grad;
             ctx.globalAlpha = 0.5;
             ctx.beginPath();
             ctx.arc(h.middleBase.x, h.middleBase.y, auraSize, 0, Math.PI * 2);
             ctx.fill();
             ctx.restore();
             drawRuneRing(ctx, h.middleBase.x, h.middleBase.y, 40, t*5, theme);
        });

    } else {
        // --- INDIVIDUAL MODE ---
        handDataRef.current.forEach((hand) => {
           drawSkeleton(ctx, hand);
           const element = hand.gesture;
           const handTheme = (element !== 'NEUTRAL' && THEMES[element]) ? THEMES[element] : THEMES['NEUTRAL'];
           const centerX = hand.middleBase.x; 
           const centerY = hand.middleBase.y; 

           if (element !== 'NEUTRAL') {
               if (flash > 0.05 && highlightRef.current > 0.05) {
                   ctx.save();
                   ctx.translate(centerX, centerY);
                   const waveSize = 120 + (1 - flash) * 100;
                   ctx.beginPath();
                   ctx.arc(0, 0, waveSize, 0, Math.PI * 2);
                   ctx.lineWidth = 10 * flash;
                   ctx.strokeStyle = handTheme.core;
                   ctx.shadowBlur = 20;
                   ctx.shadowColor = handTheme.secondary;
                   ctx.globalAlpha = flash;
                   ctx.stroke();
                   ctx.restore();
               }

               drawRuneRing(ctx, centerX, centerY, 120, t * 0.5, handTheme);
               drawSacredGeometry(ctx, centerX, centerY, 90, -t * 1.5, handTheme);
               drawSquareLayer(ctx, centerX, centerY, 65, t * 2.5, handTheme);
               const pulse = Math.sin(time * 0.005) * 0.5 + 0.5;
               drawPentagram(ctx, centerX, centerY, 40, t, pulse, handTheme);

               spawnParticles(centerX, centerY, element, handTheme);
           } else {
               ctx.globalAlpha = 0.3;
               drawRuneRing(ctx, centerX, centerY, 50, t * 0.2, handTheme);
           }
        });
    }

    updateParticles(ctx, width, height, centerX, centerY);
    requestRef.current = requestAnimationFrame(animate);
  }, [width, height, currentElement, hasStarted, isGameOver]);

  useEffect(() => {
    requestRef.current = requestAnimationFrame(animate);
    return () => { if (requestRef.current) cancelAnimationFrame(requestRef.current); };
  }, [animate]);

  return (
    <div className="relative w-full h-full overflow-hidden flex items-center justify-center font-sans">

        {/* Dynamic Background */}
        <div 
            className="absolute inset-0 transition-colors duration-700 ease-in-out z-0"
            style={{ backgroundColor: currentTheme.background }}
        />

        {/* Hidden Webcam */}
        <Webcam 
            ref={webcamRef} 
            audio={false} 
            width={width} 
            height={height} 
            mirrored={true} 
            screenshotFormat="image/jpeg" 
            className="absolute opacity-0 pointer-events-none" 
            onUserMedia={() => setCameraReady(true)}
            onUserMediaError={(e: any) => setLoadingError("摄像头访问失败: " + e)}
        />

        {/* Canvas Layer */}
        <canvas ref={canvasRef} style={{ width, height }} className="absolute top-0 left-0 z-10" />

        {/* GAME OVER SCREEN */}
        {isGameOver && (
             <div className="absolute inset-0 flex items-center justify-center bg-black/80 z-50 backdrop-blur-sm">
                <div className="text-center p-8 border border-red-500/50 rounded-xl bg-black/80 shadow-[0_0_50px_rgba(255,0,0,0.3)]">
                    <h2 className="text-4xl font-bold text-red-500 mb-4 tracking-widest">能量核心崩溃</h2>
                    <div className="text-2xl text-white mb-6">最终得分: <span className="text-amber-500 font-mono">{uiScore}</span></div>
                    <button 
                        onClick={startExperience}
                        className="px-8 py-3 bg-red-900 hover:bg-red-700 text-white font-bold rounded border border-red-500 transition-colors"
                    >
                        重启时间线
                    </button>
                </div>
             </div>
        )}

        {!isModelLoaded && !isGameOver && (
            <div className="absolute inset-0 flex items-center justify-center bg-black bg-opacity-90 z-50">
                <div className="flex flex-col items-center">
                    <div className="text-amber-500 font-mono text-xl animate-pulse tracking-widest mb-4">🔮 正在校准魔法维度...</div>
                    {loadingError ? (
                        <div className="text-red-500 font-bold bg-black/50 p-2 rounded">{loadingError}</div>
                    ) : (
                        <div className="w-64 h-1 bg-gray-800 rounded-full overflow-hidden">
                            <div className="h-full bg-amber-500 animate-[width_1s_ease-in-out_infinite]" style={{width: '50%'}}></div>
                        </div>
                    )}
                    <div className="mt-4 text-xs text-gray-400 font-mono">{debugInfo}</div>
                </div>
            </div>
        )}

        {!hasStarted && isModelLoaded && !isGameOver && (
            <div className="absolute inset-0 flex items-center justify-center bg-black/60 z-50 cursor-pointer backdrop-blur-sm" onClick={startExperience}>
                <div className="border border-amber-500/50 bg-black/80 p-8 rounded-lg text-center shadow-[0_0_30px_rgba(255,160,20,0.3)] hover:scale-105 transition-transform duration-300">
                    <h2 className="text-3xl font-bold text-amber-500 mb-2">准备就绪</h2>
                    <p className="text-white/80 mb-6">点击屏幕开启守护试炼</p>
                    <button className="px-6 py-2 bg-amber-600 hover:bg-amber-500 text-black font-bold rounded">进入</button>
                </div>
            </div>
        )}

        {/* Dynamic Spell Name */}
        <div className="absolute top-20 left-0 w-full flex justify-center z-20 pointer-events-none">
             <div className={`text-4xl md:text-5xl font-bold tracking-widest transition-all duration-300 drop-shadow-[0_0_15px_rgba(255,255,255,0.4)] px-8 py-2 rounded-full ${highlightRef.current > 0.1 ? 'scale-110 bg-black/20 backdrop-blur-sm' : ''} ${
                currentElement === 'FIRE' ? 'text-orange-500' :
                currentElement === 'WATER' ? 'text-blue-500' :
                currentElement === 'WIND' ? 'text-cyan-300' :
                currentElement === 'THUNDER' ? 'text-purple-500' : 
                currentElement === 'INFERNO' ? 'text-red-600' :
                currentElement === 'BLIZZARD' ? 'text-cyan-100' :
                currentElement === 'VOID' ? 'text-violet-400' : 'text-amber-400'
            }`}>
                {ELEMENT_NAMES_CN[currentElement]}
            </div>
        </div>

        {/* RIGHT SIDE HUD - SCOREBOARD */}
        {hasStarted && (
            <div className="absolute top-1/2 right-4 -translate-y-1/2 z-20 flex flex-col gap-4 items-end">
                <div className="bg-black/60 backdrop-blur-sm border border-amber-500/30 p-4 rounded-xl text-right w-48 shadow-lg">
                    <div className="text-xs text-amber-500/80 uppercase tracking-widest mb-1">Score</div>
                    <div className="text-3xl font-mono text-white font-bold tabular-nums">
                        {uiScore.toLocaleString()}
                    </div>
                </div>

                <div className="bg-black/60 backdrop-blur-sm border border-white/20 p-4 rounded-xl text-right w-48 shadow-lg">
                    <div className="text-xs text-white/60 uppercase tracking-widest mb-2">Core Integrity</div>
                    <div className="w-full h-3 bg-gray-800 rounded-full overflow-hidden mb-1">
                        <div 
                            className={`h-full transition-all duration-300 ${uiHealth > 30 ? 'bg-green-500' : 'bg-red-500 animate-pulse'}`} 
                            style={{ width: `${Math.max(0, uiHealth)}%` }}
                        />
                    </div>
                    <div className="text-sm font-mono text-white/80">{Math.max(0, uiHealth)}%</div>
                </div>
            </div>
        )}

        {/* Toggle Controls Button */}
        <div className="absolute top-4 right-4 z-30">
            <button 
                onClick={() => setShowControls(!showControls)}
                className="bg-black/40 border border-white/10 p-2 rounded hover:bg-white/10 transition-colors text-white/50 text-xs uppercase font-mono tracking-wider"
            >
                {showControls ? 'Hide Controls' : 'Show Controls'}
            </button>
        </div>

        {/* Debug Info */}
        <div className="absolute top-12 right-4 z-20 text-right opacity-50 pointer-events-none">
             <div className="text-xs text-amber-200 font-mono">{debugInfo}</div>
        </div>

        {/* PARTICLE CONTROLS PANEL (Hidden by Default) */}
        {showControls && (
            <div className="absolute top-20 right-4 z-30 w-64 bg-black/60 backdrop-blur-md border border-white/10 rounded-xl p-4 shadow-2xl animate-[fadeIn_0.3s_ease-out]">
                <h3 className="text-amber-500 text-xs font-bold uppercase tracking-widest mb-4 border-b border-white/10 pb-2">粒子引擎参数</h3>

                <div className="space-y-4">
                    <div>
                        <div className="flex justify-between text-xs text-white/70 mb-1">
                            <span>速度 (Velocity)</span>
                            <span className="font-mono text-amber-400">{settings.speed.toFixed(1)}x</span>
                        </div>
                        <input 
                            type="range" min="0.1" max="10.0" step="0.1" 
                            value={settings.speed}
                            onChange={(e) => setSettings({...settings, speed: parseFloat(e.target.value)})}
                            className="w-full h-1 bg-white/20 rounded-lg appearance-none cursor-pointer accent-amber-500"
                        />
                    </div>

                    <div>
                        <div className="flex justify-between text-xs text-white/70 mb-1">
                            <span>数量 (Density)</span>
                            <span className="font-mono text-amber-400">{settings.count.toFixed(1)}x</span>
                        </div>
                        <input 
                            type="range" min="0.1" max="5.0" step="0.1" 
                            value={settings.count}
                            onChange={(e) => setSettings({...settings, count: parseFloat(e.target.value)})}
                            className="w-full h-1 bg-white/20 rounded-lg appearance-none cursor-pointer accent-amber-500"
                        />
                    </div>

                    <div>
                        <div className="flex justify-between text-xs text-white/70 mb-1">
                            <span>辉光 (Glow)</span>
                            <span className="font-mono text-amber-400">{settings.glow.toFixed(1)}x</span>
                        </div>
                        <input 
                            type="range" min="0.5" max="3.0" step="0.1" 
                            value={settings.glow}
                            onChange={(e) => setSettings({...settings, glow: parseFloat(e.target.value)})}
                            className="w-full h-1 bg-white/20 rounded-lg appearance-none cursor-pointer accent-amber-500"
                        />
                    </div>
                </div>
            </div>
        )}

        {/* Gesture Guide - Simplified for Game Mode */}
        {!hasStarted && (
            <div className="absolute bottom-0 left-0 w-full p-6 z-20">
                <div className="max-w-4xl mx-auto bg-black/40 backdrop-blur-md border border-white/10 rounded-2xl p-4 shadow-2xl">
                    <div className="flex flex-wrap justify-center items-center gap-4 md:gap-8 text-white/90 text-sm font-medium">
                        <div className="flex items-center gap-3 bg-white/5 px-4 py-2 rounded-lg border border-white/5">
                            <span className="text-2xl">✋</span> 
                            <div className="flex flex-col leading-tight">
                                <span className="text-orange-400 font-bold">火焰</span>
                                <span className="text-[10px] text-gray-400">克制流水</span>
                            </div>
                        </div>
                        <div className="flex items-center gap-3 bg-white/5 px-4 py-2 rounded-lg border border-white/5">
                            <span className="text-2xl">👇</span>
                            <div className="flex flex-col leading-tight">
                                <span className="text-blue-400 font-bold">流水</span>
                                <span className="text-[10px] text-gray-400">克制火焰</span>
                            </div>
                        </div>
                        <div className="flex items-center gap-3 bg-white/5 px-4 py-2 rounded-lg border border-white/5">
                            <span className="text-2xl">👊</span>
                            <div className="flex flex-col leading-tight">
                                <span className="text-purple-400 font-bold">雷霆</span>
                                <span className="text-[10px] text-gray-400">克制疾风</span>
                            </div>
                        </div>
                        <div className="flex items-center gap-3 bg-white/5 px-4 py-2 rounded-lg border border-white/5">
                            <span className="text-2xl">✌️</span>
                            <div className="flex flex-col leading-tight">
                                <span className="text-teal-300 font-bold">疾风</span>
                                <span className="text-[10px] text-gray-400">克制雷霆</span>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        )}
    </div>
  );
};

export default MagicOverlay;

export type ElementType = 'NEUTRAL' | 'FIRE' | 'WATER' | 'THUNDER' | 'WIND';
export type ComboType = 'BLIZZARD' | 'PLASMA' | 'STEAM' | 'TEMPEST' | 'INFERNO' | 'VOID';
export type ParticleType = 'ORB' | 'LEAF' | 'SPARK' | 'DROP' | 'MIST' | 'EMBER';

export interface Point {
  x: number;
  y: number;
  z?: number;
}

export interface Particle {
  x: number;
  y: number;
  vx: number;
  vy: number;
  life: number;
  maxLife: number;
  size: number;
  color: string;
  element: ElementType | ComboType;
  type: ParticleType;
  angle: number;           // For rotation (leaves)
  angularVelocity: number; // For rotation speed
}

export interface Monster {
  id: number;
  x: number;
  y: number;
  vx: number;
  vy: number;
  hp: number;
  maxHp: number;
  element: ElementType;
  radius: number;
  scoreValue: number;
  pulseOffset: number;
  isBoss: boolean; // New property to identify boss units
}

export interface HandData {
  wrist: Point;
  indexTip: Point;
  middleTip: Point;
  ringTip: Point;
  pinkyTip: Point;
  thumbTip: Point;
  indexBase: Point; 
  middleBase: Point;
  ringBase: Point;
  pinkyBase: Point;
  isOpen: boolean;
  gesture: ElementType;
  opacity: number;
}

export interface Theme {
  primary: string;
  secondary: string;
  core: string;
  shadow: string;
  background: string; 
}

import React, { useEffect, useRef, useCallback, useState } from 'react';
import Webcam from 'react-webcam';
import { Particle, HandData, ElementType, Theme, ParticleType, Monster } from '../types';
import { 
  drawRuneRing, 
  drawSacredGeometry, 
  drawSquareLayer, 
  drawPentagram,
  THEMES
} from '../utils/geometry';

interface MagicOverlayProps {
  width: number;
  height: number;
}

const COMBO_THEMES: Record<string, Theme> = {
  'BLIZZARD': { primary: '#00FFFF', secondary: '#E0FFFF', core: '#FFFFFF', shadow: '#008B8B', background: '#0a1a20' }, 
  'PLASMA': { primary: '#FF00FF', secondary: '#00FFFF', core: '#FFFFFF', shadow: '#9400D3', background: '#1a051a' }, 
  'STEAM': { primary: '#F0F8FF', secondary: '#B0C4DE', core: '#FFFFFF', shadow: '#778899', background: '#10151a' }, 
  'TEMPEST': { primary: '#000080', secondary: '#8A2BE2', core: '#FFFF00', shadow: '#191970', background: '#05051a' }, 
  'INFERNO': { primary: '#FF0000', secondary: '#FF4500', core: '#FFFF00', shadow: '#8B0000', background: '#2a0500' }, 
  'VOID': { primary: '#000000', secondary: '#4B0082', core: '#FFFFFF', shadow: '#9400D3', background: '#000000' }, 
};

const ELEMENT_NAMES_CN: Record<string, string> = {
    'NEUTRAL': '等待施法...',
    'FIRE': '🔥 烈焰术 (FIRE)',
    'WATER': '💧 唤雨术 (WATER)',
    'THUNDER': '⚡ 雷霆术 (THUNDER)',
    'WIND': '🌪️ 疾风术 (WIND)',
    'BLIZZARD': '❄️ 极寒风暴 (BLIZZARD)',
    'PLASMA': '⚛️ 等离子破 (PLASMA)',
    'STEAM': '♨️ 灼热蒸汽 (STEAM)',
    'TEMPEST': '⛈️ 雷暴风眼 (TEMPEST)',
    'INFERNO': '🌋 地狱烈火 (INFERNO)',
    'VOID': '🌌 虚空奇点 (VOID)'
};

const getCombo = (g1: ElementType, g2: ElementType): string | null => {
    const sorted = [g1, g2].sort().join('_');
    switch(sorted) {
        case 'WATER_WIND': return 'BLIZZARD';
        case 'FIRE_WIND': return 'PLASMA';
        case 'FIRE_WATER': return 'STEAM';
        case 'THUNDER_WATER': return 'TEMPEST';
        case 'FIRE_FIRE': return 'INFERNO';
        case 'THUNDER_THUNDER': return 'VOID';
        default: return null;
    }
};

const MagicOverlay: React.FC<MagicOverlayProps> = ({ width, height }) => {
  const webcamRef = useRef<Webcam>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>(0);

  // Game Refs
  const particlesRef = useRef<Particle[]>([]);
  const handDataRef = useRef<HandData[]>([]);
  const monstersRef = useRef<Monster[]>([]);
  const monsterSpawnTimerRef = useRef<number>(0);
  const scoreRef = useRef<number>(0);
  const coreHealthRef = useRef<number>(100);

  // Level System Refs
  const levelRef = useRef<number>(1);
  const levelProgressRef = useRef<number>(0);
  const isBossActiveRef = useRef<boolean>(false);
  const maxLevel = 5;

  // App State
  const [currentElement, setCurrentElement] = useState<string>('NEUTRAL');
  const [isModelLoaded, setIsModelLoaded] = useState(false);
  const [loadingError, setLoadingError] = useState<string | null>(null);
  const [debugInfo, setDebugInfo] = useState<string>("初始化系统...");
  const [hasStarted, setHasStarted] = useState(false);
  const [showControls, setShowControls] = useState(false); 
  const [isCameraReady, setCameraReady] = useState(false);

  // Game UI State
  const [uiScore, setUiScore] = useState(0);
  const [uiHealth, setUiHealth] = useState(100);
  const [uiLevel, setUiLevel] = useState(1);
  const [uiProgress, setUiProgress] = useState(0);
  const [isGameOver, setIsGameOver] = useState(false);

  // Settings State 
  const [settings, setSettings] = useState({
      speed: 1.0,   
      count: 0.5,   
      glow: 1.0,    
  });

  const settingsRef = useRef(settings);
  useEffect(() => { settingsRef.current = settings; }, [settings]);

  // Visual Feedback State
  const highlightRef = useRef<number>(0);
  const prevElementRef = useRef<string>('NEUTRAL');
  const activeComboRef = useRef<string | null>(null);

  // Audio Context
  const audioContextRef = useRef<AudioContext | null>(null);
  const noiseBufferRef = useRef<AudioBuffer | null>(null);

  const currentTheme = activeComboRef.current 
    ? COMBO_THEMES[activeComboRef.current] 
    : (THEMES[currentElement as ElementType] || THEMES['NEUTRAL']);

  useEffect(() => {
    const AudioContextClass = (window as any).AudioContext || (window as any).webkitAudioContext;
    if (AudioContextClass) {
        const ctx = new AudioContextClass();
        audioContextRef.current = ctx;

        const bufferSize = ctx.sampleRate * 2; 
        const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
        const data = buffer.getChannelData(0);
        for (let i = 0; i < bufferSize; i++) {
            data[i] = Math.random() * 2 - 1;
        }
        noiseBufferRef.current = buffer;
    }
  }, []);

  const startExperience = () => {
      setHasStarted(true);
      if (audioContextRef.current?.state === 'suspended') {
          audioContextRef.current.resume();
      }
      monstersRef.current = [];
      scoreRef.current = 0;
      coreHealthRef.current = 100;
      levelRef.current = 1;
      levelProgressRef.current = 0;
      isBossActiveRef.current = false;

      setUiScore(0);
      setUiHealth(100);
      setUiLevel(1);
      setUiProgress(0);
      setIsGameOver(false);
  };

  const playChime = useCallback((element: string) => {
    const ctx = audioContextRef.current;
    if (!ctx || !noiseBufferRef.current) return;
    if (ctx.state === 'suspended') ctx.resume().catch(console.error);

    const now = ctx.currentTime;
    const masterGain = ctx.createGain();
    masterGain.connect(ctx.destination);
    masterGain.gain.setValueAtTime(0.3, now); 

    const playNoise = (filterType: BiquadFilterType, freqStart: number, freqEnd: number, duration: number, vol: number = 1, delay: number = 0) => {
        const src = ctx.createBufferSource();
        src.buffer = noiseBufferRef.current;
        src.loop = true;
        const filter = ctx.createBiquadFilter();
        filter.type = filterType;
        filter.frequency.setValueAtTime(freqStart, now + delay);
        filter.frequency.exponentialRampToValueAtTime(freqEnd, now + delay + duration);
        filter.Q.value = 1;
        const amp = ctx.createGain();
        amp.gain.setValueAtTime(0, now + delay);
        amp.gain.linearRampToValueAtTime(vol, now + delay + 0.05);
        amp.gain.exponentialRampToValueAtTime(0.01, now + delay + duration);
        src.connect(filter);
        filter.connect(amp);
        amp.connect(masterGain);
        src.start(now + delay);
        src.stop(now + delay + duration + 0.2);
    };

    const playTone = (type: OscillatorType, freqStart: number, freqEnd: number, duration: number, vol: number = 1, delay: number = 0) => {
        const osc = ctx.createOscillator();
        osc.type = type;
        osc.frequency.setValueAtTime(freqStart, now + delay);
        if (freqStart !== freqEnd) osc.frequency.exponentialRampToValueAtTime(freqEnd, now + delay + duration);
        const amp = ctx.createGain();
        amp.gain.setValueAtTime(0, now + delay);
        amp.gain.linearRampToValueAtTime(vol, now + delay + 0.05);
        amp.gain.exponentialRampToValueAtTime(0.01, now + delay + duration);
        osc.connect(amp);
        amp.connect(masterGain);
        osc.start(now + delay);
        osc.stop(now + delay + duration + 0.2);
    };

    switch (element) {
        case 'FIRE': playNoise('lowpass', 500, 100, 1.0, 0.5); playTone('sawtooth', 80, 120, 0.8, 0.2); break;
        case 'WATER': playNoise('bandpass', 800, 300, 0.6, 0.4); playTone('sine', 600, 300, 0.4, 0.3, 0.1); break;
        case 'WIND': playNoise('lowpass', 200, 800, 0.4, 0.3); playNoise('highpass', 400, 1000, 0.5, 0.2, 0.1); break;
        case 'THUNDER': playTone('sawtooth', 800, 50, 0.3, 0.2); playNoise('lowpass', 1000, 50, 1.2, 0.6, 0.1); break;
        case 'BLIZZARD': playNoise('highpass', 1000, 3000, 1.5, 0.4); playTone('sine', 1500, 2000, 0.3, 0.1, 0.1); break;
        case 'INFERNO': playNoise('lowpass', 800, 50, 1.5, 0.8); playTone('square', 60, 40, 1.5, 0.2); break;
        case 'TEMPEST': playNoise('lowpass', 200, 50, 2.0, 0.8); playTone('sawtooth', 1200, 100, 0.5, 0.2, 0.1); playNoise('bandpass', 1000, 500, 1.0, 0.3); break;
        case 'VOID': playTone('sine', 50, 40, 2.5, 0.6); playNoise('bandpass', 100, 200, 2.5, 0.4); playTone('sine', 300, 290, 1.0, 0.1, 0.5); break;
        case 'PLASMA': playTone('sawtooth', 200, 800, 1.0, 0.2); playNoise('bandpass', 400, 1200, 1.0, 0.4); break;
        case 'STEAM': playNoise('highpass', 500, 1000, 1.0, 0.3); break;
        default: playTone('triangle', 440, 880, 0.3, 0.1);
    }
  }, []);

  const detectGesture = (landmarks: any[], videoWidth: number, videoHeight: number): ElementType => {
    const mapPt = (idx: number) => ({ x: (1 - landmarks[idx].x) * videoWidth, y: landmarks[idx].y * videoHeight });
    const wrist = mapPt(0);
    const indexTip = mapPt(8);
    const middleTip = mapPt(12);
    const middleMCP = mapPt(9);

    const distSq = (p1: any, p2: any) => (p1.x - p2.x)**2 + (p1.y - p2.y)**2;
    const isFingerOpen = (tip: any, mcp: any) => distSq(tip, wrist) > distSq(mcp, wrist) * 1.2;

    const isPointingDown = wrist.y < middleMCP.y;
    if (isPointingDown) return 'WATER';

    let openCount = 0;
    if (isFingerOpen(indexTip, mapPt(5))) openCount++;
    if (isFingerOpen(middleTip, mapPt(9))) openCount++;
    if (isFingerOpen(mapPt(16), mapPt(13))) openCount++;
    if (isFingerOpen(mapPt(20), mapPt(17))) openCount++;

    if (openCount >= 4) return 'FIRE';
    if (openCount >= 2) return 'WIND';
    return 'THUNDER';
  };

  const drawSkeleton = (ctx: CanvasRenderingContext2D, hand: HandData) => {
      ctx.strokeStyle = "rgba(255, 255, 255, 0.15)";
      ctx.lineWidth = 1.5;
      ctx.fillStyle = "rgba(255, 255, 255, 0.5)";
      const points = [hand.wrist, hand.indexBase, hand.indexTip, hand.middleBase, hand.middleTip, hand.ringBase, hand.ringTip, hand.pinkyBase, hand.pinkyTip, hand.thumbTip];

      const drawLine = (p1: any, p2: any) => { ctx.beginPath(); ctx.moveTo(p1.x, p1.y); ctx.lineTo(p2.x, p2.y); ctx.stroke(); }
      drawLine(hand.wrist, hand.indexBase); drawLine(hand.indexBase, hand.indexTip);
      drawLine(hand.wrist, hand.middleBase); drawLine(hand.middleBase, hand.middleTip);
      drawLine(hand.wrist, hand.pinkyBase); drawLine(hand.pinkyBase, hand.pinkyTip);

      points.forEach(p => { ctx.beginPath(); ctx.arc(p.x, p.y, 2.5, 0, Math.PI * 2); ctx.fill(); });
  };

  const onResults = useCallback((results: any) => {
    const displayWidth = width;
    const displayHeight = height;

    setIsModelLoaded((prev) => {
        if (!prev) return true;
        return prev;
    });

    if (results.multiHandLandmarks && results.multiHandLandmarks.length > 0) {
      const newHandData: HandData[] = results.multiHandLandmarks.map((landmarks: any[]) => {
        const gesture = detectGesture(landmarks, displayWidth, displayHeight);
        const mapPt = (idx: number) => ({ x: (1 - landmarks[idx].x) * displayWidth, y: landmarks[idx].y * displayHeight });
        return {
          wrist: mapPt(0), indexTip: mapPt(8), middleTip: mapPt(12), ringTip: mapPt(16), pinkyTip: mapPt(20), thumbTip: mapPt(4),
          indexBase: mapPt(5), middleBase: mapPt(9), ringBase: mapPt(13), pinkyBase: mapPt(17),
          isOpen: gesture !== 'THUNDER', gesture, opacity: 1
        };
      });

      handDataRef.current = newHandData;
      let newElement = 'NEUTRAL';
      let activeCombo = null;

      if (newHandData.length === 2) {
          const g1 = newHandData[0].gesture;
          const g2 = newHandData[1].gesture;
          if (g1 !== 'NEUTRAL' && g2 !== 'NEUTRAL') activeCombo = getCombo(g1, g2);
      }

      if (activeCombo) newElement = activeCombo;
      else {
          const activeHand = newHandData.find(h => h.gesture !== 'NEUTRAL');
          if (activeHand) newElement = activeHand.gesture;
      }

      const prevCombo = activeComboRef.current;
      activeComboRef.current = activeCombo;

      // TRIGGER ONE-SHOT COMBO EFFECTS
      if (activeCombo && activeCombo !== prevCombo) {
          highlightRef.current = 1.0; 
          playChime(activeCombo);

          if (activeCombo === 'INFERNO') {
              // INFERNO: Screen Clear
              monstersRef.current.forEach(m => {
                  if (!m.isBoss) {
                       m.hp -= 9999;
                       spawnParticles(m.x, m.y, 'FIRE', THEMES['FIRE']);
                  } else {
                       m.hp -= 500;
                  }
              });
          } else if (activeCombo === 'TEMPEST') {
              // TEMPEST: Push Back
               const centerX = displayWidth / 2;
               const centerY = displayHeight / 2;
               monstersRef.current.forEach(m => {
                   const dx = m.x - centerX;
                   const dy = m.y - centerY;
                   const len = Math.sqrt(dx*dx + dy*dy) || 1;
                   // Push hard away from center
                   m.vx += (dx/len) * 50;
                   m.vy += (dy/len) * 50;
               });
          }
      } else if (newElement !== prevElementRef.current) {
          if (newElement !== 'NEUTRAL') { highlightRef.current = 1.0; playChime(newElement); }
          prevElementRef.current = newElement;
      }
      setCurrentElement(newElement);
    } else {
      handDataRef.current = [];
      activeComboRef.current = null;
      if (prevElementRef.current !== 'NEUTRAL') { prevElementRef.current = 'NEUTRAL'; setCurrentElement('NEUTRAL'); }
    }
  }, [width, height, playChime]);

  useEffect(() => {
    let hands: any = null;
    let isActive = true;
    let frameId: number;
    let lastVideoTime = -1;

    const MP_VERSION = "0.4.1675469240";

    const initHands = async () => {
       try {
           setDebugInfo("正在加载 AI 核心 (1/3)...");
           if (!(window as any).Hands) { 
               setTimeout(initHands, 500); 
               return; 
           }

           setDebugInfo("初始化视觉模型 (2/3)...");
           hands = new (window as any).Hands({ 
               locateFile: (file: string) => `https://cdn.jsdelivr.net/npm/@mediapipe/hands@${MP_VERSION}/${file}` 
           });

           hands.setOptions({ 
               maxNumHands: 2, 
               modelComplexity: 1, 
               minDetectionConfidence: 0.5, 
               minTrackingConfidence: 0.5 
           });

           hands.onResults(onResults);

           setDebugInfo("等待摄像头许可...");

           const processVideo = async () => {
             if (!isActive) return;
             if (webcamRef.current && webcamRef.current.video && webcamRef.current.video.readyState === 4) {
                 const video = webcamRef.current.video;
                 if (video.videoWidth > 0 && video.videoHeight > 0) {
                     if (video.currentTime !== lastVideoTime) {
                         lastVideoTime = video.currentTime;
                         try { 
                             setDebugInfo("正在处理视频流...");
                             await hands.send({ image: video }); 
                         } catch (e) { 
                             console.warn("Processing warning", e); 
                         }
                     }
                 }
             }
             frameId = requestAnimationFrame(processVideo);
           };
           processVideo();
       } catch (error: any) {
           console.error("Initialization Error:", error);
           setLoadingError("AI 模型加载失败: " + error.message);
           setDebugInfo("系统错误");
       }
    };

    setTimeout(initHands, 500);

    return () => { isActive = false; if (frameId) cancelAnimationFrame(frameId); if (hands) hands.close(); };
  }, [onResults]);

  // --- GAME LOGIC ---

  const spawnBoss = (width: number, height: number, level: number) => {
      isBossActiveRef.current = true;
      const elements: ElementType[] = ['FIRE', 'WATER', 'WIND', 'THUNDER'];
      const element = elements[(level - 1) % 4];
      const boss: Monster = {
          id: Date.now(),
          x: width / 2,
          y: -150, // Start well above screen
          vx: 0, vy: 1, // Move slowly down
          hp: 1000 * level,
          maxHp: 1000 * level,
          element,
          radius: 80, // Big size
          scoreValue: 5000 * level,
          pulseOffset: 0,
          isBoss: true
      };
      monstersRef.current.push(boss);
      highlightRef.current = 1.0;
  };

  const spawnMonster = (width: number, height: number) => {
      if (isBossActiveRef.current) return; // Don't spawn small mobs during boss (or maybe reduce rate)

      const edge = Math.floor(Math.random() * 4); // 0: Top, 1: Right, 2: Bottom, 3: Left
      let x = 0, y = 0;

      switch(edge) {
          case 0: x = Math.random() * width; y = -50; break;
          case 1: x = width + 50; y = Math.random() * height; break;
          case 2: x = Math.random() * width; y = height + 50; break;
          case 3: x = -50; y = Math.random() * height; break;
      }

      const elements: ElementType[] = ['FIRE', 'WATER', 'WIND', 'THUNDER'];
      const element = elements[Math.floor(Math.random() * elements.length)];

      const monster: Monster = {
          id: Date.now() + Math.random(),
          x, y,
          vx: 0, vy: 0,
          hp: 100 + (levelRef.current * 20),
          maxHp: 100 + (levelRef.current * 20),
          element,
          radius: 20 + Math.random() * 10,
          scoreValue: 100 * levelRef.current,
          pulseOffset: Math.random() * Math.PI * 2,
          isBoss: false
      };
      monstersRef.current.push(monster);
  };

  // Distance from point p to line segment vw
  const distToSegmentSq = (p: {x: number, y: number}, v: {x: number, y: number}, w: {x: number, y: number}) => {
    const l2 = (v.x - w.x)**2 + (v.y - w.y)**2;
    if (l2 === 0) return (p.x - v.x)**2 + (p.y - v.y)**2;
    let t = ((p.x - v.x) * (w.x - v.x) + (p.y - v.y) * (w.y - v.y)) / l2;
    t = Math.max(0, Math.min(1, t));
    return (p.x - (v.x + t * (w.x - v.x)))**2 + (p.y - (v.y + t * (w.y - v.y)))**2;
  };

  const updateMonsters = (ctx: CanvasRenderingContext2D, width: number, height: number, centerX: number, centerY: number, hands: HandData[]) => {
      const monsters = monstersRef.current;
      const activeCombo = activeComboRef.current;

      const getMultiplier = (spell: string, monsterEl: string) => {
          if (spell === 'FIRE' && monsterEl === 'WATER') return 2;
          if (spell === 'WATER' && monsterEl === 'FIRE') return 2;
          if (spell === 'THUNDER' && monsterEl === 'WIND') return 2;
          if (spell === 'WIND' && monsterEl === 'THUNDER') return 2;
          if (spell === 'BLIZZARD' || spell === 'INFERNO' || spell === 'TEMPEST' || spell === 'PLASMA') return 3;
          if (spell === 'VOID') return 5;
          return 1;
      };

      for (let i = monsters.length - 1; i >= 0; i--) {
          const m = monsters[i];
          const dx = centerX - m.x;
          const dy = centerY - m.y;
          const distToCenter = Math.sqrt(dx*dx + dy*dy);

          // Movement Logic
          let speed = m.isBoss ? 0.3 : (1.5 + (levelRef.current * 0.2)); 

          // CONTINUOUS COMBO EFFECTS
          if (activeCombo === 'BLIZZARD') {
              speed *= 0.2; // Frozen Slow
          }

          let moveX = Math.cos(Math.atan2(dy, dx)) * speed;
          let moveY = Math.sin(Math.atan2(dy, dx)) * speed;

          // Apply Physics Velocity (from Pushbacks/Plasma)
          m.x += m.vx;
          m.y += m.vy;
          // Dampen velocity
          m.vx *= 0.9;
          m.vy *= 0.9;

          // PLASMA: Gravity Well towards hands center
          if (activeCombo === 'PLASMA' && hands.length === 2 && !m.isBoss) {
              const midX = (hands[0].middleBase.x + hands[1].middleBase.x) / 2;
              const midY = (hands[0].middleBase.y + hands[1].middleBase.y) / 2;
              const pdx = midX - m.x;
              const pdy = midY - m.y;
              m.vx += pdx * 0.005;
              m.vy += pdy * 0.005;
          }

          m.x += moveX;
          m.y += moveY;

          // Draw Monster
          const mTheme = THEMES[m.element];
          ctx.save();
          ctx.translate(m.x, m.y);
          const pulse = 1 + Math.sin(Date.now() * 0.005 + m.pulseOffset) * 0.2;
          const scale = m.isBoss ? 3 : 1;
          ctx.scale(pulse * scale, pulse * scale);

          ctx.beginPath();
          // Draw a spiky shape
          const spikes = m.isBoss ? 12 : 5;
          const outerRadius = m.radius;
          const innerRadius = m.radius / 2;
          for (let j = 0; j < spikes * 2; j++) {
             const r = j % 2 === 0 ? outerRadius : innerRadius;
             const a = (Math.PI * j) / spikes;
             ctx.lineTo(Math.cos(a) * r, Math.sin(a) * r);
          }
          ctx.closePath();
          ctx.fillStyle = mTheme.background;
          ctx.fill();
          ctx.strokeStyle = mTheme.primary;
          ctx.lineWidth = 3;
          ctx.stroke();

          // Boss Health Bar above head
          if (m.isBoss) {
              ctx.fillStyle = 'red';
              ctx.fillRect(-30, -50, 60 * (m.hp / m.maxHp), 5);
              ctx.strokeStyle = 'white';
              ctx.strokeRect(-30, -50, 60, 5);
          }

          ctx.shadowBlur = 15;
          ctx.shadowColor = mTheme.secondary;
          ctx.fillStyle = mTheme.core;
          ctx.beginPath();
          ctx.arc(0, 0, innerRadius * 0.5, 0, Math.PI * 2);
          ctx.fill();
          ctx.shadowBlur = 0;

          ctx.restore();

          // Check Collision with Hands
          let hit = false;
          let damageTaken = 0;

          // 1. Hand Point Collision
          for (const hand of hands) {
              if (hand.gesture !== 'NEUTRAL') {
                  const hx = hand.middleBase.x;
                  const hy = hand.middleBase.y;
                  const hDist = Math.hypot(hx - m.x, hy - m.y);

                  const hitRadius = activeCombo ? 120 : 80;

                  if (hDist < hitRadius + m.radius) {
                      const mult = getMultiplier(activeCombo || hand.gesture, m.element);
                      damageTaken += 3 * mult;
                      hit = true;
                  }
              }
          }

          // 2. Combo Line Collision
          if (activeCombo && hands.length === 2) {
              const h1 = hands[0].middleBase;
              const h2 = hands[1].middleBase;
              const distSq = distToSegmentSq(m, h1, h2);
              // Line thickness approx 30px
              if (distSq < (m.radius + 30)**2) {
                   const mult = getMultiplier(activeCombo, m.element);
                   damageTaken += 5 * mult; // Line does more damage
                   hit = true;
              }
          }

          if (hit) {
              m.hp -= damageTaken;
              if (Math.random() > 0.7) {
                  spawnParticles(m.x, m.y, activeCombo || 'NEUTRAL', mTheme);
              }
              // Flash
              ctx.save();
              ctx.globalCompositeOperation = 'lighter';
              ctx.fillStyle = '#FFFFFF';
              ctx.beginPath();
              ctx.arc(m.x, m.y, m.radius * (m.isBoss ? 3 : 1.5), 0, Math.PI*2);
              ctx.globalAlpha = 0.5;
              ctx.fill();
              ctx.restore();
          }

          // Death or Core Hit
          if (m.hp <= 0) {
              monsters.splice(i, 1);
              const mult = activeCombo ? 2 : 1; 
              scoreRef.current += m.scoreValue * mult;

              if (m.isBoss) {
                  // Boss Dead - Level Up
                  spawnParticles(m.x, m.y, m.element, mTheme);
                  // Massive explosion
                  for(let k=0; k<5; k++) spawnParticles(m.x, m.y, m.element, mTheme);

                  levelRef.current = Math.min(levelRef.current + 1, maxLevel);
                  levelProgressRef.current = 0;
                  isBossActiveRef.current = false;
                  coreHealthRef.current = Math.min(100, coreHealthRef.current + 50); // Heal on boss kill
              } else {
                  spawnParticles(m.x, m.y, m.element, mTheme);
                  // Progress update
                  if (levelProgressRef.current < 100 && !isBossActiveRef.current) {
                      levelProgressRef.current += 5; 
                  }
              }

              playChime(m.element);
          } else if (distToCenter < (m.isBoss ? 80 : 40)) {
              // Hit Core
              if (!m.isBoss) monsters.splice(i, 1); // Boss doesn't disappear, just eats core

              const dmg = m.isBoss ? 1 : 10;
              coreHealthRef.current -= dmg;
              highlightRef.current = 1.0; 
              spawnParticles(centerX, centerY, 'NEUTRAL', THEMES['NEUTRAL']);
          }
      }
  };

  // --- PHYSICS ENGINE ---
  const updateParticles = (ctx: CanvasRenderingContext2D, width: number, height: number, centerX: number, centerY: number) => {
    ctx.shadowBlur = 0; 
    const { glow } = settingsRef.current;

    for (let i = particlesRef.current.length - 1; i >= 0; i--) {
      const p = particlesRef.current[i];

      if (p.element === 'WIND' || p.element === 'BLIZZARD') {
          p.vx *= 0.995; p.vy *= 0.995;
      } else {
          p.vx *= 0.98; p.vy *= 0.98;
      }

      switch (p.element) {
          case 'WIND':
          case 'BLIZZARD':
              const dx = p.x - centerX;
              const dy = p.y - centerY;
              const dist = Math.sqrt(dx*dx + dy*dy) + 1;
              const angle = Math.atan2(dy, dx);
              p.vx += Math.cos(angle + Math.PI/2) * 2.5; 
              p.vy += Math.sin(angle + Math.PI/2) * 2.5;
              p.vx -= (dx / dist) * 0.8;
              p.vy -= (dy / dist) * 0.8;
              p.angle += p.angularVelocity * 1.5; 
              break;
          case 'WATER':
          case 'STEAM':
              p.vy += 1.5; 
              p.x += Math.sin(p.life * 0.2) * 1.0;
              break;
          case 'THUNDER':
          case 'TEMPEST':
          case 'VOID':
              p.vx += (Math.random() - 0.5) * 6; 
              p.vy += (Math.random() - 0.5) * 6;
              if (Math.random() < 0.15) {
                  p.x += (Math.random() - 0.5) * 40;
                  p.y += (Math.random() - 0.5) * 40;
              }
              break;
          case 'FIRE':
          case 'INFERNO':
              p.vy -= 1.5; 
              p.vx += (Math.random() - 0.5) * 2.0;
              p.size *= 0.95; 
              break;
          default:
              p.vy -= 0.2;
      }

      p.x += p.vx;
      p.y += p.vy;
      p.life -= 1;
      if (p.element !== 'FIRE') p.size *= 0.98;

      if (p.life <= 0 || p.size < 0.1 || p.y > height + 50 || p.y < -50 || p.x < -50 || p.x > width + 50) {
        particlesRef.current.splice(i, 1);
      } else {
        ctx.save();
        if (p.size > 2) {
             const shadowOffsetX = (p.x - centerX) * 0.05;
             const shadowOffsetY = (p.y - centerY) * 0.05;
             ctx.fillStyle = "rgba(0,0,0,0.3)";
             ctx.beginPath();
             ctx.arc(p.x + shadowOffsetX, p.y + shadowOffsetY, p.size * glow, 0, Math.PI*2);
             ctx.fill();
        }

        let alpha = Math.min(1, p.life / 10, (p.maxLife - p.life) / 5);
        if ((p.element === 'FIRE' || p.element === 'INFERNO') && p.size < 3.5 && p.type === 'EMBER') {
             alpha *= (0.5 + Math.random() * 0.5);
        }

        ctx.globalAlpha = alpha;
        const renderSize = p.size * glow;

        if (p.type === 'LEAF') {
            ctx.translate(p.x, p.y);
            ctx.rotate(p.angle);
            ctx.fillStyle = p.color;
            ctx.beginPath();
            ctx.ellipse(0, 0, renderSize, renderSize * 0.4, 0, 0, Math.PI * 2);
            ctx.fill();
        } 
        else if (p.type === 'DROP') {
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 2.5 * glow;
            ctx.lineCap = 'round';
            ctx.beginPath();
            ctx.moveTo(p.x, p.y);
            ctx.lineTo(p.x - p.vx * 1.5, p.y - p.vy * 4); 
            ctx.stroke();
        }
        else if (p.type === 'SPARK') {
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 2 * glow;
            ctx.beginPath();
            ctx.moveTo(p.x - p.vx, p.y - p.vy);
            ctx.lineTo(p.x + p.vx, p.y + p.vy);
            ctx.stroke();
        }
        else {
            ctx.fillStyle = p.color;
            ctx.beginPath();
            ctx.arc(p.x, p.y, renderSize, 0, Math.PI * 2);
            ctx.fill();
        }
        ctx.restore();
      }
    }
  };

  const spawnParticles = (x: number, y: number, element: string, theme: Theme) => {
    const { speed: speedMulti, count: countMulti } = settingsRef.current;
    const isCombo = activeComboRef.current !== null;
    let baseCount = isCombo ? 10 : 3;
    let count = Math.ceil(baseCount * countMulti);
    count = Math.min(count, 50);

    for (let i = 0; i < count; i++) {
        let type: ParticleType = 'ORB';
        let speed = (Math.random() * 8 + 4) * speedMulti; 
        let spread = 30;
        let pColor = Math.random() > 0.5 ? theme.primary : theme.secondary;
        let pSize = 4 + Math.random() * 6;
        let pLife = 30 + Math.random() * 30;

        if (element === 'WIND' || element === 'BLIZZARD') {
            type = Math.random() > 0.5 ? 'LEAF' : 'MIST';
            if (isCombo) pColor = Math.random() > 0.5 ? '#00FFFF' : '#F0FFF0';
            else if (element === 'WIND') pColor = Math.random() > 0.5 ? '#00FFFF' : '#F0FFF0'; 
        } else if (element === 'WATER' || element === 'STEAM') {
            type = Math.random() > 0.7 ? 'MIST' : 'DROP';
            spread = 50; 
        } else if (element === 'THUNDER' || element === 'TEMPEST' || element === 'VOID') {
            type = 'SPARK';
            speed = 12 * speedMulti; 
            if (element === 'THUNDER') pColor = Math.random() > 0.5 ? '#FFFF00' : '#9400D3';
        } else if (element === 'FIRE' || element === 'INFERNO') {
            const r = Math.random();
            if (r < 0.3) {
                 type = 'EMBER';
                 pColor = Math.random() > 0.5 ? '#FFD700' : '#FFFFFF';
                 pSize = 1 + Math.random() * 3;
                 pLife = 15 + Math.random() * 20; 
                 speed *= 1.5; 
            } else if (r < 0.6) {
                 type = 'MIST'; 
            } else {
                 type = 'EMBER'; 
            }
        }

        const angle = Math.random() * Math.PI * 2;
        let vx = Math.cos(angle) * speed;
        let vy = Math.sin(angle) * speed;

        if (element === 'WATER' || element === 'STEAM') { vx *= 0.3; vy = Math.random() * 5 * speedMulti + 5; } 
        if ((element === 'FIRE' || element === 'INFERNO') && pSize < 4 && type === 'EMBER') {
            vy -= 2.0; 
        }

        let spawnX = x + (Math.random() - 0.5) * spread;
        let spawnY = y + (Math.random() - 0.5) * spread;

        particlesRef.current.push({
            x: spawnX,
            y: spawnY,
            vx, vy,
            life: pLife,
            maxLife: 60,
            size: pSize,
            color: pColor,
            element: element as Particle['element'],
            type,
            angle: Math.random() * Math.PI * 2,
            angularVelocity: (Math.random() - 0.5) * 0.4
        });
    }
  };

  const animate = useCallback((time: number) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d', { alpha: false }); 
    if (!ctx) return;

    const dpr = window.devicePixelRatio || 1;
    if (canvas.width !== width * dpr || canvas.height !== height * dpr) {
        canvas.width = width * dpr;
        canvas.height = height * dpr;
    }
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

    const theme = activeComboRef.current 
        ? COMBO_THEMES[activeComboRef.current] 
        : (THEMES[currentElement as ElementType] || THEMES['NEUTRAL']);

    ctx.globalCompositeOperation = 'source-over';

    ctx.fillStyle = theme.background;
    ctx.fillRect(0, 0, width, height);

    if (highlightRef.current > 0.01) highlightRef.current *= 0.925; 
    else highlightRef.current = 0;
    const flash = highlightRef.current;

    // --- GAME LOGIC UPDATES ---
    if (hasStarted && !isGameOver) {
        monsterSpawnTimerRef.current++;
        // Spawn rate
        const spawnRate = Math.max(20, 100 - (levelRef.current * 10));

        if (!isBossActiveRef.current && monsterSpawnTimerRef.current > spawnRate) {
            spawnMonster(width, height);
            monsterSpawnTimerRef.current = 0;
        }

        // Check for Boss Spawn
        if (!isBossActiveRef.current && levelProgressRef.current >= 100) {
            spawnBoss(width, height, levelRef.current);
        }

        if (coreHealthRef.current <= 0) {
            setIsGameOver(true);
        }

        // Update UI state occasionally
        if (monsterSpawnTimerRef.current % 10 === 0) {
            setUiScore(scoreRef.current);
            setUiHealth(coreHealthRef.current);
            setUiLevel(levelRef.current);
            setUiProgress(levelProgressRef.current);
        }
    }

    if (flash > 0.01) {
        ctx.save();
        ctx.globalCompositeOperation = 'lighter';
        ctx.strokeStyle = '#FF0000'; // Damage flash
        ctx.lineWidth = 30 * flash; 
        ctx.shadowBlur = 40;
        ctx.shadowColor = '#FF0000';
        ctx.globalAlpha = flash; 
        ctx.strokeRect(0, 0, width, height);
        ctx.restore();
    }

    let centerX = width / 2;
    let centerY = height / 2;
    const t = time * 0.001;
    const comboName = activeComboRef.current;

    // Draw Core
    ctx.save();
    ctx.translate(centerX, centerY);
    // Rotating crystal/core
    ctx.rotate(t * 0.5);
    ctx.fillStyle = '#FFFFFF';
    ctx.shadowBlur = 20 + Math.sin(t * 5) * 10;
    ctx.shadowColor = '#00FFFF';
    const coreSize = 30;
    ctx.beginPath();
    ctx.moveTo(0, -coreSize);
    ctx.lineTo(coreSize, 0);
    ctx.lineTo(0, coreSize);
    ctx.lineTo(-coreSize, 0);
    ctx.fill();

    // Core Health Ring
    ctx.rotate(-t * 0.5); // Counter rotate
    ctx.beginPath();
    const hpPct = Math.max(0, coreHealthRef.current / 100);
    ctx.arc(0, 0, 50, 0, Math.PI * 2 * hpPct);
    ctx.strokeStyle = coreHealthRef.current > 30 ? '#00FF00' : '#FF0000';
    ctx.lineWidth = 5;
    ctx.lineCap = 'round';
    ctx.stroke();

    ctx.restore();

    // 2. Geometry & Particles
    ctx.globalCompositeOperation = 'lighter'; 

    // Render Monsters
    updateMonsters(ctx, width, height, centerX, centerY, handDataRef.current);

    if (comboName && handDataRef.current.length === 2) {
        // --- COMBO MODE ---
        const h1 = handDataRef.current[0];
        const h2 = handDataRef.current[1];

        const midX = (h1.middleBase.x + h2.middleBase.x) / 2;
        const midY = (h1.middleBase.y + h2.middleBase.y) / 2;

        ctx.save();
        ctx.beginPath();
        ctx.moveTo(h1.middleBase.x, h1.middleBase.y);
        ctx.lineTo(h2.middleBase.x, h2.middleBase.y);
        ctx.strokeStyle = theme.primary;
        ctx.lineWidth = 20 + Math.sin(t * 10) * 5; 
        ctx.lineCap = 'round';
        ctx.shadowBlur = 20; 
        ctx.shadowColor = theme.secondary;
        ctx.globalAlpha = 0.4;
        ctx.stroke();
        ctx.restore();

        drawRuneRing(ctx, midX, midY, 180, t, theme);
        drawSacredGeometry(ctx, midX, midY, 140, -t * 2, theme);
        spawnParticles(midX, midY, comboName, theme);

        handDataRef.current.forEach(h => {
             drawSkeleton(ctx, h);
             const auraSize = 50 + Math.sin(t * 20) * 10;
             const grad = ctx.createRadialGradient(h.middleBase.x, h.middleBase.y, 10, h.middleBase.x, h.middleBase.y, auraSize);
             grad.addColorStop(0, theme.core);
             grad.addColorStop(0.4, theme.primary);
             grad.addColorStop(1, 'rgba(0,0,0,0)');
             ctx.save();
             ctx.fillStyle = grad;
             ctx.globalAlpha = 0.5;
             ctx.beginPath();
             ctx.arc(h.middleBase.x, h.middleBase.y, auraSize, 0, Math.PI * 2);
             ctx.fill();
             ctx.restore();
             drawRuneRing(ctx, h.middleBase.x, h.middleBase.y, 40, t*5, theme);
        });

    } else {
        // --- INDIVIDUAL MODE ---
        handDataRef.current.forEach((hand) => {
           drawSkeleton(ctx, hand);
           const element = hand.gesture;
           const handTheme = (element !== 'NEUTRAL' && THEMES[element]) ? THEMES[element] : THEMES['NEUTRAL'];
           const centerX = hand.middleBase.x; 
           const centerY = hand.middleBase.y; 

           if (element !== 'NEUTRAL') {
               if (flash > 0.05 && highlightRef.current > 0.05) {
                   ctx.save();
                   ctx.translate(centerX, centerY);
                   const waveSize = 120 + (1 - flash) * 100;
                   ctx.beginPath();
                   ctx.arc(0, 0, waveSize, 0, Math.PI * 2);
                   ctx.lineWidth = 10 * flash;
                   ctx.strokeStyle = handTheme.core;
                   ctx.shadowBlur = 20;
                   ctx.shadowColor = handTheme.secondary;
                   ctx.globalAlpha = flash;
                   ctx.stroke();
                   ctx.restore();
               }

               drawRuneRing(ctx, centerX, centerY, 120, t * 0.5, handTheme);
               drawSacredGeometry(ctx, centerX, centerY, 90, -t * 1.5, handTheme);
               drawSquareLayer(ctx, centerX, centerY, 65, t * 2.5, handTheme);
               const pulse = Math.sin(time * 0.005) * 0.5 + 0.5;
               drawPentagram(ctx, centerX, centerY, 40, t, pulse, handTheme);

               spawnParticles(centerX, centerY, element, handTheme);
           } else {
               ctx.globalAlpha = 0.3;
               drawRuneRing(ctx, centerX, centerY, 50, t * 0.2, handTheme);
           }
        });
    }

    updateParticles(ctx, width, height, centerX, centerY);
    requestRef.current = requestAnimationFrame(animate);
  }, [width, height, currentElement, hasStarted, isGameOver]);

  useEffect(() => {
    requestRef.current = requestAnimationFrame(animate);
    return () => { if (requestRef.current) cancelAnimationFrame(requestRef.current); };
  }, [animate]);

  return (
    <div className="relative w-full h-full overflow-hidden flex items-center justify-center font-sans">

        {/* Dynamic Background */}
        <div 
            className="absolute inset-0 transition-colors duration-700 ease-in-out z-0"
            style={{ backgroundColor: currentTheme.background }}
        />

        {/* Hidden Webcam */}
        <Webcam 
            ref={webcamRef} 
            audio={false} 
            width={width} 
            height={height} 
            mirrored={true} 
            screenshotFormat="image/jpeg" 
            className="absolute opacity-0 pointer-events-none" 
            onUserMedia={() => setCameraReady(true)}
            onUserMediaError={(e: any) => setLoadingError("摄像头访问失败: " + e)}
        />

        {/* Canvas Layer */}
        <canvas ref={canvasRef} style={{ width, height }} className="absolute top-0 left-0 z-10" />

        {/* GAME OVER SCREEN */}
        {isGameOver && (
             <div className="absolute inset-0 flex items-center justify-center bg-black/80 z-50 backdrop-blur-sm">
                <div className="text-center p-8 border border-red-500/50 rounded-xl bg-black/80 shadow-[0_0_50px_rgba(255,0,0,0.3)]">
                    <h2 className="text-4xl font-bold text-red-500 mb-4 tracking-widest">能量核心崩溃</h2>
                    <div className="text-2xl text-white mb-6">最终得分: <span className="text-amber-500 font-mono">{uiScore}</span></div>
                    <button 
                        onClick={startExperience}
                        className="px-8 py-3 bg-red-900 hover:bg-red-700 text-white font-bold rounded border border-red-500 transition-colors"
                    >
                        重启时间线
                    </button>
                </div>
             </div>
        )}

        {!isModelLoaded && !isGameOver && (
            <div className="absolute inset-0 flex items-center justify-center bg-black bg-opacity-90 z-50">
                <div className="flex flex-col items-center">
                    <div className="text-amber-500 font-mono text-xl animate-pulse tracking-widest mb-4">🔮 正在校准魔法维度...</div>
                    {loadingError ? (
                        <div className="text-red-500 font-bold bg-black/50 p-2 rounded">{loadingError}</div>
                    ) : (
                        <div className="w-64 h-1 bg-gray-800 rounded-full overflow-hidden">
                            <div className="h-full bg-amber-500 animate-[width_1s_ease-in-out_infinite]" style={{width: '50%'}}></div>
                        </div>
                    )}
                    <div className="mt-4 text-xs text-gray-400 font-mono">{debugInfo}</div>
                </div>
            </div>
        )}

        {!hasStarted && isModelLoaded && !isGameOver && (
            <div className="absolute inset-0 flex items-center justify-center bg-black/60 z-50 cursor-pointer backdrop-blur-sm" onClick={startExperience}>
                <div className="border border-amber-500/50 bg-black/80 p-8 rounded-lg text-center shadow-[0_0_30px_rgba(255,160,20,0.3)] hover:scale-105 transition-transform duration-300">
                    <h2 className="text-3xl font-bold text-amber-500 mb-2">准备就绪</h2>
                    <p className="text-white/80 mb-6">点击屏幕开启守护试炼</p>
                    <button className="px-6 py-2 bg-amber-600 hover:bg-amber-500 text-black font-bold rounded">进入</button>
                </div>
            </div>
        )}

        {/* Dynamic Spell Name */}
        <div className="absolute top-24 left-0 w-full flex justify-center z-20 pointer-events-none">
             <div className={`text-4xl md:text-5xl font-bold tracking-widest transition-all duration-300 drop-shadow-[0_0_15px_rgba(255,255,255,0.4)] px-8 py-2 rounded-full ${highlightRef.current > 0.1 ? 'scale-110 bg-black/20 backdrop-blur-sm' : ''} ${
                currentElement === 'FIRE' ? 'text-orange-500' :
                currentElement === 'WATER' ? 'text-blue-500' :
                currentElement === 'WIND' ? 'text-cyan-300' :
                currentElement === 'THUNDER' ? 'text-purple-500' : 
                currentElement === 'INFERNO' ? 'text-red-600' :
                currentElement === 'BLIZZARD' ? 'text-cyan-100' :
                currentElement === 'VOID' ? 'text-violet-400' : 'text-amber-400'
            }`}>
                {ELEMENT_NAMES_CN[currentElement]}
            </div>
        </div>

        {/* TOP HUD - SCOREBOARD & HP */}
        {hasStarted && (
            <div className="absolute top-0 left-0 w-full z-20 flex justify-between items-start p-4 bg-gradient-to-b from-black/80 to-transparent">
                {/* Left: Health */}
                 <div className="flex flex-col gap-1 w-64">
                    <div className="flex justify-between text-xs text-white/80 uppercase tracking-widest">
                         <span>Core Integrity</span>
                         <span className="font-mono">{Math.max(0, uiHealth)}%</span>
                    </div>
                    <div className="w-full h-3 bg-gray-800/50 border border-white/10 rounded-full overflow-hidden">
                        <div 
                            className={`h-full transition-all duration-300 ${uiHealth > 30 ? 'bg-cyan-400 shadow-[0_0_10px_#00FFFF]' : 'bg-red-500 animate-pulse'}`} 
                            style={{ width: `${Math.max(0, uiHealth)}%` }}
                        />
                    </div>
                </div>

                {/* Center: Title (Already in App.tsx but adjusted here for flow) */}

                {/* Right: Score */}
                <div className="text-right">
                    <div className="text-xs text-amber-500/80 uppercase tracking-widest">Score</div>
                    <div className="text-4xl font-mono text-white font-bold tabular-nums drop-shadow-[0_0_5px_rgba(255,255,255,0.5)]">
                        {uiScore.toLocaleString()}
                    </div>
                </div>
            </div>
        )}

        {/* RIGHT SIDEBAR - LEVEL PROGRESS */}
        {hasStarted && (
            <div className="absolute top-1/2 right-4 -translate-y-1/2 z-20 flex flex-col gap-2 items-center">
                 <div className="text-amber-500 font-bold text-xl tracking-widest" style={{writingMode: 'vertical-rl'}}>LEVEL {uiLevel}</div>
                 <div className="w-4 h-64 bg-black/50 border border-white/20 rounded-full overflow-hidden flex flex-col justify-end">
                      <div 
                        className={`w-full transition-all duration-500 ease-out ${uiProgress >= 100 ? 'bg-red-500 animate-pulse' : 'bg-amber-500'}`}
                        style={{ height: `${uiProgress}%` }}
                      ></div>
                 </div>
                 {uiProgress >= 100 && <div className="text-red-500 font-bold animate-pulse text-xs">BOSS</div>}
            </div>
        )}

        {/* Toggle Controls Button */}
        <div className="absolute top-20 right-4 z-30">
            <button 
                onClick={() => setShowControls(!showControls)}
                className="bg-black/40 border border-white/10 p-2 rounded hover:bg-white/10 transition-colors text-white/50 text-xs uppercase font-mono tracking-wider"
            >
                {showControls ? 'Hide Controls' : 'Show Controls'}
            </button>
        </div>

        {/* Debug Info */}
        <div className="absolute top-20 right-28 z-20 text-right opacity-50 pointer-events-none">
             <div className="text-xs text-amber-200 font-mono">{debugInfo}</div>
        </div>

        {/* PARTICLE CONTROLS PANEL (Hidden by Default) */}
        {showControls && (
            <div className="absolute top-28 right-4 z-30 w-64 bg-black/60 backdrop-blur-md border border-white/10 rounded-xl p-4 shadow-2xl animate-[fadeIn_0.3s_ease-out]">
                <h3 className="text-amber-500 text-xs font-bold uppercase tracking-widest mb-4 border-b border-white/10 pb-2">粒子引擎参数</h3>

                <div className="space-y-4">
                    <div>
                        <div className="flex justify-between text-xs text-white/70 mb-1">
                            <span>速度 (Velocity)</span>
                            <span className="font-mono text-amber-400">{settings.speed.toFixed(1)}x</span>
                        </div>
                        <input 
                            type="range" min="0.1" max="10.0" step="0.1" 
                            value={settings.speed}
                            onChange={(e) => setSettings({...settings, speed: parseFloat(e.target.value)})}
                            className="w-full h-1 bg-white/20 rounded-lg appearance-none cursor-pointer accent-amber-500"
                        />
                    </div>

                    <div>
                        <div className="flex justify-between text-xs text-white/70 mb-1">
                            <span>数量 (Density)</span>
                            <span className="font-mono text-amber-400">{settings.count.toFixed(1)}x</span>
                        </div>
                        <input 
                            type="range" min="0.1" max="5.0" step="0.1" 
                            value={settings.count}
                            onChange={(e) => setSettings({...settings, count: parseFloat(e.target.value)})}
                            className="w-full h-1 bg-white/20 rounded-lg appearance-none cursor-pointer accent-amber-500"
                        />
                    </div>

                    <div>
                        <div className="flex justify-between text-xs text-white/70 mb-1">
                            <span>辉光 (Glow)</span>
                            <span className="font-mono text-amber-400">{settings.glow.toFixed(1)}x</span>
                        </div>
                        <input 
                            type="range" min="0.5" max="3.0" step="0.1" 
                            value={settings.glow}
                            onChange={(e) => setSettings({...settings, glow: parseFloat(e.target.value)})}
                            className="w-full h-1 bg-white/20 rounded-lg appearance-none cursor-pointer accent-amber-500"
                        />
                    </div>
                </div>
            </div>
        )}

        {/* Gesture & Combo Guide - Moved to Bottom */}
        {!hasStarted && (
            <div className="absolute bottom-0 left-0 w-full p-6 z-20">
                <div className="max-w-6xl mx-auto bg-black/60 backdrop-blur-md border border-white/10 rounded-2xl p-6 shadow-2xl grid grid-cols-1 md:grid-cols-2 gap-6">
                    {/* Basic Spells */}
                    <div>
                        <h4 className="text-amber-500 text-xs uppercase tracking-widest mb-4 border-b border-white/10 pb-2">基础手势</h4>
                        <div className="grid grid-cols-2 gap-4 text-white/90 text-sm">
                            <div className="flex items-center gap-3 bg-white/5 px-3 py-2 rounded-lg">
                                <span className="text-2xl">✋</span> 
                                <div className="flex flex-col">
                                    <span className="text-orange-400 font-bold">火焰</span>
                                    <span className="text-[10px] text-gray-400">五指张开 (克流水)</span>
                                </div>
                            </div>
                            <div className="flex items-center gap-3 bg-white/5 px-3 py-2 rounded-lg">
                                <span className="text-2xl">👇</span>
                                <div className="flex flex-col">
                                    <span className="text-blue-400 font-bold">流水</span>
                                    <span className="text-[10px] text-gray-400">掌心向下 (克火焰)</span>
                                </div>
                            </div>
                            <div className="flex items-center gap-3 bg-white/5 px-3 py-2 rounded-lg">
                                <span className="text-2xl">👊</span>
                                <div className="flex flex-col">
                                    <span className="text-purple-400 font-bold">雷霆</span>
                                    <span className="text-[10px] text-gray-400">握紧拳头 (克疾风)</span>
                                </div>
                            </div>
                            <div className="flex items-center gap-3 bg-white/5 px-3 py-2 rounded-lg">
                                <span className="text-2xl">✌️</span>
                                <div className="flex flex-col">
                                    <span className="text-teal-300 font-bold">疾风</span>
                                    <span className="text-[10px] text-gray-400">剪刀手 (克雷霆)</span>
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* Combo Effects */}
                    <div>
                        <h4 className="text-cyan-400 text-xs uppercase tracking-widest mb-4 border-b border-white/10 pb-2">组合技效果 (双手结印)</h4>
                        <div className="grid grid-cols-2 gap-4 text-white/90 text-sm">
                            <div className="bg-white/5 px-3 py-2 rounded-lg border-l-2 border-cyan-200">
                                <span className="text-cyan-200 font-bold block text-xs mb-1">❄️ 极寒风暴 (水+风)</span>
                                <span className="text-[10px] text-gray-300">全屏减速，冻结敌人</span>
                            </div>
                            <div className="bg-white/5 px-3 py-2 rounded-lg border-l-2 border-purple-400">
                                <span className="text-purple-400 font-bold block text-xs mb-1">⚛️ 等离子破 (火+风)</span>
                                <span className="text-[10px] text-gray-300">引力场，吸附敌人</span>
                            </div>
                             <div className="bg-white/5 px-3 py-2 rounded-lg border-l-2 border-blue-600">
                                <span className="text-blue-600 font-bold block text-xs mb-1">⛈️ 雷暴风眼 (雷+水)</span>
                                <span className="text-[10px] text-gray-300">释放冲击波，击退敌人</span>
                            </div>
                            <div className="bg-white/5 px-3 py-2 rounded-lg border-l-2 border-red-600">
                                <span className="text-red-600 font-bold block text-xs mb-1">🌋 地狱烈火 (火+火)</span>
                                <span className="text-[10px] text-gray-300">全屏轰炸，秒杀小怪</span>
                            </div>
                        </div>
                         <div className="mt-2 text-[10px] text-amber-500/60 text-center">
                            提示: 双手之间的连线也可以造成大量伤害!
                        </div>
                    </div>
                </div>
            </div>
        )}
    </div>
  );
};

export default MagicOverlay;

import React, { useEffect, useRef, useCallback, useState } from 'react';
import Webcam from 'react-webcam';
import { Particle, HandData, ElementType, Theme, ParticleType, Monster } from '../types';
import { 
  drawRuneRing, 
  drawSacredGeometry, 
  drawSquareLayer, 
  drawPentagram,
  THEMES
} from '../utils/geometry';

interface MagicOverlayProps {
  width: number;
  height: number;
}

const COMBO_THEMES: Record<string, Theme> = {
  'BLIZZARD': { primary: '#00FFFF', secondary: '#E0FFFF', core: '#FFFFFF', shadow: '#008B8B', background: '#0a1a20' }, 
  'PLASMA': { primary: '#FF00FF', secondary: '#00FFFF', core: '#FFFFFF', shadow: '#9400D3', background: '#1a051a' }, 
  'STEAM': { primary: '#F0F8FF', secondary: '#B0C4DE', core: '#FFFFFF', shadow: '#778899', background: '#10151a' }, 
  'TEMPEST': { primary: '#000080', secondary: '#8A2BE2', core: '#FFFF00', shadow: '#191970', background: '#05051a' }, 
  'INFERNO': { primary: '#FF0000', secondary: '#FF4500', core: '#FFFF00', shadow: '#8B0000', background: '#2a0500' }, 
  'VOID': { primary: '#000000', secondary: '#4B0082', core: '#FFFFFF', shadow: '#9400D3', background: '#000000' }, 
};

const ELEMENT_NAMES_CN: Record<string, string> = {
    'NEUTRAL': '等待施法...',
    'FIRE': '🔥 烈焰术 (FIRE)',
    'WATER': '💧 唤雨术 (WATER)',
    'THUNDER': '⚡ 雷霆术 (THUNDER)',
    'WIND': '🌪️ 疾风术 (WIND)',
    'BLIZZARD': '❄️ 极寒风暴 (BLIZZARD)',
    'PLASMA': '⚛️ 等离子破 (PLASMA)',
    'STEAM': '♨️ 灼热蒸汽 (STEAM)',
    'TEMPEST': '⛈️ 雷暴风眼 (TEMPEST)',
    'INFERNO': '🌋 地狱烈火 (INFERNO)',
    'VOID': '🌌 虚空奇点 (VOID)'
};

const getCombo = (g1: ElementType, g2: ElementType): string | null => {
    const sorted = [g1, g2].sort().join('_');
    switch(sorted) {
        case 'WATER_WIND': return 'BLIZZARD';
        case 'FIRE_WIND': return 'PLASMA';
        case 'FIRE_WATER': return 'STEAM';
        case 'THUNDER_WATER': return 'TEMPEST';
        case 'FIRE_FIRE': return 'INFERNO';
        case 'THUNDER_THUNDER': return 'VOID';
        default: return null;
    }
};

const MagicOverlay: React.FC<MagicOverlayProps> = ({ width, height }) => {
  const webcamRef = useRef<Webcam>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>(0);

  // Game Refs
  const particlesRef = useRef<Particle[]>([]);
  const handDataRef = useRef<HandData[]>([]);
  const monstersRef = useRef<Monster[]>([]);
  const monsterSpawnTimerRef = useRef<number>(0);
  const scoreRef = useRef<number>(0);
  const coreHealthRef = useRef<number>(100);

  // Level System Refs
  const levelRef = useRef<number>(1);
  const levelProgressRef = useRef<number>(0);
  const isBossActiveRef = useRef<boolean>(false);
  const maxLevel = 5;

  // App State
  const [currentElement, setCurrentElement] = useState<string>('NEUTRAL');
  const [isModelLoaded, setIsModelLoaded] = useState(false);
  const [loadingError, setLoadingError] = useState<string | null>(null);
  const [debugInfo, setDebugInfo] = useState<string>("初始化系统...");
  const [hasStarted, setHasStarted] = useState(false);
  const [showControls, setShowControls] = useState(false); 
  const [isCameraReady, setCameraReady] = useState(false);

  // Game UI State
  const [uiScore, setUiScore] = useState(0);
  const [uiHealth, setUiHealth] = useState(100);
  const [uiLevel, setUiLevel] = useState(1);
  const [uiProgress, setUiProgress] = useState(0);
  const [isGameOver, setIsGameOver] = useState(false);

  // Settings State 
  const [settings, setSettings] = useState({
      speed: 1.0,   
      count: 0.5,   
      glow: 1.0,    
  });

  const settingsRef = useRef(settings);
  useEffect(() => { settingsRef.current = settings; }, [settings]);

  // Visual Feedback State
  const highlightRef = useRef<number>(0);
  const prevElementRef = useRef<string>('NEUTRAL');
  const activeComboRef = useRef<string | null>(null);

  // Audio Context
  const audioContextRef = useRef<AudioContext | null>(null);
  const noiseBufferRef = useRef<AudioBuffer | null>(null);

  const currentTheme = activeComboRef.current 
    ? COMBO_THEMES[activeComboRef.current] 
    : (THEMES[currentElement as ElementType] || THEMES['NEUTRAL']);

  useEffect(() => {
    const AudioContextClass = (window as any).AudioContext || (window as any).webkitAudioContext;
    if (AudioContextClass) {
        const ctx = new AudioContextClass();
        audioContextRef.current = ctx;

        const bufferSize = ctx.sampleRate * 2; 
        const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
        const data = buffer.getChannelData(0);
        for (let i = 0; i < bufferSize; i++) {
            data[i] = Math.random() * 2 - 1;
        }
        noiseBufferRef.current = buffer;
    }
  }, []);

  const startExperience = () => {
      setHasStarted(true);
      if (audioContextRef.current?.state === 'suspended') {
          audioContextRef.current.resume();
      }
      monstersRef.current = [];
      scoreRef.current = 0;
      coreHealthRef.current = 100;
      levelRef.current = 1;
      levelProgressRef.current = 0;
      isBossActiveRef.current = false;

      setUiScore(0);
      setUiHealth(100);
      setUiLevel(1);
      setUiProgress(0);
      setIsGameOver(false);
  };

  const playChime = useCallback((element: string) => {
    const ctx = audioContextRef.current;
    if (!ctx || !noiseBufferRef.current) return;
    if (ctx.state === 'suspended') ctx.resume().catch(console.error);

    const now = ctx.currentTime;
    const masterGain = ctx.createGain();
    masterGain.connect(ctx.destination);
    masterGain.gain.setValueAtTime(0.3, now); 

    const playNoise = (filterType: BiquadFilterType, freqStart: number, freqEnd: number, duration: number, vol: number = 1, delay: number = 0) => {
        const src = ctx.createBufferSource();
        src.buffer = noiseBufferRef.current;
        src.loop = true;
        const filter = ctx.createBiquadFilter();
        filter.type = filterType;
        filter.frequency.setValueAtTime(freqStart, now + delay);
        filter.frequency.exponentialRampToValueAtTime(freqEnd, now + delay + duration);
        filter.Q.value = 1;
        const amp = ctx.createGain();
        amp.gain.setValueAtTime(0, now + delay);
        amp.gain.linearRampToValueAtTime(vol, now + delay + 0.05);
        amp.gain.exponentialRampToValueAtTime(0.01, now + delay + duration);
        src.connect(filter);
        filter.connect(amp);
        amp.connect(masterGain);
        src.start(now + delay);
        src.stop(now + delay + duration + 0.2);
    };

    const playTone = (type: OscillatorType, freqStart: number, freqEnd: number, duration: number, vol: number = 1, delay: number = 0) => {
        const osc = ctx.createOscillator();
        osc.type = type;
        osc.frequency.setValueAtTime(freqStart, now + delay);
        if (freqStart !== freqEnd) osc.frequency.exponentialRampToValueAtTime(freqEnd, now + delay + duration);
        const amp = ctx.createGain();
        amp.gain.setValueAtTime(0, now + delay);
        amp.gain.linearRampToValueAtTime(vol, now + delay + 0.05);
        amp.gain.exponentialRampToValueAtTime(0.01, now + delay + duration);
        osc.connect(amp);
        amp.connect(masterGain);
        osc.start(now + delay);
        osc.stop(now + delay + duration + 0.2);
    };

    switch (element) {
        case 'FIRE': playNoise('lowpass', 500, 100, 1.0, 0.5); playTone('sawtooth', 80, 120, 0.8, 0.2); break;
        case 'WATER': playNoise('bandpass', 800, 300, 0.6, 0.4); playTone('sine', 600, 300, 0.4, 0.3, 0.1); break;
        case 'WIND': playNoise('lowpass', 200, 800, 0.4, 0.3); playNoise('highpass', 400, 1000, 0.5, 0.2, 0.1); break;
        case 'THUNDER': playTone('sawtooth', 800, 50, 0.3, 0.2); playNoise('lowpass', 1000, 50, 1.2, 0.6, 0.1); break;
        case 'BLIZZARD': playNoise('highpass', 1000, 3000, 1.5, 0.4); playTone('sine', 1500, 2000, 0.3, 0.1, 0.1); break;
        case 'INFERNO': playNoise('lowpass', 800, 50, 1.5, 0.8); playTone('square', 60, 40, 1.5, 0.2); break;
        case 'TEMPEST': playNoise('lowpass', 200, 50, 2.0, 0.8); playTone('sawtooth', 1200, 100, 0.5, 0.2, 0.1); playNoise('bandpass', 1000, 500, 1.0, 0.3); break;
        case 'VOID': playTone('sine', 50, 40, 2.5, 0.6); playNoise('bandpass', 100, 200, 2.5, 0.4); playTone('sine', 300, 290, 1.0, 0.1, 0.5); break;
        case 'PLASMA': playTone('sawtooth', 200, 800, 1.0, 0.2); playNoise('bandpass', 400, 1200, 1.0, 0.4); break;
        case 'STEAM': playNoise('highpass', 500, 1000, 1.0, 0.3); break;
        default: playTone('triangle', 440, 880, 0.3, 0.1);
    }
  }, []);

  const detectGesture = (landmarks: any[], videoWidth: number, videoHeight: number): ElementType => {
    const mapPt = (idx: number) => ({ x: (1 - landmarks[idx].x) * videoWidth, y: landmarks[idx].y * videoHeight });
    const wrist = mapPt(0);
    const indexTip = mapPt(8);
    const middleTip = mapPt(12);
    const middleMCP = mapPt(9);

    const distSq = (p1: any, p2: any) => (p1.x - p2.x)**2 + (p1.y - p2.y)**2;
    const isFingerOpen = (tip: any, mcp: any) => distSq(tip, wrist) > distSq(mcp, wrist) * 1.2;

    const isPointingDown = wrist.y < middleMCP.y;
    if (isPointingDown) return 'WATER';

    let openCount = 0;
    if (isFingerOpen(indexTip, mapPt(5))) openCount++;
    if (isFingerOpen(middleTip, mapPt(9))) openCount++;
    if (isFingerOpen(mapPt(16), mapPt(13))) openCount++;
    if (isFingerOpen(mapPt(20), mapPt(17))) openCount++;

    if (openCount >= 4) return 'FIRE';
    if (openCount >= 2) return 'WIND';
    return 'THUNDER';
  };

  const drawSkeleton = (ctx: CanvasRenderingContext2D, hand: HandData) => {
      ctx.strokeStyle = "rgba(255, 255, 255, 0.15)";
      ctx.lineWidth = 1.5;
      ctx.fillStyle = "rgba(255, 255, 255, 0.5)";
      const points = [hand.wrist, hand.indexBase, hand.indexTip, hand.middleBase, hand.middleTip, hand.ringBase, hand.ringTip, hand.pinkyBase, hand.pinkyTip, hand.thumbTip];

      const drawLine = (p1: any, p2: any) => { ctx.beginPath(); ctx.moveTo(p1.x, p1.y); ctx.lineTo(p2.x, p2.y); ctx.stroke(); }
      drawLine(hand.wrist, hand.indexBase); drawLine(hand.indexBase, hand.indexTip);
      drawLine(hand.wrist, hand.middleBase); drawLine(hand.middleBase, hand.middleTip);
      drawLine(hand.wrist, hand.pinkyBase); drawLine(hand.pinkyBase, hand.pinkyTip);

      points.forEach(p => { ctx.beginPath(); ctx.arc(p.x, p.y, 2.5, 0, Math.PI * 2); ctx.fill(); });
  };

  const onResults = useCallback((results: any) => {
    const displayWidth = width;
    const displayHeight = height;

    setIsModelLoaded((prev) => {
        if (!prev) return true;
        return prev;
    });

    if (results.multiHandLandmarks && results.multiHandLandmarks.length > 0) {
      const newHandData: HandData[] = results.multiHandLandmarks.map((landmarks: any[]) => {
        const gesture = detectGesture(landmarks, displayWidth, displayHeight);
        const mapPt = (idx: number) => ({ x: (1 - landmarks[idx].x) * displayWidth, y: landmarks[idx].y * displayHeight });
        return {
          wrist: mapPt(0), indexTip: mapPt(8), middleTip: mapPt(12), ringTip: mapPt(16), pinkyTip: mapPt(20), thumbTip: mapPt(4),
          indexBase: mapPt(5), middleBase: mapPt(9), ringBase: mapPt(13), pinkyBase: mapPt(17),
          isOpen: gesture !== 'THUNDER', gesture, opacity: 1
        };
      });

      handDataRef.current = newHandData;
      let newElement = 'NEUTRAL';
      let activeCombo = null;

      if (newHandData.length === 2) {
          const g1 = newHandData[0].gesture;
          const g2 = newHandData[1].gesture;
          if (g1 !== 'NEUTRAL' && g2 !== 'NEUTRAL') activeCombo = getCombo(g1, g2);
      }

      if (activeCombo) newElement = activeCombo;
      else {
          const activeHand = newHandData.find(h => h.gesture !== 'NEUTRAL');
          if (activeHand) newElement = activeHand.gesture;
      }

      const prevCombo = activeComboRef.current;
      activeComboRef.current = activeCombo;

      // TRIGGER ONE-SHOT COMBO EFFECTS
      if (activeCombo && activeCombo !== prevCombo) {
          highlightRef.current = 1.0; 
          playChime(activeCombo);

          if (activeCombo === 'INFERNO') {
              // INFERNO: Screen Clear (Immediate Logic)
              let clearedCount = 0;
              for (let i = monstersRef.current.length - 1; i >= 0; i--) {
                  const m = monstersRef.current[i];
                  if (!m.isBoss) {
                       m.hp = -9999; // Kill instantly
                       spawnParticles(m.x, m.y, 'FIRE', THEMES['FIRE']);
                       clearedCount++;
                  } else {
                       m.hp -= 500;
                  }
              }
              if (clearedCount > 0) {
                  // Visual flash specifically for Inferno
                  spawnParticles(displayWidth / 2, displayHeight / 2, 'INFERNO', THEMES['INFERNO']);
              }
          } else if (activeCombo === 'TEMPEST') {
              // TEMPEST: Push Back (One Shot Impulse)
               const centerX = displayWidth / 2;
               const centerY = displayHeight / 2;
               monstersRef.current.forEach(m => {
                   if (!m.isBoss) {
                       const dx = m.x - centerX;
                       const dy = m.y - centerY;
                       const len = Math.sqrt(dx*dx + dy*dy) || 1;
                       // Massive impulse away from center
                       m.vx += (dx/len) * 30;
                       m.vy += (dy/len) * 30;
                   }
               });
          }
      } else if (newElement !== prevElementRef.current) {
          if (newElement !== 'NEUTRAL') { highlightRef.current = 1.0; playChime(newElement); }
          prevElementRef.current = newElement;
      }
      setCurrentElement(newElement);
    } else {
      handDataRef.current = [];
      activeComboRef.current = null;
      if (prevElementRef.current !== 'NEUTRAL') { prevElementRef.current = 'NEUTRAL'; setCurrentElement('NEUTRAL'); }
    }
  }, [width, height, playChime]);

  useEffect(() => {
    let hands: any = null;
    let isActive = true;
    let frameId: number;
    let lastVideoTime = -1;

    const MP_VERSION = "0.4.1675469240";

    const initHands = async () => {
       try {
           setDebugInfo("正在加载 AI 核心 (1/3)...");
           if (!(window as any).Hands) { 
               setTimeout(initHands, 500); 
               return; 
           }

           setDebugInfo("初始化视觉模型 (2/3)...");
           hands = new (window as any).Hands({ 
               locateFile: (file: string) => `https://cdn.jsdelivr.net/npm/@mediapipe/hands@${MP_VERSION}/${file}` 
           });

           hands.setOptions({ 
               maxNumHands: 2, 
               modelComplexity: 1, 
               minDetectionConfidence: 0.5, 
               minTrackingConfidence: 0.5 
           });

           hands.onResults(onResults);

           setDebugInfo("等待摄像头许可...");

           const processVideo = async () => {
             if (!isActive) return;
             if (webcamRef.current && webcamRef.current.video && webcamRef.current.video.readyState === 4) {
                 const video = webcamRef.current.video;
                 if (video.videoWidth > 0 && video.videoHeight > 0) {
                     if (video.currentTime !== lastVideoTime) {
                         lastVideoTime = video.currentTime;
                         try { 
                             setDebugInfo("正在处理视频流...");
                             await hands.send({ image: video }); 
                         } catch (e) { 
                             console.warn("Processing warning", e); 
                         }
                     }
                 }
             }
             frameId = requestAnimationFrame(processVideo);
           };
           processVideo();
       } catch (error: any) {
           console.error("Initialization Error:", error);
           setLoadingError("AI 模型加载失败: " + error.message);
           setDebugInfo("系统错误");
       }
    };

    setTimeout(initHands, 500);

    return () => { isActive = false; if (frameId) cancelAnimationFrame(frameId); if (hands) hands.close(); };
  }, [onResults]);

  // --- GAME LOGIC ---

  const spawnBoss = (width: number, height: number, level: number) => {
      isBossActiveRef.current = true;
      const elements: ElementType[] = ['FIRE', 'WATER', 'WIND', 'THUNDER'];
      const element = elements[(level - 1) % 4];
      const boss: Monster = {
          id: Date.now(),
          x: width / 2,
          y: -150, // Start well above screen
          vx: 0, vy: 1, // Move slowly down
          hp: 1000 * level,
          maxHp: 1000 * level,
          element,
          radius: 80, // Big size
          scoreValue: 5000 * level,
          pulseOffset: 0,
          isBoss: true
      };
      monstersRef.current.push(boss);
      highlightRef.current = 1.0;
  };

  const spawnMonster = (width: number, height: number) => {
      if (isBossActiveRef.current) return; // Don't spawn small mobs during boss

      const edge = Math.floor(Math.random() * 4); // 0: Top, 1: Right, 2: Bottom, 3: Left
      let x = 0, y = 0;

      switch(edge) {
          case 0: x = Math.random() * width; y = -50; break;
          case 1: x = width + 50; y = Math.random() * height; break;
          case 2: x = Math.random() * width; y = height + 50; break;
          case 3: x = -50; y = Math.random() * height; break;
      }

      const elements: ElementType[] = ['FIRE', 'WATER', 'WIND', 'THUNDER'];
      const element = elements[Math.floor(Math.random() * elements.length)];

      const monster: Monster = {
          id: Date.now() + Math.random(),
          x, y,
          vx: 0, vy: 0,
          hp: 100 + (levelRef.current * 20),
          maxHp: 100 + (levelRef.current * 20),
          element,
          radius: 20 + Math.random() * 10,
          scoreValue: 100 * levelRef.current,
          pulseOffset: Math.random() * Math.PI * 2,
          isBoss: false
      };
      monstersRef.current.push(monster);
  };

  // Distance from point p to line segment vw
  const distToSegmentSq = (p: {x: number, y: number}, v: {x: number, y: number}, w: {x: number, y: number}) => {
    const l2 = (v.x - w.x)**2 + (v.y - w.y)**2;
    if (l2 === 0) return (p.x - v.x)**2 + (p.y - v.y)**2;
    let t = ((p.x - v.x) * (w.x - v.x) + (p.y - v.y) * (w.y - v.y)) / l2;
    t = Math.max(0, Math.min(1, t));
    return (p.x - (v.x + t * (w.x - v.x)))**2 + (p.y - (v.y + t * (w.y - v.y)))**2;
  };

  const updateMonsters = (ctx: CanvasRenderingContext2D, width: number, height: number, centerX: number, centerY: number, hands: HandData[]) => {
      const monsters = monstersRef.current;
      const activeCombo = activeComboRef.current;

      const getMultiplier = (spell: string, monsterEl: string) => {
          if (spell === 'FIRE' && monsterEl === 'WATER') return 2;
          if (spell === 'WATER' && monsterEl === 'FIRE') return 2;
          if (spell === 'THUNDER' && monsterEl === 'WIND') return 2;
          if (spell === 'WIND' && monsterEl === 'THUNDER') return 2;
          if (spell === 'BLIZZARD' || spell === 'INFERNO' || spell === 'TEMPEST' || spell === 'PLASMA') return 3;
          if (spell === 'VOID') return 5;
          return 1;
      };

      for (let i = monsters.length - 1; i >= 0; i--) {
          const m = monsters[i];
          const dx = centerX - m.x;
          const dy = centerY - m.y;
          const distToCenter = Math.sqrt(dx*dx + dy*dy);

          // Movement Logic
          let speed = m.isBoss ? 0.3 : (1.5 + (levelRef.current * 0.2)); 

          // CONTINUOUS COMBO EFFECTS
          if (activeCombo === 'BLIZZARD') {
              speed *= 0.1; // Drastic Slow (Frozen)
          }

          let moveX = Math.cos(Math.atan2(dy, dx)) * speed;
          let moveY = Math.sin(Math.atan2(dy, dx)) * speed;

          // Apply Physics Velocity (from Pushbacks/Plasma)
          m.x += m.vx;
          m.y += m.vy;
          // Dampen velocity - slightly more slippery to allow pushback
          m.vx *= 0.95;
          m.vy *= 0.95;

          // PLASMA: Gravity Well towards hands center
          if (activeCombo === 'PLASMA' && hands.length === 2 && !m.isBoss) {
              const midX = (hands[0].middleBase.x + hands[1].middleBase.x) / 2;
              const midY = (hands[0].middleBase.y + hands[1].middleBase.y) / 2;
              const pdx = midX - m.x;
              const pdy = midY - m.y;
              // Strong Pull Force
              m.vx += pdx * 0.02;
              m.vy += pdy * 0.02;
          }

          m.x += moveX;
          m.y += moveY;

          // Draw Monster
          const mTheme = THEMES[m.element];
          ctx.save();
          ctx.translate(m.x, m.y);
          const pulse = 1 + Math.sin(Date.now() * 0.005 + m.pulseOffset) * 0.2;
          const scale = m.isBoss ? 3 : 1;
          ctx.scale(pulse * scale, pulse * scale);

          ctx.beginPath();
          // Draw a spiky shape
          const spikes = m.isBoss ? 12 : 5;
          const outerRadius = m.radius;
          const innerRadius = m.radius / 2;
          for (let j = 0; j < spikes * 2; j++) {
             const r = j % 2 === 0 ? outerRadius : innerRadius;
             const a = (Math.PI * j) / spikes;
             ctx.lineTo(Math.cos(a) * r, Math.sin(a) * r);
          }
          ctx.closePath();
          ctx.fillStyle = mTheme.background;
          ctx.fill();
          ctx.strokeStyle = mTheme.primary;
          ctx.lineWidth = 3;
          ctx.stroke();

          // Boss Health Bar above head
          if (m.isBoss) {
              ctx.fillStyle = 'red';
              ctx.fillRect(-30, -50, 60 * (m.hp / m.maxHp), 5);
              ctx.strokeStyle = 'white';
              ctx.strokeRect(-30, -50, 60, 5);
          }

          ctx.shadowBlur = 15;
          ctx.shadowColor = mTheme.secondary;
          ctx.fillStyle = mTheme.core;
          ctx.beginPath();
          ctx.arc(0, 0, innerRadius * 0.5, 0, Math.PI * 2);
          ctx.fill();
          ctx.shadowBlur = 0;

          // Frozen Effect Overlay
          if (activeCombo === 'BLIZZARD') {
              ctx.fillStyle = 'rgba(0, 255, 255, 0.4)';
              ctx.fill();
          }

          ctx.restore();

          // Check Collision with Hands
          let hit = false;
          let damageTaken = 0;

          // 1. Hand Point Collision
          for (const hand of hands) {
              if (hand.gesture !== 'NEUTRAL') {
                  const hx = hand.middleBase.x;
                  const hy = hand.middleBase.y;
                  const hDist = Math.hypot(hx - m.x, hy - m.y);

                  const hitRadius = activeCombo ? 120 : 80;

                  if (hDist < hitRadius + m.radius) {
                      const mult = getMultiplier(activeCombo || hand.gesture, m.element);
                      damageTaken += 3 * mult;
                      hit = true;
                  }
              }
          }

          // 2. Combo Line Collision
          if (activeCombo && hands.length === 2) {
              const h1 = hands[0].middleBase;
              const h2 = hands[1].middleBase;
              const distSq = distToSegmentSq(m, h1, h2);
              // Line thickness approx 30px
              if (distSq < (m.radius + 30)**2) {
                   const mult = getMultiplier(activeCombo, m.element);
                   damageTaken += 5 * mult; // Line does more damage
                   hit = true;
              }
          }

          if (hit) {
              m.hp -= damageTaken;
              if (Math.random() > 0.7) {
                  spawnParticles(m.x, m.y, activeCombo || 'NEUTRAL', mTheme);
              }
              // Flash
              ctx.save();
              ctx.globalCompositeOperation = 'lighter';
              ctx.fillStyle = '#FFFFFF';
              ctx.beginPath();
              ctx.arc(m.x, m.y, m.radius * (m.isBoss ? 3 : 1.5), 0, Math.PI*2);
              ctx.globalAlpha = 0.5;
              ctx.fill();
              ctx.restore();
          }

          // Death or Core Hit
          if (m.hp <= 0) {
              monsters.splice(i, 1);
              const mult = activeCombo ? 2 : 1; 
              scoreRef.current += m.scoreValue * mult;

              if (m.isBoss) {
                  // Boss Dead - Level Up
                  spawnParticles(m.x, m.y, m.element, mTheme);
                  // Massive explosion
                  for(let k=0; k<5; k++) spawnParticles(m.x, m.y, m.element, mTheme);

                  levelRef.current = Math.min(levelRef.current + 1, maxLevel);
                  levelProgressRef.current = 0;
                  isBossActiveRef.current = false;
                  coreHealthRef.current = Math.min(100, coreHealthRef.current + 50); // Heal on boss kill
              } else {
                  spawnParticles(m.x, m.y, m.element, mTheme);
                  // Progress update
                  if (levelProgressRef.current < 100 && !isBossActiveRef.current) {
                      levelProgressRef.current += 5; 
                  }
              }

              playChime(m.element);
          } else if (distToCenter < (m.isBoss ? 80 : 40)) {
              // Hit Core
              if (!m.isBoss) monsters.splice(i, 1); // Boss doesn't disappear, just eats core

              const dmg = m.isBoss ? 1 : 10;
              coreHealthRef.current -= dmg;
              highlightRef.current = 1.0; 
              spawnParticles(centerX, centerY, 'NEUTRAL', THEMES['NEUTRAL']);
          }
      }
  };

  // --- PHYSICS ENGINE ---
  const updateParticles = (ctx: CanvasRenderingContext2D, width: number, height: number, centerX: number, centerY: number) => {
    ctx.shadowBlur = 0; 
    const { glow } = settingsRef.current;

    for (let i = particlesRef.current.length - 1; i >= 0; i--) {
      const p = particlesRef.current[i];

      if (p.element === 'WIND' || p.element === 'BLIZZARD') {
          p.vx *= 0.995; p.vy *= 0.995;
      } else {
          p.vx *= 0.98; p.vy *= 0.98;
      }

      switch (p.element) {
          case 'WIND':
          case 'BLIZZARD':
              const dx = p.x - centerX;
              const dy = p.y - centerY;
              const dist = Math.sqrt(dx*dx + dy*dy) + 1;
              const angle = Math.atan2(dy, dx);
              p.vx += Math.cos(angle + Math.PI/2) * 2.5; 
              p.vy += Math.sin(angle + Math.PI/2) * 2.5;
              p.vx -= (dx / dist) * 0.8;
              p.vy -= (dy / dist) * 0.8;
              p.angle += p.angularVelocity * 1.5; 
              break;
          case 'WATER':
          case 'STEAM':
              p.vy += 1.5; 
              p.x += Math.sin(p.life * 0.2) * 1.0;
              break;
          case 'THUNDER':
          case 'TEMPEST':
          case 'VOID':
              p.vx += (Math.random() - 0.5) * 6; 
              p.vy += (Math.random() - 0.5) * 6;
              if (Math.random() < 0.15) {
                  p.x += (Math.random() - 0.5) * 40;
                  p.y += (Math.random() - 0.5) * 40;
              }
              break;
          case 'FIRE':
          case 'INFERNO':
              p.vy -= 1.5; 
              p.vx += (Math.random() - 0.5) * 2.0;
              p.size *= 0.95; 
              break;
          default:
              p.vy -= 0.2;
      }

      p.x += p.vx;
      p.y += p.vy;
      p.life -= 1;
      if (p.element !== 'FIRE') p.size *= 0.98;

      if (p.life <= 0 || p.size < 0.1 || p.y > height + 50 || p.y < -50 || p.x < -50 || p.x > width + 50) {
        particlesRef.current.splice(i, 1);
      } else {
        ctx.save();
        if (p.size > 2) {
             const shadowOffsetX = (p.x - centerX) * 0.05;
             const shadowOffsetY = (p.y - centerY) * 0.05;
             ctx.fillStyle = "rgba(0,0,0,0.3)";
             ctx.beginPath();
             ctx.arc(p.x + shadowOffsetX, p.y + shadowOffsetY, p.size * glow, 0, Math.PI*2);
             ctx.fill();
        }

        let alpha = Math.min(1, p.life / 10, (p.maxLife - p.life) / 5);
        if ((p.element === 'FIRE' || p.element === 'INFERNO') && p.size < 3.5 && p.type === 'EMBER') {
             alpha *= (0.5 + Math.random() * 0.5);
        }

        ctx.globalAlpha = alpha;
        const renderSize = p.size * glow;

        if (p.type === 'LEAF') {
            ctx.translate(p.x, p.y);
            ctx.rotate(p.angle);
            ctx.fillStyle = p.color;
            ctx.beginPath();
            ctx.ellipse(0, 0, renderSize, renderSize * 0.4, 0, 0, Math.PI * 2);
            ctx.fill();
        } 
        else if (p.type === 'DROP') {
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 2.5 * glow;
            ctx.lineCap = 'round';
            ctx.beginPath();
            ctx.moveTo(p.x, p.y);
            ctx.lineTo(p.x - p.vx * 1.5, p.y - p.vy * 4); 
            ctx.stroke();
        }
        else if (p.type === 'SPARK') {
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 2 * glow;
            ctx.beginPath();
            ctx.moveTo(p.x - p.vx, p.y - p.vy);
            ctx.lineTo(p.x + p.vx, p.y + p.vy);
            ctx.stroke();
        }
        else {
            ctx.fillStyle = p.color;
            ctx.beginPath();
            ctx.arc(p.x, p.y, renderSize, 0, Math.PI * 2);
            ctx.fill();
        }
        ctx.restore();
      }
    }
  };

  const spawnParticles = (x: number, y: number, element: string, theme: Theme) => {
    const { speed: speedMulti, count: countMulti } = settingsRef.current;
    const isCombo = activeComboRef.current !== null;
    let baseCount = isCombo ? 10 : 3;
    let count = Math.ceil(baseCount * countMulti);
    count = Math.min(count, 50);

    for (let i = 0; i < count; i++) {
        let type: ParticleType = 'ORB';
        let speed = (Math.random() * 8 + 4) * speedMulti; 
        let spread = 30;
        let pColor = Math.random() > 0.5 ? theme.primary : theme.secondary;
        let pSize = 4 + Math.random() * 6;
        let pLife = 30 + Math.random() * 30;

        if (element === 'WIND' || element === 'BLIZZARD') {
            type = Math.random() > 0.5 ? 'LEAF' : 'MIST';
            if (isCombo) pColor = Math.random() > 0.5 ? '#00FFFF' : '#F0FFF0';
            else if (element === 'WIND') pColor = Math.random() > 0.5 ? '#00FFFF' : '#F0FFF0'; 
        } else if (element === 'WATER' || element === 'STEAM') {
            type = Math.random() > 0.7 ? 'MIST' : 'DROP';
            spread = 50; 
        } else if (element === 'THUNDER' || element === 'TEMPEST' || element === 'VOID') {
            type = 'SPARK';
            speed = 12 * speedMulti; 
            if (element === 'THUNDER') pColor = Math.random() > 0.5 ? '#FFFF00' : '#9400D3';
        } else if (element === 'FIRE' || element === 'INFERNO') {
            const r = Math.random();
            if (r < 0.3) {
                 type = 'EMBER';
                 pColor = Math.random() > 0.5 ? '#FFD700' : '#FFFFFF';
                 pSize = 1 + Math.random() * 3;
                 pLife = 15 + Math.random() * 20; 
                 speed *= 1.5; 
            } else if (r < 0.6) {
                 type = 'MIST'; 
            } else {
                 type = 'EMBER'; 
            }
        }

        const angle = Math.random() * Math.PI * 2;
        let vx = Math.cos(angle) * speed;
        let vy = Math.sin(angle) * speed;

        if (element === 'WATER' || element === 'STEAM') { vx *= 0.3; vy = Math.random() * 5 * speedMulti + 5; } 
        if ((element === 'FIRE' || element === 'INFERNO') && pSize < 4 && type === 'EMBER') {
            vy -= 2.0; 
        }

        let spawnX = x + (Math.random() - 0.5) * spread;
        let spawnY = y + (Math.random() - 0.5) * spread;

        particlesRef.current.push({
            x: spawnX,
            y: spawnY,
            vx, vy,
            life: pLife,
            maxLife: 60,
            size: pSize,
            color: pColor,
            element: element as Particle['element'],
            type,
            angle: Math.random() * Math.PI * 2,
            angularVelocity: (Math.random() - 0.5) * 0.4
        });
    }
  };

  const animate = useCallback((time: number) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d', { alpha: false }); 
    if (!ctx) return;

    const dpr = window.devicePixelRatio || 1;
    if (canvas.width !== width * dpr || canvas.height !== height * dpr) {
        canvas.width = width * dpr;
        canvas.height = height * dpr;
    }
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

    const theme = activeComboRef.current 
        ? COMBO_THEMES[activeComboRef.current] 
        : (THEMES[currentElement as ElementType] || THEMES['NEUTRAL']);

    ctx.globalCompositeOperation = 'source-over';

    ctx.fillStyle = theme.background;
    ctx.fillRect(0, 0, width, height);

    if (highlightRef.current > 0.01) highlightRef.current *= 0.925; 
    else highlightRef.current = 0;
    const flash = highlightRef.current;

    // --- GAME LOGIC UPDATES ---
    if (hasStarted && !isGameOver) {
        monsterSpawnTimerRef.current++;
        // Spawn rate
        const spawnRate = Math.max(20, 100 - (levelRef.current * 10));

        if (!isBossActiveRef.current && monsterSpawnTimerRef.current > spawnRate) {
            spawnMonster(width, height);
            monsterSpawnTimerRef.current = 0;
        }

        // Check for Boss Spawn
        if (!isBossActiveRef.current && levelProgressRef.current >= 100) {
            spawnBoss(width, height, levelRef.current);
        }

        if (coreHealthRef.current <= 0) {
            setIsGameOver(true);
        }

        // Update UI state occasionally
        if (monsterSpawnTimerRef.current % 10 === 0) {
            setUiScore(scoreRef.current);
            setUiHealth(coreHealthRef.current);
            setUiLevel(levelRef.current);
            setUiProgress(levelProgressRef.current);
        }
    }

    if (flash > 0.01) {
        ctx.save();
        ctx.globalCompositeOperation = 'lighter';
        ctx.strokeStyle = '#FF0000'; // Damage flash
        ctx.lineWidth = 30 * flash; 
        ctx.shadowBlur = 40;
        ctx.shadowColor = '#FF0000';
        ctx.globalAlpha = flash; 
        ctx.strokeRect(0, 0, width, height);
        ctx.restore();
    }

    let centerX = width / 2;
    let centerY = height / 2;
    const t = time * 0.001;
    const comboName = activeComboRef.current;

    // Draw Core
    ctx.save();
    ctx.translate(centerX, centerY);
    // Rotating crystal/core
    ctx.rotate(t * 0.5);
    ctx.fillStyle = '#FFFFFF';
    ctx.shadowBlur = 20 + Math.sin(t * 5) * 10;
    ctx.shadowColor = '#00FFFF';
    const coreSize = 30;
    ctx.beginPath();
    ctx.moveTo(0, -coreSize);
    ctx.lineTo(coreSize, 0);
    ctx.lineTo(0, coreSize);
    ctx.lineTo(-coreSize, 0);
    ctx.fill();

    // Core Health Ring - Visual only (actual bar moved to UI)
    ctx.rotate(-t * 0.5); 
    ctx.beginPath();
    ctx.arc(0, 0, 50, 0, Math.PI * 2);
    ctx.strokeStyle = 'rgba(255,255,255,0.2)';
    ctx.lineWidth = 2;
    ctx.stroke();

    ctx.restore();

    // 2. Geometry & Particles
    ctx.globalCompositeOperation = 'lighter'; 

    // Render Monsters
    updateMonsters(ctx, width, height, centerX, centerY, handDataRef.current);

    if (comboName && handDataRef.current.length === 2) {
        // --- COMBO MODE ---
        const h1 = handDataRef.current[0];
        const h2 = handDataRef.current[1];

        const midX = (h1.middleBase.x + h2.middleBase.x) / 2;
        const midY = (h1.middleBase.y + h2.middleBase.y) / 2;

        ctx.save();
        ctx.beginPath();
        ctx.moveTo(h1.middleBase.x, h1.middleBase.y);
        ctx.lineTo(h2.middleBase.x, h2.middleBase.y);
        ctx.strokeStyle = theme.primary;
        ctx.lineWidth = 20 + Math.sin(t * 10) * 5; 
        ctx.lineCap = 'round';
        ctx.shadowBlur = 20; 
        ctx.shadowColor = theme.secondary;
        ctx.globalAlpha = 0.4;
        ctx.stroke();
        ctx.restore();

        drawRuneRing(ctx, midX, midY, 180, t, theme);
        drawSacredGeometry(ctx, midX, midY, 140, -t * 2, theme);
        spawnParticles(midX, midY, comboName, theme);

        handDataRef.current.forEach(h => {
             drawSkeleton(ctx, h);
             const auraSize = 50 + Math.sin(t * 20) * 10;
             const grad = ctx.createRadialGradient(h.middleBase.x, h.middleBase.y, 10, h.middleBase.x, h.middleBase.y, auraSize);
             grad.addColorStop(0, theme.core);
             grad.addColorStop(0.4, theme.primary);
             grad.addColorStop(1, 'rgba(0,0,0,0)');
             ctx.save();
             ctx.fillStyle = grad;
             ctx.globalAlpha = 0.5;
             ctx.beginPath();
             ctx.arc(h.middleBase.x, h.middleBase.y, auraSize, 0, Math.PI * 2);
             ctx.fill();
             ctx.restore();
             drawRuneRing(ctx, h.middleBase.x, h.middleBase.y, 40, t*5, theme);
        });

    } else {
        // --- INDIVIDUAL MODE ---
        handDataRef.current.forEach((hand) => {
           drawSkeleton(ctx, hand);
           const element = hand.gesture;
           const handTheme = (element !== 'NEUTRAL' && THEMES[element]) ? THEMES[element] : THEMES['NEUTRAL'];
           const centerX = hand.middleBase.x; 
           const centerY = hand.middleBase.y; 

           if (element !== 'NEUTRAL') {
               if (flash > 0.05 && highlightRef.current > 0.05) {
                   ctx.save();
                   ctx.translate(centerX, centerY);
                   const waveSize = 120 + (1 - flash) * 100;
                   ctx.beginPath();
                   ctx.arc(0, 0, waveSize, 0, Math.PI * 2);
                   ctx.lineWidth = 10 * flash;
                   ctx.strokeStyle = handTheme.core;
                   ctx.shadowBlur = 20;
                   ctx.shadowColor = handTheme.secondary;
                   ctx.globalAlpha = flash;
                   ctx.stroke();
                   ctx.restore();
               }

               drawRuneRing(ctx, centerX, centerY, 120, t * 0.5, handTheme);
               drawSacredGeometry(ctx, centerX, centerY, 90, -t * 1.5, handTheme);
               drawSquareLayer(ctx, centerX, centerY, 65, t * 2.5, handTheme);
               const pulse = Math.sin(time * 0.005) * 0.5 + 0.5;
               drawPentagram(ctx, centerX, centerY, 40, t, pulse, handTheme);

               spawnParticles(centerX, centerY, element, handTheme);
           } else {
               ctx.globalAlpha = 0.3;
               drawRuneRing(ctx, centerX, centerY, 50, t * 0.2, handTheme);
           }
        });
    }

    updateParticles(ctx, width, height, centerX, centerY);
    requestRef.current = requestAnimationFrame(animate);
  }, [width, height, currentElement, hasStarted, isGameOver]);

  useEffect(() => {
    requestRef.current = requestAnimationFrame(animate);
    return () => { if (requestRef.current) cancelAnimationFrame(requestRef.current); };
  }, [animate]);

  return (
    <div className="relative w-full h-full overflow-hidden flex items-center justify-center font-sans">

        {/* Dynamic Background */}
        <div 
            className="absolute inset-0 transition-colors duration-700 ease-in-out z-0"
            style={{ backgroundColor: currentTheme.background }}
        />

        {/* Hidden Webcam */}
        <Webcam 
            ref={webcamRef} 
            audio={false} 
            width={width} 
            height={height} 
            mirrored={true} 
            screenshotFormat="image/jpeg" 
            className="absolute opacity-0 pointer-events-none" 
            onUserMedia={() => setCameraReady(true)}
            onUserMediaError={(e: any) => setLoadingError("摄像头访问失败: " + e)}
        />

        {/* Canvas Layer */}
        <canvas ref={canvasRef} style={{ width, height }} className="absolute top-0 left-0 z-10" />

        {/* GAME OVER SCREEN */}
        {isGameOver && (
             <div className="absolute inset-0 flex items-center justify-center bg-black/80 z-50 backdrop-blur-sm">
                <div className="text-center p-8 border border-red-500/50 rounded-xl bg-black/80 shadow-[0_0_50px_rgba(255,0,0,0.3)]">
                    <h2 className="text-4xl font-bold text-red-500 mb-4 tracking-widest">能量核心崩溃</h2>
                    <div className="text-2xl text-white mb-6">最终得分: <span className="text-amber-500 font-mono">{uiScore}</span></div>
                    <button 
                        onClick={startExperience}
                        className="px-8 py-3 bg-red-900 hover:bg-red-700 text-white font-bold rounded border border-red-500 transition-colors"
                    >
                        重启时间线
                    </button>
                </div>
             </div>
        )}

        {!isModelLoaded && !isGameOver && (
            <div className="absolute inset-0 flex items-center justify-center bg-black bg-opacity-90 z-50">
                <div className="flex flex-col items-center">
                    <div className="text-amber-500 font-mono text-xl animate-pulse tracking-widest mb-4">🔮 正在校准魔法维度...</div>
                    {loadingError ? (
                        <div className="text-red-500 font-bold bg-black/50 p-2 rounded">{loadingError}</div>
                    ) : (
                        <div className="w-64 h-1 bg-gray-800 rounded-full overflow-hidden">
                            <div className="h-full bg-amber-500 animate-[width_1s_ease-in-out_infinite]" style={{width: '50%'}}></div>
                        </div>
                    )}
                    <div className="mt-4 text-xs text-gray-400 font-mono">{debugInfo}</div>
                </div>
            </div>
        )}

        {!hasStarted && isModelLoaded && !isGameOver && (
            <div className="absolute inset-0 flex items-center justify-center bg-black/60 z-50 cursor-pointer backdrop-blur-sm" onClick={startExperience}>
                <div className="border border-amber-500/50 bg-black/80 p-8 rounded-lg text-center shadow-[0_0_30px_rgba(255,160,20,0.3)] hover:scale-105 transition-transform duration-300">
                    <h2 className="text-3xl font-bold text-amber-500 mb-2">准备就绪</h2>
                    <p className="text-white/80 mb-6">点击屏幕开启守护试炼</p>
                    <button className="px-6 py-2 bg-amber-600 hover:bg-amber-500 text-black font-bold rounded">进入</button>
                </div>
            </div>
        )}

        {/* Dynamic Spell Name */}
        <div className="absolute top-24 left-0 w-full flex justify-center z-20 pointer-events-none">
             <div className={`text-4xl md:text-5xl font-bold tracking-widest transition-all duration-300 drop-shadow-[0_0_15px_rgba(255,255,255,0.4)] px-8 py-2 rounded-full ${highlightRef.current > 0.1 ? 'scale-110 bg-black/20 backdrop-blur-sm' : ''} ${
                currentElement === 'FIRE' ? 'text-orange-500' :
                currentElement === 'WATER' ? 'text-blue-500' :
                currentElement === 'WIND' ? 'text-cyan-300' :
                currentElement === 'THUNDER' ? 'text-purple-500' : 
                currentElement === 'INFERNO' ? 'text-red-600' :
                currentElement === 'BLIZZARD' ? 'text-cyan-100' :
                currentElement === 'VOID' ? 'text-violet-400' : 'text-amber-400'
            }`}>
                {ELEMENT_NAMES_CN[currentElement]}
            </div>
        </div>

        {/* TOP HUD - LEVEL & SCORE */}
        {hasStarted && (
            <>
                {/* Top Center: Level Progress */}
                <div className="absolute top-0 left-0 w-full h-2 z-30 bg-gray-800">
                    <div 
                        className={`h-full transition-all duration-300 ease-out ${uiProgress >= 100 ? 'bg-red-500 animate-pulse' : 'bg-amber-500'}`}
                        style={{ width: `${Math.min(100, uiProgress)}%` }}
                    />
                </div>
                {uiProgress >= 100 && (
                     <div className="absolute top-4 left-1/2 -translate-x-1/2 z-30 text-red-500 font-bold animate-pulse text-xl tracking-[0.5em] bg-black/50 px-4 py-1 rounded">BOSS ENCOUNTER</div>
                )}
                <div className="absolute top-3 left-1/2 -translate-x-1/2 z-30 text-xs text-amber-500 font-mono tracking-widest bg-black/40 px-2 rounded">
                    LEVEL {uiLevel}
                </div>

                {/* Top Right: Score */}
                <div className="absolute top-6 right-6 z-30 text-right">
                    <div className="text-xs text-amber-500/80 uppercase tracking-widest">Score</div>
                    <div className="text-3xl font-mono text-white font-bold tabular-nums drop-shadow-[0_0_5px_rgba(255,255,255,0.5)]">
                        {uiScore.toLocaleString()}
                    </div>
                </div>
            </>
        )}

        {/* BOTTOM HUD - GUIDES & HEALTH */}
        {hasStarted && (
            <div className="absolute bottom-0 left-0 w-full flex flex-col items-center justify-end z-20 pb-4 pointer-events-none">

                 {/* Guide Panels (Slightly Transparent) */}
                 <div className="flex gap-4 mb-4 px-4 max-w-5xl mx-auto opacity-70 hover:opacity-100 transition-opacity duration-300 pointer-events-auto scale-90 origin-bottom">
                      {/* Combo Guide */}
                      <div className="bg-black/60 backdrop-blur-md border border-white/10 rounded-xl p-3 shadow-lg">
                        <div className="grid grid-cols-4 gap-2 text-white/90 text-xs">
                             <div className="text-center">
                                <span className="text-cyan-300 font-bold block">❄️ 极寒</span>
                                <span className="text-[9px] text-gray-400">水+风 (减速)</span>
                            </div>
                            <div className="text-center">
                                <span className="text-purple-400 font-bold block">⚛️ 等离子</span>
                                <span className="text-[9px] text-gray-400">火+风 (聚怪)</span>
                            </div>
                             <div className="text-center">
                                <span className="text-blue-500 font-bold block">⛈️ 风眼</span>
                                <span className="text-[9px] text-gray-400">雷+水 (击退)</span>
                            </div>
                            <div className="text-center">
                                <span className="text-red-500 font-bold block">🌋 地狱火</span>
                                <span className="text-[9px] text-gray-400">火+火 (清屏)</span>
                            </div>
                        </div>
                      </div>

                      {/* Basic Gesture Guide */}
                      <div className="bg-black/60 backdrop-blur-md border border-white/10 rounded-xl p-3 shadow-lg flex gap-4">
                           <div className="text-center">
                                <span className="text-xl block">✋</span>
                                <span className="text-[9px] text-orange-400 font-bold block">火</span>
                           </div>
                           <div className="text-center">
                                <span className="text-xl block">👇</span>
                                <span className="text-[9px] text-blue-400 font-bold block">水</span>
                           </div>
                           <div className="text-center">
                                <span className="text-xl block">👊</span>
                                <span className="text-[9px] text-purple-400 font-bold block">雷</span>
                           </div>
                           <div className="text-center">
                                <span className="text-xl block">✌️</span>
                                <span className="text-[9px] text-teal-300 font-bold block">风</span>
                           </div>
                      </div>
                 </div>

                 {/* Bottom Center: Health Bar */}
                 <div className="flex flex-col items-center gap-1 w-96 max-w-[90vw]">
                    <div className="flex justify-between w-full text-xs text-green-400 uppercase tracking-widest px-1">
                         <span>Core Integrity</span>
                         <span className="font-mono">{Math.max(0, uiHealth)}%</span>
                    </div>
                    <div className="w-full h-4 bg-gray-900 border border-green-500/30 rounded-full overflow-hidden relative shadow-[0_0_15px_rgba(0,255,0,0.2)]">
                        {/* Background Grid Pattern */}
                        <div className="absolute inset-0 opacity-20 bg-[linear-gradient(90deg,transparent_95%,#00ff00_95%)] bg-[length:10px_100%]"></div>

                        <div 
                            className={`h-full transition-all duration-300 ${uiHealth > 30 ? 'bg-green-500 shadow-[0_0_10px_#00FF00]' : 'bg-red-500 animate-pulse'}`} 
                            style={{ width: `${Math.max(0, uiHealth)}%` }}
                        />
                    </div>
                </div>
            </div>
        )}

        {/* Toggle Controls Button */}
        <div className="absolute top-20 right-4 z-30">
            <button 
                onClick={() => setShowControls(!showControls)}
                className="bg-black/40 border border-white/10 p-2 rounded hover:bg-white/10 transition-colors text-white/50 text-xs uppercase font-mono tracking-wider"
            >
                {showControls ? 'Hide Controls' : 'Show Controls'}
            </button>
        </div>

        {/* Debug Info */}
        <div className="absolute top-20 right-28 z-20 text-right opacity-50 pointer-events-none">
             <div className="text-xs text-amber-200 font-mono">{debugInfo}</div>
        </div>

        {/* PARTICLE CONTROLS PANEL (Hidden by Default) */}
        {showControls && (
            <div className="absolute top-28 right-4 z-30 w-64 bg-black/60 backdrop-blur-md border border-white/10 rounded-xl p-4 shadow-2xl animate-[fadeIn_0.3s_ease-out]">
                <h3 className="text-amber-500 text-xs font-bold uppercase tracking-widest mb-4 border-b border-white/10 pb-2">粒子引擎参数</h3>

                <div className="space-y-4">
                    <div>
                        <div className="flex justify-between text-xs text-white/70 mb-1">
                            <span>速度 (Velocity)</span>
                            <span className="font-mono text-amber-400">{settings.speed.toFixed(1)}x</span>
                        </div>
                        <input 
                            type="range" min="0.1" max="10.0" step="0.1" 
                            value={settings.speed}
