                            value={settings.glow}
                            onChange={(e) => setSettings({...settings, glow: parseFloat(e.target.value)})}
                            className="w-full h-1 bg-white/20 rounded-lg appearance-none cursor-pointer accent-amber-500"
                        />
                    </div>
                </div>
            </div>
        )}

        {/* Author Watermark */}
        <div className="absolute bottom-2 left-0 w-full text-center z-20 pointer-events-none opacity-40 hover:opacity-100 transition-opacity">
            <span className="text-[10px] text-gray-400 font-mono">Designed by soda | WeChat: scroll233</span>
        </div>
    </div>
  );
};

