                        <button 
                            onClick={(e) => { e.stopPropagation(); setDifficulty('HARD'); }}
                            className={`px-4 py-2 rounded font-bold border ${difficulty === 'HARD' ? 'bg-red-600 border-red-400 text-white' : 'bg-gray-800 border-gray-600 text-gray-400'}`}
